/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR:1299-01:0":{"b": ["Fondazione del beylik ottomano", "9f0b7c0a"], "d": ["L'inizio dell'autonomia di Osman Gazi, della tribù dei Kayı, nella regione di Söğüt e Domaniç è considerato per tradizione l'avvio della fondazione dello Stato ottomano; alcuni storici ritengono invece la vittoria di Bapheus del 1302 il vero punto di svolta. Grazie alla sua posizione sul confine bizantino, il beylik crebbe rapidamente in forza con le incursioni dei ghazi. In questo contesto di dissoluzione dell'eredità selgiuchide, Osman Gazi raccolse attorno a sé ahi, ghazi e turcomanni nomadi; il legame con lo sceicco Edebali è considerato il fondamento della legittimità spirituale del beylik. Altri luoghi annessi nella stessa data: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Conquista di Bursa", "98c727fa"], "d": ["Bursa, tenuta sotto blocco per anni, si arrese a Orhan Gazi, che guidò la fase finale dell'assedio; la città divenne la prima grande capitale del beylik. Si narra che la notizia della conquista sia stata portata a Osman Gazi sul letto di morte; per sua volontà Osman Gazi fu sepolto a Bursa. In breve tempo la città fu dotata di moschee, imaret e madrase e divenne il modello dell'urbanistica ottomana delle origini.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Conquista di İznik", "a846a811"], "d": ["İznik (Nicea), uno dei più importanti centri bizantini in Anatolia, perduta ogni speranza di resistere dopo la vittoria di Pelekanon del 1329, si arrese a Orhan Gazi. Qui fu fondata la prima madrasa ottomana e studiosi come Dâvûd-i Kayserî vi iniziarono a insegnare; la città divenne il centro del sapere del primo periodo. La chiesa di Santa Sofia fu trasformata in moschea, un esempio precoce della tradizione della conquista.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Conquista di İzmit", "06a35035"], "d": ["Con la caduta di İzmit (Nicomedia) anche l'ultima importante fortezza bizantina sulla sponda anatolica passò sotto il dominio ottomano; l'intera penisola di Kocaeli, fino alla riva opposta a Costantinopoli, divenne territorio ottomano. Il beylik, dominando così tutte le coste meridionali e orientali del Marmara, preparò le basi del passaggio in Rumelia.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Fortezza di Çimpe — il passaggio in Rumelia", "c2f0a07d"], "d": ["Süleyman Paşa, figlio di Orhan Gazi, aveva fatto della fortezza di Çimpe, concessa durante la guerra civile bizantina, la propria base nel 1352; dopo il grande terremoto che nel marzo 1354 distrusse Gallipoli, le fortezze rimaste vuote furono rapidamente fortificate e la penisola divenne una testa di ponte ottomana stabile. Sostenuto dall'insediamento di popolazione turcomanna condotta dall'Anatolia, questo passo segna l'inizio di una presenza ottomana sul continente europeo destinata a superare i 550 anni.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Conquista di Edirne", "2f54ebb0"], "d": ["La presa di Edirne (Adrianopoli), città chiave della Tracia, determinò la base principale e la direzione delle conquiste balcaniche; la data della conquista è controversa nelle fonti, tra il 1361 e il 1369. Poco dopo la città fu fatta capitale, annunciando lo spostamento del baricentro dello Stato verso la Rumelia; rimase capitale per circa 90 anni, fino alla conquista di Costantinopoli.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I salì al trono", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), salito al trono con la morte di Orhan Gazi, nei 27 anni del suo regno portò lo Stato da beylik di frontiera a ossatura di impero. Con il sistema del pençik fu posta la base del corpo dei Giannizzeri, il sistema del timar fu esteso, fu istituito il Beylerbeylik di Rumelia e fu rafforzata l'istituzione del vizirato. Le conquiste balcaniche divennero sotto di lui una politica statale sistematica.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Prima battaglia di Kosovo — il martirio di Murad I", "10b8ddc9"], "d": ["L'alleanza balcanica guidata dal knez Lazar fu sconfitta in modo decisivo nella Piana del Kosovo; la Serbia entrò sotto la sovranità ottomana. Murad I, che percorreva il campo di battaglia, fu pugnalato dal nobile serbo Miloš Obilić e cadde martire: è l'unico sultano ottomano morto sul campo di battaglia. Nell'accampamento gli succedette Yıldırım Bayezid; il fratello Yakub Çelebi fu fatto strangolare, uno dei primi esempi noti di fratricidio dinastico.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Vittoria di Nicopoli", "75716e96"], "d": ["Il grande esercito crociato, riunito per l'appello del re ungherese Sigismondo e al quale parteciparono anche cavalieri francesi e borgognoni, fu duramente sconfitto da Yıldırım Bayezid davanti a Nicopoli, sulle rive del Danubio. La vittoria consolidò il dominio ottomano sulla Bulgaria; in Europa per una generazione non fu possibile organizzare una grande crociata.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Battaglia di Ankara — inizio del Fetret Devri", "b4a99d96"], "d": ["Nella pesante sconfitta subita nella piana di Çubuk contro l'esercito di Tamerlano, Yıldırım Bayezid fu fatto prigioniero e morì in prigionia pochi mesi dopo. Tamerlano fece rivivere i beylik anatolici; i territori ottomani furono spartiti tra i figli di Bayezid e iniziò una lotta per il trono destinata a durare 11 anni (Fetret Devri). Questo periodo, la crisi più grave dalla fondazione dello Stato, impresse nella memoria ottomana l'importanza della struttura centralizzata. Altri insediamenti perduti nella stessa data: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delçev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofya, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Niğbolu, Rusçuk, Selanik, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed ricostituì l'unità", "03413dfd"], "d": ["Sconfitto Mûsâ Çelebi a Çamurlu nel regolamento di conti finale tra i fratelli, Mehmed I riunì i territori del paese sotto un'unica amministrazione; per questo è considerato il «secondo fondatore dello Stato». Durante il suo regno la struttura statale logorata fu riparata, i rapporti con i beylik anatolici furono riequilibrati e in Rumelia fu seguita una cauta politica di pace.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Rivolta dello sceicco Bedreddin", "e0a072ca"], "d": ["Il movimento religioso e sociale sviluppatosi attorno allo sceicco Bedreddin, grande giurista e mistico che era stato kazasker durante il Fetret Devri, esplose in contemporanea con le rivolte di Börklüce Mustafa a Karaburun e di Torlak Kemal a Manisa. Le rivolte furono represse nel sangue; Bedreddin, catturato nel Deliorman, fu giustiziato a Serez. L'evento lasciò una traccia profonda nella letteratura e nella storiografia come la più antica grande rivolta sociale e mahdista della storia ottomana.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Vittoria di Varna", "f739eedc"], "d": ["L'esercito crociato ungaro-polacco, che aveva rotto il trattato di Seghedino e marciava verso sud, fu annientato a Varna da Murad II, tornato alla testa dell'esercito dopo l'abdicazione; il giovane re Ladislao III morì sul campo di battaglia. La vittoria eliminò l'ultima grande possibilità di intervento esterno volto a liquidare la presenza ottomana nei Balcani e mise al sicuro la strada verso la conquista di Costantinopoli.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Seconda battaglia di Kosovo", "ebe0b662"], "d": ["L'esercito di Giovanni Hunyadi, che voleva vendicare Varna, fu sconfitto in modo decisivo da Murad II in tre giorni di aspra battaglia. È l'ultima grande battaglia campale intrapresa dai crociati contro gli Ottomani nei Balcani; con la vittoria il dominio ottomano a sud del Danubio si consolidò in modo ormai irreversibile.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Conquista di Costantinopoli", "583d5e3e"], "d": ["Dopo un assedio durato cinquantaquattro giorni (6 aprile–29 maggio 1453), la mattina del 29 maggio l'esercito ottomano superò le mura ed entrò in città; l'ultimo imperatore, Costantino XI, morì nei combattimenti e l'Impero romano d'Oriente, vecchio di 1100 anni, scomparve dalla storia. Il giovane sultano assunse il titolo di «Fâtih», fece della città la capitale e trasformò Santa Sofia in moschea; la città fu presto rianimata da insediamenti e ricostruzioni. Secondo il TDV, Silivri e Vize furono conquistate definitivamente solo nel 1453; secondo la voce Limni del TDV, l'isola entrò sotto l'amministrazione ottomana subito dopo la conquista e fu lasciata alla famiglia Gattilusio a condizione di un tributo. Nell'atlante Silivri, Vize e Limni sono registrate in questo giorno come passate da Bisanzio agli Ottomani (Limni tributaria). La fusione di cannoni giganteschi, il trasporto delle navi via terra e lo schieramento d'assedio davanti alle mura sono considerati il vertice dell'ingegneria militare dell'epoca. Nella storiografia europea la conquista è tra le date simbolo della fine del Medioevo.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Conquista di Trebisonda", "15f52403"], "d": ["Al termine della difficile campagna del Mar Nero condotta da Mehmed il Conquistatore simultaneamente con esercito e flotta, l'Impero greco di Trebisonda si arrese; con la liquidazione di quest'ultimo residuo del mondo bizantino in Anatolia, l'intera costa meridionale del Mar Nero entrò sotto il dominio ottomano. La fine della dinastia dei Comneni rafforzò la pretesa del Conquistatore di essere «sovrano di due mari e due terre». Altri luoghi annessi nella stessa data: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Conquista definitiva di Silifke — spezzata l'ultima resistenza dei Karamanidi", "d988bee4"], "d": ["La fortezza di Silifke si era arresa una volta a Gedik Ahmed Paşa nel 1472, ma nello stesso anno il karamanide Kasım Bey, con l'aiuto della flotta crociata nel Mediterraneo, l'aveva ripresa. Dopo la vittoria di Otlukbeli, il Conquistatore incaricò suo figlio e Gedik Ahmed Paşa di impadronirsi definitivamente della regione; con l'aiuto degli antichi artiglieri ottomani il deposito di polvere fu incendiato e la fortezza cadde rapidamente. Così fu spezzata l'ultima resistenza dei Karamanidi sulle montagne del Taşeli e dell'İçel; la liquidazione del beylik sarebbe stata completata nel 1474.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Battaglia di Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, sovrano degli Aqquyunlu divenuto una grande potenza a oriente e alleato di Venezia, fu duramente sconfitto a Otlukbeli dall'esercito del Conquistatore, dotato di armi da fuoco. La vittoria consolidò la supremazia ottomana in Anatolia e fu anche una prova precoce della superiorità di un esercito centrale che impiegava cannoni e fucili contro un esercito classico. Secondo la voce Gümüşhane del TDV, la città era sotto il dominio degli Aqquyunlu dal 1467; tale dominio terminò con la sconfitta di Otlukbeli e Gümüşhane passò definitivamente sotto il dominio ottomano.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["La Crimea passa sotto la protezione ottomana", "44e3f7c8"], "d": ["La flotta al comando di Gedik Ahmed Paşa conquistò le città della costa meridionale della Crimea, a cominciare da Kefe, in mano ai Genovesi; queste coste furono rese sancak direttamente ottomano. Il Khanato di Crimea, con Mengli Giray, divenne invece uno Stato vassallo privilegiato che riconosceva la sovranità ottomana e per tre secoli fu un pilastro della politica settentrionale; il Mar Nero si trasformò di fatto in un mare interno ottomano. Altri luoghi annessi nella stessa data: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Morte del Conquistatore — la questione del principe Cem", "190ecf01"], "d": ["Alla morte improvvisa del Conquistatore durante la campagna salì al trono Bayezid II; il fratello Cem Sultan, avanzando pretese al sultanato, fece leggere la khutba e coniare moneta a suo nome a Bursa. Sconfitto, si rifugiò prima presso i Mamelucchi, poi presso i cavalieri di Rodi; divenuto nelle mani dei cavalieri e del papato una carta di scambio della diplomazia europea, Cem morì a Napoli nel 1495. Questo episodio costrinse la politica estera ottomana alla cautela per quindici anni.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Vittoria di Çaldıran", "fea64ebb"], "d": ["Selim I il Severo, volendo risolvere alla radice la minaccia creata in Anatolia dalla propaganda safavide, sconfisse duramente nella piana di Çaldıran l'esercito dello shah Ismail grazie alla superiorità di cannoni e fucili. Si entrò a Tabriz; l'Anatolia orientale e sud-orientale e la linea Mosul-Diyarbakır furono incorporate nell'amministrazione ottomana. Con l'impegno di İdrîs-i Bitlisî, il legame dei principi curdi con gli Ottomani stabilì il quadro del confine orientale per i secoli a venire.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Vittoria di Marj Dabiq", "07d254d3"], "d": ["L'esercito mamelucco fu disperso in poche ore a Marj Dabiq, a nord di Aleppo; l'anziano sultano Qansuh al-Ghawri morì durante la battaglia. Con la vittoria che spalancò le porte di Aleppo e Damasco, Siria, Libano e Palestina passarono sotto il dominio ottomano; si aprì la strada alla campagna d'Egitto che avrebbe posto fine al Sultanato mamelucco.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniye — conquista dell'Egitto e califfato", "caf378d6"], "d": ["L'esercito ottomano, attraversato rapidamente il deserto del Sinai, sfondò a Ridaniye la linea difensiva di Tumanbay ed entrò al Cairo; Tumanbay, che continuava la resistenza, fu catturato e giustiziato e il Sultanato mamelucco scomparve dalla storia. Egitto, Hegiaz e città sante entrarono sotto il dominio ottomano; il califfo abbaside e le sacre reliquie furono portati a Costantinopoli. Con il passaggio del califfato alla dinastia ottomana, i sultani assunsero la pretesa di guida del mondo islamico; il controllo della Via delle Spezie procurò inoltre all'impero grandi entrate. Altri luoghi annessi nella stessa data: Akkâ, Maan, Sayda, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Solimano il Legislatore salì al trono", "f6512269"], "d": ["Il regno di 46 anni di Solimano I, salito al trono come unico figlio maschio alla morte di Selim il Severo, è considerato l'apice politico, militare, giuridico e culturale dell'impero. I kanunname, che sistematizzarono il diritto consuetudinario, gli valsero il titolo di «Kanunî» (il Legislatore); in Occidente fu chiamato «il Magnifico». Le opere dell'architetto Sinan, l'età d'oro della letteratura di divan e la supremazia della flotta nel Mediterraneo sono i simboli di questo periodo.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Conquista di Belgrado", "59ef5cec"], "d": ["Belgrado, che il Conquistatore non aveva potuto prendere nel 1456 e che era considerata la «chiave dell'Europa centrale», cadde nella prima campagna di Solimano dopo un assedio alla confluenza di Danubio e Sava. La linea difensiva meridionale dell'Ungheria crollò; con questa conquista si aprì la porta della campagna in Europa centrale, che si estese a Mohács cinque anni dopo e all'annessione di Buda vent'anni dopo.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Conquista di Rodi", "807bbb1e"], "d": ["Rodi, base dei cavalieri di San Giovanni che minacciavano le rotte marittime del Mediterraneo orientale e la via dei pellegrini, si arrese per patto dopo un sanguinoso assedio durato mesi; ai cavalieri fu permesso di lasciare liberamente l'isola (si sarebbero poi stabiliti a Malta). Fu assicurata la sicurezza delle coste anatoliche e la linea marittima Costantinopoli-Egitto passò sotto ininterrotto controllo ottomano.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Battaglia di Mohács", "f3418b0d"], "d": ["L'esercito ungherese fu annientato nella piana di Mohács in circa due ore dal fuoco dell'artiglieria e dalla superiorità di manovra; il re Luigi II morì in una palude mentre fuggiva. Mohács, una delle grandi battaglie campali vinte più rapidamente nella storia ottomana, pose di fatto fine al regno ungherese indipendente e aprì in Europa centrale l'epoca della rivalità ottomano-asburgica.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Primo assedio di Vienna", "dc49ea4f"], "d": ["Nella campagna organizzata contro le mire asburgiche sul trono ungherese l'esercito ottomano assediò Vienna; per l'abbandono dei cannoni pesanti lungo la strada, l'inverno precoce e le difficoltà di vettovagliamento l'assedio fu tolto dopo tre settimane. Pur non essendo stata presa la città, l'influenza ottomana sull'Ungheria fu mantenuta; le porte di Vienna indicarono il limite dell'accesso logistico dell'impero in Europa centrale.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Conquista di Baghdad — campagna dei Due Iraq", "897092c3"], "d": ["Nella campagna condotta sui «due Iraq» (Iraq arabo e Iraq persiano) si entrò prima a Tabriz, poi senza combattere a Baghdad; la presa dell'antica capitale degli Abbasidi diede al sovrano ottomano grande prestigio nel mondo islamico. Fu restaurato il mausoleo dell'Imam-ı Âzam Abu Hanifa; con l'annessione di Baghdad e Bassora i territori ottomani raggiunsero il Golfo Persico. Altri luoghi annessi nella stessa data: Kerkük, Kerbelâ.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Vittoria navale di Prevesa", "30dc0f97"], "d": ["La flotta crociata costituita sotto la guida del papa, benché numericamente superiore, fu dispersa al largo di Prevesa dalla tattica di Barbarossa, che sfruttò con maestria vento e costa; Andrea Doria abbandonò il campo di battaglia. La vittoria stabilì una supremazia navale ottomana incontrastata nel Mediterraneo destinata a durare circa 33 anni; è la data simbolo della Giornata della Marina nella tradizione marinara turca. Altri luoghi annessi nella stessa data: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annessione di Buda — l'Ungheria provincia ottomana", "db53b244"], "d": ["Partito in campagna per l'assedio asburgico di Buda, Solimano, dopo aver liberato la città, pose l'Ungheria centrale sotto amministrazione ottomana diretta istituendo il Beylerbeylik di Buda; la Transilvania fu invece resa principato autonomo vassallo degli Ottomani. Questo assetto dell'Ungheria divisa in tre durò circa 150 anni e costituì l'ossatura stabile del governo ottomano in Europa centrale.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Pace di Amasya", "a5afe0d1"], "d": ["È il primo trattato di pace ufficiale che pose fine alle guerre ottomano-safavidi durate anni. Baghdad e l'Iraq rimasero agli Ottomani, il confine dell'Anatolia orientale fu per la prima volta riconosciuto reciprocamente; i Safavidi si impegnarono a fermare la propaganda sciita nel territorio ottomano e gli Ottomani a garantire la sicurezza di transito dei pellegrini iraniani. Il trattato fu il primo esempio del quadro giuridico delle relazioni tra i due Stati.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — la morte di Solimano", "e2917ed2"], "d": ["Solimano, settantaduenne, morì nella sua tenda pochi ore prima della caduta della fortezza di Szigetvár, che assediava nella sua tredicesima campagna; Sokullu Mehmed Paşa nascose la morte per settimane perché l'esercito non si disperdesse. La fortezza fu presa, ma lo Stato aveva perso il sultano dal regno più lungo e più splendido; salì al trono il figlio Selim II e il peso dei grandi visir nell'amministrazione dello Stato cominciò ad aumentare.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Conquista di Cipro", "e364a2b3"], "d": ["Nel 1570 fu effettuato lo sbarco a Cipro, sotto dominio veneziano; Nicosia cadde rapidamente, mentre Famagosta si arrese solo nell'agosto 1571, dopo un assedio di undici mesi. L'isola, cruciale per la sicurezza delle rotte commerciali e dei pellegrinaggi del Mediterraneo orientale, fu organizzata come beylerbeylik e vi fu insediata popolazione dall'Anatolia; la conquista fu anche il pretesto della grande alleanza crociata che sarebbe giunta a Lepanto.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Sconfitta di Lepanto (İnebahtı)", "6a1d44a9"], "d": ["La flotta crociata, unitasi per la conquista di Cipro, colse la flotta ottomana nel golfo di Lepanto e ne distrusse la maggior parte; il kapudan paşa Müezzinzâde Ali Paşa cadde martire e si salvò solo la squadra di Uluç Ali. Dopo il disastro il gran visir Sokullu Mehmed Paşa nominò Uluç Ali Paşa kapudan paşa affidandogli il compito di ricostituire la flotta dispersa e avviò la costruzione di una nuova flotta in tutti gli arsenali, da Costantinopoli ad Alanya; tuttavia la supremazia assoluta nel Mediterraneo era stata psicologicamente scossa.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Battaglia di Mezőkeresztes (Haçova)", "da308ec5"], "d": ["Nella più grande battaglia campale della Lunga Guerra (1593–1606), l'esercito guidato personalmente da Mehmed III, nel momento in cui stava per disperdersi, si riorganizzò per l'esortazione di Hoca Sâdeddin Efendi e travolse l'esercito asburgico. È considerata l'ultima grande battaglia campale classica vinta dagli Ottomani; tuttavia il fatto che non abbia mutato l'andamento generale della guerra fu visto anche come segno del logoramento del sistema militare.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Pace di Zsitvatorok", "39c01142"], "d": ["Con il trattato che pose fine alla logorante guerra di tredici anni, il sovrano asburgico fu per la prima volta considerato pari al sultano con il titolo di «imperatore romano» e il tributo annuale fu abolito. Le perdite territoriali furono quasi nulle; ma questo mutamento del linguaggio diplomatico è letto come il simbolo della fine della pretesa ottomana di assoluta superiorità nei confronti dell'Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Trattato di Qasr-ı Şirin", "c1acf3af"], "d": ["Il trattato firmato dopo la riconquista di Baghdad da parte di Murad IV (1638) pose fine a oltre un secolo di guerre ottomano-safavidi. Baghdad e l'Iraq rimasero definitivamente agli Ottomani, Erevan fu lasciata ai Safavidi; la linea tracciata, con piccole modifiche, divenne la base dell'attuale confine turco-iraniano ed è considerata uno dei confini più longevi del mondo. Il trattato lasciò agli Ottomani Bedre, Cessân, Mendelî, Derteng e Derne; la fortezza di Zencir sul confine sarebbe stata demolita, i villaggi a ovest di essa sarebbero rimasti agli Ottomani, quelli a est all'Iran. L'area intorno alla fortezza di Zalim presso Şehrizor e Kızılca Kale rimasero agli Ottomani, Avroman e Mihriban all'Iran; le fortezze di Kotur, Mâkû e Mağazberd sarebbero state demolite da entrambe le parti.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Completata la conquista di Creta", "e0d85604"], "d": ["L'assedio di Candia, ultimo atto della guerra di Creta iniziata nel 1645, si concluse con la determinata campagna triennale di Fâzıl Ahmed Paşa; il comandante veneziano Morosini consegnò la città con un trattato. La lotta, durata circa un quarto di secolo, è registrata come il più lungo assedio della storia ottomana; anche l'ultima grande fortezza latina del Mediterraneo orientale passò sotto il dominio ottomano. Le tre piccole fortezze rocciose sulla costa settentrionale dell'isola — Suda, Spinalonga e Grabusa — rimasero ancora ai Veneziani; poiché sorgono su isolotti separati, sulla mappa non possono essere mostrate separatamente dal resto di Creta.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Pace di Buczacz — i confini più estesi", "b17b6e5a"], "d": ["Con la pace di Buczacz, firmata dopo la conquista di Kamianets nella campagna contro la Polonia, la Podolia fu annessa agli Ottomani e una parte dell'Ucraina fu posta sotto protezione. L'impero raggiunse così i suoi confini più ampi in Europa; questo punto è considerato l'apice e allo stesso tempo l'ultimo anello dell'epoca dell'espansione.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Disfatta del secondo assedio di Vienna", "7d889252"], "d": ["L'assedio di Vienna di due mesi condotto da Merzifonlu Kara Mustafa Paşa si trasformò in disfatta per l'improvviso colpo scagliato dalle colline del Kahlenberg dal re di Polonia Jan Sobieski; l'esercito si ritirò abbandonando i bagagli e Merzifonlu fu giustiziato a Belgrado. La guerra con la Lega Santa formatasi dopo la vittoria durò 16 anni; questa disfatta è indicata come il momento d'inizio del grande declino nella storia ottomana.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Conquista della fortezza di Grabusa — una delle fortezze rocciose di Creta rimaste ai Veneziani", "3ddf9eeb"], "d": ["Sebbene con la resa di Candia nel 1669 la conquista di Creta fosse considerata in gran parte completata, la fortezza insulare rocciosa di Grabusa, all'estremità nord-occidentale dell'isola, rimase in mano veneziana per altri ventitré anni. Con la sua presa nel 1692 fu eliminato uno dei tre residui veneziani a Creta; Suda e Spinalonga avrebbero atteso la campagna di Morea del 1715.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Pace di Karlowitz — la prima grande perdita territoriale", "8f7e2546"], "d": ["Con Karlowitz, che pose fine a sedici anni di guerre con la Lega Santa, Ungheria e Transilvania furono lasciate all'Austria, la Podolia alla Polonia, la Morea e le coste della Dalmazia a Venezia. Per la prima volta nella storia ottomana un territorio di tale entità andava perduto a tavolino e in modo permanente; il trattato è considerato il documento d'avvio della nuova epoca in cui l'impero passò sulla difensiva di fronte all'Europa, ed è anche una svolta della storia della diplomazia ottomana. Insediamenti che nello stesso giorno cambiano mano nell'atlante: Kostajnica e Jasenovac (dagli Ottomani agli Asburgo; il testo del trattato lascia Castanoviz nelle mani dell'imperatore, il giorno della consegna di Jasenovac non è nella fonte, è stato scritto il giorno del trattato) e Preveza (da Venezia agli Ottomani; TDV karlofca: secondo la disposizione firmata il 24 Receb 1110 / 26 gennaio 1699 furono restituiti i luoghi occupati da Venezia a nord del golfo di Lepanto). L'atlante assegna inoltre Kostayniçe (Kostajnica) e Jasenovaç al lato asburgico, Uman e Vinnitsa in Ucraina della riva destra dagli Ottomani alla Polonia (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: dominio turco 1672-99) e Nadin in Dalmazia a Venezia (il giorno di consegna specifico dell'insediamento non è nella fonte, è stato scritto il giorno del trattato; gli estremi del periodo di Nadin non sono verificati con la fonte — approssimazione dichiarata). Anche Vonitsa, a nord del golfo di Lepanto, viene restituita da Venezia agli Ottomani (TDV karlofca); in Dalmazia Vrana (Urana) è tra i luoghi rimasti a Venezia (estremo del periodo non verificato — dichiarato).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Vittoria del Prut", "2583572f"], "d": ["Nella guerra scoppiata per la questione del re di Svezia, rifugiatosi presso gli Ottomani dopo la sconfitta di Poltava, l'esercito dello zar Pietro I, accerchiato sulle rive del Prut, dovette arrendersi. Con il trattato firmato Azov fu restituita; la decisione di non annientare l'esercito e di lasciare libero lo zar è entrata nella storia come decisione discussa fino a oggi.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Conquista delle fortezze di Suda e Spinalonga — cancellata l'ultima traccia veneziana a Creta", "7261f7ba"], "d": ["Ventitré anni dopo la caduta di Grabusa nel 1692, con una diramazione della campagna di Morea furono conquistate anche Suda e Spinalonga, gli ultimi due capisaldi veneziani a Creta. Così la conquista di Creta, iniziata nel 1645, fu completata dopo quarantasei anni fino all'ultimo centimetro dell'isola.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Rivolta di Patrona Halil", "100941a4"], "d": ["L'insuccesso sul fronte persiano, le tasse e la collera per il lusso della cerchia di palazzo si trasformarono in una grande insurrezione guidata dal bagnino Patrona Halil. Il gran visir İbrahim Paşa fu ucciso, Ahmed III fu deposto e l'Età dei Tulipani terminò; il fatto che i ribelli dominassero la città per mesi mostrò in modo impressionante la fragilità dell'autorità centrale.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Pace di Belgrado — la riconquista di Belgrado, Smederevo e della Serbia settentrionale", "ba7f8e46"], "d": ["Al termine della guerra condotta su due fronti contro Austria e Russia (1736–1739), Belgrado e la Serbia settentrionale furono riprese; la Russia accettò di smilitarizzare Azov e di non mantenere una flotta nel Mar Nero. Considerato l'ultimo grande successo della diplomazia e dell'esercito ottomano del XVIII secolo, il trattato procurò all'impero un periodo di pace di un quarto di secolo. Altri insediamenti che nello stesso giorno nell'atlante tornano dall'Austria agli Ottomani: Hisarcık (Grocka) (catena dell'abi-merkez di Belgrado; TDV belgrad), Krayova (Craiova), Rimnik (Râmnicu Vâlcea) e Turnu Severin (ritorno della Piccola Valacchia agli Ottomani, nel vassallaggio della Valacchia). Bosna Brod (Bosanski Brod) e Bosna Dubiça (Bosanska Dubica), sulla fascia della Sava, tornano invece agli Ottomani nell'atlante il 28 settembre 1739 (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 settembre 1739). Anche Tırgu Jiu, nella Piccola Valacchia, torna agli Ottomani nello stesso giorno.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Incursione di Çeşme", "840b30bd"], "d": ["La flotta russa, uscita nel Mediterraneo con l'appoggio degli Inglesi, assalì con brulotti la flotta ottomana rifugiata nel porto di Çeşme e la incendiò quasi per intero. La Russia apparve per la prima volta nel Mediterraneo come grande potenza navale; il disastro fu uno dei colpi che determinarono il destino della guerra conclusasi con Küçük Kaynarca nel 1774 e rese evidente la necessità di una riforma radicale della flotta.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Trattato di Küçük Kaynarca", "2776dcdb"], "d": ["Con Küçük Kaynarca, che pose fine alla guerra del 1768–1774 ed è considerato uno dei trattati più gravi della storia ottomana, fu concessa l'«indipendenza» al Khanato di Crimea — in pratica fu creata una sfera d'influenza russa. La Russia si insediò sulla costa del Mar Nero e ottenne il diritto di passaggio dagli Stretti per le navi mercantili e un'ambasciata permanente a Costantinopoli; la vaga clausola di protezione sui sudditi ortodossi aprì la porta ai pretesti di intervento del secolo successivo. Per la prima volta un territorio a popolazione musulmana veniva sottratto al dominio ottomano.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annessione della Crimea alla Russia", "bdf6faa8"], "d": ["La Crimea «indipendente» creata da Küçük Kaynarca, con il pretesto dei disordini sotto l'ultimo khan Şahin Giray, fu annessa alla Russia con il manifesto di Caterina II. La partnership ottomano-crimeana di tre secoli finì; la perdita delle steppe settentrionali eliminò la profondità difensiva di Costantinopoli e avviò la prima grande ondata di migrazione di decine di migliaia di Tatari di Crimea verso le terre ottomane. In questo giorno la penisola di Crimea (Aluşta, Kefe, Sudak, Yalta, Balaklava, İnkirman, Mankup, Arabat) fu annessa alla Russia; Taman e Kuban passarono alla Russia con la stessa annessione (TDV Kırım: 8 aprile 1783 giuliano = 19 aprile gregoriano).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III e il Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, salito al trono in piena guerra, vedendo che le sconfitte erano strutturali, avviò un ampio programma di riforme sotto il nome di «Nizâm-ı Cedîd» (Nuovo Ordine): un nuovo esercito addestrato all'europea, un tesoro separato per finanziarlo (Îrâd-ı Cedîd), il rafforzamento delle scuole di ingegneria e le prime ambasciate permanenti nelle capitali europee. Il programma è considerato l'inizio della moderna tradizione riformatrice turca; ma per la resistenza dei corpi e degli âyân sarebbe stato abbattuto nel 1807.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidazione dei cavalieri di Malta — tappa della flotta francese lungo la rotta", "d62f901d"], "d": ["La flotta francese diretta in Egitto fece scalo a Malta, sul suo percorso; i cavalieri di San Giovanni (di Malta) consegnarono l'isola senza grande resistenza. L'ultima fortezza dell'ordine cavalleresco, cacciato da Rodi nel 1522 e stabilitosi qui, finì così. Malta sarebbe passata all'Inghilterra due anni dopo, mentre Napoleone si diresse dall'isola direttamente ad Alessandria.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Occupazione dell'Egitto da parte di Napoleone", "93fede5f"], "d": ["L'esercito del generale Bonaparte sbarcò ad Alessandria e occupò l'Egitto; questa spedizione, mirante alla via dell'India dell'Inghilterra, fu il primo attacco diretto di una potenza europea ai territori centrali ottomani. L'incursione di Nelson ad Abukir e la difesa di Acri di Cezzâr Ahmed Paşa spezzarono la marcia francese; l'occupazione terminò nel 1801, ma nel vuoto lasciato iniziarono l'ascesa di Mehmed Ali Paşa di Kavala e l'epoca della «Questione d'Oriente».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Documento firmato tra il palazzo e le potenti famiglie di âyân di provincia sotto la guida di Alemdar Mustafa Paşa, âyân di Rusçuk che aveva portato al trono Mahmud II; mentre gli âyân si impegnavano alla fedeltà al sultano e al sostegno militare, lo Stato riconosceva la loro esistenza e i loro diritti. Essendo il primo esempio nella storia ottomana di limitazione dell'autorità del sultano tramite un documento, è considerato da alcuni storici il lontano inizio della tradizione costituzionale; in pratica perse efficacia nel giro di pochi mesi.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Inizio della rivolta greca", "a7293715"], "d": ["L'insurrezione preparata dall'organizzazione Filikí Etería scoppiò prima in Valacchia e poi, con la sua forza principale, in Morea; lo Stato, impegnato con la questione di Tepedelenli Ali Paşa, tardò a intervenire. Grazie alla forte simpatia greca dell'opinione pubblica europea (filellenismo), la rivolta si trasformò rapidamente in una causa internazionale; così fu accesa la miccia del primo movimento indipendentista riuscito dell'era del nazionalismo nelle terre ottomane. Altri insediamenti perduti nella stessa data: Atina, Balyabadra (Patrasso), İstefe (Tebe), Livadya, Eleusis (Attica), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Primo levante armato in Morea", "77e6250f"], "d": ["Dopo il passaggio del Prut la rivolta si estese alla Morea: all'azione armata iniziata a Kalavryta (21 marzo giuliano) seguirono i movimenti di Patrasso, Kalamata e Mani; la Morea si trasformò rapidamente in un'insurrezione generale e l'amministrazione ottomana perse la maggior parte della penisola. Altri insediamenti perduti nella stessa data: Atina, Balyabadra (Patrasso), İstefe (Tebe), Livadya, Eleusis (Attica), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — abolito il corpo dei Giannizzeri", "08c9372a"], "d": ["I giannizzeri, che avevano rovesciato le marmitte contro l'addestramento del neocostituito corpo Eşkinci, furono annientati nelle loro caserme dell'Etmeydanı dal fuoco dei cannoni delle truppe fedeli preparate in anticipo da Mahmud II; il corpo fu abolito insieme a tutte le sue sezioni e ai tekke bektashi collegati. Questa operazione, passata alla storia con il nome di «evento fausto», liquidando un'istituzione di quattro secoli aprì la strada all'esercito degli Asâkir-i Mansûre-i Muhammediyye e a tutte le successive riforme di centralizzazione.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Incursione di Navarino", "ee579e7f"], "d": ["La flotta ottomano-egiziana, impegnata a reprimere la rivolta greca, fu incendiata a Navarino dalla flotta combinata anglo-franco-russa entrata nel porto senza dichiarazione di guerra; andarono perduti quasi sessanta navi e migliaia di marinai. L'incursione, liquidata dalla diplomazia europea come «evento sfortunato», garantì di fatto l'indipendenza greca e aprì la strada alla guerra ottomano-russa del 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Editto di Tanzimat", "5042ce7b"], "d": ["Con il Hatt-ı Hümâyun letto a Gülhane la sicurezza della vita, dei beni e dell'onore di tutti i sudditi, senza distinzione di religione, fu posta sotto garanzia dello Stato; furono proclamati i princìpi di giustizia nella tassazione, ordine nel servizio militare e nessuna pena senza processo. L'editto, opera di Mustafa Reşid Paşa, è considerato il primo grande documento di carattere costituzionale della modernizzazione ottomana e ha dato il nome all'epoca di riforme del «Periodo del Tanzimat» (1839–1876); in questo quadro furono condotte radicali ristrutturazioni dell'amministrazione, del diritto, dell'istruzione e delle finanze.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Inizio della guerra di Crimea", "3b9ca3c8"], "d": ["La crisi iniziata con la questione dei luoghi santi e la pretesa russa di protezione sui sudditi ortodossi si trasformò in conflitto aperto con la dichiarazione di guerra ottomana; dopo l'incursione di Sinope, Inghilterra e Francia (poi il Piemonte) entrarono in guerra dalla parte ottomana. La guerra, vinta con lo sbarco degli eserciti alleati in Crimea e la presa di Sebastopoli e conclusa con la pace di Parigi del 1856; tuttavia il primo debito estero contratto negli anni di guerra (1854) gettò l'impero in una spirale di dipendenza finanziaria destinata a durare mezzo secolo.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Editto di Riforma (Islahat Fermanı)", "78ff234d"], "d": ["L'editto proclamato prima dei negoziati di pace di Parigi, ampliando i princìpi del Tanzimat, riconobbe ai sudditi non musulmani ampi diritti di uguaglianza, inclusi l'impiego pubblico, il servizio militare e l'apertura di scuole; le organizzazioni comunitarie furono riordinate. Con il trattato di Parigi firmato subito dopo lo Stato ottomano fu ufficialmente ammesso alla famiglia del diritto internazionale europeo e la sua integrità territoriale fu posta sotto garanzia comune delle grandi potenze — garanzia che nella pratica sarebbe stata una nuova porta per gli interventi.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — Prima Monarchia Costituzionale", "0fe052c1"], "d": ["Nel giorno dell'apertura della conferenza internazionale riunita a Costantinopoli per discutere la crisi balcanica fu proclamata con colpi di cannone la prima costituzione ottomana; con il Kanûn-ı Esâsî, opera del movimento dei «Giovani Ottomani» guidato da Midhat Paşa, fu istituito un parlamento bicamerale. Il Meclis-i Meb'ûsan fu aperto nel marzo 1877; ma Abdülhamid II, adducendo la guerra del '93, nel febbraio 1878 sospese il parlamento a tempo indeterminato e la costituzione rimase sospesa per trent'anni.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Guerra del '93 (guerra russo-ottomana 1877–78)", "5bd96af7"], "d": ["Nella guerra detta «Guerra del '93» perché corrispondente all'anno rûmî 1293, gli eserciti russi attaccarono su due fronti; benché la difesa di Plevna di Gazi Osman Paşa e le battaglie del Caucaso di Ahmed Muhtar Paşa siano diventate epiche, il fronte crollò e i Russi avanzarono fino a Yeşilköy (Santo Stefano). La guerra avviò le grandi ondate di migrazione musulmana dai Balcani e dal Caucaso verso Costantinopoli, i cui effetti giungono fino a oggi; la struttura demografica e finanziaria dell'impero non tornò più com'era.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Trattato di Berlino", "47f76a49"], "d": ["Il Congresso di Berlino, che rivide nel nome dell'equilibrio delle grandi potenze la «Grande Bulgaria» creata da Santo Stefano, lasciò comunque un quadro pesante: Serbia, Montenegro e Romania divennero indipendenti; fu istituito il Principato autonomo di Bulgaria; Bosnia-Erzegovina fu lasciata all'occupazione austriaca, Cipro all'amministrazione inglese, Kars-Ardahan-Batum alla Russia. L'ordine ottomano di cinquecento anni in Rumelia si dissolse in gran parte; la «questione d'Oriente» divenne un tema costante della diplomazia europea. Altri insediamenti perduti nella stessa data: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Bükreş, Yaş, Köstence. La Romania, in cambio della cessione della Bessarabia alla Russia, ottenne Tulça (Tulcea) e la Dobrugia: Tulça, Babadağı (Babadag), Maçin, İshakçı (Isaccea), Hırsova (Hârșova) e Mangalya (Mangalia), nella Dobrugia settentrionale, passarono alla Romania.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Occupazione della Tunisia e Düyûn-ı Umûmiyye", "c7e25598"], "d": ["La Francia, col pretesto di incidenti sul confine algerino, occupò la Tunisia e la pose sotto il proprio protettorato con il trattato del Bardo; la presenza ottomana in Nord Africa si ridusse alla Tripolitania. Con il Decreto di Muharrem emanato nello stesso anno fu istituita l'Amministrazione del Debito Pubblico Ottomano (Düyûn-ı Umûmiyye), nella quale erano rappresentati i creditori per la gestione dei debiti esteri in bancarotta: entrate fondamentali come sale, tabacco e seta furono assegnate direttamente a questa amministrazione straniera e la sovranità finanziaria fu gravemente limitata. Altri insediamenti perduti nella stessa data: Kayrevan, Gabes, Sfaks, Cerbe (Djerba).", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Occupazione britannica dell'Egitto", "f1269768"], "d": ["Il movimento di Urâbî Paşa, sorto in Egitto contro la bancarotta finanziaria e il controllo straniero, fu schiacciato dalla vittoria di Tell el-Kebir dell'esercito britannico sbarcato dopo il bombardamento di Alessandria, e il Cairo fu occupato. Sebbene giuridicamente l'Egitto restasse legato agli Ottomani, di fatto passò sotto amministrazione britannica; il controllo del Canale di Suez si collocò al centro della strategia imperiale britannica.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Proclamazione della Seconda Monarchia Costituzionale", "95ee2fd2"], "d": ["Di fronte al movimento cresciuto con la salita in montagna in Macedonia di ufficiali legati al Comitato Unione e Progresso, Abdülhamid II rimise in vigore il Kanûn-ı Esâsî; la «proclamazione della libertà» fu accolta con entusiasmo e si andò alle elezioni. Ma la stabilità non arrivò: dopo la repressione dell'Incidente del 31 Mart (aprile 1909) Abdülhamid fu deposto; in quei mesi convulsi si ebbero anche l'indipendenza della Bulgaria, l'annessione della Bosnia e l'orientamento di Creta verso la Grecia.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Guerra di Tripolitania", "ed441994"], "d": ["L'Italia, in cerca di colonie, dichiarò guerra alla Tripolitania, ultimo territorio ottomano in Nord Africa, e ne occupò le coste; poiché lo Stato, privo di flotta, non poteva inviare un esercito regolare, giovani ufficiali come Mustafa Kemal ed Enver Bey passarono segretamente nella regione e organizzarono con le tribù senussite una resistenza efficace. Con il trattato di Ouchy (18 ottobre 1912), firmato per lo scoppio della guerra balcanica, la Libia fu lasciata all'Italia; l'Italia occupò inoltre Rodi e il Dodecaneso.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Trattato di Londra — la perdita della Rumelia", "f3f976df"], "d": ["Con il trattato di Londra, che pose fine alla Prima guerra balcanica, furono perduti tutti i territori a ovest della linea Midye-Enez e le isole dell'Egeo; l'Albania divenne indipendente. Della Rumelia, per oltre cinquecento anni baricentro demografico, economico e culturale dell'impero, sarebbe rimasta solo la Tracia orientale (Edirne fu ripresa nella Seconda guerra balcanica); la perdita irrigidì radicalmente la politica di guerra e di insediamento dell'amministrazione unionista. Andarono perduti questi luoghi a ovest della linea Midye-Enez: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Dibra), Prizren, Priştine, Peç (Pejë), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); a Creta Hanya, Kandiye, Girit (Resmo), Sitiye (Sitia) e İsfakiye (Sfakia).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Ingresso nella Prima guerra mondiale", "05a0252e"], "d": ["L'ammissione attraverso lo Stretto, come se fossero state acquistate, delle corazzate Goeben e Breslau sfuggite agli Inglesi trascinò lo Stato passo dopo passo accanto alla Germania; con il bombardamento dei porti russi da parte della flotta al comando dell'ammiraglio Souchon (29 ottobre) la guerra iniziò di fatto e le dichiarazioni reciproche giunsero all'inizio di novembre. Nonostante la proclamazione del Cihâd-ı Ekber, l'effetto atteso non si produsse; per quattro anni l'impero si trovò in una guerra per l'esistenza su cinque diversi fronti, dal Caucaso alla Palestina.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Vittoria di Çanakkale", "95d888e8"], "d": ["L'armata alleata, che mirava a prendere Costantinopoli e a raggiungere la Russia, il 18 marzo fu respinta dallo Stretto dal fuoco dei campi minati e delle batterie; lo sbarramento posato dalla nave posamine Nusret decise le sorti della battaglia. Anche l'operazione terrestre di Gallipoli, iniziata in aprile, fu fermata ad Anafartalar e a Conkbayırı; gli alleati evacuarono completamente la penisola nel gennaio 1916. Il nome del tenente colonnello Mustafa Kemal si fece conoscere su questo fronte; la vittoria, ottenuta con circa un quarto di milione tra caduti e perdite, è considerata il luogo in cui nacquero i quadri e lo spirito della Guerra di Liberazione Nazionale.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Rivolta dello sceriffo Hussein", "75f7c58c"], "d": ["L'emiro della Mecca, lo sceriffo Hussein, dopo una corrispondenza segreta con gli Inglesi si sollevò con la promessa di un regno arabo indipendente; la ferrovia del Hegiaz divenne bersaglio di incursioni. Benché la leggendaria difesa di Medina da parte di Fahreddin Paşa, protrattasi fino a dopo l'armistizio, sia rimasta come simbolo di resistenza, la rivolta, unendosi all'avanzata britannica sul fronte della Palestina, accelerò la dissoluzione del dominio ottomano nelle province arabe. Altri insediamenti perduti nella stessa data: Tâif.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Armistizio di Mudros", "9e87c767"], "d": ["Lo Stato ottomano, i cui fronti erano stati separati dal crollo della Bulgaria, uscì dalla guerra con l'armistizio firmato sulla corazzata Agamemnon. L'apertura degli Stretti e in particolare l'articolo 7, che consentiva l'occupazione dei luoghi la cui sicurezza fosse minacciata, divennero in breve il paravento giuridico di una spartizione di fatto: furono occupate Mosul, Alessandretta, poi Smirne e Costantinopoli. L'armistizio è considerato il documento della fine effettiva dell'impero. Altri insediamenti perduti nella stessa data: Hama, Şam, Humus.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal a Samsun — la Guerra di Liberazione Nazionale", "09a8f784"], "d": ["Nel clima di indignazione creato dall'occupazione di Smirne, Mustafa Kemal Paşa, sbarcato a Samsun come ispettore della 9ª Armata, volse il suo incarico ufficiale all'organizzazione della resistenza in Anatolia. La Circolare di Amasya e i congressi di Erzurum e Sivas ne sono la prosecuzione; il principio «l'indipendenza della nazione sarà salvata ancora dalla determinazione e dalla decisione della nazione» divenne il nucleo del programma politico della Guerra di Liberazione.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Apertura della Grande Assemblea Nazionale e Sèvres", "2008feec"], "d": ["Per l'occupazione ufficiale di Costantinopoli e lo scioglimento del Meclis-i Meb'ûsan, il 23 aprile 1920 fu aperta ad Ankara la Grande Assemblea Nazionale; l'assemblea, che concentrò in sé poteri straordinari, divenne il nucleo del nuovo Stato basato sulla volontà nazionale. Il trattato di Sèvres, firmato in agosto dal governo di Costantinopoli, spartiva l'Anatolia; la Grande Assemblea dichiarò traditori della patria i firmatari e Sèvres non poté mai essere applicato.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Battaglia del Sakarya", "f2f970a6"], "d": ["L'offensiva greca, giunta fino a 50 chilometri da Ankara, fu spezzata in una battaglia di 22 giorni e 22 notti condotta da Mustafa Kemal Paşa, che aveva assunto il comando supremo, con l'ordine «non esiste linea di difesa, esiste superficie di difesa». L'esercito greco passò per la prima volta alla difesa strategica; la vittoria portò a Mustafa Kemal i titoli di gazi e di müşir (maresciallo) e aprì la porta all'Accordo di Ankara con la Francia e al riconoscimento internazionale.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Grande Offensiva e liberazione di Smirne", "172a50c4"], "d": ["L'offensiva lanciata da Kocatepe la mattina del 26 agosto raggiunse il 30 agosto, a Dumlupınar, l'annientamento delle forze principali greche con la Battaglia del Comandante in Capo; con l'inseguimento condotto sotto l'ordine «Armate, il vostro primo obiettivo è il Mediterraneo, avanti!», il 9 settembre Smirne fu liberata. Con l'armistizio di Mudanya (11 ottobre) la Tracia orientale fu ripresa senza combattere; la vittoria militare determinò la forza al tavolo del nuovo Stato che sarebbe stato costituito a Losanna.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Abolizione del sultanato", "9f36a9f6"], "d": ["Poiché alle trattative di Losanna fu invitato anche il governo di Costantinopoli, il 1° novembre 1922 la Grande Assemblea Nazionale separò sultanato e califfato e abolì il sultanato; il dominio dinastico ottomano di 623 anni terminò giuridicamente. Mehmed VI Vahideddin il 17 novembre lasciò il paese su una corazzata inglese; alla carica di califfo fu chiamato con decisione dell'Assemblea Abdülmecid Efendi e anche questa carica sarebbe stata abolita il 3 marzo 1924.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Trattato di Losanna", "38c27f7d"], "d": ["Con il Trattato di pace di Losanna, firmato al termine di otto mesi di aspri negoziati, furono riconosciuti sul piano internazionale i confini, la piena indipendenza e la sovranità del nuovo Stato turco; le capitolazioni furono abolite, il Düyûn-ı Umûmiyye fu avviato alla liquidazione e fu regolato lo scambio di popolazioni. Losanna, che rese di fatto nullo Sèvres, è considerata la vittoria diplomatica della Guerra di Liberazione e il documento estero fondativo della Repubblica.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Proclamazione della Repubblica", "d5bfcdfb"], "d": ["Con l'accettazione da parte della Grande Assemblea Nazionale, tramite modifica costituzionale, della disposizione «la forma di governo dello Stato turco è la repubblica», fu proclamata la Repubblica; Mustafa Kemal Paşa fu eletto primo presidente. Così si chiudeva l'avventura ottomana di 624 anni iniziata nel 1299 come beylik di frontiera; il nuovo Stato, in cui la sovranità appartiene incondizionatamente alla nazione, fu fondato sull'eredità dell'impero.", "f5cabb8c"]},
"OLAYLAR_0073_IRAN_YANYA:1820-03-01:0":{"b": ["Destituzione di Tepedelenli Ali Pascià e inizio dell'assedio di Giannina", "e8a6530b"], "d": ["La politica di Mahmud II di epurazione delle forze locali raggiunse Tepedelenli Ali Pascià, che governava Giannina da trentatré anni e teneva di fatto in mano Tessaglia ed Epiro. Il pascià fu destituito dalla carica di capo dei derbend e il figlio Veli dal pascialato di Tirhala; poiché ci si aspettava che non vi si sarebbe adeguato, furono inviate forze contro di lui. Hurşid Ahmed Pascià, incaricato di ciò, era contemporaneamente governatore di Morea e gli era stato dato anche il seraschierato di Rumelia; tutti i governanti civili e militari della regione furono incaricati di catturare Tepedelenli. Quindi, quando scoppiò la rivolta greca, il comandante che avrebbe dovuto governare la Morea e le forze ai suoi ordini stavano assediando la fortezza di Giannina. Ali Pascià il 23 maggio 1820 tenne a Giannina una riunione con i Greci, tentò di fondare un eyalet greco sotto la propria amministrazione e diede loro aiuti in denaro e armi. Dall'altra parte non vi era una forza trascurabile: Ali Pascià disponeva di un esercito di 30-40.000 uomini, di cui 7.000 permanenti, e di una piccola flotta; la popolazione sotto la sua amministrazione era stimata in 1,5-2 milioni e il reddito annuo in 4-5 milioni di kuruş.", "d0250e2a"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:0":{"b": ["Inizia la guerra ottomano-persiana — perdita di Kars e Bayezid, assedio di Erzurum", "570b27bd"], "d": ["Nel secondo anno della rivolta greca il confine orientale dell'impero si trasformò in zona di guerra. L'erede qajar Abbas Mirza, con il pretesto che i rappresentanti ottomani avessero perquisito la carovana della moglie dello scià diretta in pellegrinaggio alla Mecca, varcò il confine con una grande forza militare; prese i vilayet di Kars e Bayezid e pose sotto assedio Erzurum. La forza che aveva di fronte non era una normale unità di frontiera: Abbas Mirza aveva addestrato l'esercito dell'Azerbaigian secondo i metodi europei e aveva fatto costruire a Tabriz una polveriera e fonderie di cannoni. L'Impero ottomano era invece in quel momento impegnato a ovest con la rivolta di Morea e a nord-ovest con la resistenza di Tepedelenli Ali Pascià a Giannina, e non aveva un esercito addestrato all'europea; il Corpo dei Giannizzeri sarebbe rimasto in piedi fino al 1826.", "88b4be76"]},
"OLAYLAR_0073_IRAN_YANYA:1821-01-01:1":{"b": ["Occupazione persiana di Sulaymaniyya e Baghdad — assedio di Kirkuk", "384d74e4"], "d": ["Contemporaneamente alle operazioni in Anatolia orientale, le forze persiane lanciarono un attacco su vasta scala contro l'Iraq settentrionale e la provincia di Baghdad, sotto amministrazione ottomana. Baghdad era allora governata da Kölemen Dâvud Pascià, governatore dal 1817; il pascià disponeva di una forza di 10.000 uomini tra fanteria e artiglieria, addestrata da Deveaux, ex aiutante di Napoleone. Nel centro dell'impero non esisteva ancora un esercito simile — le unità addestrate all'europea erano allora soltanto nelle mani di potenti governatori di provincia. Ciò che pose fine alla guerra non fu una vittoria ottomana: la resistenza ottomana e l'epidemia che colpì l'Azerbaigian costrinsero le forze persiane al ritiro.", "b60b096c"]},
"OLAYLAR_0073_IRAN_YANYA:1822-02-14:0":{"b": ["Uccisione di Tepedelenli Ali Pascià — fine dell'assedio di Giannina", "da679150"], "d": ["La resistenza a Giannina durò quasi due anni e proprio in questo periodo la rivolta greca assunse una diffusione generale. Quando Hurşid Pascià mandò spie nella fortezza e distribuì gradi e doni ai fuggiaschi, il numero dei soldati attorno ad Ali Pascià scese a quaranta-cinquanta; il pascià, con la garanzia che non sarebbe stato toccato se si fosse arreso, si ritirò nel Monastero di Pandeleimon sul lago. Nel frattempo la famiglia di Hurşid Pascià era caduta in mano ai ribelli greci; per poter tornare in Morea il più presto possibile, egli ignorò il salvacondotto che aveva dato e fece preparare un falso ordine di esecuzione. Quando fu fatto irruzione nella sua stanza, Ali Pascià rispose con le armi e fu ucciso nello scontro che ne seguì; la sua testa fu portata a Costantinopoli il 24 febbraio. L'assedio aveva portato alla luce anche la frattura interna al comando ottomano: quando la rivolta di Morea divenne più pericolosa della questione Tepedelenli, Seyyid Ali Pascià fu nominato seraschiere autonomo di Morea; Hurşid Pascià, che non lo gradiva, respinse le sue richieste di aiuto e cercò perfino di farlo apparire fallito agli occhi dello Stato. Alla fine dell'anno in cui Ali Pascià fu tolto di mezzo cadde Nauplia, la più forte fortezza della Morea.", "c7a915be"]},
"OLAYLAR_0073_IRAN_YANYA:1823-07-28:0":{"b": ["Trattato di Erzurum — ritiro delle forze persiane in sessanta giorni", "166373c3"], "d": ["La guerra, durata due anni, terminò con il trattato di pace firmato a Erzurum. In base al trattato le forze persiane dovevano ritirarsi entro sessanta giorni dai territori occupati. Il trattato non tracciò un nuovo confine, ripristinò la situazione prebellica; le controversie di confine tra i due Stati sarebbero degenerate di nuovo in scontri nel 1833-1842 e sarebbero state regolate solo nel 1847 con un secondo trattato, firmato ancora a Erzurum. La chiusura del fronte orientale era la condizione preliminare perché l'impero potesse dedicare tutto il proprio peso alla rivolta greca.", "7c54983b"]},
"OLAYLAR_2S1019:0330-05-11:0":{"b": ["Costantinopoli fu inaugurata come capitale bizantina (Impero romano d'Oriente)", "9d155dd6"], "d": ["Bisanzio, rifondata da Costantino, fu inaugurata con cerimonie durate giorni come nuova capitale dell'impero. Nell'atlante la voce bizantina (romana d'Oriente) a Istanbul comincia da questo giorno.", "c4468b48"]},
"OLAYLAR_2S1019:0969-07-06:0":{"b": ["I Fatimidi presero l'Egitto: Jawhar al-Siqilli entrò a Fustat, furono poste le basi del Cairo", "500aef7a"], "d": ["Il comandante fatimide Jawhar al-Siqilli pose fine al dominio ikhshidide in Egitto, entrò a Fustat e fece costruire a nord, a Manakh, il palazzo e le mura della nuova capitale, il Cairo.", "d9599f90"]},
"OLAYLAR_2S1019:0990-03-31:0":{"b": ["Gli Uqaylidi presero Mosul: fondazione della dinastia uqaylide di Mosul", "49eb93a6"], "d": ["Abu al-Dhawwad, uccisi Abu Tahir Ibrahim e suo figlio, prese Mosul; in città fu fondata la dinastia uqaylide, dipendente dai Buyidi.", "affdc0ec"]},
"OLAYLAR_2S1019:1084-12-12:0":{"b": ["Süleyman Shah, figlio di Qutalmish, prese Antiochia a Bisanzio", "17d1c6f0"], "d": ["Antiochia, rimasta per più di un secolo in mano bizantina, fu presa dal sovrano dei Selgiuchidi d'Anatolia Süleyman Shah; la cittadella che resisteva si arrese il 12 gennaio 1085.", "a6f1f783"]},
"OLAYLAR_2S1019:1098-06-03:0":{"b": ["I Crociati presero Antiochia: fu fondato il Principato di Antiochia", "c9f47942"], "d": ["Antiochia, che aveva resistito a un lungo assedio, cadde in mano ai Crociati per il tradimento di Firuz, comandante di Yaghi-Siyan. Il Principato di Antiochia costituito comprese anche Alessandretta.", "f6409190"]},
"OLAYLAR_2S1019:1207-03-05:0":{"b": ["Ghiyath al-Din Kaykhusraw conquistò Adalia: i Selgiuchidi raggiunsero il Mediterraneo", "9812e629"], "d": ["Adalia, passata dopo la presa di Costantinopoli da parte dei Latini nelle mani dell'italiano Aldobrandini, fu presa dal sultano dei Selgiuchidi d'Anatolia Ghiyath al-Din Kaykhusraw I, con il sostegno dei Greci scontenti dell'amministrazione latina.", "9d3888e0"]},
"OLAYLAR_2S1019:1216-01-22:0":{"b": ["Izz al-Din Kaykaus riprese Adalia ai ciprioti", "ec2446f9"], "d": ["Izz al-Din Kaykaus I riconquistò Adalia, perduta nel 1212 per una rivolta sostenuta dal re di Cipro, e ne riaffidò il governatorato a Mubariz al-Din Ertokush.", "62389ac4"]},
"OLAYLAR_2S1019:1268-03-08:0":{"b": ["Baybars prese Giaffa ai Crociati: terminò il dominio del Regno di Gerusalemme a Giaffa", "c7629d70"], "d": ["Il sultano mamelucco Baybars I pose fine al dominio crociato a Giaffa e ne fece distruggere la città; inviò il legno e il marmo della cittadella per la costruzione della sua moschea al Cairo.", "32ed8c27"]},
"OLAYLAR_2S1019:1268-05-18:0":{"b": ["Baybars prese Antiochia: fine del Principato di Antiochia", "da2b511a"], "d": ["L'esercito mamelucco con un assalto generale superò le mura di Antiochia; il principato crociato di 170 anni terminò e anche Alessandretta fu annessa di nuovo alle terre dell'Islam.", "7f091a6b"]},
"OLAYLAR_2S1019:1328-11-05:0":{"b": ["I Karamanidi ripresero Konya agli Ilkhanidi", "057ec073"], "d": ["Dopo la fuga in Egitto del governatore ilkhanide d'Anatolia Demirtash, Konya passò di nuovo ai Karamanidi. La città sarebbe passata nel 1350 a Eretna.", "c2d583f3"]},
"OLAYLAR_2S1019:1344-03-26:0":{"b": ["Il re di Castiglia Alfonso XI prende Algeciras: dopo venti mesi di assedio finisce il dominio merinide", "5de2a877"], "d": ["Dopo l'assedio di circa venti mesi del re di Castiglia Alfonso XI, al termine dei negoziati iniziati il 21 marzo 1344 il sovrano merinide Abu'l-Hasan comunicò ai musulmani di lasciare la città; il 26 marzo fu evacuata Villa Nueva, il giorno dopo Villa Vieja, e i Castigliani ne presero possesso. Alfonso XI entrò solennemente in città il 28 marzo 1344 (Domenica delle Palme). Algeciras rimase a Castiglia fino al 1369.", "ceda27c4"]},
"OLAYLAR_2S1019:1345-01-01:0":{"b": ["Stefano Dušan prese Serre a Bisanzio", "2cc79d36"], "d": ["Il re serbo Stefano Dušan, approfittando della guerra civile bizantina, prese Serre e ne fece la capitale dell'Impero serbo.", "24066996"]},
"OLAYLAR_2S1019:1375-01-01:0":{"b": ["La contea di Feldkirch venduta all'Austria asburgica", "fe4a0306"], "d": ["Rudolf, ultimo conte del ramo Montfort-Feldkirch, vendette nel 1375 tutti i suoi possedimenti agli Asburgo, duchi d'Austria; il passaggio effettivo si compì con la sua morte (1390). Feldkirch fu la prima grande parte del Vorarlberg a passare in mano asburgica.", "6f5d639e"]},
"OLAYLAR_2S1019:1389-07-01:0":{"b": ["Balçık e la costa della Dobrugia passano sotto l'amministrazione ottomana", "dfd348b9"], "d": ["Dopo la vittoria di Kosovo, Balçık, sulla costa della Dobrugia, passò sotto l'amministrazione ottomana. Subito dopo il voivoda di Valacchia Mircea avrebbe occupato la regione, e il dominio ottomano sarebbe stato ristabilito nel 1393.", "e99a023b"]},
"OLAYLAR_2S1019:1392-10-26:0":{"b": ["I Sayyid di Mar'aş si arrendono a Tamerlano a Mâhâneser — il Mazandaran passa ai Timuridi", "125dbed8"], "d": ["Entrato nel Mazandaran durante la campagna quinquennale, Tamerlano strinse i Mar'aşî, che gli si erano opposti a Karatogân, nella fortezza di Mâhâneser e la ricevette in resa. A Sârî e Âmul avvenne un grande massacro; Sârî fu data a İskender Şeyhî, figlio di Kiyâ Efrâsiyâb.", "0352c0d3"]},
"OLAYLAR_2S1019:1412-01-01:0":{"b": ["Sebenico torna sotto l'amministrazione della Repubblica di Venezia", "9b7998bf"], "d": ["Dopo che Ladislao di Napoli ebbe venduto a Venezia nel 1409 i suoi diritti sulla Dalmazia, Sebenico, che aveva resistito, tornò nel 1412 sotto l'amministrazione veneziana. La città rimase possedimento dalmata di Venezia fino alla caduta della Repubblica nel 1797.", "ed5b7778"]},
"OLAYLAR_2S1019:1417-02-18:0":{"b": ["Campagna di Çelebi Mehmed contro i Candaroğulları: Çankırı assegnata a Kasım Bey, sotto protezione ottomana", "da03b919"], "d": ["Marciando contro Isfendiyar Bey dei Candaroğulları, che aveva aiutato lo sceicco Bedreddin a passare in Valacchia, Çelebi Mehmed avanzò fino a Kastamonu e assediò Sinope, dove Isfendiyar si era ritirato. Isfendiyar riconobbe la sovranità ottomana; fissato il confine sul monte Ilgaz, Çankırı e i suoi dintorni furono assegnati al figlio Kasım Bey, rifugiatosi presso gli Ottomani.", "f88b8d5e"]},
"OLAYLAR_2S1019:1439-08-27:0":{"b": ["Con la presa di Smederevo anche Hisarcık (Grocka) passa agli Ottomani", "ab724ec9"], "d": ["Smederevo fu presa dopo tre mesi di assedio. Hisarcık (Grocka), a 17 km da Smederevo, nell'atlante segue la sorte del suo centro maggiore, Smederevo, e passa nello stesso giorno dal Dispotato serbo agli Ottomani (sarà restituita nel 1444).", "81989831"]},
"OLAYLAR_2S1019:1451-01-01:0":{"b": ["La prima metà della contea di Bregenz venduta all'Austria asburgica", "3a9598db"], "d": ["Elisabeth di Hochberg, erede dei Montfort-Bregenz, vendette nel 1451 agli Asburgo la metà della contea di Bregenz; l'altra metà fu acquisita nel 1523. Bregenz divenne così parte del Vorarlberg asburgico.", "c02a452c"]},
"OLAYLAR_2S1019:1458-08-06:0":{"b": ["Con la resa di Gördüs (Corinto) anche Sicione passa agli Ottomani", "c7b0d22d"], "d": ["Nella campagna di Morea Maometto il Conquistatore prese pacificamente Gördüs (Corinto) dopo tre mesi di assedio. Sicione, a 17 km da Corinto, nell'atlante segue la sorte del suo centro maggiore, Gördüs, e passa agli Ottomani nello stesso giorno.", "42b1e20d"]},
"OLAYLAR_2S1019:1459-06-20:0":{"b": ["Con la resa di Smederevo anche Hisarcık (Grocka) passa agli Ottomani", "e3d76f5c"], "d": ["Helena, vedova di Lazar Branković, consegnò agli Ottomani la fortezza di Smederevo; il Dispotato serbo ebbe fine. Hisarcık (Grocka), che faceva capo a Smederevo come centro maggiore, passa agli Ottomani nello stesso giorno.", "13f15640"]},
"OLAYLAR_2S1019:1475-06-06:0":{"b": ["Resa di Caffa e vassallaggio del khan di Crimea — la costa della Circassia (Soči, Tuapse, Majkop) legata al Khanato di Crimea come area di protezione lasca", "e99eb8e8"], "d": ["Dopo un assedio di quattro giorni Caffa si arrese ad Ahmed Pascià e Mengli Giray accettò la sovranità del sultano ottomano. L'area di Soči, Tuapse e Majkop, patria delle tribù circasse che riconoscevano come signori i khan di Crimea, da questa data è rappresentata nell'atlante come legata al Khanato di Crimea da una protezione lasca.", "63b788a5"]},
"OLAYLAR_2S1019:1500-01-01:0":{"b": ["Mosca prende Brjansk al Granducato di Lituania", "fb1c3a61"], "d": ["Nella guerra moscovito-lituana del 1500-1503 l'esercito russo prese Brjansk e la città fu annessa allo Stato moscovita; la tregua del 1503 riconobbe questo guadagno.", "8e507991"]},
"OLAYLAR_2S1019:1500-04-12:0":{"b": ["Muore Leonhard, ultimo conte di Gorizia — Lienz e la Val Pusteria passano all'Austria asburgica (Tirolo)", "93331339"], "d": ["Leonhard, ultimo rappresentante dei conti di Gorizia (Görz), morì a Lienz il 12 aprile 1500. In base a un accordo successorio preso in precedenza, la contea anteriore, comprendente Lienz e la Val Pusteria, passò a Massimiliano I e fu annessa al Tirolo.", "996079fc"]},
"OLAYLAR_2S1019:1516-08-24:0":{"b": ["Bıyıklı Mehmed Pascià prende ai Safavidi Mosul, Sinjar e Imâdiye", "3039d6af"], "d": ["Dopo aver sconfitto Kara Han a Koçhisar, Bıyıklı Mehmed Pascià, mentre assediava Mardin, tolse ai Safavidi le fortezze circostanti: furono conquistate Mosul, Urfa, Birecik e Sinjar, e Imâdiye e gli altri signori curdi accettarono la sovranità ottomana. La fortezza di Mardin sarebbe stata invece ricevuta in resa dopo il ritorno del Pascià da Marj Dabiq.", "0ce2275b"]},
"OLAYLAR_2S1019:1523-06-06:0":{"b": ["Gustavo Vasa eletto re a Strängnäs — il Regno di Svezia esce dall'Unione di Kalmar", "a6e95f4c"], "d": ["Dopo il Bagno di sangue di Stoccolma (1520), Gustav Eriksson Vasa, sollevatosi contro il re di Danimarca Cristiano II, fu eletto re il 6 giugno 1523 dal Riksdag svedese riunito a Strängnäs nel maggio dello stesso anno. La Svezia e la Finlandia, ad essa legata, uscirono così definitivamente dall'Unione di Kalmar, in vigore dal 1397, e iniziò l'epoca Vasa del Regno di Svezia indipendente.", "64dcc4c4"]},
"OLAYLAR_2S1019:1526-12-05:0":{"b": ["Gli Stati di Slesia riconoscono Ferdinando I come re — la Slesia passa all'Austria asburgica", "a28e10c2"], "d": ["Gli Stati dell'Alta e Bassa Slesia, riuniti in assemblea generale, il 5 dicembre 1526 riconobbero come re Ferdinando d'Asburgo, eletto nell'ottobre 1526 alla corona di Boemia rimasta vacante per la morte di Luigi II a Mohács, e come regina la moglie Anna, a condizione della conferma dei loro privilegi. I ducati di Slesia entrarono così, insieme alla corona di Boemia, sotto l'amministrazione asburgica.", "bc2a3ff9"]},
"OLAYLAR_2S1019:1550-06-12:0":{"b": ["Il re di Svezia Gustavo Vasa fonda Helsinki", "43468b54"], "d": ["Nel 1550 il re di Svezia Gustavo Vasa fece fondare Helsinki alla foce del fiume Vantaa come nuova città commerciale che rivaleggiasse con Reval (Tallinn) nel commercio baltico. Nel 1640 la città fu trasferita nel sito attuale, verso il mare.", "eb67b9f0"]},
"OLAYLAR_2S1019:1633-01-01:0":{"b": ["L'imam Ya'rubide dell'Oman Nâsır b. Mürşid prende Julfar ai Portoghesi", "6ca9fb0c"], "d": ["I Portoghesi, che avevano resistito a Julfar anche dopo la caduta di Hormuz nel 1622, furono scacciati dalla regione con la conquista dell'imam Ya'rubide dell'Oman Nâsır b. Mürşid nel 1633.", "55e774dd"]},
"OLAYLAR_2S1019:1686-09-30:0":{"b": ["Perdita della fortezza di Sinj a favore di Venezia — entroterra dalmata", "3af8e103"], "d": ["Durante la guerra di Morea le forze veneziane nel 1686 presero agli Ottomani la fortezza di Sinj, nell'entroterra dalmata; la fortezza resistette anche all'assedio ottomano del 1715 e rimase a Venezia.", "9c5c08b5"]},
"OLAYLAR_2S1019:1687-09-06:0":{"b": ["Varadino e Bač passano al Regno d'Ungheria (Corona asburgica) — ritirata dalla Bačka dopo Harsány", "6bc2b1ac"], "d": ["L'esercito di Sarı Süleyman Pascià, in ritirata dopo la disfatta di Harsány, passò da Varadino il 1° settembre 1687 e lasciò la fortezza a Câfer Pascià; poco dopo Varadino e Bač, nella Bačka, caddero in mano alle forze asburgiche alleate. A Karlowitz, con il riconoscimento della Sava come confine, Varadino rimase dal lato austriaco.", "5ba42bd5"]},
"OLAYLAR_2S1019:1687-09-26:0":{"b": ["Osijek passa al Regno d'Ungheria (Corona asburgica) — inizia la perdita della Slavonia", "7af97ffe"], "d": ["Dopo la disfatta di Harsány la fortezza-ponte di Osijek sulla Drava passò il 26 settembre 1687 alle forze asburgiche. La presenza militare ottomana e la popolazione turca in Slavonia si ritirarono gradualmente tra il 1686 e il 1688; la regione passò sotto l'amministrazione asburgica.", "ae45a854"]},
"OLAYLAR_2S1019:1687-09-30:0":{"b": ["Perdita di Herceg Novi a favore di Venezia — imboccatura delle Bocche di Cattaro", "b88046d8"], "d": ["Durante la guerra di Morea la flotta veneziana e i suoi alleati nel 1687 assediarono e presero la fortezza di Herceg Novi, all'imboccatura delle Bocche di Cattaro; la città rimase a Venezia fino alla caduta della Repubblica veneziana nel 1797.", "aae8f2d8"]},
"OLAYLAR_2S1019:1794-06-15:0":{"b": ["La Corsica annessa alla corona britannica — Regno anglo-corso", "10f18bde"], "d": ["Paoli, insorto contro la Francia rivoluzionaria, con l'appoggio della flotta britannica liberò l'isola dalle guarnigioni francesi; la consulta riunita a Corte adottò una costituzione che univa la Corsica al re d'Inghilterra. L'isola rimase per due anni Regno anglo-corso, sotto l'amministrazione del viceré britannico Gilbert Elliot.", "bdf0e618"]},
"OLAYLAR_2S1019:1796-10-01:0":{"b": ["Evacuazione della Corsica da parte degli Inglesi — l'isola torna alla Francia", "c9f986fe"], "d": ["Messa in difficoltà nel Mediterraneo dalle vittorie di Bonaparte in Italia e dal passaggio della Spagna dalla parte della Francia, l'Inghilterra evacuò la Corsica. Il Regno anglo-corso finì e l'isola fu di nuovo annessa alla Francia.", "0338523e"]},
"OLAYLAR_2S1019:1878-09-18:0":{"b": ["L'esercito austro-ungarico spezza la resistenza e prende Bihać", "ffec53e0"], "d": ["L'Austria-Ungheria, che con il Trattato di Berlino aveva ottenuto il diritto di occupare la Bosnia-Erzegovina, incontrò a Bihać la resistenza dei musulmani locali. Le forze al comando del generale Wilhelm von Reinländer presero la città il 18 settembre 1878; con la stessa operazione anche la guarnigione di Ostrovica, nella valle dell'Una, uscì dalle mani ottomane.", "207d2a2b"]},
"OLAYLAR_2S1019:1903-03-15:0":{"b": ["Gli Inglesi occupano Sokoto — il Califfato di Sokoto perde la capitale", "e744f986"], "d": ["Dopo che il Regno Unito ebbe dichiarato colonia la Nigeria settentrionale nel 1900, il suo governatore Lugard, preso uno dopo l'altro gli emirati, inflisse una dura sconfitta all'esercito di Sokoto e il 15 marzo 1903 occupò la capitale. Con l'uccisione a Burmi, a luglio, del califfo fuggiasco Tâhir, il dominio politico del califfato ebbe fine.", "fe9507bb"]},
"OLAYLAR_2S1019:1906-04-13:0":{"b": ["Ibn Sa'ud sconfigge l'emiro rashidide — il Qasim passa dall'Emirato di Shammar ai Sauditi", "a32201dd"], "d": ["Abdülazîz b. Suûd, che aveva ripreso Riyad nel 1902, il 13 aprile 1906 sconfisse e uccise l'emiro rashidide Abdülazîz b. Müt'ib. Dopo questa battaglia si impadronì della regione del Qasim (Buraydah, Unayzah); da allora i Rashidi regnarono soltanto su Ha'il e dintorni.", "c99fc129"]},
"OLAYLAR_2S1019:1915-06-10:0":{"b": ["L'isola di Kamaran occupata dagli Inglesi", "c514bb66"], "d": ["L'isola di Kamaran, sulla costa yemenita del Mar Rosso, fu occupata dagli Inglesi nel 1915 durante la prima guerra mondiale e iniziò a essere amministrata da Aden.", "33e76176"]},
"OLAYLAR_2S1019:1918-09-21:0":{"b": ["Occupazione britannica di Nablus — crollo del fronte di Palestina", "b5e85950"], "d": ["Nel settembre 1918 la grande offensiva di Allenby sul fronte palestinese disperse la 7ª e l'8ª armata ottomana; Nablus cadde in mano agli Inglesi e nella città finì il dominio ottomano di quattro secoli. La città rimase sotto amministrazione militare britannica fino al 1920.", "d3195be1"]},
"OLAYLAR_2S1019:1918-11-08:0":{"b": ["Ingresso degli Inglesi a Mosul — occupazione del vilayet di Mosul in violazione dell'armistizio", "ed5e8e33"], "d": ["Quando fu firmato l'armistizio di Mudros, Mosul era in mano alle forze turche. Gli Inglesi, appellandosi all'articolo 7 dell'armistizio, entrarono in città l'8 (o il 10) novembre 1918 e il 15 novembre le unità turche furono costrette a ritirarsi dal vilayet. La questione di Mosul non fu risolta nemmeno a Losanna e fu rinviata al Trattato di Ankara del 1926.", "168f5310"]},
"OLAYLAR_2S1114D5:1923-07-24:0":{"b": ["Trattato di Losanna — Patmo lasciata all'Italia, confermata la sovranità greca sulle isole dell'Egeo", "185960b3"], "d": ["Con l'articolo 15 di Losanna la Turchia rinunciò in favore dell'Italia a tutti i diritti e titoli sul Dodecaneso, compresa Patmo; le isole erano di fatto sotto occupazione italiana dal 1912. L'articolo 12 confermò invece la sovranità greca su Lemno, Samotracia, Lesbo, Chio, Samo e Ikaria. Agios Efstratios e Furni erano in mano greca dal 1912 e rimasero alla Grecia anche dopo Losanna; i nomi di queste due isole non sono citati nell'articolo 12 di Losanna.", "73a0b71c"]},
"OLAYLAR_2S1114D5:1935-12-25:0":{"b": ["Legge di Tunceli — al posto del sancak di Dersim viene istituito il vilayet di Tunceli (centro Kalan)", "1ae9ad50"], "d": ["Con la legge n. 2885 fu decisa l'istituzione di un nuovo vilayet chiamato Tunceli nella regione di Dersim; il centro amministrativo del vilayet fu la località di Kalan, che in seguito prese il nome di Tunceli. La regione rimase all'interno della Repubblica di Turchia; ciò che cambiò furono lo status amministrativo e il nome.", "7970d4ac"]},
"OLAYLAR_2S1114D5:1956-03-02:0":{"b": ["Indipendenza del Marocco: finisce il protettorato francese, Salé e Rabat restano al Regno del Marocco", "a62a3fdb"], "d": ["Con il trattato di indipendenza firmato il 2 marzo 1956 finì il protettorato francese in vigore dal 1912; Salé e Rabat divennero territorio del Regno del Marocco indipendente. La Spagna riconobbe l'indipendenza del Marocco il 5 aprile 1956.", "e888afb6"]},
"OLAYLAR_2S1114D5:1980-07-30:0":{"b": ["Le Nuove Ebridi diventano indipendenti: nasce la Repubblica di Vanuatu", "cc93330f"], "d": ["Il Condominio delle Nuove Ebridi, sotto sovranità congiunta di Francia e Regno Unito, il 30 luglio 1980 divenne indipendente con il nome di Vanuatu. La capitale Port Vila, sull'isola di Efate, e la località di Teouma passarono dall'amministrazione del condominio a Vanuatu.", "29b000d6"]},
"OLAYLAR_2S1114D5:1994-03-01:0":{"b": ["Il Sudafrica cede Walvis Bay alla Namibia", "96bb0184"], "d": ["Il 1° marzo 1994 la Repubblica del Sudafrica cedette al governo namibiano il porto di Walvis Bay e le dodici isole al largo; il controllo sudafricano, durato ottantaquattro anni, ebbe fine.", "fdd93117"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Legame di Jaghbub, centro desertico dei Senussi, con l'ordinamento ottomano — firmano di esenzione di Abdülmecid", "039fce6d"], "d": ["Muhammad b. Ali al-Sanusi, rimasto a lungo alla Mecca, dopo il ritorno in Tripolitania si stabilì nell'oasi di Jaghbub al confine egiziano e vi fece costruire su una roccia dominante una grande zâviye; il luogo, composto di poche baracche, si trasformò presto in una città. Nel 1856, con il firmano del sultano Abdülmecid, i beni appartenenti ai membri della confraternita furono esentati dalle imposte e ai murid fu data l'autorità di raccogliere la zakat. Questo firmano fece dell'oasi, sulla via carovaniera che collega l'Africa occidentale e il Sudan al Cairo, una parte dell'ordinamento finanziario e amministrativo ottomano e rafforzò Jaghbub come centro commerciale. La fedeltà della popolazione della regione al califfo è confermata anche dal resoconto di viaggio del miralay Sadık el-Müeyyed, che visitò il luogo nel 1884 e nel 1893.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Inizio dello scavo del Canale di Suez e fondazione di Port Said", "cef0be8d"], "d": ["I lavori di scavo del progetto Lesseps, approvato dalla Sublime Porta il 5 gennaio 1856, iniziarono il 25 aprile 1859; il canale sarebbe stato completato dieci anni dopo, il 16 novembre 1869. All'estremità mediterranea dello scavo, sul cordone costiero tra il lago Menzaleh e il mare, il villaggio di baracche di cinque case costruito per gli operai costituì il nucleo di Port Said. Alla città fu dato nel 1860 dai dirigenti della società del canale questo nome, che significa 'porto di Said', in omaggio all'allora governatore d'Egitto Said Pascià. Così sulla mappa ottomana nacque un nuovo porto su una striscia costiera in cui non c'era stato prima alcun insediamento.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Visita del sultano Abdülaziz in Egitto e fondazione di Ismailia sull'istmo di Suez", "bcfacf38"], "d": ["Il sultano Abdülaziz, su incoraggiamento del gran visir Yûsuf Kâmil Pascià, si recò in Egitto il 3 aprile 1863 e fu accolto con grandi manifestazioni; lo scopo era rafforzare il legame con il centro della provincia che dalla rivolta di Mehmed Ali Pascià di Kavala aveva cominciato di fatto a diventare uno Stato separato. Nello stesso anno sull'istmo, sulle colline di Tilâlülcisr sulla riva del lago Timsah, fu stabilito il centro amministrativo della società del canale: prima il villaggio di Karyetüttimsah per gli ingegneri, poi quello di Karyetülarab per gli operai. Poiché il khedivé İsmâil Pascià si interessava da vicino al canale d'acqua dolce e fece costruire per sé un padiglione su questa collina, l'insediamento fu detto con il suo nome Ismailia. La fondazione della città è datata al 1863; il giorno esatto non è noto.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Governatorato di Midhat Pascià a Baghdad e insediamento tribale — fondazione di Ramadi e Nasiriyya", "0fa98f06"], "d": ["Midhat Pascià, tolto dalla presidenza dello Şûrâ-yı Devlet e allontanato da Istanbul, governò la provincia di Baghdad, comprendente anche Mosul e Bassora, tra il 1869 e il 1872 con ampi poteri, avendo anche il comando della Sesta Armata. Applicandovi il Codice Fondiario (Arazi Kanunnâmesi) e la nuova legge sulle province, distribuì le terre con il tapu, legando le tribù nomadi all'ordinamento sedentario e all'autorità dello Stato. Come prodotto di questa politica di insediamento nel 1869 furono fondate Ramadi sull'Eufrate per la tribù dei Dulaym e, nel sud, Nasiriyya per mano del mutasarrıf dei Muntafiq Nâsır Pascià es-Sa'dûn; entrambe nacquero in punti in cui fino ad allora non c'erano insediamenti ed entrarono sulla mappa per la prima volta in questa data.", "7babb36f"]},
"OLAYLAR_ALM1115B:1024-09-08:0":{"b": ["Corrado II eletto re di Germania e incoronato a Magonza — inizia la dinastia salica", "c88123e8"], "d": ["Dopo la morte di Enrico II, i principi tedeschi si riunirono il 4 settembre 1024 a Kamba, sulla riva destra del Reno; l'elezione fu diretta dall'arcivescovo di Magonza Aribo. Corrado il Vecchio prevalse sul giovane cugino Corrado e, nella festa della Natività di Maria (8 settembre), fu incoronato re a Magonza da Aribo.", "1d5ce932"]},
"OLAYLAR_ALM1115B:1039-06-04:0":{"b": ["Muore a Utrecht l'imperatore Corrado II", "f967406b"], "d": ["Corrado II, primo imperatore della dinastia salica, morì a Utrecht il 4 giugno 1039 dopo una breve e dolorosa malattia.", "6af4f169"]},
"OLAYLAR_ALM1115B:1122-09-23:0":{"b": ["Concordato di Worms — termina la lotta per le investiture", "8073e4a0"], "d": ["Per mediazione della legazione papale, la pace tra l'imperatore Enrico V e papa Callisto II fu proclamata a Worms il 23 settembre 1122 (a Lobwiesen, subito presso la città). Enrico rinunciò all'investitura con anello e pastorale e accettò l'elezione canonica di vescovi e abati.", "a915c2e7"]},
"OLAYLAR_ALM1115B:1125-05-23:0":{"b": ["Muore a Utrecht l'imperatore Enrico V", "790cadc4"], "d": ["L'imperatore Enrico V morì a Utrecht il 23 maggio 1125; è ricordato come l'imperatore del Concordato di Worms (1122).", "8402ca28"]},
"OLAYLAR_ALM1115B:1152-03-05:0":{"b": ["Federico I Barbarossa eletto re di Germania a Francoforte", "b91f29a3"], "d": ["I principi elevarono Federico al trono a Francoforte il 5 marzo 1152; fu incoronato ad Aquisgrana il 9 marzo. Iniziò così l'epoca di Barbarossa della dinastia degli Hohenstaufen.", "26fcdb8c"]},
"OLAYLAR_ALM1115B:1156-09-17:0":{"b": ["Privilegium Minus — l'Austria diventa ducato, la Baviera è data a Enrico il Leone", "a64c125b"], "d": ["Per sentenza dei principi a Ratisbona l'Austria fu elevata a ducato e a Enrico Jasomirgott furono concessi diritti speciali; nello stesso accordo Enrico restituì la Baviera all'imperatore, il quale la diede in feudo a Enrico il Leone.", "fe899d87"]},
"OLAYLAR_ALM1115B:1218-01-01:0":{"b": ["Con l'estinzione dei Zähringen Berna diventa città imperiale libera", "1473c219"], "d": ["Quando nel 1218 si estinse la dinastia degli Zähringen, Berna divenne città libera dipendente direttamente dall'Impero; nel 1353 entrò nella Confederazione svizzera come ottavo membro.", "8bbdceab"]},
"OLAYLAR_ALM1115B:1264-01-01:0":{"b": ["Langraviato d'Assia: Enrico I di Brabante diventa il primo langravio d'Assia, pace con Meißen nel 1264", "57067f04"], "d": ["La storia dell'Assia come paese indipendente inizia con Enrico I (il «Fanciullo»); la pace con Meißen fu conclusa nel 1264. Enrico fece costruire un castello a Kassel, che negli anni seguenti divenne la sua residenza abituale; nel 1292 fu elevato a principe dell'Impero (Reichsfürstenstand).", "43d237e5"]},
"OLAYLAR_ALM1115B:1358-12-01:0":{"b": ["La contea di Schwerin passa con un accordo al duca di Meclemburgo Alberto II", "013b6860"], "d": ["Alberto II, con un contratto del 1° dicembre 1358, ottenne la contea di Schwerin pagando 10.000 marchi d'argento al conte Nicolaus; da allora la città fu territorio del ducato di Meclemburgo (il suo consolidarsi come capitale avvenne invece nel XVI secolo).", "1d69a777"]},
"OLAYLAR_ALM1115B:1567-03-31:0":{"b": ["Muore a Kassel il langravio Filippo il «Magnanimo» — l'Assia è divisa tra i quattro figli", "c0cb27ed"], "d": ["Il langravio d'Assia Filippo I, uno dei capi politici della Riforma, morì a Kassel il 31 marzo 1567. Secondo il testamento del 1562 il paese fu spartito tra i quattro figli in Assia-Kassel (Guglielmo IV), Assia-Marburgo (Ludovico IV), Assia-Rheinfels (Filippo II) e Assia-Darmstadt (Giorgio); il Langraviato d'Assia unito ebbe così fine.", "288ab83b"]},
"OLAYLAR_ALM1115B:1637-03-10:0":{"b": ["Muore a Stettino Bogislao XIV, ultimo duca di Pomerania — si estingue la dinastia dei Grifoni", "ab96746a"], "d": ["Bogislao XIV, ultimo duca di Pomerania, morì a Stettino il 10 marzo 1637 e con lui si estinse la dinastia pomerana locale. La spartizione effettiva del ducato (Brandeburgo-Svezia) fu sancita dalla Pace di Vestfalia del 1648.", "2e5f6d25"]},
"OLAYLAR_ALM1115B:1646-01-01:0":{"b": ["Ferdinando III concede a Brema i privilegi di città imperiale libera", "174142ee"], "d": ["L'imperatore Ferdinando III nel 1646 riconobbe a Brema i privilegi di città imperiale libera; la Svezia vi si oppose e nel 1666 tentò di sottomettere la città con le armi, senza riuscirci. Quando l'elettore di Hannover ottenne l'arcivescovato (1720), riconobbe Brema come città libera.", "4a574693"]},
"OLAYLAR_ALM1115B:1810-01-01:0":{"b": ["Brema entra a far parte dell'Impero francese — diventa capoluogo del dipartimento delle Bocche del Weser", "d5d149ae"], "d": ["Brema fu occupata dai Francesi nel 1806 e dal 1810 al 1813 fu capoluogo del dipartimento delle Bocche del Weser (Bouches-du-Weser).", "0ac80a63"]},
"OLAYLAR_ALM1115B:1810-12-01:0":{"b": ["Napoleone annette Lubecca all'Impero francese", "1ca78afe"], "d": ["Dopo la resa di Blücher presso Lubecca nel novembre 1806, la città era stata saccheggiata dai Francesi; nel dicembre 1810 Napoleone la annesse al proprio impero. Fino a quella data Lubecca era stata città imperiale libera dal 1226.", "b7bf744b"]},
"OLAYLAR_ALM1115B:1813-01-01:0":{"b": ["Lubecca si ribella al dominio francese e riottiene lo status di città libera", "84e70d49"], "d": ["Lubecca, sollevatasi nel 1813 contro il dominio francese, nel 1815 fu riconosciuta dal Congresso di Vienna come città libera e anseatica della Confederazione germanica.", "f5432e01"]},
"OLAYLAR_ALM1115B:1813-01-01:1":{"b": ["Finisce il dominio francese — Brema riottiene lo status di città libera", "4afa71be"], "d": ["La permanenza di Brema sotto amministrazione francese come capoluogo del dipartimento delle Bocche del Weser terminò nel 1813; la città fu resa indipendente nel 1815 dal Congresso di Vienna ed entrò nella Confederazione germanica.", "b4e1a2ef"]},
"OLAYLAR_ALM1115B:1815-01-01:0":{"b": ["Il ducato di Meclemburgo-Schwerin assume il titolo di granducato", "3f5d05eb"], "d": ["Il duca di Meclemburgo-Schwerin Federico Francesco I nel 1815 assunse il titolo di granducato (\"großherzogliche Würde\"); la scheda del ducato di Meclemburgo (1348-1815) termina a questo punto, e il paese prosegue come granducato all'interno della Confederazione germanica.", "bfbe2246"]},
"OLAYLAR_ALM1115B:1937-04-01:0":{"b": ["Entra in vigore la Legge della Grande Amburgo — termina lo status di Stato indipendente di Lubecca", "6df2f92a"], "d": ["La Legge della Grande Amburgo, emanata il 26 gennaio 1937, entrò in vigore il 1° aprile 1937; Lubecca perse un'autonomia di oltre 700 anni e fu unita alla provincia prussiana dello Schleswig-Holstein, mentre i confini di Amburgo si ampliarono.", "b96594d2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0014-01-01:0":{"b": ["Rezia e Norico furono annesse a Roma: Tiberio e Druso presero il territorio oltre le Alpi", "be6f2a15"], "d": ["Nel 15 a.C. Tiberio e Druso sconfissero le tribù alpine e completarono la Rezia (e l'annessione del Norico); la riva superiore del Danubio divenne il confine romano.", "b564c899"]},
"OLAYLAR_ANTIK_AKDENIZ:-0024-01-01:0":{"b": ["Con la morte di Aminta la Galazia divenne provincia romana", "e4250ad7"], "d": ["Quando il re dei Galati Aminta, nominato da Antonio, fu ucciso in Cilicia (25 a.C.), Augusto trasformò la Galazia in provincia romana unendola a Pisidia e Licaonia. La capitale fu Ancira (Ankara); l'iscrizione delle Res Gestae di Augusto (Monumentum Ancyranum) fu scritta qui.", "d9e5074f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0026-01-16:0":{"b": ["Ottaviano assunse il titolo di «Augusto»: iniziò il Principato (periodo imperiale)", "310297b6"], "d": ["Il 16 gennaio del 27 il Senato conferì a Ottaviano il titolo di Augusto; Ottaviano ottenne a lungo termine il comando (imperium) di gran parte delle province. Questa data è considerata l'inizio dell'Impero romano.", "6a533271"]},
"OLAYLAR_ANTIK_AKDENIZ:-0032-01-01:0":{"b": ["Bocco II morì; la Mauretania passò sotto il controllo di Ottaviano", "414fa36c"], "d": ["Quando Bocco II morì senza figli nel 33, la Mauretania entrò sotto il dominio romano per eredità di Ottaviano per testamento; rimase per un certo tempo sotto amministrazione diretta romana e nel 25 fu data a Giuba II.", "ab445b2d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0035-01-01:0":{"b": ["Antonio fece Archelao re di Cappadocia", "1e83e691"], "d": ["Antonio, riordinando l'Oriente, diede il trono di Cappadocia ad Archelao; Archelao regnò fino a quando nel 17 d.C. fu richiamato a Roma da Tiberio. La Cappadocia divenne provincia romana nel 17 d.C. (evento che nella cronologia ha una voce a parte).", "cdb79213"]},
"OLAYLAR_ANTIK_AKDENIZ:-0041-01-01:0":{"b": ["Filippi: Ottaviano e Antonio sconfissero Bruto e Cassio", "4386016f"], "d": ["Nell'ottobre del 42 presso Filippi si svolsero due battaglie distinte; Cassio e Bruto si uccisero e la forza repubblicana scomparve. I triumviri si spartirono il mondo romano.", "ee38e78c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:0":{"b": ["Giulio Cesare fece rifondare Corinto come colonia romana", "283a5daa"], "d": ["Poco prima dell'assassinio di Cesare a Corinto furono insediati coloni cittadini romani (in gran parte liberti); la città divenne uno dei centri importanti della provincia romana d'Acaia. La decisione della rifondazione è datata al 44 a.C., l'insediamento al 44/43 a.C.", "237b35af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-01-01:1":{"b": ["Burebista fu vittima di un complotto: il regno dei Daci si frantumò", "9b9edb14"], "d": ["Strabone scrive che Burebista fu ucciso con un colpo di mano interno prima della morte di Cesare e che il regno fu diviso in cinque e poi in quattro parti. L'unione dacica non fu ricostituita fino a Decebalo (87 d.C.).", "eaa97397"]},
"OLAYLAR_ANTIK_AKDENIZ:-0043-03-15:0":{"b": ["Cesare fu ucciso in Senato alle Idi di Marzo (15 marzo)", "18649074"], "d": ["Cesare, proclamato dittatore perpetuo, il 15 marzo del 44 fu pugnalato da un gruppo di senatori durante una seduta del Senato nel Teatro di Pompeo. La sua morte preparò il terreno a nuove guerre civili e al potere di Augusto.", "4180e38f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0044-03-17:0":{"b": ["Munda: Cesare sconfisse i figli di Pompeo", "e1e93362"], "d": ["Il 17 marzo del 45 a Munda Cesare sconfisse l'esercito di Gneo Pompeo e Sesto Pompeo; l'Hispania rimase a Cesare. È l'ultima grande battaglia della guerra civile.", "67dd7b63"]},
"OLAYLAR_ANTIK_AKDENIZ:-0045-01-01:0":{"b": ["Tapso: Cesare sconfisse Giuba I; la Numidia orientale divenne la provincia di Africa Nova", "77b28c50"], "d": ["Cesare nella primavera del 46 a Tapso sbaragliò l'esercito di Scipione e Giuba I; Giuba si uccise. La parte orientale della Numidia divenne la provincia di Africa Nova governata da Sallustio, la parte occidentale fu data a Bocco e Sittio.", "a92567de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0046-05-21:0":{"b": ["Zela: Cesare sconfisse Farnace II («veni vidi vici»)", "11bf082a"], "d": ["Farnace II, figlio di Mitridate, approfittando della guerra civile tentò di riprendere il Ponto; Cesare nel 47 lo sconfisse a Zela e riordinò il Ponto sotto il controllo romano. Farnace fuggì nel Bosforo e vi morì.", "8dc5a21a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0047-01-01:0":{"b": ["Farsalo: Cesare sconfisse Pompeo", "e821abe8"], "d": ["Cesare, dopo la ritirata a Durazzo, sbaragliò a Farsalo il più numeroso esercito di Pompeo. Pompeo fuggì in Egitto e fu ucciso; le province orientali si aprirono a Cesare.", "c606b7e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0051-01-01:0":{"b": ["Alesia: Cesare assediò e sconfisse Vercingetorige, la resistenza della Gallia fu spezzata", "d57cab9f"], "d": ["Nel 52 a.C. la rivolta gallica guidata dall'arverno Vercingetorige fu repressa con l'assedio di Alesia da parte di Cesare e la difesa della linea d'assedio; Vercingetorige si arrese. La Gallia entrò completamente sotto il controllo romano l'anno seguente.", "9e045798"]},
"OLAYLAR_ANTIK_AKDENIZ:-0057-01-01:0":{"b": ["Iniziò la campagna di Gallia di Cesare: gli Elvezi furono sconfitti", "1e594bb3"], "d": ["Nel 58 a.C. Cesare, governatore della Gallia Cisalpina e Transalpina, fermò la migrazione degli Elvezi presso Bibracte; poi sconfisse i Germani di Ariovisto. La campagna sarebbe durata otto anni e avrebbe annesso la Gallia a Roma.", "b0789047"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:0":{"b": ["Mitridate VI morì a Panticapeo; il Bosforo restò a Farnace", "0831b871"], "d": ["Mitridate, fuggito da Pompeo, per la rivolta del figlio Farnace si uccise nella fortezza di Panticapeo (63). Farnace consegnò il Bosforo a Pompeo e fu riconosciuto come re amico di Roma.", "13030863"]},
"OLAYLAR_ANTIK_AKDENIZ:-0062-01-01:1":{"b": ["Pompeo unì Bitinia e parte occidentale del Ponto e fondò la provincia di Bitinia e Ponto", "b2865ea8"], "d": ["Nel riordinamento orientale (65-63) Pompeo unì la Bitinia con la metà occidentale del Ponto creando la provincia di Bitinia e Ponto; le zone interne del Ponto orientale furono date a principi locali.", "2c7b03c0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0063-01-01:0":{"b": ["Pompeo riconobbe la Commagene come amica e alleata di Roma", "a48ba55c"], "d": ["Nel riordinamento orientale Pompeo confermò il regno di Antioco I e una parte della regione di Seleucia (Zeugma), facendo della Commagene un cuscinetto alleato tra Roma e i Parti. Il regno fu annesso come provincia romana nel 17 d.C. e in modo definitivo nel 72 d.C. (eventi che nella cronologia hanno voci a parte).", "47b7f8de"]},
"OLAYLAR_ANTIK_AKDENIZ:-0065-01-01:0":{"b": ["Pompeo sconfisse Mitridate; il Ponto fu annesso a Roma", "8f3f50a6"], "d": ["Pompeo nel 66 sbaragliò di notte l'esercito di Mitridate nella piana del Lico; Mitridate fuggì dalla Colchide al Bosforo. Le città costiere del Ponto entrarono sotto il controllo romano e nel 63 fu costituita la provincia unita alla Bitinia.", "2e29932b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0069-01-01:0":{"b": ["Antioco I Theos salì al trono di Commagene", "b1680d3f"], "d": ["Il re di Commagene Antioco I fece costruire il tempio-tomba del Nemrut Dağı, che unisce le stirpi persiana e macedone. Il regno era un cuscinetto tra Roma e i Parti.", "c8db269f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:0":{"b": ["Cirene divenne provincia romana (Cirenaica)", "f9993ffb"], "d": ["Vent'anni dopo che Tolomeo Apione ebbe lasciato in eredità a Roma il proprio regno (96), Roma ordinò la Cirenaica in provincia; nel 67 fu unita a Creta.", "214aba0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0073-01-01:1":{"b": ["Nicomede IV lasciò in eredità il suo regno a Roma", "e29d9fbc"], "d": ["Con la morte di Nicomede IV (75/74) la Bitinia passò per testamento al Popolo Romano; Mitridate VI non lo accettò e iniziò la Terza Guerra Mitridatica. La Bitinia fu trasformata in provincia diretta di Roma.", "b6ff7464"]},
"OLAYLAR_ANTIK_AKDENIZ:-0081-01-01:0":{"b": ["Burebista unificò le tribù dacie e getiche", "3648f92e"], "d": ["Secondo Strabone Burebista riunì Geti e Daci in un unico regno e condusse campagne a sud del Danubio fino ai confini della Tracia e dell'Illiria. Il regno cominciò a rappresentare una minaccia per Roma lungo il Danubio.", "6eefe618"]},
"OLAYLAR_ANTIK_AKDENIZ:-0084-01-01:0":{"b": ["Pace di Dardano: Mitridate si ritirò da Asia e Bitinia", "535818ed"], "d": ["Con la Pace di Dardano conclusa con Silla Mitridate accettò di sgomberare tutte le conquiste (Asia, Bitinia, Cappadocia, Paflagonia) e di consegnare 70 navi e 2000-3000 talenti. Ma il prevalere a Roma dei nemici di Silla portò alla Seconda Guerra Mitridatica.", "baf04269"]},
"OLAYLAR_ANTIK_AKDENIZ:-0087-01-01:0":{"b": ["Mitridate invase la provincia d'Asia; Vespri efesini (massacro di 80.000 Romani)", "3986833b"], "d": ["All'inizio della Prima Guerra Mitridatica (89/88) Mitridate invase la Bitinia e la provincia d'Asia; per un suo ordine a Efeso i cittadini romani furono uccisi in massa. Anche Atene passò dalla parte del Ponto (Aristione).", "1dc4fbbb"]},
"OLAYLAR_ANTIK_AKDENIZ:-0089-01-01:0":{"b": ["Lex Iulia: Roma concesse la cittadinanza agli alleati italici (Guerra Sociale)", "f72ba27d"], "d": ["In seguito alla rivolta degli alleati italici di Roma (91-88), la Lex Iulia (90) e la Lex Plautia Papiria (89) concessero la cittadinanza romana agli alleati rimasti fedeli e a quelli che si erano arresi. Così la penisola italiana fino al Po divenne un'unica comunità di cittadini.", "8b973270"]},
"OLAYLAR_ANTIK_AKDENIZ:-0094-01-01:0":{"b": ["Silla pose Ariobarzane sul trono di Cappadocia", "8bdd078c"], "d": ["Contro il controllo della Cappadocia da parte di Mitridate VI tramite un re bambino, Roma fece proclamare re Ariobarzane durante il governatorato di Silla in Cilicia. Nel secolo seguente la Cappadocia fu il cuscinetto nelle contese tra Roma, Persia e Ponto.", "d8f615b3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0095-01-01:0":{"b": ["Tolomeo Apione lasciò in eredità Cirene a Roma", "5edef477"], "d": ["Tolomeo Apione, che governava Cirene, morendo senza figli lasciò il suo regno al Popolo Romano (96); il Senato lasciò le città libere e rinviò fino al 74 la trasformazione in provincia romana.", "14d9ff7c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0104-01-01:0":{"b": ["Bocco consegnò Giugurta a Roma; la parte occidentale della Numidia fu annessa alla Mauretania", "7619ad15"], "d": ["Bocco I, re di Mauretania e suocero di Giugurta, si riconciliò con Roma consegnando Giugurta a Silla; in cambio gli fu lasciata la parte occidentale della Numidia. Giugurta morì in prigione a Roma nel 104.", "0097a34f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0108-01-01:0":{"b": ["Pairisade V lasciò il regno a Mitridate VI: il Bosforo fu legato al Ponto", "835bbe74"], "d": ["Pairisade V, sotto la pressione scitica, con l'aiuto del comandante di Mitridate Diofanto cedette il regno a Mitridate; il Bosforo divenne così un'estensione settentrionale del Ponto. Il commercio del grano del Mar Nero passò in quella data al Ponto come risorsa di Mitridate.", "f9df6329"]},
"OLAYLAR_ANTIK_AKDENIZ:-0109-01-01:0":{"b": ["Il comandante di Mitridate Diofanto sconfisse gli Sciti in Crimea", "d8d48c68"], "d": ["Diofanto sconfisse l'esercito di Palaco, figlio del re scita Scilure, e prese i dintorni di Neapolis nella Taurica; il Bosforo e il Chersoneso furono legati al Ponto.", "aa4118e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0111-01-01:0":{"b": ["Giugurta prese Cirta: Roma intervenne negli affari della Numidia", "660eb34a"], "d": ["Nel 112 a.C. Giugurta assediò Cirta e uccise Aderbale; i mercanti italici uccisi in città spinsero Roma a dichiarare guerra a Giugurta. La guerra durò fino al 105.", "e2064bc2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0117-01-01:0":{"b": ["Fu fondata Narbo Martius: la Gallia meridionale (Gallia Transalpina) divenne provincia romana", "20c4bdfa"], "d": ["Roma, entrata in Gallia per la richiesta di aiuto di Massalia (125), con le vittorie di Aquae Sextiae (122) e sugli Allobrogi prese la valle del Rodano; nel 118 a.C. fu fondata in Gallia, come prima colonia romana, Narbo Martius. La regione divenne provincia di Gallia Transalpina.", "41f61541"]},
"OLAYLAR_ANTIK_AKDENIZ:-0119-01-01:0":{"b": ["Mitridate VI Eupatore salì al trono del Ponto", "c2d5fd41"], "d": ["Mitridate VI, salito al trono da bambino con la morte di Mitridate V (120/119), dopo alcuni anni di tutela fece del Ponto una potenza rivale di Roma intorno al Mar Nero.", "d5779c35"]},
"OLAYLAR_ANTIK_AKDENIZ:-0124-01-01:0":{"b": ["Su richiesta di Massalia Roma entrò in Gallia", "eaf7eb0a"], "d": ["Quando Massalia, sotto la pressione dei Salluvii e dei Liguri, chiese aiuto a Roma, questa nel 125 inviò un esercito nella Gallia meridionale. Questo intervento portò alla fondazione di Narbo Martius (118) e alla presa della Gallia Transalpina.", "2260c90e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0128-01-01:0":{"b": ["Aristonico fu sconfitto; con le terre di Pergamo fu costituita la provincia d'Asia", "7ccdc59e"], "d": ["Aristonico, che rivendicava il trono con il nome di Eumene III, fu sconfitto e catturato dall'esercito romano (129); con il riordinamento di Manio Aquilio l'antico regno di Pergamo divenne provincia d'Asia. Il sistema fiscale della provincia (publicani) fu per Roma una grande fonte di entrate.", "c32277b7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0132-01-01:0":{"b": ["Numanzia cadde: la Celtiberia fu annessa a Roma", "ced07244"], "d": ["Scipione Emiliano, dopo otto mesi di assedio, ottenne la resa di Numanzia per fame (133); la città fu distrutta. Le guerre celtiberiche terminarono e l'interno della Hispania Citerior fu annesso a Roma.", "27b1db44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:0":{"b": ["Guerra Achea: la Lega Achea fu sconfitta da Roma e sciolta", "e434cfe0"], "d": ["La Lega Achea, ribellatasi a Roma per una disputa di confine con Sparta, fu sconfitta nel 146 a Leucopetra; Corinto fu distrutta e la Lega fu di fatto sciolta, mentre una parte della Grecia passò sotto la sorveglianza della provincia di Macedonia.", "5fc3bb08"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:1":{"b": ["Terminò la Terza Guerra Punica: Cartagine fu distrutta, fu istituita la provincia d'Africa", "522515b4"], "d": ["Dopo un assedio di tre anni P. Cornelio Scipione Emiliano prese Cartagine nella primavera del 146; la città fu incendiata e distrutta e i territori annessi a Roma. L'entroterra di Cartagine divenne provincia d'Africa; la Numidia di Massinissa restò vicina a ovest.", "cbee045b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0145-01-01:2":{"b": ["La Macedonia divenne provincia romana", "dc6d2352"], "d": ["Dopo la repressione della rivolta di Andrisco (148) le quattro regioni della Macedonia furono unite in un'unica provincia romana (146); a sud della provincia anche il controllo della Grecia fu lasciato alla sorveglianza del governatore di Macedonia. La Via Egnazia fu costruita negli anni seguenti dall'Adriatico a Salonicco.", "ac02ecf5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0147-01-01:0":{"b": ["Rivolta di Andrisco: il regno di Macedonia fu per breve tempo ricostituito, represso da Metello", "0119ff73"], "d": ["Andrisco, che si diceva figlio di Perseo, nel 150/149 riunificò la Macedonia e sconfisse le prime forze romane; nel 148 Metello riprese la Macedonia. La rivolta fu la causa dell'annessione della Macedonia al governo diretto di Roma.", "b03ea4e9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0148-01-01:0":{"b": ["Roma dichiarò guerra a Cartagine: iniziò la Terza Guerra Punica", "2e34c235"], "d": ["La difesa di Cartagine contro gli attacchi di Massinissa fu considerata una violazione del trattato; Roma nel 149 dichiarò guerra e legò a sé Utica. La città di Cartagine resistette per tre anni sotto assedio.", "89432e4f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0149-01-01:0":{"b": ["Massinissa attaccò i territori di Cartagine: guerra tra Numidia e Cartagine", "b47559a5"], "d": ["Quando Massinissa si impadronì di territori di Cartagine (151/150), Cartagine gli dichiarò guerra e fu sconfitta da Massinissa; Roma lo considerò una violazione del trattato e nel 149 dichiarò guerra. Massinissa morì nel 148 a novant'anni.", "f6ed046f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:0":{"b": ["Roma ordinò a Rodi di ritirare i suoi governatori dalla Licia e dalla Caria; la Lega Licia (Patara) uscì dal dominio rodio", "6bbe2b54"], "d": ["Dopo la Terza Guerra Macedonica il Senato romano ordinò a Rodi di ritirare entro un certo giorno i suoi governatori dalla Licia e dalla Caria; Rodi, ritenendo queste perdite più lievi di una minaccia di guerra, accettò. La Lega Licia (con centro a Patara) uscì così dal dominio rodio e proseguì come Lega Licia sotto la protezione di Roma.", "8f86b52d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:1":{"b": ["L'Epiro fu saccheggiato da Roma: settanta città distrutte", "456fb461"], "d": ["Dopo la Terza Guerra Macedonica le città molosse dell'Epiro rimaste vicine a Perseo furono saccheggiate per ordine di Emilio Paolo e circa 150.000 persone furono ridotte in schiavitù. Nel secolo seguente l'Epiro rimase povero sotto il dominio romano.", "0504e2ee"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:2":{"b": ["La Macedonia fu divisa da Roma in quattro regioni autonome (merides)", "7a795ba0"], "d": ["Per decisione del Senato (167 a.C.) il regno di Macedonia fu diviso in quattro regioni con centro ad Anfipoli, Tessalonica (Salonicco), Pella e Pelagonia; tra le regioni furono vietati i matrimoni e l'acquisto di proprietà e fu limitato lo sfruttamento delle miniere.", "de7135d5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0166-01-01:3":{"b": ["Roma tolse Licia e Caria a Rodi; Delo fu dichiarata porto franco", "09c8143f"], "d": ["Nella Terza Guerra Macedonica fu punito il tentativo di mediazione di Rodi tra Roma e Perseo: il Senato tolse Licia e Caria a Rodi dichiarandole libere, diede Delo ad Atene trasformandola in porto franco. Le entrate commerciali di Rodi crollarono.", "9636f108"]},
"OLAYLAR_ANTIK_AKDENIZ:-0167-06-22:0":{"b": ["Pidna: Emilio Paolo sconfisse Perseo; il regno antigonide terminò", "a59c5270"], "d": ["Il 22 giugno del 168 a Pidna le legioni romane sconfissero la falange macedone ponendo fine alla Terza Guerra Macedonica; Perseo si arrese a Samotracia e fu portato a Roma al trionfo. La dinastia antigonide terminò.", "d363d3f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:0":{"b": ["Pace di Apamea: Eumene II ottenne per Pergamo il Chersoneso tracico, gran parte di Frigia, Lidia e Misia", "f25ed9af"], "d": ["Dopo la sconfitta di Magnesia Antioco III nel 188 firmò la pace con Roma: lasciò il nord dei Monti Tauro. Gran parte di questi territori fu data a Pergamo, alleato di Eumene II (Chersoneso tracico, Grande Frigia, Lidia, Misia, parte della Ionia).", "8ae36db5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0187-01-01:1":{"b": ["Pace di Apamea: Rodi ebbe la Licia e il sud della Caria", "aa5173c6"], "d": ["Dopo Magnesia Roma diede all'alleata Rodi la Licia e la parte della Caria a sud del Meandro. Rodi perse questi territori nel 167.", "74a2ccb5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:0":{"b": ["Manlio Vulsone sconfisse le tribù galate: l'indipendenza dei Galati passò sotto la sorveglianza di Roma", "30ae73d7"], "d": ["Dopo Magnesia Cn. Manlio Vulsone invase il paese dei Galati e sconfisse Tolistoagi e Tectosagi sull'Olimpo e a Magaba; con il trattato i Galati accettarono di non attaccare i vicini. La Galazia rimase in gran parte indipendente ma legata all'equilibrio romano-pergameno.", "fb7daca7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0188-01-01:1":{"b": ["L'Etolia fece pace con Roma: perse Ambracia e Eniade, riconobbe la sovranità di Roma", "f332c6bf"], "d": ["L'Etolia, che nella guerra di Antioco si era schierata con Antioco, dopo l'assedio di Ambracia da parte di Fulvio Nobiliore fece pace con Roma; riconobbe la «maestà» di Roma, pagò un'indennità e lasciò città come Ambracia ed Eniade.", "a6d05b8b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0189-01-01:0":{"b": ["Magnesia al Sipilo: Roma e Pergamo sconfissero Antioco III", "f650ef21"], "d": ["Nell'inverno 190/189 a Magnesia L. Scipione ed Eumene II sbaragliarono l'esercito di Antioco III. La Pace di Apamea (188) seguita alla vittoria portò Antioco a lasciare il nord del Tauro.", "04d021ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0191-01-01:0":{"b": ["Sparta entrò nella Lega Achea: Filopemene dopo Nabide legò la Laconia alla lega", "2629b6e1"], "d": ["Dopo l'uccisione del tiranno spartano Nabide (192), lo stratego acheo Filopemene incorporò con la forza Sparta nella Lega Achea. Sparta perse del tutto l'indipendenza nel 188 con la demolizione delle mura.", "6ed14d83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0195-01-01:0":{"b": ["Flaminino proclamò la libertà dei Greci ai Giochi Istmici", "3d850bf2"], "d": ["Dopo Cinocefale il comandante romano T. Quinzio Flaminino ai Giochi Istmici del 196 a.C. proclamò che le guarnigioni macedoni a Corinto, Calcide e Demetriade sarebbero state ritirate e che le città greche erano «libere, esenti da tributi e soggette alle proprie leggi». Roma si stabilì così in Grecia come arbitro.", "41ba1fc4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:0":{"b": ["Cinocefale: Roma sconfisse Filippo V; la Macedonia fu costretta a ritirarsi dalla Grecia", "9cb44ca6"], "d": ["Nel giugno del 197 le legioni romane di Flaminino sbaragliarono a Cinocefale la falange macedone. Nella pace del 196 Filippo lasciò tutte le posizioni in Grecia (Demetriade, Calcide, Corinto), consegnò la flotta e pagò 1000 talenti.", "da059ad7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0196-01-01:1":{"b": ["In Hispania furono istituite due province romane: Citeriore e Ulteriore", "1baa8383"], "d": ["I territori della Hispania presi a Cartagine furono divisi nel 197 per la prima volta in due province distinte, ciascuna governata da un pretore. Da allora le guerre contro Celtiberi e Lusitani nella penisola furono condotte per estendere l'ordinamento provinciale romano.", "5b732530"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:0":{"b": ["Pace dopo Zama: Cartagine perse la Hispania e le isole del Mediterraneo, la flotta e si assunse un'indennità di 10.000 talenti", "8654422d"], "d": ["Dopo Zama (202) Roma ristrinse Cartagine ai suoi territori in Africa: furono accettate le condizioni di abbandonare la Hispania e le isole del Mediterraneo, consegnare la flotta (salvo 10 navi), pagare 10.000 talenti in 50 anni e non dichiarare guerra senza il permesso di Roma. La Numidia di Massinissa divenne vicina indipendente.", "fcba363e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0200-01-01:1":{"b": ["Roma premiò Massinissa con il regno di Siface", "54ba7a64"], "d": ["Nella pace di Zama Roma assegnò a Massinissa il regno di Siface e i territori di confine presi a Cartagine; le rivendicazioni di Massinissa sulla regione di «Emporia» e sul confine di Cartagine furono poi causa di guerra.", "106adff6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0201-01-01:0":{"b": ["Zama: Scipione e Massinissa sconfissero Annibale", "52e188e6"], "d": ["Nella battaglia di Zama, avvenuta dopo il richiamo di Annibale in Africa, le legioni di Scipione e la cavalleria numida di Massinissa sconfissero l'esercito cartaginese. La Seconda Guerra Punica con questa battaglia terminò definitivamente a favore di Roma.", "0cd233b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0202-01-01:0":{"b": ["Siface fu sconfitto e fatto prigioniero; Massinissa unificò la Numidia", "a42a3cb0"], "d": ["Scipione e Massinissa nel 203 sconfissero l'esercito di Siface e lo fecero prigioniero; Massinissa, con l'appoggio di Roma, prese Cirta e il regno di Siface. La Numidia divenne un regno forte con l'unione delle parti orientale e occidentale.", "d6649bd5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0205-01-01:0":{"b": ["Ilipa e Gades: la Hispania passò da Cartagine a Roma", "31e5a50c"], "d": ["Scipione nel 206 a Ilipa sconfisse l'esercito di Asdrubale Gisgone e di Magone, ponendo fine al controllo cartaginese in Hispania; anche Gades passò poco dopo a Roma. Cartagine perse le miniere d'argento e il serbatoio di soldati della Hispania.", "dd505492"]},
"OLAYLAR_ANTIK_AKDENIZ:-0208-01-01:0":{"b": ["Fabio Massimo riprese Taranto ad Annibale", "bd605091"], "d": ["Taranto, arresasi ad Annibale nel 212, nel 209 passò a Q. Fabio Massimo per un tradimento. Con la caduta della città Annibale perse il suo porto più prezioso nell'Italia meridionale.", "33c6b48f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0210-01-01:0":{"b": ["Capua cadde in mano romana: fu perduta la base campana di Annibale", "cfcb9c9a"], "d": ["Roma, che assediava da due anni Capua, passata ad Annibale dopo Canne, la prese nonostante la mossa di Annibale di marciare su Roma, e la punì duramente; l'autonomia di Capua fu abolita. Annibale si ritirò sulla difensiva nell'Italia meridionale.", "9a129e81"]},
"OLAYLAR_ANTIK_AKDENIZ:-0215-01-01:0":{"b": ["Canne: Annibale accerchiò e annientò l'esercito romano; l'Italia meridionale cominciò a passare a Cartagine", "94f5110a"], "d": ["Nel 216 a Canne, in Apulia, lo schieramento a tenaglia di Annibale annientò l'esercito romano di circa settantamila uomini. Capua, Taranto e molte città dell'Italia meridionale passarono dalla parte di Cartagine.", "1a19e07d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:0":{"b": ["L'esercito romano sbarcò in Hispania: prima base romana a Emporion", "8cb47853"], "d": ["Dopo la marcia di Annibale verso l'Italia, Cn. Cornelio Scipione nel 218 a.C. sbarcò a Emporion dando inizio alla presenza romana in Hispania lungo l'Ebro; la penisola divenne il secondo fronte della Seconda Guerra Punica.", "ef7a1d28"]},
"OLAYLAR_ANTIK_AKDENIZ:-0217-01-01:1":{"b": ["Annibale attraversò le Alpi ed entrò in Italia", "a1d3bf5a"], "d": ["Annibale, attraversati l'Ebro, i Pirenei e il Rodano, in autunno superò le Alpi e scese nell'Italia settentrionale; sconfisse gli eserciti romani al Ticino e alla Trebbia. Il centro della guerra italiana di Cartagine fu così portato dentro Roma.", "8a70efb1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0218-01-01:0":{"b": ["Annibale prese Sagunto: fu accesa la miccia della Seconda Guerra Punica", "a497a334"], "d": ["Annibale, dopo un assedio di otto mesi, prese Sagunto, alleata di Roma (219 a.C.); Roma inviò ambasciatori chiedendo la consegna di Annibale e, al rifiuto, fu dichiarata la guerra. La guerra durò diciassette anni in Italia, Hispania e Africa.", "8f80d7b4"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:0":{"b": ["Sellasia: Antigono Dosone sconfisse Cleomene, Sparta subì per la prima volta un'occupazione straniera", "dc64a8db"], "d": ["Nell'estate del 222 a Sellasia l'alleanza macedone-achea sconfisse l'esercito spartano di Cleomene; Cleomene fuggì in Egitto. Dosone entrò a Sparta e la riportò all'ordinamento di Licurgo; gli Spartani subirono per la prima volta nella loro storia l'occupazione di un esercito straniero.", "575b0c9d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0221-01-01:1":{"b": ["Mediolanum (Milano) cadde in mano romana: gli Insubri furono sconfitti, l'Italia settentrionale si aprì a Roma", "d3ec639f"], "d": ["Roma, che aveva sconfitto i Galli a Talamone (225), nel 222 a.C. con la vittoria di Marcello a Clastidio e la presa di Mediolanum prese il controllo di gran parte della pianura padana. La regione fu organizzata come Gallia Cisalpina.", "710258fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0223-01-01:0":{"b": ["La Lega Achea consegnò Acrocorinto ad Antigono Dosone: Corinto tornò alla Macedonia", "c8ec9d0c"], "d": ["La Lega Achea, sotto la pressione di Cleomene III, chiese per mezzo di Arato l'aiuto della Macedonia e cedette Acrocorinto e Corinto ad Antigono Dosone; Dosone fondò la Lega Ellenica (Hellenikos symmachia).", "4337420d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0225-01-01:0":{"b": ["Trattato dell'Ebro: Cartagine accettò di non passare a nord dell'Ebro", "a199de0b"], "d": ["Asdrubale, proseguendo la conquista della Hispania iniziata da Amilcare, concluse con Roma il Trattato dell'Ebro: Cartagine non avrebbe attraversato l'Ebro in armi. L'attacco di Annibale a Sagunto nel 219 fu motivato sull'interpretazione di questo trattato.", "42aa3953"]},
"OLAYLAR_ANTIK_AKDENIZ:-0237-01-01:0":{"b": ["Roma prese a Cartagine Sardegna e Corsica", "4f7295ee"], "d": ["Quando i mercenari ribelli di Cartagine in Sardegna chiesero aiuto a Roma, Roma occupò l'isola; Cartagine, sotto la minaccia di guerra, dovette lasciare le isole e pagare altri 1200 talenti. Roma creò la seconda provincia (Sardinia et Corsica).", "60cb31ea"]},
"OLAYLAR_ANTIK_AKDENIZ:-0240-01-01:0":{"b": ["Isole Egadi: la flotta cartaginese fu distrutta; la Sicilia divenne la prima provincia romana", "8bd16e8f"], "d": ["Lutazio Catulo nel marzo del 241 sbaragliò davanti alle Egadi la flotta cartaginese di Annone; poi con la Pace di Lutazio Cartagine sgomberò la Sicilia e accettò di pagare 3200 talenti di indennità di guerra. La Sicilia (esclusa la Siracusa di Gerone) divenne la prima provincia di Roma.", "24ff35a3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0242-01-01:0":{"b": ["Arato sorprese Acrocorinto: Corinto passò dalla Macedonia alla Lega Achea", "a88dfda6"], "d": ["Arato di Sicione, con un attacco notturno, neutralizzò la guarnigione di Antigono Gonata ad Acrocorinto e unì Corinto alla Lega Achea; anche Megara, Trezene ed Epidauro passarono alla lega. La Macedonia perse la sua fortezza chiave nel Peloponneso.", "84d43a24"]},
"OLAYLAR_ANTIK_AKDENIZ:-0250-01-01:0":{"b": ["Arato unì Sicione alla Lega Achea", "6f413f9c"], "d": ["Il giovane Arato rovesciò il tiranno di Sicione e legò la città alla Lega Achea; questo passo estese la Lega alle rive settentrionale e meridionale del Golfo di Corinto e portò Arato a essere eletto stratego.", "1becea45"]},
"OLAYLAR_ANTIK_AKDENIZ:-0262-01-01:0":{"b": ["Gerone II si alleò con Roma: la Sicilia orientale divenne alleata di Roma", "5e95a134"], "d": ["Gerone, all'inizio della Prima Guerra Punica, per la questione di Messana si era alleato con Cartagine contro Roma; nel 263 fece pace e alleanza con Roma e rimase per tutta la vita (fino al 215) fedele alleato di Roma. Siracusa divenne lo Stato alleato della Sicilia romana, rimasto fuori dalla provincia.", "4be7c84b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:0":{"b": ["Nicomede I fondò Nicomedia (Izmit)", "a89ed42a"], "d": ["Nicomede, dopo la distruzione di Astaco, fondò Nicomedia all'estremità orientale del golfo; la città divenne nei secoli seguenti il centro della Bitinia e, ai tempi di Diocleziano, capitale orientale di Roma.", "a172ed71"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:1":{"b": ["Iniziò la Prima Guerra Punica: Appio Claudio passò a Messana", "636e1533"], "d": ["Quando i Mamertini di Messana, contro il re di Siracusa Gerone, chiesero aiuto prima a Cartagine e poi a Roma, il console romano Appio Claudio Caudice nel 264 passò in Sicilia e prese Messana alla guarnigione cartaginese. Così Roma entrò per la prima volta in guerra fuori dall'Italia.", "de7b7f25"]},
"OLAYLAR_ANTIK_AKDENIZ:-0263-01-01:2":{"b": ["Volsinii cadde: l'ultima grande città indipendente dell'Etruria passò a Roma", "b6aed092"], "d": ["Roma prese nel 264 Volsinii, che si era rivolta a Roma per aiuto a causa di una rivolta di schiavi, e trasferì gli abitanti della città in un nuovo luogo. L'Etruria da allora entrò di fatto sotto il dominio romano.", "4384ae1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:0":{"b": ["Pirro morì ad Argo", "2b4996fa"], "d": ["Nella campagna del Peloponneso, nel combattimento di strada ad Argo, Pirro fu ferito da una tegola e morì (272). L'Epiro perse peso contro la Macedonia e ristabilì i rapporti con Roma.", "2e7f4937"]},
"OLAYLAR_ANTIK_AKDENIZ:-0271-01-01:1":{"b": ["Taranto si arrese a Roma: l'Italia meridionale fu annessa a Roma", "6e87c924"], "d": ["Dopo la partenza di Pirro la guarnigione epirota di Taranto si ritirò e la città si arrese a Roma (272). Con il Bruzio e la Lucania le città greche dell'Italia meridionale divennero alleate di Roma; così Roma divenne padrona della penisola italiana fino alla pianura padana.", "b7f98699"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:0":{"b": ["Maleventum (Benevento): Pirro si ritirò dall'Italia", "ab67e9f5"], "d": ["Il nuovo attacco di Pirro a Roma dopo il ritorno dalla campagna di Sicilia fallì a Maleventum davanti a Manio Curio Dentato; Pirro tornò in Epiro nel 275. Lasciò a Taranto una piccola guarnigione; Roma restò senza rivali in Italia.", "f2c89575"]},
"OLAYLAR_ANTIK_AKDENIZ:-0274-01-01:1":{"b": ["Antioco I sconfisse i Galati nella «Battaglia degli Elefanti»", "1e88c2d0"], "d": ["Antioco I, sconfitti i Galati con i suoi elefanti, assunse l'epiteto di Soter («salvatore»); i Galati tornarono a un sistema di tributo e incursioni stanziale nell'Anatolia centrale. Nei secoli seguenti proseguirono i conflitti con Pergamo e la Bitinia.", "f925c4fd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0275-01-01:0":{"b": ["Antigono Gonata divenne re di Macedonia: la dinastia antigonide si consolidò", "4b907dd6"], "d": ["Gonata acquistò fama sconfiggendo i Galati a Lisimachia nel 277 e nel 276 si stabilì sul trono di Macedonia. La dinastia governò la Macedonia fino al 168; in Grecia tenne le fortezze di Corinto, Calcide e del Pireo.", "d13f42b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0277-01-01:0":{"b": ["Nicomede I fece passare i Galati in Anatolia", "9e5ab10b"], "d": ["Il re di Bitinia Nicomede I, contro il fratello Zipoite e la pressione di Seleuco, fece passare dal Bosforo e prese al proprio servizio le tribù galate (celtiche); i Galati si stabilirono poi nell'Anatolia centrale; il ramo dei Tectosagi fece di Ancira la capitale (TDV «Ankara»: «dal 278 al 189 a.C. fu capitale del ramo dei Tectosagi dei Galati venuti dalla Tracia»). Data del passaggio: 278/277.", "b9f3dcc3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0278-01-01:0":{"b": ["La Lega Etolica difese Delfi dall'incursione dei Galati", "5488966a"], "d": ["L'esercito galata di Brenno, superate le Termopili, avanzò verso Delfi; la resistenza di Etoli e Focesi disperse l'incursione. Il peso dell'Etolia nell'Anfizionia di Delfi crebbe con questa vittoria.", "af3aba53"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:0":{"b": ["Pirro passò in Italia in aiuto di Taranto; sconfisse i Romani a Eraclea", "55f18e85"], "d": ["Pirro, sbarcato in Italia nel 280 su invito di Taranto contro Roma, sconfisse a Eraclea con elefanti e cavalleria l'esercito di Valerio Levino, ma subì gravi perdite. Vinse di nuovo ad Ascoli nel 279 e passò in Sicilia nel 278-276.", "60cab05c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0279-01-01:1":{"b": ["La Lega Achea fu ricostituita: Patre, Dime, Tritea, Fare", "81bba071"], "d": ["Nell'Acaia sotto controllo antigonide quattro città (Dime, Patre, Tritea, Fare) nel 280 a.C. ricostituirono un'unione federale; negli anni seguenti si unirono Egio e altre città. La Lega, sotto la guida di Arato, divenne la grande potenza del Peloponneso.", "2426b2cc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0280-01-01:0":{"b": ["Filetero dopo Curupedio passò a Seleuco; Pergamo formò di fatto una dinastia indipendente", "ac6b3e31"], "d": ["Dopo la caduta di Lisimaco Filetero si legò a Seleuco con il tesoro e protesse e arricchì Pergamo; con la morte di Seleuco (281) divenne di fatto indipendente. Livio dà come durata del governo della dinastia attalide su Pergamo il periodo dal 283 al 129.", "cbc3946d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0284-01-01:0":{"b": ["Lisimaco scacciò Pirro dalla Macedonia e divenne unico re di Macedonia", "a83e6c64"], "d": ["Dopo l'inverno del 285, quando Demetrio si arrese a Seleuco, Lisimaco cacciò Pirro dalla Macedonia e governò da solo il paese. Il suo Stato giunse a comprendere un'ampia regione che abbracciava Tracia, Macedonia e Anatolia occidentale.", "8ba7b764"]},
"OLAYLAR_ANTIK_AKDENIZ:-0286-01-01:0":{"b": ["Pirro e Lisimaco divisero la Macedonia; Demetrio Poliorcete fu rovesciato", "63371ab8"], "d": ["Nell'estate del 287, quando Demetrio passò in Asia, Pirro e Lisimaco insieme divisero la Macedonia in due parti; Demetrio fu abbattuto. Questa spartizione durò solo due anni.", "9e4b93b2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0289-01-01:0":{"b": ["Il Sannio fu annesso a Roma: terminò la Terza Guerra Sannitica", "bede9942"], "d": ["Manio Curio Dentato sconfisse definitivamente Sanniti e Sabini; il Sannio divenne alleato di Roma. Roma divenne padrona dell'Italia centrale e si trovò di fronte alle città greche dell'Italia meridionale (Taranto).", "9c7619a6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0293-01-01:0":{"b": ["Demetrio Poliorcete fu proclamato re di Macedonia", "a2b1eba3"], "d": ["Approfittando della lotta per il trono nella dinastia di Cassandro, Demetrio nell'autunno del 294 fu proclamato re di Macedonia dall'esercito. È la prima sovranità della stirpe di Antigono in Macedonia; crollò nel 288, Gonata la rese stabile nel 276.", "959705f1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0294-01-01:0":{"b": ["Sentino: l'alleanza di Etruschi, Umbri, Sanniti e Galli fu sconfitta da Roma", "b5affc1b"], "d": ["Nella Terza Guerra Sannitica la battaglia di Sentino distrusse l'ultima grande alleanza antiromana in Italia; le città etrusche furono costrette una a una all'alleanza con Roma.", "b5bfb032"]},
"OLAYLAR_ANTIK_AKDENIZ:-0295-01-01:0":{"b": ["Pirro tornò sul trono d'Epiro con il sostegno di Tolomeo", "6288bf69"], "d": ["Pirro, rimasto in ostaggio in Egitto dopo Ipso, tornò in Epiro con l'aiuto di Tolomeo e riprese il trono. L'Epiro da allora ebbe voce nelle questioni di Macedonia e d'Italia.", "e15989dd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0300-01-01:0":{"b": ["Lisimaco depose il suo tesoro a Pergamo; Filetero divenne custode della fortezza", "e1b4ab77"], "d": ["Dopo Ipso Lisimaco fece custodire il suo tesoro nella fortezza di Pergamo, sulla collina, e ne affidò la custodia all'eunuco Filetero. Filetero nel 281 passò a Seleuco e gettò le basi della dinastia.", "6fabb342"]},
"OLAYLAR_ANTIK_AKDENIZ:-0301-01-01:0":{"b": ["Mitridate I Ctiste fondò la dinastia del Ponto", "490c338c"], "d": ["Mitridate, avvicinatosi ad Antigono Monoftalmo, nel 302 sfuggì al pericolo di essere ucciso e si rifugiò a Cimiata, nella regione montuosa del Ponto cappadoce, dove formò il nucleo del regno del Ponto. La dinastia durò fino al 63.", "e0d99a55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0303-01-01:0":{"b": ["L'assedio di Rodi da parte di Demetrio Poliorcete terminò con un fallimento", "dae6f4d6"], "d": ["Demetrio nel 305 cinse d'assedio con giganteschi macchinari Rodi, rimasta con Tolomeo contro Antigono; i Rodiesi resistettero un anno e nell'estate del 304 si giunse alla pace. In città, con il denaro di questa vittoria, fu eretto il Colosso del dio Sole Helios.", "013a6951"]},
"OLAYLAR_ANTIK_AKDENIZ:-0305-01-01:0":{"b": ["A Salamina di Cipro Demetrio sconfisse Tolomeo; Antigono e Demetrio assunsero il titolo di re", "cc308941"], "d": ["Nella primavera del 306 Demetrio Poliorcete sconfisse davanti a Cipro la flotta di Tolomeo e pose Cipro in mano ad Antigono; in estate Antigono e Demetrio assunsero il titolo di re e gli altri Diadochi in breve assunsero lo stesso titolo. Tolomeo riprese Cipro nel 294.", "0720c1b6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0308-01-01:0":{"b": ["Lisimaco fondò Lisimachia: capitale nel Chersoneso tracico", "83b83160"], "d": ["Lisimaco fece di Lisimachia, da lui fondata sull'istmo della penisola di Gallipoli, la capitale del regno di Tracia; il controllo degli Stretti e del passaggio dei Dardanelli fu concentrato nelle sue mani. La città fu devastata da un terremoto nel III secolo a.C.", "8ff0e638"]},
"OLAYLAR_ANTIK_AKDENIZ:-0310-01-01:0":{"b": ["Pace dei Diadochi: Antigono ebbe il governo dell'Asia, Cassandro dell'Europa, Tolomeo dell'Egitto", "811c80f0"], "d": ["Nella pace firmata nel dicembre 311 Antigono fu riconosciuto comandante dell'Asia, Cassandro stratego dell'Europa, Lisimaco governatore della Tracia, Tolomeo dell'Egitto e dei dintorni; passò il principio della libertà delle città greche. La Babilonia di Seleuco restò fuori da questa pace.", "3c9a7c4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0313-01-01:0":{"b": ["Tiro passò ad Antigono: la Fenicia fu tolta a Tolomeo", "30f78257"], "d": ["Antigono nel 315 entrò in Siria, prese la Fenicia e assediò Tiro; la città cadde nel 314. La costa fenicia e la costa fino a Gaza passarono nelle sue mani (Gaza fu restituita a Tolomeo nel 312 nella battaglia di Gaza).", "54b4c2dc"]},
"OLAYLAR_ANTIK_AKDENIZ:-0314-01-01:0":{"b": ["Cassandro fondò Salonicco", "7043bd8a"], "d": ["Cassandro, unendo più di venti insediamenti a nord del Golfo Termaico, fondò la città con il nome della moglie (figlia di Filippo II) Tessalonica. Salonicco fu per i mille anni seguenti il porto più importante della Macedonia.", "b6a8e171"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:0":{"b": ["Cassandro fece ricostruire Tebe", "0167e784"], "d": ["Tebe, distrutta da Alessandro, con il sostegno di Cassandro e con gli aiuti giunti da Atene e dall'Eubea fu ricostruita con le mura riparate. Fu di nuovo dato un centro alla Lega Beotica.", "8f93a07f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0315-01-01:1":{"b": ["Gabiene: Antigono sconfisse Eumene e divenne signore dell'Asia fino all'Iran", "d2990dfd"], "d": ["Nell'inverno 316/5 a Gabiene l'esercito di Eumene fu sbaragliato; il suo comandante fu consegnato ad Antigono dai propri soldati e giustiziato. Antigono divenne unico signore di un'ampia regione dall'altopiano persiano all'Anatolia; Seleuco fuggì in Egitto.", "afa9a54f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0319-01-01:0":{"b": ["Accordo di Triparadiso: Antigono Monoftalmo divenne stratego dell'Asia", "69f6fafb"], "d": ["Dopo l'uccisione di Perdicca in Egitto (maggio 320) Antipatro ridistribuì a Triparadiso le satrapie; Antigono fu posto a capo delle forze dell'Asia e Seleuco prese Babilonia. Da questa posizione Antigono si accinse a costituire il proprio impero.", "17f6bc6b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0321-09-05:0":{"b": ["Cranone: la Guerra Lamiaca fu perduta; una guarnigione macedone entrò ad Atene, la democrazia fu sospesa", "6931c4f6"], "d": ["Il 5 settembre del 322 a Cranone l'alleanza greca fu sconfitta da Antipatro e Cratero; Atene accettò di ricevere una guarnigione macedone a Munichia e di limitare il criterio di cittadinanza ai possidenti. Demostene si uccise; la democrazia ateniese classica terminò di fatto.", "ee0f58da"]},
"OLAYLAR_ANTIK_AKDENIZ:-0322-01-01:0":{"b": ["Guerra Lamiaca: le città greche si ribellarono all'egemonia macedone dopo la morte di Alessandro", "c31c7da4"], "d": ["Alla notizia della morte di Alessandro (giugno 323) Atene e la Lega Etolica si sollevarono contro Antipatro; Antipatro fu assediato a Lamia. La guerra terminò con la vittoria macedone a Cranone (settembre 322) e la supremazia macedone nel quadro della Lega di Corinto fu ristabilita.", "57d15260"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:0":{"b": ["Idaspe: Poro fu sconfitto; il Punjab fu legato ad Alessandro", "abab206b"], "d": ["Nel maggio del 326, con il sostegno del raja di Taxila Ambhi, Alessandro attraversò lo Jhelum e sconfisse Poro; il regno di Poro fu lasciato ad Alessandro come vassallo. Da qui Alessandro avanzò a est, ma si fermò all'Ifasi per il rifiuto dell'esercito.", "b8f65fb3"]},
"OLAYLAR_ANTIK_AKDENIZ:-0325-01-01:1":{"b": ["Sulla riva dell'Ifasi (Beas) l'esercito rifiutò di avanzare: confine orientale di Alessandro", "17b23afc"], "d": ["Per le piogge monsoniche e la stanchezza l'esercito macedone rifiutò di passare oltre l'Ifasi; Alessandro fece erigere dodici altari e dovette tornare indietro. L'Ifasi fu il confine orientale delle conquiste macedoni in India.", "14c7c1e0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0326-01-01:0":{"b": ["Battriana e Sogdiana si sottomisero ad Alessandro; Alessandro sposò Rossane", "a050508d"], "d": ["Tra il 329 e il 327 la regione oltre l'Oxus fu presa con una intensa lotta di guerriglia; Spitamene fu ucciso, la Roccia di Sogdiana e la fortezza di Corieno si arresero. Alessandro sposando la principessa battriana Rossane legò all'amministrazione i nobili locali.", "918611e2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0333-01-01:0":{"b": ["La costa dell'Anatolia occidentale passò ad Alessandro: Efeso, Mileto e Alicarnasso", "f67084a4"], "d": ["Efeso aprì le porte con un regime democratico, Mileto fu presa dopo l'assedio (estate 334); l'assedio di Alicarnasso si concluse in autunno con la caduta della città e la satrapia di Caria fu data ad Ada. Alessandro applicò così la strategia di prendere via terra i porti della flotta persiana.", "8ad1fb18"]},
"OLAYLAR_ANTIK_AKDENIZ:-0334-01-01:0":{"b": ["Tebe fu distrutta per ordine di Alessandro", "26c4193c"], "d": ["Tebe, ribellatasi con la morte di Filippo, fu presa da Alessandro in autunno; pose una guarnigione macedone nella Cadmea, fece distruggere la città e ridusse in schiavitù la popolazione (salvo la casa di Pindaro). La Lega Beotica con questa distruzione terminò di fatto (la rifondò Cassandro nel 316).", "1aac0f0a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0335-01-01:0":{"b": ["Filippo II fu assassinato a Ege; Alessandro salì al trono", "417d909e"], "d": ["Al posto di Filippo, ucciso a teatro dalla sua guardia del corpo Pausania durante la festa di nozze della figlia Cleopatra, il figlio Alessandro fu proclamato re dall'esercito. La campagna persiana e il controllo della Grecia restarono ad Alessandro.", "29a2af26"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:0":{"b": ["Fu fondata la Lega di Corinto: le città greche unite sotto l'egemonia di Filippo II", "c38074dc"], "d": ["Dopo Cheronea Filippo riunì a Corinto le città greche sotto un patto di pace comune (koine eirene) e di difesa comune; furono decisi soldati e comando di egemone per la campagna contro i Persiani. Solo Sparta non partecipò.", "753c39e6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:1":{"b": ["Cheronea: Filippo sconfisse l'esercito di Atene e Tebe e prese il controllo della Grecia", "5e5d77e7"], "d": ["Nell'agosto del 338 nella piana di Cheronea l'esercito ateniese-tebano fu sbaragliato dalla carica di cavalleria comandata dal giovane Alessandro; a Tebe fu posta una guarnigione macedone, Atene fu risparmiata con indulgenza. La vittoria pose fine all'indipendenza delle città greche e aprì la via alla Lega di Corinto.", "b2f75989"]},
"OLAYLAR_ANTIK_AKDENIZ:-0337-01-01:2":{"b": ["La Lega Latina fu sciolta: il Lazio fu annesso a Roma", "58849f84"], "d": ["Al termine della Guerra Latina (340-338) Roma sciolse la Lega Latina; le città furono incorporate nella cittadinanza romana o legate a Roma una a una e fu vietata l'alleanza tra loro. È la base del modello di espansione di Roma in Italia.", "5ebbdf2e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0338-01-01:0":{"b": ["Filippo II sconfisse il re scita Ateas", "e4dee658"], "d": ["La guerra del re Ateas con Filippo sulle rive dell'Istro (Danubio) si concluse con la morte di Ateas; al ritorno Filippo subì un attacco dei Triballi. La potenza scita si spostò a ovest oltre il Danubio.", "29f62ac6"]},
"OLAYLAR_ANTIK_AKDENIZ:-0340-01-01:0":{"b": ["Filippo sottomise la Tracia insieme alla dinastia odrisia", "b543427a"], "d": ["Filippo nelle campagne del 342-341 a.C. avanzò nell'interno della Tracia, rese tributario il re odrisio Cersoblepte e fondò città come Filippopoli (Plovdiv). La Tracia divenne un'estensione orientale della Macedonia.", "82201f3c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0347-01-01:0":{"b": ["Distruzione di Olinto: la Lega Calcidica passò alla Macedonia", "89d77301"], "d": ["Nonostante la richiesta di aiuto di Olinto ad Atene, Filippo prese la città con un tradimento e la distrusse; la penisola calcidica fu annessa alla Macedonia. Le orazioni Olintiache di Demostene si basano su questo appello.", "c69e91c8"]},
"OLAYLAR_ANTIK_AKDENIZ:-0354-01-01:0":{"b": ["Terminò la Guerra Sociale: Bisanzio, Chio, Rodi e Cos lasciarono la Seconda Lega Ateniese", "856a9763"], "d": ["La rivolta iniziata nel 357 a.C. terminò con la sconfitta dei comandanti ateniesi a Chio e con l'accettazione della pace da parte di Atene quando il sostegno persiano si volse contro di lei; quattro membri importanti ottennero l'indipendenza. La Lega si indebolì e restò indifesa di fronte alla Macedonia.", "170647af"]},
"OLAYLAR_ANTIK_AKDENIZ:-0356-01-01:0":{"b": ["Filippo prese Anfipoli ad Atene", "2c793bc6"], "d": ["Filippo, assediata e presa Anfipoli, la città ateniese alla foce dello Strimone, ottenne l'accesso alle miniere d'oro e d'argento e alle risorse di legname della città e si aprì verso la costa tracia. Questa conquista diede inizio al conflitto ateniese-macedone.", "731bf35a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0358-01-01:0":{"b": ["Filippo II divenne re di Macedonia", "d557268d"], "d": ["Alla morte di Perdicca III in guerra contro gli Illiri (360/359 a.C.) Filippo divenne prima reggente e poi re; respinse le minacce di Illiria, Peonia e Tracia e attuò la riforma dell'esercito (falange di sarisse). L'ascesa della Macedonia comincia con questo regno.", "417218f0"]},
"OLAYLAR_ANTIK_AKDENIZ:-0361-01-01:0":{"b": ["Mantinea: Epaminonda morì, l'egemonia beotica terminò", "94be8d5c"], "d": ["L'esercito tebano vinse la battaglia, ma Epaminonda, ferito, morì; Senofonte conclude: «incertezza e confusione in Grecia maggiori di prima». La breve egemonia di Tebe terminò nello stesso anno, l'equilibrio Atene-Sparta-Tebe fu mantenuto.", "42ad0729"]},
"OLAYLAR_ANTIK_AKDENIZ:-0368-01-01:0":{"b": ["Fu fondata la Lega Arcade: questa parte della Lega del Peloponneso si dissolse", "42fdc676"], "d": ["Dopo Leuttra le città dell'Arcadia con il sostegno di Tebe formarono un'unione federale e costruirono la nuova capitale Megalopoli. Così la Lega del Peloponneso di Sparta si dissolse di fatto; Sparta si ritirò nella sola Laconia.", "4cf7dd83"]},
"OLAYLAR_ANTIK_AKDENIZ:-0369-01-01:0":{"b": ["La Messenia si staccò da Sparta; fu fondata Messene", "e4ef9302"], "d": ["Nella campagna di Epaminonda nel Peloponneso dopo Leuttra (inverno 370/69) gli iloti della Messenia furono liberati e ai piedi del monte Itome fu fondata la città di Messene, dalle forti mura. Sparta perdette per la prima volta dopo secoli i territori della Messenia che formavano la sua base economica.", "fe6af875"]},
"OLAYLAR_ANTIK_AKDENIZ:-0370-01-01:0":{"b": ["Leuttra: l'esercito tebano sconfisse gli Spartani; Sparta perse la supremazia terrestre", "e7829597"], "d": ["Lo schieramento di Epaminonda con l'ala destra profonda sbaragliò a Leuttra le forze spartane del re Cleombroto; con la morte di circa 400 Spartiati Sparta non fu più in grado di colmare la perdita di popolazione. Iniziò un periodo di egemonia sotto la guida di Tebe.", "41f8774e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0376-01-01:0":{"b": ["Fu fondata la Seconda Lega Ateniese (decreto di Aristotele)", "0e5dcaf2"], "d": ["Atene chiamò nella lega le città dell'Egeo contro Sparta con il principio dell'autonomia e del non pagamento di tributi; il decreto passò su proposta di Aristotele e l'elenco delle città membri fu scritto su pietra. La fondazione della Lega fece di Atene di nuovo una potenza navale.", "20a9657f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0378-01-01:0":{"b": ["Pelopida liberò Tebe; la guarnigione spartana fu scacciata dalla Cadmea", "eb15a9d7"], "d": ["La Cadmea di Tebe, presa da Sparta nel 382 a.C. con una guarnigione, fu ripresa con un attacco notturno degli esuli; Tebe tornò a essere il centro della Lega Beotica. L'evento è l'inizio della dissoluzione dell'egemonia spartana.", "4cd862c2"]},
"OLAYLAR_ANTIK_AKDENIZ:-0388-01-01:0":{"b": ["Allia: i Galli sconfissero l'esercito romano e saccheggiarono la città", "db864bc9"], "d": ["Sulle rive dell'Allia, affluente del Tevere, i Galli Senoni sbaragliarono l'esercito romano; Roma fu occupata, a eccezione del Campidoglio, e saccheggiata. Livio scrive che il «giorno dell'Allia» (18 luglio) fu considerato infausto dai Romani.", "7babd2e7"]},
"OLAYLAR_ANTIK_AKDENIZ:-0391-01-01:0":{"b": ["Corinto si unì ad Argo (isopolitia Argo-Corinto)", "135a3d3a"], "d": ["Durante la Guerra di Corinto (395-387 a.C.) Corinto formò con Argo un'unione di cittadinanza comune; una guarnigione argiva rimase a Corinto. Sparta con la Pace del Re (386) fece sciogliere questa unione.", "9f979507"]},
"OLAYLAR_ANTIK_AKDENIZ:-0395-01-01:0":{"b": ["Veio cadde in mano romana: fu perduta la prima grande città dell'Etruria meridionale", "0d1c4fe4"], "d": ["Dopo un assedio di dieci anni Camillo prese Veio (secondo la tradizione nel 396 a.C.); la popolazione fu ridotta in schiavitù, i territori annessi a Roma e l'ager Romanus quasi raddoppiò. La potenza delle città etrusche a sud del Tevere fu spezzata.", "7571ce55"]},
"OLAYLAR_ANTIK_AKDENIZ:-0403-01-01:0":{"b": ["Atene si arrese a Sparta; terminarono l'impero marittimo ateniese e la Lega di Delo", "43f2ddf9"], "d": ["Atene, persa la flotta ad Egospotami, si arrese per fame; le Lunghe Mura furono demolite, l'impero marittimo si dissolse e in città giunse il governo dei Trenta fatto istituire dagli Spartani. Nelle isole e sulle coste tracie, già membri della Lega, si insediarono i governi di decarchie fondati da Lisandro e le guarnigioni spartane.", "3d808acd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:0":{"b": ["Dionisio I divenne tiranno a Siracusa", "1ad10305"], "d": ["Negli anni in cui Cartagine prese Agrigento e Gela, Dionisio nel 405 divenne stratego e poi tiranno di Siracusa; fece pace con Cartagine (405) e legò a sé le città greche della Sicilia. Il governo di Dionisio, durato 38 anni, fece della Sicilia una delle grandi potenze del Mediterraneo.", "3068782f"]},
"OLAYLAR_ANTIK_AKDENIZ:-0404-01-01:1":{"b": ["Egospotami: la flotta ateniese fu distrutta; la Lega di Delo fu sul punto di crollare", "ce62187c"], "d": ["Nel settembre del 405 Lisandro catturò con un attacco la flotta ateniese ancorata ad Egospotami; furono perse quasi tutta la flotta e migliaia di prigionieri. La rotta dell'Ellesponto fu chiusa e il rifornimento di grano di Atene fu interrotto; pochi mesi dopo Atene si arrese.", "d42a037e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0407-01-01:0":{"b": ["Fu fondata la città di Rodi: Lindo, Ialiso e Camiro si unirono", "2de55901"], "d": ["Nel 408 a.C. le tre città dell'isola di Rodi formarono uno Stato comune e si unirono nella nuova città di Rodi; la città, costruita con il piano di Ippodamo, divenne una delle più importanti basi navali e centri commerciali del mondo ellenistico.", "0db6207d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0408-01-01:0":{"b": ["Annibale Magone distrusse Selinunte e Imera: Cartagine si stabilì nella Sicilia occidentale", "358f4417"], "d": ["Annibale Magone, sbarcato in Sicilia su richiesta di Segesta, nel 409 a.C. prese Selinunte e Imera; la regione divenne epicrazia di Cartagine. Il conflitto Cartagine-Siracusa durò due secoli.", "58abf6b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0412-01-01:0":{"b": ["La spedizione di Sicilia finì in catastrofe: l'esercito ateniese fu annientato davanti a Siracusa", "b363df0d"], "d": ["La spedizione di Sicilia, iniziata da Atene nel 415 a.C., dopo il mancato investimento di Siracusa si concluse con la resa di Nicia e Demostene sul fiume Assinaro durante la ritirata (autunno 413 a.C.). Atene perse l'esercito e gran parte della flotta.", "2d1f3d05"]},
"OLAYLAR_ANTIK_AKDENIZ:-0429-01-01:0":{"b": ["Sitalce si alleò con Atene: il Regno degli Odrisi entrò nella Guerra del Peloponneso", "4562f13d"], "d": ["Atene fece cittadino ateniese il figlio di Sitalce e stipulò con lui un'alleanza; Sitalce nel 429 attaccò la Macedonia. La potenza odrisia raggiunse in questo periodo l'apice.", "64e00572"]},
"OLAYLAR_ANTIK_AKDENIZ:-0430-01-01:0":{"b": ["Iniziò la Guerra del Peloponneso: la Lega del Peloponneso si mobilitò contro Atene", "2adee4a1"], "d": ["Con l'incursione notturna di Tebe a Platea (primavera 431) la pace fu di fatto rotta; all'inizio dell'estate l'esercito della Lega del Peloponneso al comando del re Archidamo invase l'Attica. La guerra durò 27 anni tra l'impero marittimo di Atene e la lega terrestre di Sparta.", "6d950c3b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0432-01-01:0":{"b": ["Sibota: la guerra Corinto-Corcira trascinò Atene nell'intervento", "dc07b0ac"], "d": ["Nella battaglia navale in cui Corinto entrò per la colonia Corcira ed Epidamno, Atene sostenne Corcira. L'ira di Corinto verso Atene fu una delle cause dirette della Guerra del Peloponneso.", "f4639e4c"]},
"OLAYLAR_ANTIK_AKDENIZ:-0437-01-01:0":{"b": ["Spartoco divenne arconte nel Bosforo: dinastia degli Spartocidi", "ddc76f79"], "d": ["Alla dinastia degli Archeanattidi a Panticapeo subentrò Spartoco, di origine tracia (438/7); la dinastia degli Spartocidi fondò il regno del Bosforo e gestì l'esportazione di grano verso Atene. La dinastia durò fino al 109 a.C.", "36cf3454"]},
"OLAYLAR_ANTIK_AKDENIZ:-0445-01-01:0":{"b": ["Pace dei Trent'anni: Atene perse l'impero terrestre (Beozia, Megara, Acaia)", "4f33ff13"], "d": ["Dopo la vittoria dei Beoti sull'esercito ateniese a Coronea (447), poi le rivolte di Eubea e Megara e l'invasione spartana dell'Attica, Atene firmò la Pace dei Trent'anni. Atene lasciò Megara, Nisea, Pege e Trezene e Acaia nel Peloponneso; conservò solo l'impero marittimo.", "fc720780"]},
"OLAYLAR_ANTIK_AKDENIZ:-0449-01-01:0":{"b": ["Tere fondò il regno degli Odrisi: il primo grande Stato della Tracia", "83caf189"], "d": ["Tucidide scrive che Tere fondò il primo grande regno in Tracia; il figlio Sitalce portò il regno dal Danubio all'Egeo. Il regno odrisio condusse una politica di equilibrio tra Atene, Macedonia e Persia.", "442e0b64"]},
"OLAYLAR_ANTIK_AKDENIZ:-0453-01-01:0":{"b": ["Il tesoro della Lega fu trasferito da Delo ad Atene", "173f2e5b"], "d": ["Con il pretesto della sconfitta nella spedizione d'Egitto e del timore della flotta persiana, il tesoro comune fu portato da Delo ad Atene; le liste della quota «di un sessantesimo» data alla dea di Atene iniziano da quest'anno. Questo passo è interpretato come segno che la Lega si trasformava in pratica nell'impero ateniese.", "c7c6b1db"]},
"OLAYLAR_ANTIK_AKDENIZ:-0462-01-01:0":{"b": ["La rivolta di Taso fu repressa; la Lega di Delo divenne un impero da cui i membri non potevano uscire", "d24bd124"], "d": ["Taso, entrata in conflitto con Atene per le miniere, tentò di uscire dalla lega; dopo un assedio di due anni (463 a.C.) dovette abbattere le mura, consegnare la flotta e perse la regione mineraria sulla costa tracia. L'evento è il primo precedente che mostra che l'appartenenza alla Lega non poteva essere abbandonata.", "eb9beb44"]},
"OLAYLAR_ANTIK_AKDENIZ:-0473-01-01:0":{"b": ["Battaglia navale di Cuma: Siracusa sconfisse la flotta etrusca, la potenza navale etrusca fu spezzata", "2e81670b"], "d": ["Su richiesta di aiuto di Cuma, il tiranno di Siracusa Gerone I sconfisse la flotta etrusca davanti a Cuma; Gerone celebrò la vittoria con il dono di un elmo a Delfi (l'elmo etrusco menzionato da Livio). Il dominio etrusco sulla Campania fu scosso.", "db3832ad"]},
"OLAYLAR_ANTIK_AKDENIZ:-0477-01-01:0":{"b": ["Fu fondata la Lega di Delo: alleanza dell'Egeo sotto la guida di Atene", "f0de153a"], "d": ["Dopo il modo di governare di Pausania, le città ioniche chiesero ad Atene la guida; con il tributo fissato da Aristide (460 talenti) fu costituito a Delo un tesoro comune. La Lega diede ad Atene una flotta permanente e una base fiscale sull'Egeo.", "bb661e1d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0478-01-01:0":{"b": ["Salamina (29 settembre 480) e Platea: l'invasione persiana fu respinta", "479b17e6"], "d": ["Dopo che Serse ebbe preso e incendiato Atene, con l'inganno di Temistocle la flotta persiana fu sbaragliata nello stretto di Salamina (29 settembre 480); l'anno seguente a Platea l'esercito terrestre greco al comando di Pausania sconfisse Mardonio, ponendo fine all'invasione. Così la Grecia dell'Egeo fu liberata dal dominio persiano.", "dd5f48b5"]},
"OLAYLAR_ANTIK_AKDENIZ:-0479-01-01:0":{"b": ["Imera: i Greci di Sicilia sconfissero l'esercito cartaginese", "ece09580"], "d": ["L'alleanza di Gelone e Terone sbaragliò davanti a Imera l'esercito cartaginese di Amilcare; Cartagine non poté fare una nuova grande campagna in Sicilia per mezzo secolo. Secondo Erodoto e Diodoro nello stesso giorno fu vinta Salamina (tradizione).", "1706c09a"]},
"OLAYLAR_ANTIK_AKDENIZ:-0489-01-01:0":{"b": ["Maratona: Atene fermò l'incursione persiana", "0967ce7c"], "d": ["Gli opliti di Atene e Platea al comando di Milziade sconfissero la forza persiana nella piana di Maratona impedendo lo sbarco in Attica. La vittoria alimentò la fiducia della democrazia ateniese e la politica navale che condusse poi alla Lega di Delo.", "1b107bcd"]},
"OLAYLAR_ANTIK_AKDENIZ:-0490-01-01:0":{"b": ["Mardonio sottomise la Macedonia ai Persiani", "7bde569c"], "d": ["Mardonio, genero di Dario, attraversata la Tracia, pose la Macedonia sotto il dominio persiano; il re macedone diede ai Persiani terra e acqua. La Macedonia si scrollò di dosso questa dipendenza dopo Platea (479).", "04f10eac"]},
"OLAYLAR_ANTIK_AKDENIZ:-0492-01-01:0":{"b": ["Foedus Cassianum: Roma si alleò con la Lega Latina", "56db407d"], "d": ["Con il trattato che porta il nome di Spurio Cassio, Roma e la Lega Latina strinsero un'alleanza sulla base della difesa reciproca, della spartizione del bottino e di un esercito comune. Questo trattato è il quadro dei rapporti Roma-Lazio fino alla Guerra Latina (340-338).", "cb723394"]},
"OLAYLAR_ANTIK_AKDENIZ:-0504-01-01:0":{"b": ["Con il ritiro di Corinto la spedizione della Lega del Peloponneso contro Atene si dissolse", "b44adf6b"], "d": ["Sparta spinse l'esercito della Lega del Peloponneso in Attica contro l'Atene democratica di Clistene; il ritiro dell'esercito di Corinto a Eleusi e il disaccordo dei due re spartani fecero fallire la spedizione. L'evento è considerato il primo esempio noto in cui il diritto di voto degli alleati cominciò a operare nell'assemblea della lega.", "f54c0949"]},
"OLAYLAR_ANTIK_AKDENIZ:-0507-01-01:0":{"b": ["Riforma di Clistene: furono poste le basi istituzionali della democrazia ateniese", "b2421c86"], "d": ["Dopo la caduta di Ippia, Clistene organizzò i cittadini sui demi, unità di insediamento, e su dieci nuove tribù; il Consiglio dei Cinquecento divenne il centro di questo ordinamento. È l'ordinamento in cui nacquero i concetti di isonomia/democrazia.", "f3da7080"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:0":{"b": ["L'ultimo re Tarquinio il Superbo fu cacciato; la monarchia terminò, iniziò la Repubblica", "5a4a9061"], "d": ["Secondo Livio Tarquinio il Superbo e la sua famiglia furono cacciati dalla città nel 509 a.C. e furono eletti i primi consoli (Bruto, Collatino). Polibio lega il primo trattato tra Roma e Cartagine all'anno dei primi consoli; sebbene nella storiografia moderna sia considerata «tradizione», la data si colloca alla fine del VI secolo a.C.", "b86ee69b"]},
"OLAYLAR_ANTIK_AKDENIZ:-0508-01-01:1":{"b": ["Primo trattato tra Roma e Cartagine (Polibio 3.22)", "cdef940f"], "d": ["Polibio riporta con il testo il trattato concluso tra Roma e Cartagine nell'anno dei primi consoli, che assegna a Roma le coste del Lazio e limita Cartagine alla Sicilia occidentale e alla Libia. Roma è indicata come padrona del Lazio.", "d5a9571d"]},
"OLAYLAR_ANTIK_AKDENIZ:-0534-01-01:0":{"b": ["Battaglia navale di Alalia: Etruschi e Cartaginesi scacciarono i Focei dalla Corsica", "25efbea8"], "d": ["Ad Alalia i Greci focei vinsero sulla carta ma persero gran parte della flotta; lasciata la Corsica, si ritirarono a Elea nell'Italia meridionale. Sull'isola si stabilì il dominio etrusco (Caere).", "50ab95a1"]},
"OLAYLAR_ANTIK_AKDENIZ:-0549-01-01:0":{"b": ["Trattato Sparta-Tegea: si formò il nucleo della Lega del Peloponneso", "57098e47"], "d": ["Sparta, sconfitta Tegea in Arcadia, le fece accettare un'alleanza perpetua (symmachia) in cambio del non devastare le sue terre; lo stesso schema si estese alle città del Peloponneso e nacque sotto la guida di Sparta la Lega del Peloponneso. La Lega funzionava al suo interno come assemblea di Sparta e degli alleati (sotto il comando di Sparta).", "b9500385"]},
"OLAYLAR_ANTIK_AKDENIZ:-0598-01-01:0":{"b": ["I Focei fondarono Massalia (Marsiglia)", "5d46bdf2"], "d": ["I coloni focei fondarono Massalia intorno al 600 a.C. alla foce del Rodano; la città divenne il centro del commercio greco nel Mediterraneo occidentale e del contatto con il mondo celtico.", "f4a73ff9"]},
"OLAYLAR_ANTIK_AKDENIZ:-0630-01-01:0":{"b": ["Batto di Tera fondò Cirene", "67fd477f"], "d": ["I coloni venuti da Tera, secondo l'oracolo di Delfi, guidati da Batto fondarono Cirene; la dinastia dei Battiadi regnò fino al 440. Livio dà come data di fondazione «ca. 630».", "e51d3a78"]},
"OLAYLAR_ANTIK_AKDENIZ:-0719-01-01:0":{"b": ["Sparta vinse la Prima Guerra Messenica: la Messenia fu annessa a Sparta", "74ad461c"], "d": ["Nella tradizione riferita da Pausania la Prima Guerra Messenica durò vent'anni e con la caduta di Itome la pianura messenica passò a Sparta; la popolazione fu ridotta allo stato di iloti. Questa conquista fu considerata l'evento fondamentale che determinò la forza agricola e la società militare di Sparta.", "2066959e"]},
"OLAYLAR_ANTIK_AKDENIZ:-0732-01-01:0":{"b": ["Siracusa fu fondata dal corinzio Archia", "10217104"], "d": ["Secondo Tucidide, un anno dopo Nasso il corinzio Archia fondò Siracusa. La città divenne la più grande città greca della Sicilia.", "e5643a95"]},
"OLAYLAR_ANTIK_AKDENIZ:-0813-01-01:0":{"b": ["Fondazione tradizionale di Cartagine (Timeo: 814/813 a.C.)", "908099b5"], "d": ["Secondo Timeo Cartagine fu fondata nel 814/813 a.C. da coloni di Tiro; Giustino indica il 825. Gli strati archeologici indicano la fine dell'VIII secolo a.C.", "c7e72545"]},
"OLAYLAR_ANTIK_AKDENIZ:-1199-01-01:0":{"b": ["I centri palaziali micenei furono distrutti: l'ordinamento palaziale crollò nel Peloponneso", "d2c79152"], "d": ["Alla fine dell'Elladico Tardo IIIB / inizio IIIC i centri palaziali di Pilo, Tirinto e Micene mostrano strati di distruzione o abbandono; l'economia palaziale basata sulla scrittura Lineare B termina. La causa della distruzione (terremoto, conflitti interni, Popoli del Mare, siccità) è controversa; gli strati di distruzione non si collocano in un solo anno ma si distribuiscono su alcuni decenni.", "53e45d98"]},
"OLAYLAR_ANTIK_AKDENIZ:-1449-01-01:0":{"b": ["Distruzione dei palazzi minoici a Creta; a Cnosso iniziò il controllo miceneo", "1a7f7f2b"], "d": ["Alla fine del Tardo Minoico IB (metà del XV secolo a.C.) i centri palaziali e le ville di Creta subiscono distruzione; nella fase successiva le tavolette in Lineare B di Cnosso, scritte in greco, mostrano un'amministrazione palaziale, cioè il controllo miceneo. Così il dominio minoico a Creta termina.", "2b9cf7f8"]},
"OLAYLAR_ANTIK_AKDENIZ:0009-01-01:0":{"b": ["Foresta di Teutoburgo: le tre legioni di Varo furono annientate; Roma abbandonò la linea dell'Elba", "1684ae43"], "d": ["Nel 9 d.C. la coalizione germanica guidata da Arminio annientò nella Foresta di Teutoburgo le legioni XVII, XVIII e XIX di P. Quintilio Varo. Augusto rinunciò alle conquiste oltre il Reno e il confine del Reno divenne permanente.", "842869dc"]},
"OLAYLAR_ANTIK_AKDENIZ:0014-08-19:0":{"b": ["Augusto morì; Tiberio divenne imperatore", "0221344d"], "d": ["Augusto morì a Nola il 19 agosto del 14; gli succedette Tiberio. Nel Principato il principio di successione (adozione all'interno della famiglia) si consolidò così.", "e55fc404"]},
"OLAYLAR_ANTIK_AKDENIZ:0040-01-01:0":{"b": ["Il re Tolomeo fu ucciso da Caligola; l'indipendenza della Mauretania terminò", "11337627"], "d": ["Tolomeo, figlio di Giuba II, fu ucciso a Lugdunum nel 40 d.C. per ordine di Caligola; poi in Mauretania scoppiò la rivolta di Edemone e Claudio nel 44 divise il paese in due province, Tingitana e Cesariense.", "87e30934"]},
"OLAYLAR_ANTIK_AKDENIZ:0043-01-01:0":{"b": ["Claudio invase la Britannia", "f42ba7f7"], "d": ["Nel 43 d.C. quattro legioni al comando di Aulo Plauzio sbarcarono sulla costa del Kent; Camulodunum (Colchester) fu presa e Claudio si trattenne brevemente in città. Il sud della Britannia divenne una nuova provincia romana.", "96a1d864"]},
"OLAYLAR_ANTIK_AKDENIZ:0046-01-01:0":{"b": ["Roma fece della Tracia una provincia: la dinastia odrisia terminò", "af2ba1b2"], "d": ["Dopo l'uccisione del re di Tracia Remetalce III da parte della moglie e il successivo disordine, Claudio nel 46 trasformò la Tracia in provincia romana. È uno degli ultimi passi che completarono l'ordinamento provinciale romano nei Balcani orientali.", "4d5f0125"]},
"OLAYLAR_ANTIK_AKDENIZ:0106-01-01:0":{"b": ["Traiano conquistò la Dacia: Sarmizegetusa cadde, Decebalo morì, fu istituita la provincia di Dacia", "a9277172"], "d": ["Nella Seconda Guerra Dacica (105-106) Traiano prese Sarmizegetusa; Decebalo si uccise per sfuggire alla cattura. La Dacia divenne provincia romana e le miniere d'oro furono legate all'economia romana. Le fasi precedenti della guerra (101-105) hanno voci a parte nella cronologia.", "ba1d2c29"]},
"OLAYLAR_ANTIK_AKDENIZ:0122-01-01:0":{"b": ["Adriano iniziò in Britannia la costruzione del Vallo sul confine settentrionale", "f4a886ec"], "d": ["Adriano, dopo aver visitato la Britannia nel 122 d.C., fece costruire un muro di confine lungo la linea Tyne-Solway. Il Vallo simboleggia la politica di confine difensiva di Roma; l'avanzata fu tentata con il Vallo Antonino (142) ma non fu duratura.", "1486c2c9"]},
"OLAYLAR_ANTIK_AKDENIZ:0198-01-01:0":{"b": ["Settimio Severo fece della Mesopotamia una provincia; Ctesifonte fu saccheggiata", "df466924"], "d": ["Settimio Severo nella guerra partica (195-198) prese Nisibis, saccheggiò Ctesifonte e organizzò l'Alta Mesopotamia come provincia romana. La provincia portò l'avanzata più orientale di Roma nel III secolo.", "1707eedd"]},
"OLAYLAR_ANTIK_AKDENIZ:0212-01-01:0":{"b": ["Constitutio Antoniniana: la cittadinanza romana fu concessa a tutti gli abitanti liberi dell'impero", "dd4e4024"], "d": ["Caracalla nel 212 d.C. fece cittadini romani gli abitanti liberi delle province; nell'impero cadde la distinzione tra cittadini e stranieri. Il provvedimento ampliò anche la base fiscale.", "b9e20124"]},
"OLAYLAR_ANTIK_AKDENIZ:0260-01-01:0":{"b": ["Postumo fondò in Gallia l'Impero gallico separatista", "4dcda41d"], "d": ["Dopo la cattura di Valeriano da parte dei Parti (260) Postumo, con gli eserciti del Reno, proclamò un impero in Gallia; Gallia, Britannia e gran parte della Hispania si staccarono da Roma fino al 274. Gallieno non poté eliminare la secessione.", "f1eada99"]},
"OLAYLAR_ANTIK_AKDENIZ:0271-01-01:0":{"b": ["Aureliano evacuò la Dacia: il nord del Danubio fu abbandonato", "db2ca714"], "d": ["Per la pressione dei Goti Aureliano evacuò la provincia di Dacia e ritirò le legioni e la popolazione civile a sud del Danubio (Dacia Ripensis). Roma, dopo 165 anni, lasciò il primo grande territorio a nord del Danubio.", "3e19ae74"]},
"OLAYLAR_ANTIK_AKDENIZ:0272-01-01:0":{"b": ["Aureliano sconfisse l'Impero di Palmira: i territori orientali di Zenobia tornarono a Roma", "0a358790"], "d": ["Aureliano nel 272 sconfisse l'esercito di Zenobia ad Antiochia e a Emesa e assediò Palmira; Zenobia fu catturata. Siria, Egitto e sud dell'Anatolia furono nuovamente legati a Roma.", "7b626384"]},
"OLAYLAR_ANTIK_AKDENIZ:0274-01-01:0":{"b": ["Aureliano sconfisse l'Impero gallico: Roma fu riunificata", "c1a6a642"], "d": ["Aureliano nel 274 sconfisse Tetrico ai Campi Catalaunici; Gallia, Britannia e Hispania tornarono a Roma. L'impero, dopo 14 anni di divisione, si riunì e Aureliano assunse il titolo di «Restitutor Orbis» («colui che ricostituisce il mondo»).", "872ee29d"]},
"OLAYLAR_ANTIK_AKDENIZ:0358-01-01:0":{"b": ["Giuliano stabilì i Franchi Salii a Toxandria come foederati romani", "0fb618fe"], "d": ["Il Cesare Giuliano nel 358 sconfisse i Franchi Salii e permise loro di stabilirsi in territorio romano a Toxandria (odierno confine olandese-belga). È l'inizio dell'insediamento, sotto la protezione romana, della regione in cui sarebbe nato il regno franco.", "ab1db90c"]},
"OLAYLAR_ANTIK_AKDENIZ:0375-01-01:0":{"b": ["Gli Unni attraversarono il Don e attaccarono Alani e Ostrogoti: inizio delle Grandi Migrazioni", "659eb875"], "d": ["Secondo Ammiano gli Unni nel 375 attraversarono il Don e sconfissero gli Alani, poi distrussero il regno del re ostrogoto Ermanarico; il popolo visigoto (Tervingi) si trovò allora spinto sul Danubio. Così in Europa iniziò l'epoca del dominio degli Unni.", "bc56aef2"]},
"OLAYLAR_ANTIK_AKDENIZ:0376-01-01:0":{"b": ["I Goti Tervingi attraversarono il Danubio e si stabilirono in territorio romano", "3e9de0e6"], "d": ["Per la pressione degli Unni i Goti Tervingi di Fritigerno nel 376 ottennero da Valente il permesso di attraversare il Danubio e stabilirsi in territorio romano; i problemi di rifornimento e di amministrazione si trasformarono in rivolta. L'esito fu la sconfitta di Adrianopoli nel 378.", "ce90a65f"]},
"OLAYLAR_ANTIK_AKDENIZ:0406-12-31:0":{"b": ["Vandali, Alani e Svevi attraversarono il Reno ed entrarono in Gallia", "2b3354ba"], "d": ["Alla data tradizionale del 31 dicembre 406 (sul Reno gelato) Vandali, Alani e Svevi entrarono nella Gallia romana; la difesa del Reno crollò. Il successivo passaggio in Spagna (409) staccò province fondamentali dell'Impero romano d'Occidente.", "2dbbe2e6"]},
"OLAYLAR_ANTIK_AKDENIZ:0409-01-01:0":{"b": ["Vandali, Alani e Svevi passarono in Spagna: la Hispania fu spartita", "b7036608"], "d": ["Gruppi di Vandali, Alani e Svevi, che nell'autunno del 409 avevano attraversato i Pirenei dalla Gallia, nel 411 si spartirono la penisola: Asdingi e Svevi presero la Gallaecia, i Silingi la Betica, gli Alani la Lusitania e la Cartaginense. I Visigoti (416-418), schiacciati Silingi e Alani, prepararono il passaggio dei Vandali in Africa.", "28caca34"]},
"OLAYLAR_ANTIK_AKDENIZ:0418-01-01:0":{"b": ["Roma stabilì i Visigoti in Aquitania Seconda: regno visigoto con centro a Tolosa", "38a7699e"], "d": ["Roma, al comando di Costanzo, dopo aver usato i Visigoti di Vallia in Hispania contro Vandali e Alani, nel 418 li insediò come foederati nell'Aquitania Seconda, nella valle della Garonna. Il regno visigoto con centro a Tolosa è considerato il primo regno germanico su suolo romano.", "49ca3c3f"]},
"OLAYLAR_ANTIK_AKDENIZ:0434-01-01:0":{"b": ["Trattato di Margus: gli Unni ottennero da Roma 700 libbre d'oro all'anno", "833d8854"], "d": ["Dopo la morte del re unno Rua (433/4) Attila e Bleda conclusero a Margus un trattato con Roma d'Oriente: il tributo annuo fu portato da 350 a 700 libbre d'oro e furono restituiti i rifugiati unni. Gli Unni ottennero il diritto di commerciare sul confine del Danubio.", "d18e188d"]},
"OLAYLAR_ANTIK_AKDENIZ:0435-01-01:0":{"b": ["Trattato di Ippona: Roma riconobbe i Vandali come foederati in una parte di Numidia e Mauretania", "f7dba59f"], "d": ["Il re vandalo Genserico, passato in Africa nel 429, nel 435 concluse con Roma il trattato di Ippona; i Vandali tennero come foederati parte della Numidia e della Mauretania. Il trattato fu violato nel 439 con la presa di Cartagine.", "1cde8863"]},
"OLAYLAR_ANTIK_AKDENIZ:0441-01-01:0":{"b": ["Attila prese le fortezze del Danubio: Viminacium e Singidunum (Belgrado) passarono agli Unni", "0abb2c54"], "d": ["Poiché l'esercito di Roma d'Oriente era impegnato nella campagna di Sicilia e contro i Vandali, Attila nel 441 attraversò il Danubio; furono prese Margus, Viminacium e Singidunum. Anche Sirmio cadde in queste campagne e gli Unni giunsero nell'interno dei Balcani.", "93414c5c"]},
"OLAYLAR_ANTIK_AKDENIZ:0442-01-01:0":{"b": ["Roma e i Vandali conclusero un nuovo trattato: Africa Proconsolare, Bizacena e parte della Numidia restarono ai Vandali", "e5700ddc"], "d": ["Genserico, che aveva preso Cartagine (439), con il trattato concluso nel 442 con Valentiniano III rese giuridicamente terra vandala l'Africa Proconsolare, la Bizacena, l'Abaritana e parte della Numidia; Roma tenne solo la Mauretania e l'ovest della Numidia.", "3910a28d"]},
"OLAYLAR_ANTIK_AKDENIZ:0448-01-01:0":{"b": ["Pace di Anatolio: un'ampia striscia a sud del Danubio fu lasciata agli Unni", "ee8ad838"], "d": ["Dopo la sconfitta di Roma d'Oriente a Utus, Anatolio nel 447 fece pace con Attila: Roma lasciò agli Unni, a sud del Danubio, una striscia larga cinque giorni di cammino da Singidunum a Novae e il tributo annuo fu portato a 2100 libbre d'oro.", "591853fc"]},
"OLAYLAR_ANTIK_AKDENIZ:0451-01-01:0":{"b": ["Battaglia dei Campi Catalaunici (Châlons): Ezio e Teodorico I scacciarono Attila dalla Gallia", "80f10e32"], "d": ["Nel 451 Attila entrò in Gallia e assediò Orléans; la coalizione di Ezio e del re visigoto Teodorico I lo respinse nella Piana Catalaunica (con la morte di Teodorico). L'avanzata degli Unni in Europa occidentale si fermò così.", "89c6bc9e"]},
"OLAYLAR_ANTIK_AKDENIZ:0452-01-01:0":{"b": ["Attila entrò in Italia; Aquileia fu distrutta", "1349c67a"], "d": ["Nel 452 Attila entrò nell'Italia settentrionale da oltre le Alpi, rase al suolo Aquileia e saccheggiò la pianura padana; si ritirò per la malattia e per il contrattacco di Roma d'Oriente. Gli abitanti fuggiaschi di Aquileia formarono nelle lagune il nucleo di Venezia.", "cb78da70"]},
"OLAYLAR_ANTIK_AKDENIZ:0453-01-01:0":{"b": ["Attila morì; lo Stato unno si dissolse", "47009384"], "d": ["Attila morì nel 453 la notte delle nozze; la spartizione tra i figli e la rivolta dei sudditi germanici un anno dopo a Nedao (454) posero fine alla supremazia unna. Gli Unni si ritirarono nell'Europa orientale.", "f5a5a41d"]},
"OLAYLAR_ANTIK_AKDENIZ:0475-01-01:0":{"b": ["Il regno visigoto di Eurico si separò di fatto da Roma: l'Alvernia fu lasciata ai Visigoti", "4bbe7b0c"], "d": ["Eurico dal 466 ampliò il regno con conquiste in Hispania e Gallia; nel 475 Giulio Nepote, cedendo l'Alvernia, ne riconobbe di fatto la sovranità indipendente. Il regno visigoto controllava i territori dell'Impero romano d'Occidente dalla Loira al Mediterraneo.", "06af5e95"]},
"OLAYLAR_ANTIK_AKDENIZ:0480-01-01:0":{"b": ["Giulio Nepote fu ucciso in Dalmazia: l'ultimo imperatore legittimo d'Occidente", "3b965f33"], "d": ["Nepote, ritiratosi in Dalmazia dopo la deposizione di Romolo, fu ucciso nel 480; dopo la sua morte non rimase nessuno che rivendicasse il trono d'Occidente e Odoacre continuò il suo potere effettivo in Italia a nome di Zenone.", "4f4d9885"]},
"OLAYLAR_ANTIK_AKDENIZ:0489-08-28:0":{"b": ["Teodorico condusse gli Ostrogoti in Italia: Odoacre fu sconfitto sull'Isonzo e a Verona", "6a998bf8"], "d": ["Con il consenso dell'imperatore d'Oriente Zenone, Teodorico entrò in Italia nel 489, sconfisse Odoacre sull'Isonzo e a Verona; Odoacre si chiuse a Ravenna. L'assedio di tre anni terminò nel 493 con la resa di Ravenna.", "092f7492"]},
"OLAYLAR_ANTIK_AKDENIZ:0493-03-05:0":{"b": ["Teodorico fece uccidere Odoacre a Ravenna; l'Italia divenne del Regno ostrogoto", "5a2db0ed"], "d": ["Fine del Regno d'Italia di Odoacre: tutta l'Italia (comprese città come Genova, Brindisi, Aricia) passò al Regno degli Ostrogoti (Goti orientali). Dopo il lungo assedio di tre anni di Ravenna, nel marzo del 493 Odoacre e Teodorico si accordarono per un governo comune; poi Teodorico uccise Odoacre durante un banchetto. L'Italia divenne Regno ostrogoto con il consenso di Roma d'Oriente e la sua capitale è Ravenna.", "1024674c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0020-01-01:0":{"b": ["Pace di Samo: gli ambasciatori di Kush ottennero la pace da Augusto; Roma abolì il tributo imposto a Kush e il confine fu fissato nella Bassa Nubia (Hiera Sykaminos)", "c3c4c20d"], "d": ["Gli ambasciatori della Candace, guidati da Petronio, si recarono a Samo dove trovarono Augusto; Augusto accolse tutte le loro richieste e abolì anche i tributi imposti da Petronio a Kush. In seguito alla pace il confine romano-kushita si fissò a sud di File, sulla linea di Hiera Sykaminos (Maharraqa), e per circa trecento anni non vi furono scontri gravi.", "4ff5e832"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0022-01-01:0":{"b": ["Petronio condusse una campagna contro Kush e prese Pselchis, Premnis e Napata; pose una guarnigione a Ibrim", "4884ed51"], "d": ["Il prefetto Petronio, con circa diecimila fanti e ottocento cavalieri, sconfisse trentamila soldati kushiti, prese Pselchis, conquistò al primo assalto la fortezza di Premnis (Qasr Ibrim) e rase al suolo Napata, sede del palazzo della Candace. Ritenendo difficile avanzare oltre, sulla via del ritorno lasciò a Premnis una guarnigione di quattrocento uomini con viveri per due anni. Quando la Candace tentò di riprendere Premnis, Petronio accorse e difese la fortezza.", "672f8f4e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0024-01-01:0":{"b": ["Kush, sotto la guida della Candace, prese Elefantina, Siene e File; Augusto ne abbatté le statue", "aa665fad"], "d": ["Quando parte delle truppe romane in Egitto fu ritirata per la spedizione di Elio Gallo in Arabia, i Kushiti entrarono nella Tebaide; sconfissero la guarnigione di tre coorti a Siene, presero Siene, Elefantina e File, ridussero in schiavitù la popolazione e abbatterono le statue di Cesare. Strabone scrive che la regina che governava Kush in quel periodo era una donna con il titolo di «Candace», cieca da un occhio.", "63e07dc6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0028-01-01:0":{"b": ["Cornelio Gallo divenne il primo prefetto d'Egitto; represse le rivolte di Heroonpolis e Tebe e il confine con Kush fu assicurato", "9f688855"], "d": ["Ottaviano fece dell'Egitto una provincia speciale soggetta a tributo, affidandone l'amministrazione non a un senatore ma a un prefetto di rango equestre; il primo prefetto fu Cornelio Gallo. Strabone scrive che Gallo prese con pochi soldati una città ribelle a Heroonpolis e represse in breve tempo la rivolta scoppiata a Tebe per le tasse. La stele di Gallo a File riferisce che gli ambasciatori del sovrano di Kush furono ricevuti qui e che la regione del Triacontaschoinos fu posta sotto protezione.", "ae3f8fab"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0029-08-01:0":{"b": ["Ottaviano entrò ad Alessandria; lo Stato tolemaico terminò, l'Egitto passò a Roma", "553804ca"], "d": ["Dopo che la flotta e la cavalleria di Antonio passarono a Ottaviano, questi entrò ad Alessandria; Antonio si tolse la vita e poco dopo morì anche Cleopatra. Ottaviano risparmiò gli Alessandrini e, dicendo «volevo vedere un re, non dei morti», non visitò le tombe dei Tolomei; affidò l'Egitto, come paese soggetto a tributo, a Cornelio Gallo. Con questa data terminò il regno tolemaico, durato trecento anni.", "c1595889"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0030-09-02:0":{"b": ["Battaglia navale di Azio: Ottaviano sconfisse Antonio e Cleopatra", "7e46cc73"], "d": ["La flotta di Ottaviano sconfisse ad Azio la flotta di Antonio e Cleopatra; la coppia si ritirò in Egitto. Dione, autore che evita di fornire date, segnala questo giorno in particolare perché da allora Ottaviano tenne da solo l'impero e gli anni del suo potere furono contati da questo giorno.", "7747a2e5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0033-01-01:0":{"b": ["Donazioni di Alessandria: Antonio proclamò Cleopatra e i suoi figli sovrani dei regni orientali", "24e24981"], "d": ["Antonio, fatti erigere troni d'oro davanti alla folla riunita nel Ginnasio, proclamò Cleopatra regina d'Egitto, di Cipro, della Libia e della Celesiria, Cesarione suo co-sovrano e i suoi figli re di Armenia, Media, Partia e di Fenicia-Siria-Cilicia. A Roma questa cerimonia divenne propaganda contro Antonio e accelerò la guerra civile.", "dc9e5d73"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0035-01-01:0":{"b": ["Antonio donò a Cleopatra Cipro, la Fenicia, la Celesiria e parte della Cilicia", "cf19a357"], "d": ["Secondo Plutarco, quando giunse in Siria Antonio diede a Cleopatra la Fenicia, la Celesiria, Cipro, gran parte della Cilicia, la parte della Giudea che produce balsamo e la parte della Nabatea che si estende sul mare. Così lo Stato tolemaico, per la prima volta dai tempi di Tolomeo III, controllò un'ampia area del Mediterraneo orientale (nonostante l'ira di Roma).", "2c5122e4"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0046-01-01:0":{"b": ["Guerra alessandrina: Cesare sconfisse Tolomeo XIII e lasciò l'Egitto a Cleopatra", "96c9b516"], "d": ["Quando Cesare giunse ad Alessandria volendo fare da arbitro tra Cleopatra e Tolomeo XIII, le forze di palazzo lo assediarono; nei combattimenti di strada durati tutto l'inverno giunsero aiuti a Cesare e nella battaglia del Nilo Tolomeo XIII annegò. Cesare diede l'Egitto a Cleopatra e al fratello minore Tolomeo XIV; le legioni romane rimasero ad Alessandria.", "bc41a5ff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0054-01-01:0":{"b": ["Gabinio rimise Tolomeo XII sul trono d'Egitto con un esercito romano; a Alessandria rimase una guarnigione romana", "41d8f47d"], "d": ["Il deposto Tolomeo XII (Aulete), con una grossa tangente al governatore di Siria Gabinio, si comprò l'ingresso in Egitto; Gabinio, lasciata la campagna partica, entrò in Egitto da Pelusio e riportò Aulete sul trono. Questo è il momento in cui l'indipendenza dell'Egitto fu di fatto vincolata alla garanzia romana. Gabinio fu poi processato a Roma.", "2ebc08ef"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0057-01-01:0":{"b": ["Roma tolse Cipro ai Tolomei e la annesse; Catone fu mandato sull'isola", "678b2115"], "d": ["Il re di Cipro, fratello di Tolomeo XII, non si oppose alla presa dell'isola da parte di Roma su proposta di Clodio; Catone fu inviato a prendere in consegna l'isola. Lo Stato tolemaico perse Cipro e l'ultima base navale sulla costa. Plutarco ricorda l'«invio di Catone a Cipro» nella vita di Pompeo.", "2ec72ea2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0167-01-01:0":{"b": ["«Giorno di Eleusi»: l'ambasciatore romano Popilio Lenate costrinse Antioco IV a ritirarsi dall'Egitto", "e6883e6a"], "d": ["Subito dopo la battaglia di Pidna (22 giugno 168 a.C.), l'ambasciatore romano Gaio Popilio Lenate comunicò ad Antioco, che assediava Alessandria, l'ordine del Senato di porre fine alla guerra; tracciò un cerchio attorno al re perché ponderasse la risposta. Antioco si ritirò. L'Egitto mantenne la propria indipendenza sotto la protezione di Roma senza perderla.", "4831dad7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0168-01-01:0":{"b": ["Antioco IV attaccò l'Egitto; nella Sesta Guerra di Siria avanzò su Menfi e Naucrati", "b85e6712"], "d": ["Antioco IV, in risposta ai preparativi di Tolomeo VI per riprendere la Celesiria, entrò in Egitto e scese da Pelusio al Nilo; difese il proprio diritto sulla Celesiria e a Naucrati trattò bene la popolazione. La guerra, senza distruggere l'Egitto ma indebolendo lo Stato, terminò un anno dopo per l'intervento di Roma.", "f329f8b1"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0185-01-01:0":{"b": ["La rivolta di Tebe fu repressa: Comano riportò l'Alto Egitto sotto il dominio tolemaico", "4c0e4f10"], "d": ["Dopo circa vent'anni di governo separatista, il comandante tolemaico Comano riprese Tebe al faraone indigeno Ankhwennefer e l'Alto Egitto fu di nuovo unito allo Stato tolemaico.", "24386cc8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0195-03-27:0":{"b": ["Il sinodo di Menfi emanò il Decreto di Rosetta: Tolomeo V concesse esenzioni fiscali ai templi", "5643b91f"], "d": ["Il sinodo riunito a Menfi dai sacerdoti egiziani, confermando l'ascesa al trono di Tolomeo V, proclamò le esenzioni fiscali concesse dal re ai templi, la repressione delle rivolte e l'istituzione del culto del re. Il decreto fu scritto in greco, demotico e geroglifico; la Stele di Rosetta è questo testo trilingue. Il testo accenna anche alla repressione dei ribelli del Delta (Licopoli).", "80eb0165"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0199-01-01:0":{"b": ["Battaglia di Paneion: Antioco III sconfisse Scopa; la Celesiria passò dai Tolomei ai Seleucidi", "97e30e58"], "d": ["Nella Quinta Guerra di Siria Antioco III sconfisse a Paneion il comandante tolemaico, l'etolo Scopa; secondo Giuseppe Flavio Antioco riprese le città della Celesiria prese da Scopa e conquistò anche la Samaria, e i Giudei si unirono ad Antioco di loro volontà. La Celesiria (Siria-Palestina) passò da allora sotto il dominio seleucide; lo Stato tolemaico si ritirò dalla regione.", "930d7d22"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0204-01-01:0":{"b": ["A Tebe comparvero faraoni indigeni separatisti: l'Alto Egitto si staccò dal dominio tolemaico", "d10abb36"], "d": ["Gli Egiziani indigeni, armati dopo la vittoria di Rafia, secondo l'espressione di Polibio, inorgogliti dalla vittoria non obbedivano più agli ordini del re; scoppiarono rivolte nel Delta e nell'Alto Egitto. A Tebe i faraoni indigeni (Horwennefer, poi Ankhwennefer) tennero l'Alto Egitto contro i Tolomei per circa vent'anni.", "aed92c1c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0216-01-01:0":{"b": ["Battaglia di Rafia: Tolomeo IV sconfisse Antioco III; la Celesiria rimase ai Tolomei", "34362178"], "d": ["A Rafia l'esercito di Tolomeo IV, composto anche da un gran numero di falangiti (opliti) egiziani indigeni, sconfisse l'esercito di Antioco III; Antioco si ritirò dalla Celesiria e la regione rimase in mano tolemaica fino al 200. L'armamento degli Egiziani indigeni alimentò poi le rivolte separatiste dell'Alto Egitto.", "e5e7e848"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0218-01-01:0":{"b": ["Antioco III riprese Seleucia di Pieria ai Tolomei", "39ee3a52"], "d": ["Antioco III assediò Seleucia di Pieria, in mano tolemaica, e la prese corrompendo gli ufficiali; Polibio scrive che la città era tenuta dai tempi di Tolomeo III da una guarnigione appartenente ai re d'Egitto. Con questa vittoria i Seleucidi riottennero il porto di Antiochia e si prepararono alla marcia sulla Celesiria (Quarta Guerra di Siria).", "6964f9b2"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0245-01-01:0":{"b": ["Nella Guerra Laodicea Tolomeo III invase la Siria e la Mesopotamia; Seleucia di Pieria passò ai Tolomei", "04472253"], "d": ["Tolomeo II morì il 28 gennaio 246 a.C.; Tolomeo III attaccò lo Stato seleucide per proteggere la sorella Berenice. Fu accolto a Seleucia di Pieria e ad Antiochia; la Cronaca di Babilonia (BCHP 11) riferisce che il suo esercito arrivò a Babilonia dal dicembre 246 a.C. L'iscrizione di Adulis sostiene che conquistò le terre a ovest dell'Eufrate, la Cilicia, la Panfilia e la Tracia. Seleucia di Pieria rimase per molti anni in mano tolemaica.", "54ffdc9c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0300-01-01:0":{"b": ["Dopo Ipso Tolomeo occupò la Celesiria; Seleuco protestò (origine delle Guerre di Siria)", "a109388f"], "d": ["Dopo la battaglia di Ipso (301 a.C.) Seleuco, Lisimaco e Cassandro si accordarono assegnando l'intera Siria a Seleuco; Tolomeo invece occupò con le armi la Celesiria e la tenne. Questa controversia generò nei due secoli seguenti sei Guerre di Siria. Antioco III sostenne poi questa pretesa, come riferito da Polibio.", "21348480"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0304-01-01:0":{"b": ["Tolomeo si proclamò re; la dinastia tolemaica fu ufficialmente fondata", "008c723a"], "d": ["Dopo che Antigono e Demetrio ebbero assunto il titolo di re (306 a.C.), anche Tolomeo assunse il titolo regale; l'Egitto iniziò a essere indicato come regno ellenistico indipendente. La presentazione della dinastia come faraoni d'Egitto accelerò anche l'intesa con la classe sacerdotale indigena.", "318a8821"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0311-01-01:0":{"b": ["Battaglia di Gaza: Tolomeo e Seleuco sconfissero Demetrio (la Siria passò per poco ai Tolomei)", "ea0d264f"], "d": ["Demetrio, figlio di Antigono, fu sconfitto davanti a Gaza dall'esercito congiunto di Tolomeo e Seleuco; Tolomeo entrò in Celesiria. Con la controffensiva di Antigono la regione fu di nuovo perduta poco dopo e la pace (311 a.C.) lo fissò.", "619ae833"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0320-01-01:0":{"b": ["La spedizione di Perdicca in Egitto fallì al passaggio del Nilo; Perdicca fu ucciso dal suo stesso esercito", "c1792117"], "d": ["Nella guerra dei Diadochi Perdicca, reggente di Alessandro, entrò in Egitto contro Tolomeo, che aveva sottratto il corteo funebre di Alessandro, ma non riuscì ad attraversare il Nilo, perse molti uomini e fu ucciso dai suoi ufficiali. Tolomeo tenne l'Egitto.", "0057b746"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0321-01-01:0":{"b": ["Tolomeo annesse Cirene (Cirenaica) all'Egitto", "65316c50"], "d": ["Tolomeo, intervenendo nelle lotte interne di Cirene, annesse all'Egitto la Cirenaica, in Libia, con il comando di Ofella. Così l'Egitto tolemaico si estese anche a ovest; la Cirenaica nei secoli seguenti rimase in mano a un ramo della dinastia tolemaica.", "5d0e2ba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0330-01-01:0":{"b": ["Alessandro consultò l'Oracolo di Ammone nell'Oasi di Siwa", "c437ced0"], "d": ["Alessandro dalla costa passò nel deserto e si recò all'Oasi di Siwa, dove si trova il Tempio di Ammone, e consultò l'oracolo; Arriano scrive che ricevette la risposta gradita. Questa visita alimentò la legittimità di Alessandro in Egitto e i racconti sulla sua successiva considerazione come figlio del dio.", "40603afa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0331-01-01:0":{"b": ["Alessandro entrò in Egitto; il satrapo persiano Mazace si arrese, l'Egitto passò sotto il dominio macedone", "c4a5f014"], "d": ["Partito da Gaza, Alessandro giunse al settimo giorno a Pelusio, dove era arrivata anche la sua flotta. Il satrapo Mazace, rimasto senza sostegno persiano dopo Isso, non oppose resistenza e accolse amichevolmente Alessandro nelle città. Alessandro pose una guarnigione a Pelusio e avanzò su Menfi; affidò l'amministrazione a due governatori indigeni (Doloaspi, Petisis) e nominò comandanti macedoni a Menfi e Pelusio. L'Egitto uscì dal dominio persiano e fu incorporato nell'impero di Alessandro.", "08c837eb"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0342-01-01:0":{"b": ["Artaserse III riconquistò l'Egitto; Nectanebo II fuggì in Nubia", "55d78a8d"], "d": ["Nella marcia di Artaserse III verso l'Egitto dopo la presa di Sidone la difesa di Pelusio crollò; Nectanebo II, senza attendere l'assedio a Menfi, fuggì nell'Alto Egitto e in Nubia. L'Egitto divenne per la seconda volta satrapia persiana; la sorte dell'ultimo faraone indigeno è ignota.", "373a5f39"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0359-01-01:0":{"b": ["Tacos partì per la campagna di Siria; Nectanebo II prese il trono con un colpo di Stato, Agesilao cambiò schieramento", "4e1e9804"], "d": ["Tacos radunò mercenari greci (il re di Sparta Agesilao e l'ateniese Cabria) per attaccare la Siria persiana; mentre era in campagna il nipote Nectanebo II si proclamò re. Agesilao si schierò con Nectanebo; Plutarco scrive che in Grecia fu criticato il fatto che Agesilao in vecchiaia combattesse a pagamento per un «ribelle barbaro».", "d9ffa449"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0372-01-01:0":{"b": ["Nectanebo I respinse l'invasione persiana (Farnabazo-Ificrate)", "0a8bc67d"], "d": ["Nectanebo I, fondatore della XXX dinastia, respinse lo sbarco nel Delta dell'esercito persiano al comando di Farnabazo e dell'ateniese Ificrate grazie alla piena del Nilo e ai dissidi tra i comandanti. Questo successo prolungò l'indipendenza dell'Egitto di altri 30 anni.", "edb11f45"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0459-01-01:0":{"b": ["Rivolta di Inaro: l'insurrezione egiziana sostenuta da Atene strinse i Persiani a Menfi, crollò a Prosopitide nel 454", "0cd93c33"], "d": ["Il libico Inaro sollevò contro Artaserse quasi tutto l'Egitto e chiese aiuto agli Ateniesi; la flotta ateniese entrò nel Nilo e prese due terzi di Menfi, assediando la restante «Fortezza Bianca». Il comandante persiano Megabizo assediò per un anno e sei mesi gli Ateniesi nell'isola di Prosopitide (prosciugando il canale) e li annientò; Inaro fu catturato e crocifisso. Amirteo, nelle paludi del Delta, non fu invece catturato.", "452e1e06"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0485-01-01:0":{"b": ["L'Egitto si ribellò al dominio persiano; Serse I represse la rivolta e governò l'Egitto in modo più duro", "9d3d7462"], "d": ["La rivolta egiziana iniziata prima della morte di Dario I fu repressa nei primi anni di Serse I; Serse nominò satrapo il fratello Achemene e cominciò a governare l'Egitto in modo più duro che ai tempi di Dario.", "db4dbf1d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0522-01-01:0":{"b": ["La spedizione di Cambise a Kush fallì per la sete e la mancanza di viveri; il confine meridionale dell'Egitto rimase a Elefantina", "4ebbad8c"], "d": ["Dopo l'Egitto, Cambise progettò una spedizione contro i «Etiopi Longevi» (Kush); secondo Erodoto il re di Kush inviò un arco agli ambasciatori persiani dicendo di attaccare «quando fossero riusciti a tendere l'arco facilmente». L'esercito rimase senza viveri nel deserto e tornò indietro. Anche Strabone ricorda il luogo dove l'esercito di Cambise perì in una tempesta nel deserto. Kush rimase indipendente; il confine meridionale dei Persiani si fermò a Elefantina.", "141a4dc5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0569-01-01:0":{"b": ["Amasi sconfisse Apries e salì sul trono d'Egitto; i mercanti greci furono stabiliti a Naucrati", "75a24b0b"], "d": ["Apries, tornato dalla campagna di Libia con mercenari greci, fu sconfitto a Momemfi da Amasi, messosi a capo delle truppe indigene dell'esercito; Amasi governò l'Egitto da Sais e assegnò ai Greci Naucrati come unico porto di commercio. Alla fine del suo potere (526 a.C.) crebbe la minaccia persiana.", "821328d0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0592-01-01:0":{"b": ["Psammetico II condusse una campagna in Nubia: la pressione di Kush sul confine egiziano fu spezzata", "8f0aaf9d"], "d": ["La campagna nubiana di Psammetico II è ricordata da Erodoto come «spedizione in Etiopia»; l'esercito egiziano e i mercenari greci/cari lasciarono iscrizioni in greco ad Abu Simbel. La stele dell'anno 3 a Tebe (Karnak) riferisce che fu inflitta una grave sconfitta al regno di Kush e la stele della vittoria di Kalabsha la ricorda; si ritiene che la campagna sia giunta fino alla Terza o Quarta Cateratta. Secondo le fonti, il centro politico di Kush si spostò più tardi (Aspelta, ca. 591 a.C.) a sud, a Meroe.", "17c955db"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0600-01-01:0":{"b": ["Nabucodonosor attaccò il confine egiziano; in battaglia campale entrambe le parti subirono gravi perdite, Babilonia si ritirò", "45655313"], "d": ["Il re di Babilonia Nabucodonosor nel suo quarto anno marciò contro l'Egitto; il re d'Egitto radunò l'esercito e gli andò incontro, e in una battaglia campale le due parti si logorarono gravemente a vicenda. Nabucodonosor tornò a Babilonia per riequipaggiare l'esercito. L'Egitto difese il proprio confine, ma la Siria-Palestina era rimasta a Babilonia.", "c561b28b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0604-01-01:0":{"b": ["Battaglia di Carchemish: Nabucodonosor sconfisse l'esercito egiziano; l'Egitto perse la Siria", "ba486ac1"], "d": ["Il principe ereditario Nabucodonosor con l'esercito babilonese attraversò l'Eufrate contro l'esercito egiziano a Carchemish e lo sbaragliò, annientò i fuggiaschi nella regione di Hamat e prese l'intera regione di Hamat. L'Egitto si ritirò dalla Siria tornando dietro il confine del Sinai; Babilonia divenne padrona della Siria-Palestina.", "61bb7c47"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0608-01-01:0":{"b": ["Necao II entrò in Siria-Palestina; sconfisse Giosia a Megiddo e avanzò verso l'Eufrate", "f887d6fd"], "d": ["Necao II, mirando a impadronirsi delle province occidentali dell'Assiria in rovina, marciò in Siria; fece uccidere a Megiddo Giosia, re di Giuda, che gli sbarrava il cammino. Erodoto dice: «Necao sconfisse i Siri a Magdolo e prese Cadite, grande città della Siria». Così l'Egitto controllò per breve tempo la Siria-Palestina fino all'Eufrate.", "573a58de"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0655-01-01:0":{"b": ["Psammetico I, facendo adottare la figlia Nitocri dalla Sposa del Dio di Tebe, prese il controllo dell'Alto Egitto", "bf768452"], "d": ["Nel suo nono anno Psammetico I fece mandare a Tebe la figlia Nitocri come figlia adottiva di Shepenupet (figlia del re di Kush Taharqa), Sposa del Dio di Tebe; Shepenupet cedette i suoi beni a Nitocri e il patrimonio dei templi di Tebe passò così ai Saiti. La stele di adozione mostra che Psammetico ottenne il pieno controllo di Tebe nel suo nono anno e che Tanutamani aveva perso l'Alto Egitto fino a quella data.", "f750f320"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0662-01-01:0":{"b": ["L'esercito assiro saccheggiò Tebe; Tanutamani si ritirò a sud, il dominio di Kush sull'Egitto crollò", "777fc1a5"], "d": ["Gli eserciti di Assurbanipal, inseguito Tanutamani da Menfi, avanzarono fino a Tebe e la saccheggiarono; i tesori dei templi di Tebe furono portati a Ninive. Tanutamani si ritirò in Nubia; il dominio di Kush sull'Alto Egitto si dissolse. Questo saccheggio è ricordato nell'Antico Testamento come «No-Amon» (Naum 3:8).", "3d4dea25"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:0":{"b": ["Iniziò la XXVI dinastia: Psammetico I giunse al potere nel Basso Egitto a Sais come vassallo assiro", "f270eac3"], "d": ["Tra i principi del Delta insediati dall'Assiria in Egitto, il signore di Sais Psammetico I diede inizio alla XXVI dinastia (saitica). Secondo Erodoto Psammetico si distinse tra i «dodici re» e, spinto nella palude, riconquistò il Delta. Dopo l'Assiria e Kush l'Egitto passò di nuovo a una dinastia indigena; la conquista di Tebe e dell'Alto Egitto richiese alcuni anni.", "eaebf639"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0663-01-01:1":{"b": ["Tanutamani scese da Kush e riprese Tebe e Menfi; assediò i vassalli assiri", "f84c87a4"], "d": ["Tanutamani, successore di Taharqa, secondo la Stele del Sogno, dopo l'incoronazione a Napata scese a nord lungo il fiume: a Elefantina fece offerte a Khnum, giunse a Tebe e a Menfi dove prese la città passando a fil di spada chi gli si opponeva, mentre i capi del Delta si nascosero o si sottomisero. Questa impresa minacciò l'assetto del Delta di Psammetico I e dell'Assiria e provocò la spedizione punitiva assira.", "d8ce2798"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0670-01-01:0":{"b": ["Asarhaddon entrò in Egitto e prese Menfi; Taharqa si ritirò a sud", "a138bcac"], "d": ["Il re assiro Asarhaddon nel suo decimo anno marciò sull'Egitto; l'esercito assiro compì un grande massacro in Egitto e il re di Kush Taharqa fuggì a sud. I principati del Delta divennero vassalli assiri; Menfi e il Nord dell'Egitto passarono temporaneamente in mano assira. Asarhaddon morì in viaggio due anni dopo, mentre partiva per una nuova campagna.", "4c58b398"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0700-01-01:0":{"b": ["Nella campagna di Giuda Sennacherib incontrò a Eltekeh l'esercito kushita-egiziano", "7f423351"], "d": ["Nella campagna di Canaan del re assiro Sennacherib, l'esercito egiziano kushita venne in aiuto di Giuda e combatté contro gli Assiri a Eltekeh; l'esercito assiro si ritirò senza poter prendere Gerusalemme. Giuseppe Flavio racconta che Sennacherib, venuto a sapere che il re di Kush Tirhaka stava arrivando con un grande esercito, lasciò Pelusio. Questo è il primo scontro diretto tra Kush-Egitto e Assiria.", "0bc942e3"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0724-01-01:0":{"b": ["Piye (Pankhi) scese in Egitto: sconfisse la coalizione di Tefnakht e sottomise i sovrani di Menfi e del Delta", "bb36f7c4"], "d": ["Tefnakht di Sais aveva formato un'alleanza che si estendeva dal Delta a Menfi e all'Egitto medio e assediava Eracleopoli. Piye, partito da Napata, nel suo ventunesimo anno scese a nord, prese le città alleate (Ermopoli, Menfi, Eliopoli) e accettò la sottomissione dei principi del Delta; poi tornò a Napata. Così Kush divenne capo dell'intero Egitto (XXV dinastia).", "8a8bbba6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0749-01-01:0":{"b": ["Il re di Kush (Napata) Kashta avanzò nell'Alto Egitto; estese la sua influenza a Elefantina e Tebe", "b0f5be7f"], "d": ["I re di Kush a Napata, approfittando della frammentazione dell'Egitto nel Terzo Periodo Intermedio, si rafforzarono verso nord. Dai monumenti si comprende che Kashta stabilì la sua influenza nell'Alto Egitto fino a Elefantina; Amenirdis I (sorella di Piye) della dinastia kushita fu installata a Tebe con il titolo di «Sposa del Dio» di Amon e questa carica divenne lo strumento di Kush su Tebe. Si preparò così il terreno per la fondazione della XXV dinastia.", "3540bb2c"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0924-01-01:0":{"b": ["Sheshonq condusse una campagna a Canaan: Gerusalemme e le città di Israele-Giuda entrarono nella lista di Karnak", "1607ae3a"], "d": ["La campagna di Sheshonq a Canaan concorda con il racconto biblico (1 Re 14:25), secondo cui nel quinto anno del re Roboamo egli ricevette tributo da Gerusalemme; nel Portale Bubastide a Karnak sono elencati circa 150 nomi di città (all'incirca cinquanta-sessanta d'Israele, un centinaio di Giuda). Anche Giuseppe Flavio racconta che Sisak prese Gerusalemme e portò via il tesoro. Questa campagna è la più lunga operazione esterna dell'Egitto nel Terzo Periodo Intermedio.", "13f6482e"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-0944-01-01:0":{"b": ["Sheshonq I (di discendenza meshwesh/libica) fondò la XXII dinastia; capitale Bubasti", "dae122c7"], "d": ["I generali meshwesh di origine libica si erano stabiliti nel Delta dopo il Nuovo Regno; tra loro Sheshonq I, dopo la XXI dinastia di Tanis, riunificò l'Egitto. Facendo del figlio il Sommo Sacerdote di Amon legò alla dinastia anche Tebe. Questa epoca portò una breve ripresa che riorientò l'Egitto verso la politica estera (campagna di Canaan).", "09d0b8f9"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1068-01-01:0":{"b": ["Il Nuovo Regno terminò: negli ultimi anni di Ramses XI Smendes (Tanis) nel Delta e il sommo sacerdote di Amon a Tebe divennero di fatto indipendenti", "1828ceb0"], "d": ["Nell'ultimo periodo di Ramses XI lo Stato centrale crollò: a Tebe il Sommo Sacerdote di Amon Herihor controlla l'Alto Egitto, nel Delta a Tanis governa Nesubanebdjed (Smendes); il Racconto di Wenamon registra questa divisione (il viaggio di Wenamon da Herihor a Smendes). Smendes fondò infine la XXI dinastia; in questo disordine anche la Nubia uscì dal controllo egiziano.", "2317479f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1176-01-01:0":{"b": ["Ramses III sconfisse i Popoli del Mare sulla terraferma (Djahy) e in mare nel Delta", "9068ae7b"], "d": ["Nell'ottavo anno di Ramses III, Peleset, Tjeker, Denyen, Shardana e altri Popoli del Mare si mossero verso il confine egiziano da terra e da mare; l'esercito egiziano li fermò prima al confine di Canaan, poi nella battaglia navale alle foci del Delta. I rilievi di Medinet Habu lo documentano. L'Egitto mantenne Canaan ma da quest'epoca la sua influenza nel Mediterraneo orientale cominciò a erodersi.", "a7654a37"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1208-01-01:0":{"b": ["Merenptah sconfisse nel Delta occidentale l'alleanza dei Libici e dei Popoli del Mare; a Canaan il nome «Israele» fu menzionato per la prima volta", "e512311e"], "d": ["Nel quinto anno di Merenptah i Meshwesh guidati dai Libu e i «Popoli venuti dal mare» (Ekwesh, Teresh, Lukka, Shardana, Shekelesh) invasero il Delta occidentale; l'esercito egiziano li disperse a Perire in una battaglia di sei ore. La stele della vittoria che racconta questi eventi nomina, a Canaan, Ascalona, Gezer, Yenoam e «Israele»; è la più antica menzione nota del nome di Israele.", "6a9d6afc"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1258-01-01:0":{"b": ["«Trattato Eterno» tra Ramses II e Hattusili III: la guerra egizio-ittita terminò", "100f2a75"], "d": ["Nel ventunesimo anno di Ramses II gli ambasciatori ittiti portarono a Pi-Ramses la tavoletta del trattato. Il trattato pose fine alla guerra di Siria durata circa quindici anni: le due parti rinunciarono a ulteriori progetti di conquista in Siria, strinsero un'alleanza difensiva e accettarono l'estradizione dei fuggiaschi e l'aiuto reciproco. Secondo il riassunto di Breasted, il confine non è indicato nel testo; le sfere d'influenza dei due Stati restarono quelle di fatto (la fascia Kadesh-Amurru agli Ittiti, Canaan all'Egitto).", "9b723519"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1273-01-01:0":{"b": ["Ramses II affrontò a Kadesh gli Ittiti di Muwatalli II; l'esito fu un pareggio", "f5ad96db"], "d": ["Ramses II incontrò l'esercito ittita davanti a Kadesh sull'Oronte; con l'imboscata dei carri da guerra ittiti l'esercito egiziano fu sul punto di essere disfatto, Ramses con le sue guardie contrattaccò e li respinse. La battaglia non diede esito decisivo; Kadesh e Amurru rimasero sotto il controllo ittita e il confine settentrionale dell'Egitto rimase di nuovo sulle coste di Canaan.", "b58cad94"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1293-01-01:0":{"b": ["Seti I condusse una campagna dal Canaan meridionale alla costa fenicia: l'Egitto riprese il dominio su Canaan e sulla costa libanese, prese Kadesh", "ad7bf1cd"], "d": ["Secondo i rilievi di Karnak, la campagna dell'anno 1 di Seti I sottomise prima i beduini Shasu, poi risalendo a nord attraverso la Palestina Peher e Beth-Shean, Yenoam, Tiro e i signori del Libano. Nella fila superiore dei rilievi è raffigurata anche la presa di Kadesh. Breasted osserva che il confine settentrionale stabile non si estendeva oltre la linea est-ovest lungo la costa fenicia e che la potenza ittita non fu spezzata; è lo sfondo della battaglia di Kadesh di Ramses II.", "aa320c30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1339-01-01:0":{"b": ["Nell'epoca di Amarna il dominio egiziano nella Siria settentrionale si dissolse; Amurru e Kadesh passarono nella sfera d'influenza ittita", "90d00c5a"], "d": ["Le lettere di Amarna (EA) mostrano che i vassalli della Siria settentrionale (Aziru di Amurru, i sovrani di Kadesh) giocavano tra Egitto, Mitanni e Hatti e che l'Egitto non poteva intervenire nella regione. In seguito alle campagne del re ittita Suppiluliuma I che logorarono il Mitanni, Amurru e Kadesh entrarono nell'influenza ittita; così il confine settentrionale dell'Egitto in Siria si ritirò a Canaan.", "c876708d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1347-01-01:0":{"b": ["Amenhotep IV (Akhenaton) trasferì la capitale d'Egitto ad Akhetaton (Amarna)", "53cadac3"], "d": ["Akhenaton, fatto del culto di Aton la religione di Stato, proclamò capitale una nuova città (Akhetaton) aperta nel deserto dell'Egitto medio; le «Stele di Confine» che ne fissano i limiti sono datate agli anni 4-5. Le lettere di Amarna mostrano che in quest'epoca i vassalli della Siria chiedevano aiuto ma l'Egitto non rispondeva.", "a7911bcf"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1424-01-01:0":{"b": ["Amenhotep II raggiunse Napata in Nubia ed eresse una stele di confine meridionale: il punto più meridionale dell'Egitto", "2f61f824"], "d": ["Amenhotep II, tornando dalla campagna di Siria (luglio), passò in Nubia; secondo le iscrizioni dei templi di Elefantina e Amada, dei sette principi portati dalla Siria ne fece appendere sei alle mura di Tebe e il settimo alle mura di Napata. Secondo Breasted il re eresse a Napata o poco oltre una stele che indicava il confine meridionale: il dominio effettivo dell'Egitto in Nubia si estese così oltre Tombos (Terza Cateratta) fino alla regione della Quarta Cateratta.", "31d51fb0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1446-01-01:0":{"b": ["Thutmosi III attraversò l'Eufrate ed entrò nelle terre del Mitanni; eresse una stele di confine a Naharin", "ebdbeebe"], "d": ["Nell'anno 33 Thutmosi III avanzò da Retenu, attraversò l'Eufrate, saccheggiò le città di Naharin ed eresse una stele di confine a est del fiume; ne pose una seconda accanto a quella del padre. Questa campagna è il punto più lontano a nord dell'influenza egiziana e mostra la soglia di uno scontro diretto con il Mitanni.", "e7a917e6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1456-01-01:0":{"b": ["Thutmosi III sconfisse a Megiddo la coalizione cananea guidata da Kadesh; Canaan e Siria entrarono sotto il dominio egiziano", "439dc6e8"], "d": ["Nel giorno 21 del primo mese di Shemu dell'anno 23 di Thutmosi III, davanti a Megiddo, fu sconfitta la coalizione cananea guidata dal sovrano di Kadesh; i nemici fuggirono in città e Megiddo si arrese dopo un lungo assedio. Questa campagna, registrata negli Annali di Karnak, rese permanente la dipendenza di Canaan e della Siria meridionale dall'Egitto e fu l'inizio dell'espansione dell'impero.", "8c75d558"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1498-01-01:0":{"b": ["Thutmosi I condusse una campagna in Asia fino alla riva dell'Eufrate (Naharin)", "50ce0679"], "d": ["Secondo le iscrizioni di Ahmose-Pennekhbet e Ahmose-Ebana, Thutmosi I dopo la campagna di Nubia condusse una grande spedizione a Naharin; Thutmosi III più tardi aggiunse la propria stele accanto a quella di confine eretta dal padre sull'Eufrate. È il primo periodo registrato in cui l'influenza egiziana giunse fino all'Eufrate.", "bc058844"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1524-01-01:0":{"b": ["Ahmose condusse una campagna nella Bassa Nubia e sottomise i montanari nubiani", "dbbd94b7"], "d": ["Ahmose, dopo aver sconfitto gli Asiatici, risalì il fiume a sud fino a Khent-hen-nefer e sottomise i montanari nubiani. Questa campagna è il primo passo del processo di annessione all'Egitto della Bassa Nubia, in mano a Kerma dai tempi della linea di fortezze del Medio Regno.", "df3be70d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1529-01-01:0":{"b": ["Ahmose prese Avaris, capitale degli Hyksos, e assediò e conquistò Sharuhen", "b7bb3099"], "d": ["Ahmose assediò e prese Avaris, nel Delta orientale; gli Hyksos fuggirono in Asia ed egli li inseguì fino a Sharuhen, nel Canaan meridionale. L'iscrizione di Ahmose figlio di Ebana riferisce che Sharuhen fu assediata per 6 anni. Così il Delta d'Egitto uscì dal controllo hyksos e l'Egitto fu in grado di esercitare un'influenza politica su Canaan.", "48e6f876"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1549-01-01:0":{"b": ["Ahmose I salì al trono a Tebe; iniziarono la XVIII dinastia e il periodo del Nuovo Regno", "0798cfa3"], "d": ["Ahmose, fratello di Kamose, ultimo re della XVII dinastia di Tebe, salì al trono da bambino; durante il suo regno avrebbe cacciato gli Hyksos dall'Egitto e ristabilito il dominio su Nubia e Canaan, dando inizio alla XVIII dinastia e al Nuovo Regno. L'ascesa al trono non è la fine degli Hyksos ma l'inizio della fase finale della lotta.", "a003c4aa"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1649-01-01:0":{"b": ["L'Egitto si divise in due: gli Hyksos (XV dinastia) governarono da Avaris il Basso e Medio Egitto, la XVII dinastia di Tebe l'Alto Egitto", "cd743737"], "d": ["I «sovrani stranieri» (Hyksos) di origine cananea stabilitisi ad Avaris, nel Delta orientale, fondarono la XV dinastia e governarono il Basso Egitto e l'Egitto medio fino a Cusae; la dinastia indigena XVII di Tebe teneva invece l'Alto Egitto. A sud di Tebe il regno di Kerma restava una potenza indipendente. Che Avaris fosse la capitale hyksos è confermato in Breasted dal racconto dell'assedio di Ahmose.", "6bb8eb9b"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1866-01-01:0":{"b": ["Sesostri III a Semna portò il confine meridionale dell'Egitto alla Seconda Cateratta; vietò il passaggio ai Nubiani", "753ef5fd"], "d": ["La stele di Semna di Sesostri III, datata all'anno 8, fissa il «confine meridionale»: è vietato ai Nubiani, salvo a chi giunge a Iken per commercio, attraversare questa linea per terra o per fiume. Il re creò nella Bassa Nubia una catena di fortezze (Buhen, Semna, Kumma, Uronarti e altre) e fermò l'espansione di Kerma verso nord. È il confine stabile più meridionale del Medio Regno in Nubia.", "e50a591d"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-1984-01-01:0":{"b": ["Amenemhat I fondò la XII dinastia; la capitale fu trasferita a Itj-tawy", "26c43dad"], "d": ["Amenemhat I, divenuto re da visir, fondò la XII dinastia e trasferì la capitale da Tebe a una nuova città (Itj-tawy) tra Menfi e il Fayum. Questa dinastia fondò il periodo più stabile del Medio Regno e il sistema di fortezze in Nubia.", "55432fe0"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2015-01-01:0":{"b": ["Montuhotep II sconfisse Eracleopoli e riunificò l'Egitto (Sematawy)", "dbc6136f"], "d": ["Verso il trentanovesimo anno di regno Montuhotep II, eliminando Eracleopoli, riunì Alto e Basso Egitto sotto un'unica amministrazione e aggiunse alla sua titolatura il nome «Colui che unisce le Due Terre» (Sematawy). Il governo centrale fu trasferito a Tebe; i poteri dei nomarchi furono ridotti.", "d3ad8b02"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2054-01-01:0":{"b": ["Montuhotep II salì al trono a Tebe; iniziò il Medio Regno e si intensificò la guerra contro Eracleopoli", "edde038d"], "d": ["Il lungo regno di Montuhotep II (51 anni) è considerato l'inizio del Medio Regno. Nella prima metà del suo regno Tebe fu in guerra con Eracleopoli; nel suo quattordicesimo anno, quando le forze di Eracleopoli profanarono il cimitero sacro di Abido, il re mandò l'esercito a nord. L'effettiva riunificazione dell'Egitto avvenne molto più tardi, verso il trentanovesimo anno del suo regno (voce seguente).", "5db4eeba"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2124-01-01:0":{"b": ["A Tebe iniziò la XI dinastia: la dinastia Intef fondò un regno indipendente nell'Alto Egitto", "0e021743"], "d": ["I nomarchi di Tebe della stirpe Intef assunsero il titolo regale e fondarono il proprio regno all'estremità meridionale dell'Alto Egitto (da Elefantina ad Abido). Un successivo Intef dichiara nella sua iscrizione di aver preso il nomo di Thinis, dove si trova Abido, e di aver «aperto tutte le sue fortezze»; così il confine tebano-eracleopolitano fu tracciato nei dintorni di Abido.", "eddec482"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2159-01-01:0":{"b": ["A Eracleopoli (Henen-nesut) IX-X dinastia: la dinastia dei Kheti governò l'Egitto settentrionale", "9dde2d0c"], "d": ["Nel Primo Periodo Intermedio il vuoto di Menfi fu riempito dalla dinastia di Eracleopoli; nomarchi fedeli come Tefibi, governatore di Siut nell'Egitto medio, combatterono a fianco di questo regno contro il sud (Tebe). L'iscrizione tombale di Siut racconta l'avanzata dei meridionali verso nord da Elefantina e il loro respingimento fino al «confine meridionale». L'Egitto si divise così in due potenze principali: Eracleopoli (Nord) e Tebe (Sud).", "5e8484b5"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2180-01-01:0":{"b": ["L'Antico Regno crollò: dopo Pepi II lo Stato centrale si dissolse, iniziò il Primo Periodo Intermedio", "0339e96b"], "d": ["Dopo il lunghissimo regno di Pepi II la VI dinastia terminò; il regno si divise in regioni in cui i nomarchi (governatori provinciali) erano di fatto indipendenti. Le iscrizioni tombali (Siut, Elefantina e altre) mostrano che i governatori locali datavano a proprio nome e mobilitavano i propri soldati. Le effimere VII-VIII dinastie di Menfi non riuscirono a controllare l'intero paese.", "67f3dd29"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2279-01-01:0":{"b": ["Le spedizioni del governatore di Elefantina Harkhuf nella terra di Yam: un legame diplomatico-commerciale oltre la Nubia", "705b9808"], "d": ["Il governatore di Elefantina Harkhuf compì per Merenra e Pepi II diverse spedizioni a sud, nella terra di Yam; la sua iscrizione descrive la via che controllava e i prodotti che portò. Nell'iscrizione tombale si conserva anche la lettera che il re bambino Pepi II gli scrisse. Queste spedizioni sono la registrazione dei contatti, al confine meridionale dell'Antico Regno, con le comunità pre-Kerma/dell'Antico Kerma.", "31a49890"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2299-01-01:0":{"b": ["Nella VI dinastia grande campagna al comando di Weni verso il confine di Canaan con truppe nubiane", "69c94c55"], "d": ["Secondo l'autobiografia di Weni il re radunò un esercito di decine di migliaia di uomini contro gli «Asiatici Abitanti delle Sabbie»; l'esercito era composto da truppe reclutate nell'Egitto meridionale (fino a Elefantina), nel Nord e anche dalle tribù della Nubia (Irtjet, Medja, Yam, Wawat, Kau). Il testo mostra che l'Antico Regno usava la Nubia come serbatoio di soldati e poteva condurre campagne fino al Canaan meridionale.", "4a1574fe"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2559-01-01:0":{"b": ["Fu costruita la Grande Piramide di Cheope (Khufu) a Giza", "282359fc"], "d": ["La piramide di Khufu, sovrano della IV dinastia, a Giza è il simbolo della mobilitazione di manodopera e risorse dell'Antico Regno. Il racconto dei sacerdoti egiziani riferito da Erodoto dipinge Khufu come un tiranno che chiuse i templi e costrinse il popolo a trasportare pietre; è lo sguardo dell'epoca successiva, non un documento coevo.", "6bc26700"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-2685-01-01:0":{"b": ["Gioser (III dinastia) salì al trono; periodo dell'Antico Regno e Piramide a Gradoni di Saqqara", "23e99ef4"], "d": ["Con il governo di Gioser (Netjerikhet) inizia l'Antico Regno con centro a Menfi; la Piramide a Gradoni, primo grande esempio di architettura in pietra, fu costruita per lui. In questo periodo lo Stato amministra dal centro la Valle del Nilo e il Delta; le miniere del Sinai e il confine con la Nubia (Elefantina) sono sotto il controllo dello Stato.", "3b6eb1c6"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:-3099-01-01:0":{"b": ["Narmer (Menes) unificò l'Alto e il Basso Egitto; iniziò la I dinastia e Menfi divenne capitale", "cd3fadb1"], "d": ["Narmer, sovrano dell'Alto Egitto (dintorni di Thinis/Abido), secondo la maggior parte degli egittologi è la stessa persona di Menes. Con l'annessione del Basso Egitto la Valle del Nilo e il Delta divennero per la prima volta un unico Stato. Secondo il racconto antico Menes fondò il sito di Menfi deviando il corso del Nilo; l'unificazione non è un evento unico ma il risultato di un lungo processo che prosegue da Naqada III.", "f5802ba8"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0069-07-01:0":{"b": ["Vespasiano fu proclamato imperatore ad Alessandria: il grano d'Egitto decise le sorti della guerra civile", "02b78348"], "d": ["Il prefetto d'Egitto Tiberio Alessandro fece prestare alle legioni di Alessandria giuramento di fedeltà a nome di Vespasiano; il giuramento fu prestato il 1 luglio e Vespasiano considerò questo giorno il giorno della propria ascesa al trono. L'esercito della Giudea prestò giuramento due giorni dopo alla presenza di Vespasiano. La produzione cerealicola dell'Egitto è considerata il sostegno strategico di questa impresa.", "da411a30"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0115-01-01:0":{"b": ["Rivolta giudaica in Egitto, a Cirene e a Cipro: sotto Traiano Roma la represse a fatica", "54787782"], "d": ["Mentre era in corso la campagna partica di Traiano, a Cirene i Giudei guidati da Andrea massacrarono Romani e Greci; secondo Dione eventi simili si verificarono in Egitto e a Cipro e il numero dei morti è indicato in centinaia di migliaia. Lusio Quieto, inviato da Traiano, represse la rivolta; fu vietato ai Giudei l'ingresso a Cipro.", "40f5a14f"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0172-01-01:0":{"b": ["Rivolta dei Bucoli: una rivolta nel Delta minacciò Alessandria, repressa da Avidio Cassio", "5f94e6bf"], "d": ["La popolazione del Delta detta Bucoli (pastori) si sollevò guidata da un sacerdote di nome Isidoro; secondo Dione i ribelli sconfissero un'unità romana e furono a un passo dal prendere Alessandria. Cassio, inviato dalla Siria, represse la rivolta disgregando le forze dei ribelli.", "ab9f3aff"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0175-01-01:0":{"b": ["Avidio Cassio si proclamò imperatore in Siria e in Egitto; fu ucciso tre mesi dopo", "ce33ca9d"], "d": ["Cassio, comandante delle province orientali, si proclamò imperatore alla notizia della morte di Marco Aurelio; la rivolta si estese alla Siria e all'Egitto (in Dione si legge che il governatore d'Egitto Flavio Calvisio, per il suo legame con la rivolta, non fu poi messo a morte ma esiliato in un'isola). Cassio, dopo un «sogno di impero» durato, secondo Dione, tre mesi e sei giorni, fu ucciso da uno dei suoi ufficiali; Marco Aurelio visitò Egitto e Siria senza punire nessuno.", "d3821bc7"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0270-01-01:0":{"b": ["Palmira (Zenobia) invase l'Egitto; il generale romano Probo fu sconfitto", "54568441"], "d": ["Il generale palmireno Zabda, agendo a nome di Zenobia, entrò in Egitto con un esercito di settantamila uomini; il generale romano Tenagino Probo riprese per un certo tempo Alessandria ma, sconfitto, si chiuse nella fortezza di Babilonia e, fatto prigioniero, si uccise. L'Egitto fu considerato per un anno o due parte dello Stato di Palmira a nome di Zenobia.", "ea44ec63"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0297-01-01:0":{"b": ["Domizio Domiziano fu proclamato imperatore in Egitto; Diocleziano represse la rivolta assediando Tebe e poi Alessandria", "3c765005"], "d": ["In reazione alla riforma fiscale e al ritiro delle unità romane verso il fronte partico, in Egitto Domizio Domiziano fu proclamato Augusto tra luglio e agosto 297; gran parte dell'Egitto, Alessandria compresa, lo riconobbe. In autunno Diocleziano represse i ribelli di Tebe e assediò Alessandria; Domiziano morì nel dicembre 297, la difesa della città fu continuata da Aurelio Achille e la città, dopo un assedio di circa otto mesi, si arrese con ogni probabilità nel marzo 298.", "8d6ec081"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0298-01-01:0":{"b": ["Diocleziano ritirò il confine meridionale dell'Egitto alla linea Elefantina/File; la Bassa Nubia fu lasciata ai Nobati", "725574bb"], "d": ["Procopio racconta che Diocleziano, vedendo il costo di mantenere il vasto deserto all'estremo sud dell'Egitto (Dodecascheno), lasciò la regione a sud di Elefantina ai Nobati e ai Blemmi e fissò il confine a Elefantina (si riferisce anche che in cambio fu stabilito un pagamento annuo). L'amministrazione romana si ritirò così dal confine di Hiera Sykaminos tracciato da Augusto.", "bba78e53"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0349-01-01:0":{"b": ["Il re di Aksum Ezana sconfisse Kush; il regno di Meroe terminò (ca. 350 d.C.)", "7c9d95d7"], "d": ["Il re di Aksum Ezana attaccò il regno di Kush, indebolito dalla pressione di Noba e Blemmi; le iscrizioni di Ezana raccontano la sua campagna contro i popoli Noba e Kasu (Kush) e a Meroe sono state trovate due iscrizioni greche frammentarie relative alla vittoria aksumita. Le ultime piramidi di Meroe sono datate alla metà del IV secolo; lo Stato di Kush si dissolse dividendosi nei regni di Nobatia, Makuria e Alodia.", "49687083"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0391-01-01:0":{"b": ["Teofilo fece demolire il Serapeo di Alessandria: il centro del culto pagano in Egitto fu chiuso", "119a26c7"], "d": ["Dopo gli editti di Teodosio I che vietavano i culti pagani, il vescovo di Alessandria Teofilo fece demolire il tempio di Serapide (Serapeo); la tensione in città tra cristiani e pagani culminò in questo evento. La sorte dei testi sacri e delle raccolte di libri è controversa.", "5128d07a"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0395-01-17:0":{"b": ["Teodosio I morì; l'impero fu diviso definitivamente in due, l'Egitto restò nell'Impero Romano d'Oriente (Arcadio)", "54a12472"], "d": ["Alla morte di Teodosio i figli Arcadio ebbe l'Oriente e Onorio l'Occidente; l'Egitto, pur essendo il principale fornitore del fabbisogno di grano di Roma, rimase provincia dell'Impero d'Oriente (bizantino) e nei secoli seguenti divenne la fonte di grano di Costantinopoli.", "c418b085"]},
"OLAYLAR_ANTIK_MISIR_NUBYA:0451-10-08:0":{"b": ["Concilio di Calcedonia: il patriarca di Alessandria Dioscoro fu condannato; la Chiesa egiziana si separò dalla Chiesa imperiale", "5d2d05c6"], "d": ["Quando il Concilio di Calcedonia condannò Dioscoro, patriarca di Alessandria d'Egitto, la maggior parte dei cristiani egiziani non accettò le decisioni; così in Egitto si separarono la Chiesa copta (egiziana) e la Chiesa imperiale (melchiti). Questa divisione preparò il terreno per il successivo allontanamento politico dell'Egitto da Bisanzio.", "0d1827cd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0019-01-01:0":{"b": ["Accordo tra Augusto e Fraate IV: furono restituite le insegne romane di Crasso", "be5f8bda"], "d": ["Le insegne romane perdute da Crasso e Antonio furono restituite ad Augusto da Fraate IV come gesto diplomatico. L'accordo consolidò l'Eufrate come confine romano-partico e lasciò l'Armenia come cuscinetto.", "8cca70ad"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0039-01-01:0":{"b": ["Pacoro e Labieno invasero la Siria e la Palestina", "68669aa1"], "d": ["Il principe partico Pacoro e Labieno, fuggito da Roma e rifugiatosi presso i Parti, invasero le province romane di Siria e presero Antiochia e la Palestina. Ventidio, generale di Antonio, nel 38 sconfisse i Parti a Gindaro e riprese la regione.", "c3d65f7c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0052-01-01:0":{"b": ["Battaglia di Carre (Harran): Surena annientò l'esercito romano di Crasso", "3a91cd75"], "d": ["Le legioni romane di Crasso furono sconfitte presso Harran dalla cavalleria e dagli arcieri a cavallo parti; Crasso fu ucciso. La battaglia è una delle più gravi sconfitte di Roma in Oriente e consolidò a favore dei Parti il confine sull'Eufrate.", "3f9d31bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0091-01-01:0":{"b": ["Silla e l'ambasciatore partico Orobazo si incontrarono sull'Eufrate; primo contatto diplomatico romano-partico", "f8913f2b"], "d": ["Silla, governatore di Cappadocia, incontrò sulla riva dell'Eufrate Orobazo, ambasciatore del re partico Mitridate II; Roma e i Parti stabilirono per la prima volta un contatto ufficiale. L'Eufrate sarebbe poi diventato il confine tra i due Stati.", "64f67e31"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0128-01-01:0":{"b": ["Antioco VII Sidete morì nella campagna contro i Parti; i Seleucidi non riuscirono a riprendere la Mesopotamia", "e5897112"], "d": ["Antioco VII Sidete nel 130-129 riprese ai Parti la Mesopotamia e la Media, ma negli acquartieramenti invernali, per una rivolta e un attacco partico, perse l'esercito e la vita. Questo fallimento pose fine alle pretese seleucidi in Oriente.", "0ceb2108"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0137-01-01:0":{"b": ["I Parti catturarono Demetrio II Nicatore; i Seleucidi persero definitivamente Babilonia e la Mesopotamia", "94a764ce"], "d": ["L'esercito partico di Mitridate I catturò il re seleucide Demetrio II e lo tenne alla corte partica. Mitridate annesse la Mesopotamia all'Impero partico; lo Stato seleucide, stretto verso la costa, si ritirò in Siria.", "d53eb877"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0166-01-01:0":{"b": ["Rivolta dei Maccabei: in Giudea iniziò l'insurrezione contro i divieti religiosi di Antioco IV", "41c25b76"], "d": ["Quando Antioco IV Epifane dedicò il Tempio di Gerusalemme a Zeus Olimpio e vietò le pratiche religiose giudaiche, a Modin si sollevarono Mattatia e i suoi figli. Giuda Maccabeo nel 164 riprese e purificò il Tempio (Hanukkah); nacque lo Stato degli Asmonei.", "ad039b3f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0170-01-01:0":{"b": ["Mitridate I salì al trono partico; iniziò il periodo di espansione dell'impero partico", "cc77639b"], "d": ["Mitridate I trasformò i Parti in un impero: prese la Media (147), Babilonia e Seleucia (141) e stabilì la sovranità su Elimaide e Persia. Ctesifonte sarebbe poi diventata capitale invernale.", "248f554a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0187-01-01:0":{"b": ["Pace di Apamea: i Seleucidi si ritirarono a ovest dei Monti Tauro e pagarono un'indennità", "f5197a70"], "d": ["Il trattato tra Roma e Antioco III assegnò l'Anatolia a ovest del Tauro agli alleati di Roma (Pergamo, Rodi); la flotta e il numero di elefanti seleucidi furono limitati e fu pagata un'indennità di 15.000 talenti. I Seleucidi divennero ormai uno Stato siro-mesopotamico.", "08e214af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0204-01-01:0":{"b": ["Campagna orientale di Antioco III (209-204): i re di Partia e Battriana furono resi tributari dei Seleucidi", "5c81f302"], "d": ["Antioco III marciò su Media, Partia e Battriana per riprendere i territori orientali perduti dai Seleucidi: Arsace II ed Eutidemo furono resi tributari. Dopo questa campagna Antioco assunse il titolo di «il Grande».", "473faaed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:0":{"b": ["Arsace I e Tiridate presero Parthava e fondarono lo Stato partico (arsacide)", "2cd572ca"], "d": ["Arsace, capo della tribù nomade dei Parni, rovesciò il satrapo seleucide Andragora, prese Parthava e divenne il primo re del regno partico; la sua capitale è Ecatompilo. Lo Stato partico sarebbe stato per i tre secoli seguenti il signore della Mesopotamia e dell'Iran.", "1fb67f39"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0249-01-01:1":{"b": ["Il satrapo di Battriana Diodoto si staccò dai Seleucidi; nacque il Regno Greco-Battriano", "52faafa6"], "d": ["Diodoto, satrapo di Battriana e Sogdiana, approfittando della debolezza di Antioco II dichiarò l'indipendenza. La Greco-Battriana costrinse il confine orientale dello Stato seleucide a ritirarsi da Parthava e dalla Battriana.", "ac02ccda"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0273-01-01:0":{"b": ["Prima Guerra di Siria (274-272): le forze seleucidi ripresero Damasco; fu fatta la pace", "0c17ee3d"], "d": ["Dopo aver sconfitto i Galati con la «battaglia degli elefanti» (275) e messosi al sicuro, Antioco I combatté di nuovo contro Tolomeo II: il generale seleucide riprese Damasco, Magas attaccò l'Egitto e infine nel 272 fu fatta la pace. La guerra è l'inizio della contesa tolemaico-seleucide per la Celesiria.", "20ab588f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0279-01-01:0":{"b": ["Guerra Cariana: Tolomeo II prese ad Antioco I Ionia, Caria, Licia, Panfilia e parte della Cilicia", "afe190ca"], "d": ["Con una breve e fortunata campagna Tolomeo II prese le coste meridionali e occidentali dell'Anatolia e raggiunse Damasco; vedendo che la forza di Antioco non era inferiore a quella del padre, concluse una tregua. Antioco accettò la perdita perché doveva riordinare le conquiste del padre nell'interno dell'Anatolia.", "868966e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0280-01-01:0":{"b": ["Seleuco I fu ucciso da Tolomeo Cerauno; Antioco I salì al trono", "4703b674"], "d": ["Seleuco, che aveva sconfitto Lisimaco a Curupedio e preso l'Anatolia, mentre passava in Europa fu pugnalato da Tolomeo Cerauno. Il figlio Antioco I ereditò lo Stato ma avrebbe avuto difficoltà nell'Anatolia occidentale.", "18a3f3a5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0299-01-01:0":{"b": ["Seleuco I fondò Antiochia (Antakya)", "f4b98967"], "d": ["Seleuco, dopo Ipso, fondò in Siria sulle rive dell'Oronte Antiochia, in nome del proprio padre; la città divenne la capitale occidentale del Regno seleucide e una delle più grandi città dell'Antichità. Seleucia sul Tigri era stata fondata in precedenza come capitale orientale.", "0ab29d65"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0300-01-01:0":{"b": ["Battaglia di Ipso: Seleuco e Lisimaco sconfissero Antigono; la Siria passò a Seleuco", "93bf2aa9"], "d": ["Nella battaglia decisiva delle guerre dei Diadochi Seleuco e Lisimaco sconfissero Antigono (Antigono morì in battaglia). L'intero Oriente e la Siria toccarono a Seleuco; Tolomeo invece, occupando la Celesiria, fu all'origine delle prime guerre di Siria.", "a2ab17a8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:0":{"b": ["Seleuco I fondò Seleucia sul Tigri", "032efabd"], "d": ["Seleuco fondò Seleucia sulle rive del Tigri presso Babilonia e cominciò a trasferirvi la popolazione di Babilonia. Con circa 300.000 abitanti Seleucia fu la più grande città ellenistica dell'Oriente e poi la città gemella della capitale dell'impero partico.", "a1aa43e3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0304-01-01:1":{"b": ["Seleuco I concluse un trattato in India con Chandragupta Maurya; Aracosia, Gedrosia e Paropamisadi furono lasciate ai Maurya", "3ef3bdee"], "d": ["Seleuco marciò in India per riprendere le satrapie indiane di Alessandro, ma si accordò con Chandragupta e cedette parte dei territori orientali in cambio di 500 elefanti da guerra. Il trattato portò il confine occidentale dell'Impero Maurya all'Hindu Kush e procurò a Seleuco gli elefanti per l'Occidente.", "95b2b8bb"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0309-01-01:0":{"b": ["Alessandro IV fu ucciso insieme alla madre Rossane; la dinastia argeade terminò", "3be9d974"], "d": ["Dopo la pace del 311, per ordine di Cassandro (secondo Diodoro, il carnefice fu Glaucia) furono uccisi Alessandro IV, dodicenne, e sua madre Rossane. Non rimase alcun sovrano nominale dell'Impero di Alessandro; i Diadochi si volsero a proclamare i propri regni (306-305 a.C.).", "46aa8fb2"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:0":{"b": ["Alessandro raggiunse Persepoli; la città e il tesoro passarono ai Macedoni", "c1dbaada"], "d": ["Dopo Susa, Alessandro, superate le Porte Persiane, raggiunse Persepoli alla fine di gennaio del 330; la città si arrese senza resistenza. Il possesso achemenide di Persepoli termina in quest'anno (il palazzo fu incendiato nel maggio del 330).", "de8726c8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-01-01:1":{"b": ["Incendio dei palazzi di Persepoli (aprile)", "6e6cdfe0"], "d": ["Alessandro nell'aprile del 330 fece incendiare a Persepoli diversi edifici di palazzo; come motivi si indicano che il tesoro non cadesse in mano nemica e che non vi fosse ancora un sovrano unico. Archeologicamente si vede che bruciò anche il Palazzo di Serse; l'intera città fu abbandonata.", "c22d037f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0329-07-01:0":{"b": ["Dario III fu ucciso da uomini di Besso, satrapo di Battriana; la dinastia achemenide terminò", "bedcca87"], "d": ["Dario III, fuggito da Ecbatana verso est, nel luglio del 330 in Partia fu ferito e abbandonato da Besso e dai suoi seguaci e morì; Alessandro mandò il corpo a Persepoli. Fine effettiva dell'Impero achemenide.", "dc8ceef3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-01:0":{"b": ["Battaglia di Gaugamela: Alessandro sconfisse definitivamente l'esercito di Dario III", "a5b082d7"], "d": ["A Gaugamela l'esercito di Dario, composto da numerosi carri da guerra e cavalleria, si disperse nell'attacco in cui Alessandro, con la difesa dell'ala sinistra, sfondò e penetrò; Dario fuggì ancora. La battaglia decise la fine dell'Impero persiano; Babilonia e Susa aprirono le porte.", "b31c6746"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-10-22:0":{"b": ["Alessandro entrò a Babilonia; Mazeo consegnò la città e la satrapia di Babilonia passò ad Alessandro", "c8d2afb3"], "d": ["Dopo Gaugamela il satrapo di Babilonia Mazeo aprì le porte ad Alessandro; Alessandro ordinò il restauro del tempio di Marduk e usò la città per 34 giorni. Babilonia passò dal dominio persiano a quello macedone.", "b84160e8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0330-12-15:0":{"b": ["Alessandro prese Susa; il tesoro persiano fu catturato", "fbf417db"], "d": ["Partito da Babilonia, Alessandro entrò a Susa; il satrapo Abulite consegnò la città e il grande tesoro. Susa divenne la base finanziaria della campagna orientale macedone.", "b65699b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0331-01-01:0":{"b": ["Assedio di Tiro: Alessandro prese e distrusse la città sull'isola costruendo un terrapieno", "89ede146"], "d": ["Alessandro prese in sette mesi l'isola di Tiro, base della flotta persiana, costruendo un passaggio artificiale; la città fu saccheggiata e gran parte della popolazione fu uccisa o ridotta in schiavitù. La potenza navale persiana crollò e la via per l'Egitto fu aperta.", "22842728"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0332-11-01:0":{"b": ["Battaglia di Isso: Alessandro sconfisse Dario III; Dario abbandonò la famiglia e fuggì", "3803fc30"], "d": ["In una stretta pianura costiera il grande esercito di Dario III fu sconfitto da Alessandro; il re persiano fuggì abbandonando la famiglia e il tesoro. La vittoria di Isso fece passare ad Alessandro la Siria e la costa fenicia, e poi l'Egitto.", "a711a81e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0333-01-01:0":{"b": ["Battaglia del Granico: Alessandro sconfisse i satrapi persiani", "1aae30d4"], "d": ["Il re di Macedonia Alessandro passò in Asia nel maggio del 334 e all'inizio di giugno sconfisse i satrapi persiani al Granico. Le porte dell'Anatolia occidentale si aprirono; Sardi e le città della Ionia si arresero ad Alessandro.", "8cc08bd9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0335-01-01:0":{"b": ["Dario III salì al trono persiano (uccisione di Arse)", "706f8a9f"], "d": ["Il funzionario di palazzo Bagoa uccise Artaserse IV; il satrapo di Armenia Artashata divenne re con il nome di Dario III (Codomanno). Nell'ottobre del 336 Filippo fu assassinato in Macedonia e Alessandro salì al trono.", "c082bdae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0337-01-01:0":{"b": ["Artaserse III morì; Artaserse IV (Arse) salì al trono", "d38e2edc"], "d": ["Artaserse III morì nell'estate del 338 per cause naturali (nonostante il racconto di avvelenamento di Diodoro); Arse salì al trono. Le rivolte di Egitto e Babilonia e i preparativi di Filippo, re di Macedonia, per l'Anatolia coincidono con questo periodo.", "09f24497"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0344-01-01:0":{"b": ["Artaserse III prese e distrusse Sidone; la rivolta di Tenne fu repressa", "d1b533cc"], "d": ["Durante la rivolta antipersiana di Tenne, re di Sidone, sostenuta dall'Egitto, Artaserse III prese la città; Tenne tradì i Persiani, la città si diede alle fiamme e molte persone morirono. Le città fenicie tornarono sotto il controllo persiano e fu aperta la via alla conquista dell'Egitto.", "050b8e4e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0386-01-01:0":{"b": ["Pace del Re (di Antalcida): le città greche d'Anatolia e Cipro furono lasciate ai Persiani", "17e871ad"], "d": ["Con la pace dettata dal re persiano Artaserse II le città greche d'Asia e Cipro furono considerate persiane e fu riconosciuta l'autonomia alle città greche. Sparta applicò la pace come portavoce dei Persiani.", "7bf00868"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0400-01-01:0":{"b": ["Battaglia di Cunassa: Ciro il Giovane fu sconfitto dal fratello maggiore Artaserse II e morì", "90346087"], "d": ["Ciro il Giovane marciò su Babilonia con i Diecimila, composti da mercenari greci, e fu sconfitto a Cunassa dal fratello maggiore Artaserse II e morì in battaglia. La marcia di ritorno dei Diecimila verso il Mar Nero è raccontata nell'Anabasi di Senofonte.", "664d8d4f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:0":{"b": ["Serse attraversò l'Ellesponto; Termopili e presa di Atene", "9bf22df1"], "d": ["Serse con il suo grande esercito sconfisse alle Termopili le truppe spartane e alleate di Leonida ed entrò in Attica; Atene fu evacuata e incendiata con l'Acropoli. L'esercito persiano avanzò fino al centro della Grecia.", "3b81a962"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0479-01-01:1":{"b": ["Battaglia navale di Salamina: la flotta greca sbaragliò la flotta persiana", "010e3aab"], "d": ["La flotta greca al comando di Temistocle sconfisse a Salamina la flotta persiana in uno stretto, conquistando la supremazia navale. Serse tornò in Asia con gran parte dell'esercito di terra, mentre Mardonio rimase in Grecia.", "f55ed3ca"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0483-01-01:0":{"b": ["A Babilonia le rivolte di Bêl-šimânni e Šamaš-eriba furono represse da Serse I", "ebcef5a9"], "d": ["All'inizio del regno di Serse I scoppiarono a Babilonia due rivolte (Bêl-šimânni, Šamaš-eriba). Serse le represse; divise la satrapia di Babilonia e ridusse i privilegi della città.", "015c253c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0493-01-01:0":{"b": ["Battaglia navale di Lade: la flotta persiana sconfisse la flotta ionica; Mileto cadde", "86396cf1"], "d": ["La flotta persiana, a prevalenza fenicia, sbaragliò a Lade la flotta ionica; Mileto fu assediata e distrutta e la sua popolazione deportata in Mesopotamia. La Rivolta Ionica terminò e la Ionia tornò sotto il controllo persiano.", "b72ba00d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0497-01-01:0":{"b": ["Gli Ioni incendiarono Sardi", "adf677bd"], "d": ["Gli Ioni e le truppe ateniesi ed eretriesi marciarono su Sardi, centro della satrapia persiana, e la incendiarono. Dario da allora decise di punire Atene; l'evento è il motivo della spedizione di Maratona.", "32e33dce"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0498-01-01:0":{"b": ["Iniziò la Rivolta Ionica: dopo il fallimento della spedizione di Aristagora a Nasso, le città greche della Ionia si ribellarono ai Persiani", "aab8ff2f"], "d": ["Fallita la spedizione a Nasso del tiranno di Mileto Aristagora, le città della Ionia rovesciarono i loro tiranni e chiesero aiuto ad Atene ed Eretria. Questa rivolta è la miccia delle guerre persiane.", "7d70c2ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0512-01-01:0":{"b": ["Dario attraversò l'Istro (Danubio) e intraprese la campagna scitica; la Tracia fu annessa alla satrapia persiana", "a5891101"], "d": ["Dario passò in Tracia su un ponte attraverso il Bosforo, sottomise i Geti, attraversò il Danubio e intraprese la campagna contro gli Sciti. Pur non riuscendo a sconfiggere gli Sciti, Megabazo annesse la Tracia e la costa macedone al dominio persiano.", "f464fbf8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-05-08:0":{"b": ["L'esercito di Dario sconfisse il ribelle medo Fravartish (Fraorte)", "4a9c4633"], "d": ["L'esercito di Fravartish, che in Media si era proclamato re come discendente di Ciassare, fu sconfitto; Fravartish, mentre fuggiva, fu catturato a Ragai (presso Teheran) e ucciso con la tortura. La Media tornò a essere provincia persiana.", "efea5aea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0520-12-28:0":{"b": ["Il generale di Dario sconfisse il ribelle di Margiana Frada; l'ultima grande rivolta fu repressa", "76e0ea1c"], "d": ["Il satrapo di Battriana Dadarshi, marciando per 300 km attraverso il deserto del Karakum, sconfisse il ribelle di Margiana Frada il 28 dicembre 521. Nel primo anno di regno di Dario, con diciannove battaglie, tutte le rivolte furono represse.", "5c0c9cfa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-03-11:0":{"b": ["Gaumata (Bardiya) prese il trono persiano; Cambise morì al ritorno dall'Egitto", "1606d9c1"], "d": ["Secondo l'iscrizione di Behistun, il sacerdote Gaumata, facendosi passare per Bardiya (Smerdi), figlio di Ciro, salì al trono nel marzo 522; Cambise morì in Siria. Dario e sei nobili uccisero Gaumata il 29 settembre 522.", "f143e726"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-09-29:0":{"b": ["Dario e sei nobili uccisero Gaumata; Dario I salì al trono persiano", "08897d54"], "d": ["Dario, con i sei nobili compagni, uccise il falso Bardiya nella fortezza di Sikayauvati in Media. La morte di Gaumata scatenò rivolte in molte parti dell'impero; Dario le represse in un anno con diciannove battaglie.", "daebf974"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0521-12-18:0":{"b": ["Dario riprese Babilonia; Nidintu-Bêl (Nabucodonosor III) fu catturato e ucciso", "365cdd51"], "d": ["Alla morte di Gaumata, Nidintu-Bêl si proclamò figlio di Nabonedo e Nabucodonosor III e staccò Babilonia dai Persiani. L'esercito di Dario il 13 dicembre attraversò il Tigri con otri gonfiati e sbaragliò l'esercito ribelle; il 18 dicembre Babilonia fu ripresa e Nidintu-Bêl fu ucciso. La rivolta elamita di Susa fu repressa in quel periodo.", "4bd29dc6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0529-01-01:0":{"b": ["Ciro morì; il figlio Cambise salì al trono", "de69f4d5"], "d": ["Ciro, secondo Erodoto, morì in battaglia nel paese dei Massageti (secondo Senofonte morì nel suo palazzo); la notizia della morte giunse a Babilonia nel dicembre 530 e i documenti furono datati come «primo anno di Cambise». Cambise ampliò l'impero con la conquista dell'Egitto.", "9900a295"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:0":{"b": ["Editto di Ciro: i Giudei in esilio a Babilonia poterono tornare a Gerusalemme e fu permessa la ricostruzione del Tempio", "715eac6b"], "d": ["Ciro, preso Babilonia, rimandò indietro le statue degli dei dei popoli deportati e permise loro di tornare ai luoghi d'origine (Cilindro di Ciro). La Bibbia (Esdra 1:1-4) riporta a parte questo editto per i Giudei: gli esiliati possono tornare a Gerusalemme e ricostruire il Tempio. La regione divenne la satrapia persiana di «Yehud».", "a8c7f81c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0537-01-01:1":{"b": ["Le città-Stato fenicie (Tiro, Sidone, Biblo) accettarono il dominio persiano; divennero il nucleo della flotta persiana", "d9f7f277"], "d": ["Con la caduta di Babilonia la costa fenicia entrò sotto il dominio persiano all'interno della satrapia «Oltre il Fiume» (Ebir-Nari). Le flotte fenicie divennero la spina dorsale della potenza navale persiana; Sidone e Tiro conservarono il privilegio dell'amministrazione interna.", "bb0c17fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-01-01:0":{"b": ["Battaglia di Opis: Ciro sconfisse l'esercito babilonese sulle rive del Tigri", "d91708c6"], "d": ["I Persiani di Ciro affrontarono e sconfissero a Opis, sul Tigri, l'esercito accadico; la popolazione di Babilonia si ritirò e vi furono saccheggi e massacri. La battaglia aprì la via alla caduta di Babilonia due settimane dopo.", "20739fbd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-10:0":{"b": ["Sippar passò ai Persiani senza combattere; Nabonedo fuggì", "47f6d3a5"], "d": ["Dopo la battaglia di Opis, il 14 Tashritu Sippar cadde senza combattere nelle mani di Ciro e Nabonedo fuggì. I Persiani sarebbero entrati a Babilonia due giorni dopo.", "5a23a85c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-12:0":{"b": ["L'esercito persiano al comando di Gobria (Ugbaru) entrò a Babilonia senza combattere; terminò il Neobabilonese", "f67bf0e3"], "d": ["Il governatore di Gutium Ugbaru (Gobria) e l'esercito di Ciro entrarono a Babilonia il 16 Tashritu senza scontri; Nabonedo fu catturato. I riti nell'Esagila non furono interrotti. Ciro entrò in città il 3 Arahsamnu (29 ottobre) e l'impero babilonese passò sotto il dominio persiano.", "891c267b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0538-10-29:0":{"b": ["Ciro entrò a Babilonia; il controllo di Babilonia passò agli Achemenidi e Gobria fu nominato governatore", "fd45fa83"], "d": ["Ciro entrò a Babilonia il 3 Arahsamnu; salutò la popolazione della città e nominò Gubaru (Gobria) governatore della città. Le statue degli dei accadici che Nabonedo aveva radunato in città furono riportate ai loro luoghi in Kislimu-Addaru. Il figlio Cambise partecipò come principe ereditario al rito di Nabu.", "17d2bc46"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0546-01-01:0":{"b": ["Creso attraversò l'Halys e prese Pteria; la battaglia di Pteria con Ciro finì senza vincitori", "eee7aef1"], "d": ["Creso, fidando nell'oracolo di Delfi, attraversò l'Halys, assediò Pteria e cacciò i Siri di Cappadocia. Poiché la sanguinosa battaglia con Ciro rimase senza esito, Creso tornò a Sardi e radunò eserciti alleati; Ciro, con un'improvvisa campagna, lo sconfisse a Timbra e Sardi cadde.", "419ac6ed"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0551-01-01:0":{"b": ["Nabonedo si stabilì nell'oasi di Teima (Arabia) e non venne a Babilonia; la festa di Akitu non poté essere celebrata", "2ce93701"], "d": ["Mentre Nabonedo restava nell'oasi di Teima, il principe ereditario Baldassarre attese con l'esercito in Accad; in aprile, poiché il re non venne, Marduk non entrò a Babilonia e la festa del Nuovo Anno (Akitu) non fu celebrata. Questo fu uno dei motivi per cui i sacerdoti dei templi sostennero Ciro contro Nabonedo.", "d1e857db"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0555-01-01:0":{"b": ["Nabonedo salì al trono di Babilonia con un colpo di Stato", "b7ab73ce"], "d": ["Dopo la morte di Nabucodonosor (562) erano venuti Amel-Marduk, Neriglissar (559-556) e il brevissimo Labashi-Marduk; Nabonedo, pur non essendo di stirpe regale, fece un colpo di Stato nel 556. La sua particolare devozione al dio lunare Sin irritò i sacerdoti di Marduk.", "6b2f9204"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0559-01-01:0":{"b": ["Creso salì al trono di Lidia; rese tributarie Efeso e le città greche della Ionia", "5544cfa4"], "d": ["Creso, dopo la morte del padre Aliatte, rese tributaria Efeso e poi le altre città greche di Ionia, Eolide e Caria. La Lidia è l'unica unità politica dall'Anatolia occidentale fino all'Halys; il tesoro di Creso e i suoi doni a Delfi divennero leggendari.", "88136bde"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0584-01-01:0":{"b": ["Battaglia dell'Halys (Kızılırmak): per un'eclissi solare Aliatte e Ciassare fecero la pace; l'Halys divenne il confine tra Lidia e Media", "9ababdd3"], "d": ["La guerra di cinque anni tra Aliatte e il re dei Medi Ciassare si concluse con la pace per un'eclissi solare avvenuta di giorno; mediarono il re di Cilicia Siennesi e il re di Babilonia «Labineto». Il fiume Halys divenne il confine dei due regni e la Media fu considerata estesa fino all'interno dell'Anatolia.", "ddab1c12"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:0":{"b": ["Nabucodonosor iniziò l'assedio di Tiro; l'assedio durò tredici anni", "5b753ca0"], "d": ["Secondo Giuseppe Flavio (Contro Apione 1.156), Nabucodonosor assediò Tiro per tredici anni al tempo del re Itobaal. La vicenda si concluse infine con un assetto di pace/vassallaggio; Tiro entrò nell'influenza babilonese mentre l'amministrazione indipendente della città sull'isola continuò.", "0975583d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0585-01-01:1":{"b": ["Gerusalemme fu distrutta, il Tempio di Salomone bruciò; il Regno di Giuda terminò, la popolazione fu deportata a Babilonia", "c9f78b2a"], "d": ["Per la ribellione di Sedecia a Babilonia, Nabucodonosor prese Gerusalemme per la seconda volta e la incendiò; il Tempio fu distrutto e gran parte della popolazione fu deportata a Babilonia (Cattività babilonese). L'esistenza di Giuda come Stato indipendente terminò.", "f53414ac"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0596-03-16:0":{"b": ["Nabucodonosor prese Gerusalemme; il re Ioiachin fu portato prigioniero e gli successe Sedecia", "55b14c31"], "d": ["L'esercito babilonese assediò la «città di Giuda» e la prese il 2 Addaru; il re Ioiachin fu catturato e portato a Babilonia e al suo posto fu posto Sedecia (Mattania), scelto da Babilonia. La città entrò per la prima volta sotto il dominio babilonese.", "12a9d088"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0599-01-01:0":{"b": ["Le fortezze di Urartu furono distrutte e incendiate; lo Stato crollò", "6be90688"], "d": ["Lo strato di incendio visibile in fortezze come Karmir-blur indica che prima del 600 a.C. un'invasione di Sciti/Cimmeri, i Medi o un altro nemico distrusse Urartu. Per l'interruzione delle fonti assire la data dopo l'ultimo re Rusa III è incerta; Urartu divenne poco dopo satrapia achemenide (Armina).", "1e7ff200"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0603-12-01:0":{"b": ["Nabucodonosor II prese Ascalona, catturò il suo re e ridusse la città in rovina", "7429839d"], "d": ["Nel primo anno di Nabucodonosor «tutti i re del paese di Hatti» gli portarono tributo; solo Ascalona resistette. La città fu presa nel mese di Kislimu, il re fu catturato e la città ridotta a una collina di rovine.", "a455db32"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0604-09-07:0":{"b": ["Nabopolassar morì, Nabucodonosor II salì al trono di Babilonia", "bce88c5a"], "d": ["Il re di Babilonia Nabopolassar morì l'8 Abu (15 agosto 605) dopo un regno di 21 anni; Nabucodonosor, vittorioso a Carchemish, tornato in patria si sedette sul trono il 1 Ulûlu (7 settembre 605). Quattro anni di campagne legarono a Babilonia il paese di Hatti (Siria-Palestina).", "b519ffaa"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:0":{"b": ["Harran cadde; Assur-uballit II si ritirò in Egitto", "b2d122c2"], "d": ["Dopo la caduta di Ninive l'ultimo re d'Assiria, Assur-uballit II, si era ritirato a Harran; quando i Medi e i Babilonesi marciarono su Harran, le truppe assire ed egiziane lasciarono la città ritirandosi oltre l'Eufrate. Nabopolassar prese e saccheggiò Harran.", "cb81464b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0609-01-01:1":{"b": ["Aliatte salì al trono di Lidia; cacciò i Cimmeri dall'Anatolia e ampliò il regno", "160e291d"], "d": ["Aliatte nel suo lungo regno ripulì l'Anatolia occidentale dai Cimmeri e combatté contro Mileto; portò i confini del regno nel centro dell'Anatolia fino all'incontro con la Media sul confine dell'Halys.", "54aee50b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0613-01-01:0":{"b": ["Ciassare e Nabopolassar conclusero un'alleanza davanti ad Assur", "650f0e5a"], "d": ["Quando i Medi presero Assur, il re di Babilonia Nabopolassar, arrivato in ritardo, incontrò presso la città il re dei Medi e strinse un'alleanza. Secondo Beroso il legame fu rafforzato dal matrimonio di Nabucodonosor con Amiti, figlia di Ciassare.", "450ae215"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0624-01-01:0":{"b": ["Ciassare (Umakishtar) salì al trono di Media", "67896ea0"], "d": ["Secondo la tradizione di Erodoto Ciassare regnò quarant'anni, unificò la Media e intraprese la campagna contro l'Assiria. L'alleanza con Babilonia (614) e la presa di Ninive (612) cadono nel suo regno; in questi anni la Media raggiunse i confini più ampi.", "4094aac8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0630-01-01:0":{"b": ["Assurbanipal morì; in Assiria iniziarono la contesa per il trono e la rivolta di Babilonia", "dbe19d8c"], "d": ["La morte di Assurbanipal lasciò l'Assiria divisa tra due eredi. I governatori di Babilonia si ribellarono a Sin-shumu-lishir e Sin-shar-ishkun; il crollo dell'impero ebbe inizio nel giro di dieci anni.", "9537e9f3"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0644-01-01:0":{"b": ["Assurbanipal distrusse Susa; il Regno Neoelamita crollò", "cb341293"], "d": ["Come punizione per la ribellione dell'Elam all'Assiria insieme a Babilonia, Assurbanipal prese e saccheggiò Susa, distrusse i templi e portò le statue degli dei a Ninive. L'Elam, suddiviso in principati semi-indipendenti, entrò nell'influenza persiana/di Anshan.", "327f1322"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0647-01-01:0":{"b": ["Babilonia si sottomise ad Assurbanipal dopo la rivolta di Shamash-shuma-ukin", "d6964932"], "d": ["Il fratello di Assurbanipal, re di Babilonia Shamash-shuma-ukin, nel 652 si ribellò all'Assiria; gli alleati elamiti e arabi diedero un sostegno temporaneo. La guerra di quattro anni si concluse con la caduta di Babilonia e la morte di Shamash-shuma-ukin.", "b038173f"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0651-01-01:0":{"b": ["I Cimmeri saccheggiarono Sardi; Gige morì", "950e5f80"], "d": ["L'invasione cimmeria, dopo Gordio (696/695), si estese anche alla Lidia e saccheggiò la città bassa di Sardi. Le fonti assire riferiscono che il re di Lidia Gugu (Gige) cercò l'aiuto assiro contro i Cimmeri; Gige morì durante o dopo queste guerre.", "93736177"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0652-01-01:0":{"b": ["Battaglia di Til-Tuba/Ulai: Assurbanipal sconfisse e uccise il re elamita Teumman", "177e87cf"], "d": ["Assurbanipal sconfisse e uccise il re elamita Teumman sulle rive dell'Ulai (Karun/Karkheh) presso Susa; la sua testa fu portata a Ninive. La battaglia preparò la fine del ruolo dell'Elam nella contesa assiro-babilonese.", "3aa28a86"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0663-01-01:0":{"b": ["Assurbanipal saccheggiò Tebe", "179269c7"], "d": ["Dopo la morte di Asarhaddon, quando in Egitto la rivolta kushita con Tanutamani si riaccese, Assurbanipal entrò nell'Alto Egitto e saccheggiò Tebe. L'Assiria faticò a tenere di fatto l'Egitto e si ritirò in breve tempo.", "c292bcf0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0676-01-01:0":{"b": ["Asarhaddon distrusse Sidone e la rifondò con il nome di Kar-Asarhaddon", "bd713ae6"], "d": ["Quando il re di Sidone Abdi-Milkutti si ribellò all'Assiria, Asarhaddon distrusse la città, uccise il re decapitandolo e al posto della città fondò Kar-Asarhaddon («Porto di Asarhaddon»), centro di provincia assira.", "2a506319"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0684-01-01:0":{"b": ["Gige rovesciò Candaule e fondò la dinastia dei Mermnadi", "37e46a38"], "d": ["Secondo Erodoto Gige, guardia di palazzo, rovesciò il re Candaule e prese il trono di Lidia, fondando la dinastia dei Mermnadi. Dopo il crollo della Frigia per l'attacco cimmerio, la Lidia cominciò a diventare la potenza principale dell'Anatolia occidentale.", "e477b6b5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0688-01-01:0":{"b": ["Sennacherib distrusse Babilonia, saccheggiò i templi e vi fece scorrere l'Eufrate", "82265d98"], "d": ["Dopo le ripetute rivolte di Babilonia, Sennacherib prese e distrusse la città, portò via la statua di Marduk e vi fece riversare le acque dei canali. Babilonia rimase in rovina per mezzo secolo fino al restauro di Asarhaddon; la distruzione è la mossa più dura della politica assira verso Babilonia.", "e4312fee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:0":{"b": ["Sennacherib invase Giuda; prese Lachish e assediò Gerusalemme", "dc11fa2d"], "d": ["Sennacherib, represso la rivolta di Ezechia all'Assiria, prese quarantasei città di Giuda, conquistò Lachish e assediò Gerusalemme. Ezechia salvò la città pagando un pesante tributo; i rilievi di Lachish a Ninive raffigurano questa campagna.", "ebc2ce02"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0700-01-01:1":{"b": ["Sennacherib prese Sidone; il re Luli fuggì a Cipro", "41bb1358"], "d": ["Nel 701 Sennacherib sottomise le città fenicie: il re di Sidone Luli (Elulaios) fuggì a Cipro e le città dipendenti da Sidone e Tiro passarono all'Assiria. Con queste conquiste, prima della campagna di Giuda, fu assicurata la costa occidentale.", "3b2c6518"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0704-01-01:0":{"b": ["Sargon II morì in battaglia a Tabal; Sennacherib salì al trono", "2f6ae581"], "d": ["Sargon II morì in Anatolia durante la campagna contro il re di Tabal Gurdi e il suo corpo non fu recuperato. Il figlio Sennacherib trasferì la corte a Ninive; la città del padre, Dur-Sharrukin, fu abbandonata e molte province si ribellarono.", "21ee2771"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0711-01-01:0":{"b": ["Sargon II prese Malatya (Melid); Gunzinanu fu deportato", "3ef6a5c9"], "d": ["Il re di Melid (Malatya) Gunzinanu, per aver collaborato con Tabal e Urartu, fu sconfitto da Sargon e il suo regno divenne provincia assira. Il dominio neoittita nell'Anatolia orientale terminò così.", "281f75fd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0713-01-01:0":{"b": ["Sargon II entrò in Urartu: Rusa I fu sconfitto, Musasir fu saccheggiata e fu presa la statua di Haldi", "38992d24"], "d": ["L'ottava campagna di Sargon saccheggiò Urartu scendendo dai dintorni del Lago di Urmia; il tempio di Haldi a Musasir fu spogliato. Il re Rusa I, di fronte alla grave sconfitta, si tolse la vita (tradizione). Urartu non poté più tentare una grande impresa contro l'Assiria.", "7d05af4c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0716-01-01:0":{"b": ["Sargon II prese Carchemish; il regno di Pisiri divenne provincia assira", "cfcc3ee4"], "d": ["Il re di Carchemish Pisiri tentò di allearsi con Mida (Mita) contro l'Assiria; Sargon prese la città e compì deportazioni. L'indipendenza di un secolo e mezzo di Carchemish terminò e il confine sull'Eufrate passò all'Assiria.", "87f1f2e6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0719-01-01:0":{"b": ["Sargon II sconfisse Hama (Hamat), uccise Yau-bidi a Qarqar e fece del regno una provincia", "aeca8edc"], "d": ["Il re di Hamat Yau-bidi era a capo della coalizione siro-palestinese formata contro Sargon; Sargon lo sconfisse a Qarqar e distrusse la città, e Hamat fu trasformata in provincia assira.", "70e2d509"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0732-01-01:0":{"b": ["Tiglat-Pileser III prese a Israele Galilea e Galaad e ne fece province assire", "0b59ead2"], "d": ["Quando l'Israele di Pekach si oppose all'Assiria insieme a Damasco, Tiglat-Pileser III trasformò Israele settentrionale (Galilea, Galaad, dintorni di Megiddo) in province assire e compì deportazioni; al posto di Pekach subentrò Osea. Il Regno d'Israele fu ridotto a Samaria e alla regione montuosa circostante.", "28d3a30e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0733-01-01:0":{"b": ["Tiglat-Pileser III prese Gaza; la costa palestinese entrò sotto il controllo assiro", "1c89131f"], "d": ["Tiglat-Pileser, rivolgendosi alla striscia costiera palestinese, fece fuggire in Egitto il re di Gaza Hanunu e ne prese possesso. Le città-Stato palestinesi negli anni seguenti divennero una fascia vassalla dell'Assiria.", "ff623a4d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0742-01-01:0":{"b": ["Tiglat-Pileser III sconfisse presso Arpad il re di Urartu Sarduri II", "7478a232"], "d": ["Il tentativo di Sarduri II di spingere gli Stati siriani all'indipendenza si concluse con la vittoria di Tiglat-Pileser III. Urartu perse la sua influenza in Siria; l'Assiria non lasciò rivali per l'Anatolia e la Siria.", "b851f23b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0744-01-01:0":{"b": ["Tiglat-Pileser III salì al trono; fu istituito il sistema provinciale assiro", "b5889059"], "d": ["Tiglat-Pileser III, salito al trono con una rivolta a Calah, istituì il sistema provinciale ponendo governatori assiri al posto dei regni vassalli; legò Babilonia con unione personale e condusse campagne contro Damasco, Gaza e Israele. Da qui deriva l'ordinamento amministrativo usato dagli imperi successivi (babilonese, persiano, seleucide).", "7deb8187"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0795-01-01:0":{"b": ["Adad-nirari III sconfisse il re di Damasco Mari e ne ricevette tributo", "3e01dbfa"], "d": ["Adad-nirari III sconfisse il re di Damasco Mari (Bar-Hadad) ricevendone un grande tributo; la forza interna di Aram-Damasco si indebolì e Israele respirò per un periodo.", "c5c0a66d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0809-01-01:0":{"b": ["Minua estese Urartu dal Lago di Van alla Valle dell'Arasse e al Lago di Urmia", "d77231e4"], "d": ["Al tempo di Minua e del figlio Argishti I Urartu divenne un regno che comprendeva l'intero paese alto, dal centro del Lago di Van fino ai dintorni dell'Arasse e del Lago di Urmia. Tushpa (Van) fu ampliata con nuovi insediamenti e opere di irrigazione.", "289fc554"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0839-01-01:0":{"b": ["Il re di Moab Mesha proclamò l'indipendenza da Israele (Stele di Mesha)", "e9c264b2"], "d": ["La Stele di Mesha racconta la liberazione del re di Moab Mesha dalla tutela d'Israele e le vittorie ottenute contro la dinastia di Omri. La Bibbia e la stele insieme mostrano il periodo di debolezza della dinastia di Omri.", "ffefe5fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0840-01-01:0":{"b": ["Salmanassar III sconfisse Hazael, assediò Damasco; il re d'Israele Ieu pagò tributo", "93aacc56"], "d": ["Salmanassar III sconfisse il re di Aram-Damasco Hazael sul monte Senir (Hermon) e assediò Damasco; il re d'Israele Ieu è raffigurato sull'Obelisco Nero mentre offre tributo all'Assiria. La coalizione di Qarqar si sciolse e l'Assiria divenne la potenza dominante a ovest.", "2992ec0c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0852-01-01:0":{"b": ["Battaglia di Qarqar: Salmanassar III affrontò la coalizione di Damasco, Hamat e Israele", "9a736e92"], "d": ["Salmanassar III combatté a Qarqar contro una coalizione di dodici re, tra cui il re di Damasco Hadad-ezer (Adad-idri), il re di Hamat Irhuleni e il re d'Israele Acab. Anche se i documenti assiri rivendicano la vittoria, dovette abbandonare l'avanzata; la coalizione fermò per anni l'Assiria.", "524874c7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0857-01-01:0":{"b": ["Salmanassar III iniziò campagne contro Urartu (Arame); Urartu comparve per la prima volta nelle fonti assire", "375ce993"], "d": ["Nei primi anni di regno Salmanassar III marciò contro le terre di Urartu del re Arame; gli annali assiri in queste campagne menzionano per la prima volta Urartu con il nome di «paese di Urartu». È la prima attestazione datata dello Stato che nei secoli seguenti sarebbe stato il principale rivale dell'Assiria in questa regione.", "759a75b7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0876-01-01:0":{"b": ["Assurnasirpal II attraversò l'Eufrate e ricevette tributo da Carchemish e dagli Stati neoittiti/aramaici", "5e385948"], "d": ["Assurnasirpal II nella campagna occidentale attraversò l'Eufrate, raggiunse Carchemish, Patina e la costa fenicia e raccolse tributo. Questa campagna è l'inizio del processo di sottomissione all'Assiria delle città-Stato neoittite e aramee.", "8432c2ea"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0878-01-01:0":{"b": ["Assurnasirpal II fece di Calah (Nimrud) la nuova capitale dell'Assiria", "fbb17248"], "d": ["Assurnasirpal II trasformò Calah, piccola cittadina, in una grande capitale con 47.000 operai; nella città, sei volte più estesa di Assur, fu costruito il palazzo nord-occidentale. Calah rimase capitale dell'Assiria fino al 706.", "5a0f00b6"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0879-01-01:0":{"b": ["Omri fece di Samaria la capitale e prese Moab", "e060c4b7"], "d": ["Omri fondò il primo vero Stato d'Israele: conquistò la Transgiordania (Moab compresa), rafforzò le fortezze di confine e fece di Samaria la nuova capitale. Il figlio Acab, sposando Gezabele, figlia del re di Sidone Ethbaal, legò Israele al commercio fenicio.", "14f7df9d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0910-01-01:0":{"b": ["Adad-nirari II salì al trono; iniziò la ripresa neoassira", "e6887ba9"], "d": ["Dopo un declino durato circa un secolo e mezzo, Adad-nirari II cominciò a riunire di nuovo le terre assire; condusse campagne contro gli Aramei e il confine babilonese. Con i suoi successori Assurnasirpal II e Salmanassar III nacque l'Impero neoassiro.", "beab377b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-0929-01-01:0":{"b": ["Il regno di Salomone si divise; Geroboamo I fondò al nord il Regno d'Israele", "cfbbc025"], "d": ["Secondo la Bibbia, alla morte di Salomone l'aumento delle tasse da parte del figlio Roboamo portò alla separazione delle dieci tribù del nord; Geroboamo fu eletto re e fece di Tirza la capitale. Al sud Giuda continuò con la dinastia di Davide. Inizia la storia separata dei due Stati.", "7e2e066d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1099-01-01:0":{"b": ["Tiglat-Pileser I marciò a ovest e ricevette tributo dalle città fenicie sulla costa mediterranea", "0b2822b7"], "d": ["Tiglat-Pileser I raggiunse le foreste del Libano e porti come Arvad, Biblo (Gebal) e Sidone, raccolse tributo e navigò sul Mediterraneo. Poiché dopo il crollo ittita non vi era a ovest una potenza in grado di fermarlo, queste campagne iniziano l'orientamento occidentale dell'Assiria.", "60dc7824"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1109-01-01:0":{"b": ["Nabucodonosor I (Isin II) marciò sull'Elam e riprese la statua di Marduk", "3c551c03"], "d": ["Nabucodonosor I della dinastia di Isin II marciò sull'Elam e riportò a Babilonia la statua di Marduk portata via da Kutir-Nahhunte. La vittoria è ricordata nella storia babilonese come «il ritorno di Marduk» e rese centrale il culto di Marduk.", "fdd1a6a4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1157-01-01:0":{"b": ["Shutruk-Nahhunte saccheggiò il paese di Babilonia; portò a Susa le stele di Hammurabi e di Naram-Sin", "3d499fcc"], "d": ["Il re del Medio Elam Shutruk-Nahhunte attaccò Babilonia e saccheggiò città come Sippar; bottini come la stele del Codice di Hammurabi e la Stele della Vittoria di Naram-Sin furono portati a Susa. Il figlio Kutir-Nahhunte nel 1155 a.C. pose fine alla dinastia cassita.", "2179c21e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1174-01-01:0":{"b": ["A Carchemish Kuzi-Teshub continuò l'eredità ittita con il titolo di «Gran Re»", "0bda7a64"], "d": ["Dopo la distruzione di Hattusa il regno di Carchemish rimase in piedi per mano di un ramo della dinastia ittita; Kuzi-Teshub si proclamò «Gran Re». Le città-Stato luvio-aramaiche come Carchemish, Malatya (Melid) e Hama costituirono il mondo «neoittita».", "214de0bd"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1179-01-01:0":{"b": ["Hattusa bruciò e fu abbandonata; l'Impero ittita crollò", "64d58b6b"], "d": ["La città di Hattusa fu incendiata e abbandonata al tempo dell'ultimo re ittita Suppiluliuma II; fa parte del crollo della tarda Età del Bronzo, nel contesto di carestia, conflitti interni e Popoli del Mare. Lo Stato ittita lasciò il posto alle città-Stato neoittite come Carchemish e Malatya.", "34ee5436"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1224-01-01:0":{"b": ["Il re di Assur Tukulti-Ninurta I conquistò Babilonia; portò la statua di Marduk ad Assur", "2cc39251"], "d": ["Tukulti-Ninurta I (ca. 1243-1207) sconfisse il re cassita Kashtiliash IV e prese Babilonia, ne fece abbattere le mura e trasportò la statua di Marduk ad Assur. Babilonia rimase per circa sette anni sotto il controllo di Assur; l'Assiria divenne la potenza più forte dell'epoca.", "8abcb249"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1259-01-01:0":{"b": ["Salmanassar I fondò la città di Calah (Nimrud)", "e0bf279a"], "d": ["Salmanassar I fondò Calah sulle rive del Tigri; la città nell'883 sarebbe stata rifondata da Assurnasirpal II e sarebbe divenuta capitale dell'Assiria.", "8a213755"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1269-01-01:0":{"b": ["Salmanassar I annesse Hanigalbat; il Mitanni scomparve", "88620feb"], "d": ["Salmanassar I, represso l'insurrezione del re di Hanigalbat Shattuara II, annesse direttamente il paese all'Assiria e ne deportò la popolazione. Lo Stato del Mitanni fu cancellato dalla scena storica dai colpi successivi di Ittiti e Assiri.", "c6c8615e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1274-01-01:0":{"b": ["Untash-Napirisha fondò la città di Dur-Untash (Chogha Zanbil) e il suo ziggurat", "117fbc13"], "d": ["Il re del Medio Elam Untash-Napirisha fondò presso Susa una città di culto con ziggurat per il dio Inshushinak; sebbene rimasta incompiuta, la città fu usata per oltre due secoli. Chogha Zanbil è lo ziggurat meglio conservato dell'Iran.", "fe8afd09"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1294-01-01:0":{"b": ["Adad-nirari I sconfisse Hanigalbat (resto del Mitanni) e lo rese vassallo", "1adb5969"], "d": ["Adad-nirari I, nipote di Assur-uballit I, sconfisse il regno di Hanigalbat, resto del Mitanni colpito dagli Ittiti, e lo rese vassallo; sotto il re successivo, Salmanassar I, il paese fu trasformato in provincia assira. L'Assiria si estese fino all'Eufrate.", "24941786"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1317-01-01:0":{"b": ["Mursili II sconfisse e divise Arzawa (Anatolia occidentale)", "4a204e42"], "d": ["Mursili II all'inizio del regno sconfisse la potente confederazione di Arzawa dell'Anatolia occidentale, la divise in sottoregni e la rese vassalla degli Ittiti. Il confine ittita dell'Anatolia occidentale si avvicinò alla costa egea.", "c2f9977c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1327-01-01:0":{"b": ["Suppiluliuma pose i figli a capo dei regni di Carchemish e Aleppo", "1c5bc8b3"], "d": ["Suppiluliuma governò la Siria conquistata per mezzo di «re» della dinastia ittita: Carchemish e Aleppo furono date ai figli. Il vicereame di Carchemish sarebbe sopravvissuto per circa 500 anni anche dopo il crollo ittita.", "40eeaf84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1344-01-01:0":{"b": ["Suppiluliuma I sconfisse il Mitanni (Tushratta) e prese Aleppo e Carchemish; la Siria settentrionale passò agli Ittiti", "52f9627a"], "d": ["Suppiluliuma sconfisse il re del Mitanni Tushratta e prese le città della Siria, tra cui Carchemish e Aleppo; la parte occidentale dei territori del Mitanni fu annessa all'impero ittita. I problemi interni dell'Egitto di Akhenaton facilitarono questa espansione.", "c80de115"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:0":{"b": ["La Babilonia cassita nella diplomazia di Amarna ebbe il ruolo di grande potenza pari all'Egitto", "5e7b31a2"], "d": ["I re cassiti Kadashman-Enlil I e Burna-Buriash II appartenevano alla lega dei «grandi re» che conduceva con i faraoni egiziani una diplomazia di matrimoni e doni. Le lettere di Amarna elencano come membri di questa lega Egitto, Babilonia, Mitanni, Hatti e Assur.", "8ecd665d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1349-01-01:1":{"b": ["Suppiluliuma I salì al trono ittita; iniziò il periodo del Nuovo Regno", "58b301b7"], "d": ["Suppiluliuma I è il fondatore del Nuovo Regno ittita e il creatore dell'esercito professionale di carri da guerra. Il suo regno di trentacinque anni trasformò gli Ittiti in un impero esteso dall'Anatolia alla Siria.", "72c7f3af"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1362-01-01:0":{"b": ["Assur-uballit I si liberò dalla tutela del Mitanni; l'Assiria divenne indipendente e «grande re»", "5f280058"], "d": ["Assur, vassalla del Mitanni, ottenne l'indipendenza sotto Assur-uballit I approfittando del colpo inferto dagli Ittiti al Mitanni. Il re scrisse al faraone egiziano con il titolo di «grande re»; ciò inaugura il periodo medio-assiro.", "690fb956"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1399-01-01:0":{"b": ["Alleanza Mitanni-Egitto: pace tra Artatama I e Thutmosi IV, una principessa del Mitanni andò sposa in Egitto", "017f13d2"], "d": ["Dopo l'ostilità, il re del Mitanni Artatama I fece pace con il faraone egiziano e gli mandò la figlia. L'alleanza stabilì nella Siria settentrionale l'equilibrio egizio-mitannico contro la minaccia ittita e preparò la diplomazia dell'epoca di Amarna.", "72df719d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1499-01-01:0":{"b": ["Il regno del Mitanni (Hanigalbat) fu fondato nella regione del Khabur-Eufrate", "04920d91"], "d": ["Il regno hurrita-mitannico sorse nell'Alta Mesopotamia nel vuoto lasciato dal crollo dell'Antico Babilonese e dal declino ittita. La capitale era Washshukanni; in alcuni decenni il regno rese vassalle Assur e la Siria settentrionale.", "c6aa0237"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1524-01-01:0":{"b": ["Telipinu salì al trono ed emanò un editto; i rapporti con Kizzuwatna furono fissati con un trattato", "e1f0895b"], "d": ["Telipinu ricostituì il diritto ittita con il suo editto che regolava la successione; il trattato firmato con Kizzuwatna riconosce il paese non come dipendente ma come partner indipendente. L'Antico Regno ittita termina con questo editto.", "47b927f1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1569-01-01:0":{"b": ["La dinastia cassita ricompose Babilonia al tempo di Agum-kakrime; la statua di Marduk tornò dalla prigionia ittita", "0d525e02"], "d": ["Dopo il saccheggio di Babilonia da parte del re ittita Mursili I (1595 a.C.) la città passò sotto il dominio della dinastia cassita. La tradizione racconta che Agum-kakrime riprese agli Ittiti la statua di Marduk; i Cassiti adottarono in breve la cultura babilonese e fondarono la dinastia che sarebbe durata circa quattro secoli.", "d91fcc1e"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1589-01-01:0":{"b": ["Mursili I fu ucciso in una congiura; il regno ittita si indebolì nelle lotte interne", "fa5a6ea9"], "d": ["Nel ritorno da Babilonia Mursili I fu ucciso dal cognato Hantili e da Zidanta. Le lotte per il trono e la nuova potenza hurrita/mitannica lasciarono il regno debole per mezzo secolo; Telipinu riuscì a ristabilire l'ordine solo verso il 1525 a.C.", "90711b8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1599-01-01:0":{"b": ["Mursili I prese e distrusse Aleppo (Yamhad)", "78c81e82"], "d": ["Mursili I, nipote e successore di Hattusili, prese e distrusse il regno di Aleppo, che aveva resistito per decenni. La fine di Yamhad assicurò la supremazia ittita nella Siria settentrionale e aprì la via alla campagna di Mursili contro Babilonia.", "327a9d55"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1629-01-01:0":{"b": ["Hattusili I attraversò il Tauro e condusse una campagna nella Siria settentrionale; Alalakh fu distrutta, il regno di Aleppo (Yamhad) attaccato", "92b0d44b"], "d": ["Hattusili I (ca. 1650-1620) attraversò il Tauro e condusse una campagna nella Siria settentrionale; Alalakh fu distrutta e il regno di Aleppo (Yamhad) attaccato, ma Aleppo non fu presa. L'annessione di Kizzuwatna (Cilicia) non avvenne con questa campagna: Kizzuwadna oscillò poi tra Hatti e Mitanni e l'annessione ittita avvenne all'inizio del Nuovo Regno.", "cf12effe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1749-01-01:0":{"b": ["Il re di Kussara Anitta fece di Kanesh la capitale e distrusse Hattusa", "1eea344b"], "d": ["Secondo il Testo di Anitta, il re di Kussara Anitta unificò molte città-Stato in Anatolia, fece di Nesa (Kanesh) la capitale e distrusse Hattusa pronunciando su di essa una maledizione. È ricordato come il primo tentativo ittita di unificazione politica.", "01d03ad4"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1753-01-01:0":{"b": ["Fu eretta la stele del Codice di Hammurabi", "b4c80ab9"], "d": ["La raccolta di leggi di Hammurabi, di 282 articoli, fu scritta su una stele di basalto ed eretta nei templi. La stele fu portata a Susa dal re elamita Shutruk-Nahhunte nel XII secolo a.C., fu ritrovata lì nel 1901 e oggi si trova al Louvre.", "e37255ee"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1760-01-01:0":{"b": ["Hammurabi prese Mari; due anni dopo ne fece abbattere le mura", "4f4114b4"], "d": ["Hammurabi, preso Mari, la città dell'ex alleato Zimri-Lim, ne fece abbattere anche le mura. La distruzione di Mari è la fine del regno amorreo nella valle dell'Eufrate; Babilonia divenne la potenza dominante nel nord fino ad Assur ed Eshnunna.", "5bbc9e99"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1762-01-01:0":{"b": ["Hammurabi prese Larsa e sconfisse Rim-Sin I; la Mesopotamia meridionale fu annessa a Babilonia", "6f95399b"], "d": ["Hammurabi, nello stesso anno, dopo aver combattuto Elam ed Eshnunna, si volse contro Larsa e sconfisse Rim-Sin I. La Mesopotamia meridionale (Sumer) fu annessa al regno di Babilonia; da allora questa regione è chiamata «paese di Accad» (Babilonia).", "4be6f89b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1793-01-01:0":{"b": ["Il re di Larsa Rim-Sin I conquistò Isin; la dinastia di Isin terminò", "88964ca6"], "d": ["Il re di Larsa Rim-Sin I conquistò Isin, rivale di lunga data, e fece di Larsa l'unica grande potenza della Mesopotamia meridionale. Così la dinastia di Isin terminò dopo 223 anni di dominio.", "f1928082"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1794-01-01:0":{"b": ["Shamshi-Adad prese Mari e nominò re di Mari il figlio Yasmah-Adad", "a428b4eb"], "d": ["Shamshi-Adad, re di Assur e di Ekallatum, prese il regno di Mari sull'Eufrate, eliminò la dinastia di Yahdun-Lim e nominò a Mari il figlio minore Yasmah-Adad. Il «Regno dell'Alta Mesopotamia» divenne così un impero amorreo esteso dallo Zagros all'Eufrate.", "8d0ec094"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1799-01-01:0":{"b": ["Aleppo è ricordata come capitale del Regno di Yamhad", "9ad40400"], "d": ["Aleppo compare nel XVIII secolo a.C. come capitale del Regno di Yamhad; la fonte non fornisce l'anno esatto di fondazione del regno.", "f9ad9832"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1821-01-01:0":{"b": ["Rim-Sin I salì al trono di Larsa", "a24e891e"], "d": ["Rim-Sin I (ca. 1822-1763), nei suoi 60 anni di regno, legò a Larsa Uruk, Isin e Nippur e fece di una dinastia di origine elamita l'unica signora del sud. Il suo regno terminò con la conquista di Larsa da parte di Hammurabi (1763 a.C.).", "dcc872e1"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1835-01-01:0":{"b": ["Lo strato II del karum di Kanesh (Kültepe) fu distrutto; tra le città-Stato anatoliche emerse Anitta", "084f9472"], "d": ["La distruzione dello strato II di Kültepe è la fine del primo grande periodo dei karum dei mercanti assiri. In seguito il re di Kussara Anitta fece di Kanesh la capitale e aprì la via alla costituzione politica degli Ittiti.", "c3514f06"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1899-01-01:0":{"b": ["I mercanti assiri fondarono il karum di Kanesh (Kültepe); la rete commerciale paleo-assira si estese all'Anatolia", "b81b0cb9"], "d": ["I mercanti della città di Assur fondarono in Anatolia karum (colonie commerciali) con centro a Kanesh per il commercio di rame, stagno e stoffe. Le decine di migliaia di tavolette cuneiformi ritrovate a Kültepe segnano l'inizio della scrittura e della storia scritta in Anatolia.", "2311e7a7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1924-01-01:0":{"b": ["Il re di Larsa Gungunum prese Ur a Isin", "6c857c01"], "d": ["Gungunum (ca. 1932-1906) rese per la prima volta Larsa una grande potenza: nei nomi d'anno sono proclamati la presa di Ur e un successo contro l'Elam. Con il passaggio di Ur ebbe inizio il confinamento di Isin al nord.", "0108b079"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-1960-01-01:0":{"b": ["Naplanum fondò a Larsa una dinastia amorrea indipendente", "86a820f8"], "d": ["Il capo amorreo Naplanum, proclamando il proprio dominio a Larsa, fondò la seconda grande dinastia del sud dopo Ur III. Larsa, nella rivalità durata secoli con Isin, avrebbe legato a sé prima Ur, poi Uruk e Isin.", "ab808712"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2001-01-01:0":{"b": ["Ishbi-Erra scacciò la guarnigione elamita da Ur; prese in suo dominio Isin, Ur e Nippur", "a68018b2"], "d": ["Dopo la presa di Ur da parte dell'Elam (ca. 2004), Ishbi-Erra scacciò la guarnigione elamita da Ur e legò a Isin Ur e Nippur. Isin, erede politica di Ur, portò per secoli il titolo di re di Sumer e Accad.", "77884c9c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2016-01-01:0":{"b": ["Ishbi-Erra si separò a Isin da Ur III; fu fondata la dinastia di Isin", "8d9e3116"], "d": ["Ishbi-Erra, generale di Ibbi-Sin, fondò a Isin una dinastia indipendente mentre lo Stato di Ur III crollava. Isin, come dinastia con il titolo di «re di Sumer e Accad» che proseguiva l'eredità culturale di Ur, fu per circa 220 anni una delle principali potenze della Mesopotamia meridionale.", "b28db4ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2025-01-01:0":{"b": ["Ibbi-Sin salì al trono come ultimo re di Ur III", "0afa3ef5"], "d": ["Ibbi-Sin (ca. 2028-2004), successore di Shu-Sin, diresse il processo di disgregazione dello Stato: pressione amorrea, carestia, perdita di Susa e delle province orientali, indipendenza di Ishbi-Erra a Isin. Il suo regno terminò con il saccheggio di Ur da parte dell'attacco elamita/di Simashki.", "19e45ed0"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2031-01-01:0":{"b": ["Shu-Sin costruì il muro «Muriq-tidnim» contro gli Amorrei", "a09bfd57"], "d": ["Il re di Ur III Shu-Sin, per fermare i nomadi amorrei (Martu) provenienti da ovest, costruì tra Tigri ed Eufrate una lunga linea di muro (Muriq-tidnim, «che tiene lontani gli Occidentali»). Il muro mostra che la pressione amorrea metteva a dura prova lo Stato; Ur III crollò poco dopo per questa pressione e per l'attacco elamita.", "e5ec4e9a"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2091-01-01:0":{"b": ["Shulgi salì al trono di Ur III; fondò il sistema amministrativo centrale dello Stato", "06ea0c7b"], "d": ["Shulgi, figlio di Ur-Nammu (ca. 2094-2047), nei 48 anni di regno centralizzò lo Stato di Ur III: sistema di tasse e consegna di bestiame (Puzrish-Dagan), riforma dell'esercito, governatorati cittadini e nuovo calendario. Ur III è considerato lo Stato antico burocraticamente più sviluppato della storia mesopotamica.", "d6f42381"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2099-01-01:0":{"b": ["Puzur-Inshushinak, ultimo re awan, si liberò a Susa in Elam dalla tutela accadica", "cd91f4a2"], "d": ["Puzur-Inshushinak, ultimo re della dinastia di Awan, nel crollo dello Stato accadico unì Susa e l'altopiano elamita sottraendosi alla tutela accadica e lasciò iscrizioni oltre che in cuneiforme in «elamita lineare». Con l'ascesa di Ur-Nammu l'Elam entrò di nuovo sotto il controllo mesopotamico.", "d16fe5e9"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2110-01-01:0":{"b": ["Il re di Uruk Utu-hegal sconfisse il re dei Guti Tirigan e pose fine al dominio dei Guti", "aa67620c"], "d": ["Il re di Uruk Utu-hegal sconfisse e catturò sulle rive del Tigri Tirigan, re dei Guti che governava Sumer; i Guti si ritirarono da Sumer e al sud fu ristabilita la sovranità sumerica guidata da Uruk. Il generale di Utu-hegal, Ur-Nammu, avrebbe presto fondato la dinastia di Ur III.", "45b2db48"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2152-01-01:0":{"b": ["Gutium: secondo la Lista Reale Sumerica i Guti regnarono a Sumer dopo Accad", "506ad1cb"], "d": ["I Guti, scesi dallo Zagros, dopo il crollo dello Stato accadico dominarono gran parte della Mesopotamia. La Lista Reale Sumerica elenca Gutium come dinastia tra Accad e Uruk V e Ur III (21 re, circa 91-124 anni); anche se la fonte è distorta, il governo dei Guti è documentato come debole successione più che come potente minaccia esterna.", "8ee58415"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2229-01-01:0":{"b": ["Naram-Sin sconfisse nello Zagros i montanari Lullubi (Stele della Vittoria)", "de84161d"], "d": ["La stele a rilievo che mostra la vittoria di Naram-Sin sui Lullubi (Zagros) è l'opera più nota dell'arte accadica. La stele fu poi portata a Susa dal re elamita Shutruk-Nahhunte e fu ritrovata lì nel 1898.", "5e6a3ff7"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2249-01-01:0":{"b": ["Naram-Sin represse la «Grande Rivolta»: fu sconfitta la coalizione di città-Stato guidata da Kish e Uruk", "6e9373e8"], "d": ["All'inizio del regno di Naram-Sin le città del sud, guidate dal re di Kish Iphur-Kish, si ribellarono ad Accad. Naram-Sin, sconfitti i ribelli in nove battaglie, ristabilì il dominio accadico; raccontò la sua vittoria nell'iscrizione dedicata ai templi delle città.", "c9f67d8c"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2260-01-01:0":{"b": ["Naram-Sin salì al trono di Accad; assunse il titolo di «re dei quattro angoli del mondo»", "e9e5261d"], "d": ["Naram-Sin (ca. 2254-2218), nipote di Sargon, guidò lo Stato accadico al suo apice. Fu il primo sovrano mesopotamico a usare per sé il titolo di re divinizzato e l'epiteto di «re dei quattro angoli».", "b56983fc"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:0":{"b": ["Sargon sottomise l'Elam (Awan, Susa, Parahshum)", "1b7806f5"], "d": ["I nomi d'anno e le iscrizioni di Sargon riferiscono la sconfitta dell'Elam (Awan, Parahshum); Susa divenne una città accadica amministrata da governatori accadici e con documenti in accadico. È la prima volta che l'Elam è legato a un impero con centro in Mesopotamia.", "7214e566"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:-2299-01-01:1":{"b": ["Sargon sconfisse il re di Uruk Lugalzagesi e legò ad Accad le città-Stato di Sumer", "aad96bc9"], "d": ["Sargon, re di Agade (Accad), sconfitto il re di Uruk Lugalzagesi, riunì in un'unica mano le città sumeriche (Uruk, Ur, Lagash, Umma, dintorni di Kish). Accad divenne il primo impero a governare l'intera Mesopotamia meridionale.", "4ff76ffe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0231-01-01:0":{"b": ["Ardashir I attaccò la Mesopotamia romana; iniziarono le guerre romano-sasanidi", "576ebb06"], "d": ["Ardashir I, che aveva rovesciato i Parti, nel 230-231 attaccò i dintorni di Nisibis e Carre dando inizio a una lotta con Roma destinata a durare secoli; la campagna del 232 di Severo Alessandro fu senza esito.", "7040e38b"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0240-01-01:0":{"b": ["Hatra cadde in mano sasanide (240-241)", "4f8a58ad"], "d": ["Hatra, città-fortezza commerciale del deserto, dopo la lunga contesa partico-romana fu presa e distrutta nel 240-241 da Ardashir I e Shapur I. La caduta di Hatra eliminò un importante alleato di Roma in Mesopotamia.", "12f25195"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0244-01-01:0":{"b": ["Gordiano III morì presso Ctesifonte; Filippo l'Arabo concluse con Shapur una pace gravosa", "25d270ee"], "d": ["Gordiano III, dopo una campagna in Mesopotamia inizialmente vittoriosa, fu sconfitto da Shapur e morì. Il successore Filippo l'Arabo fece pace con i Persiani; Shapur nella sua iscrizione (ŠKZ) considera l'ascesa al trono di Filippo opera propria e riferisce di aver ricevuto tributo.", "d975e0ec"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:0":{"b": ["Shapur I invase la Siria e saccheggiò Antiochia", "6f938d07"], "d": ["Shapur I condusse una grande campagna nella provincia romana di Siria saccheggiando decine di città, Antiochia compresa, e insediò i prigionieri in Iran. La registrazione di questa campagna è nell'iscrizione ŠKZ di Naqsh-e Rostam.", "17b20275"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0256-01-01:1":{"b": ["Dura-Europos fu presa dai Sasanidi", "c7f39e98"], "d": ["Dura-Europos, guarnigione di frontiera romana sull'Eufrate, cadde dopo un lungo assedio e fu abbandonata; i tunnel d'assedio sasanidi e i controtunnel romani sono documentati archeologicamente. La città non fu mai più abitata.", "889d9ece"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0260-01-01:0":{"b": ["Battaglia di Edessa: Shapur I catturò e fece prigioniero l'imperatore romano Valeriano", "654d57e3"], "d": ["Shapur I sconfisse presso Edessa l'esercito dell'imperatore Valeriano e fece prigioniero personalmente l'imperatore. I rilievi di Bishapur e di Naqsh-e Rostam raccontano questa vittoria; la morte di Valeriano nella prigionia sasanide è la più grande umiliazione della storia di Roma.", "2da6ab5d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0298-01-01:0":{"b": ["Pace di Nisibis: Galerio sconfisse Narseh; i territori oltre il Tigri passarono a Roma", "3046c0f4"], "d": ["L'attacco di Narseh alla Mesopotamia romana si concluse con la vittoria di Galerio; con la pace del 298 le cinque regioni oltre il Tigri (Transtigritania) e Nisibis furono lasciate a Roma. Il trattato fissò per mezzo secolo il confine romano-sasanide.", "4c01c338"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0309-01-01:0":{"b": ["Shapur II salì al trono sasanide dalla nascita (309-379)", "aeed05eb"], "d": ["Dopo la morte di Ormisda II, nella lotta per il trono, Shapur II, nato dalla regina lasciata incinta, fu incoronato prima della nascita e regnò 70 anni. Il suo regno è il periodo della ripresa della lotta con Roma e dell'ingresso dei Kushan sotto il dominio sasanide.", "a2b5cb22"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0359-01-01:0":{"b": ["Shapur II assediò e prese Amida (agosto-ottobre 359)", "0b812592"], "d": ["Shapur II, con gli alleati kushano-chioniti, prese Amida dopo un assedio di 73 giorni, poi conquistò Singara e Bezabde. Ammiano Marcellino era presente all'assedio e lo racconta nei dettagli.", "a86e216d"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-01-01:0":{"b": ["Trattato di Gioviano: Nisibis e cinque regioni oltre il Tigri furono cedute ai Sasanidi", "6e619831"], "d": ["Gioviano, per salvare l'esercito accerchiato, accettò di lasciare ai Sasanidi Nisibis, Singara e le cinque regioni oltre il Tigri; Roma perse le conquiste del 298 durate mezzo secolo. La popolazione di Nisibis si ritirò verso Roma.", "21055f84"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0363-06-26:0":{"b": ["Giuliano morì presso Samarra; la guerra sasanide volse al termine", "86970a50"], "d": ["Dopo che la campagna di Giuliano contro Ctesifonte fu fermata dalle inondazioni, nel ritiro dell'esercito romano l'imperatore, ferito a Maranga in un attacco sasanide, morì. Gioviano, scelto dall'esercito, dovette concludere un trattato con Shapur II.", "9de62fd5"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0387-01-01:0":{"b": ["Accordo romano-sasanide per la spartizione dell'Armenia (Teodosio I - Shapur III)", "228f4d6b"], "d": ["La maggior parte dell'Armenia (orientale) fu lasciata all'influenza sasanide e la piccola parte occidentale all'influenza romana; il regno armeno degli Arsacidi si avviò di fatto alla fine. La divisione determinò per circa due secoli il confine romano-iranico.", "d65941ae"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0451-01-01:0":{"b": ["Battaglia di Avarayr: Yazdgard II represse la rivolta armena", "1bf1df2d"], "d": ["I nobili armeni guidati da Vardan Mamikonian si ribellarono contro l'imposizione dello zoroastrismo da parte dei Sasanidi; ad Avarayr l'esercito fu sconfitto e Vardan morì. Nonostante la sconfitta politica gli Armeni poterono conservare il cristianesimo.", "453512fe"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0484-01-01:0":{"b": ["Peroz I morì in guerra contro gli Eftaliti; i Sasanidi iniziarono a pagare tributo agli Unni", "a418d8ae"], "d": ["Peroz fu annientato con il suo esercito di fronte agli Eftaliti (Unni Bianchi) guidati da Akhshunwar. Lo Stato sasanide dovette accettare un grosso tributo e che il figlio Kavad restasse in ostaggio alla corte eftalita; il confine orientale si indebolì in modo permanente.", "0e4bc9f8"]},
"OLAYLAR_ANTIK_YAKIN_DOGU:0496-01-01:0":{"b": ["Kavad I fu deposto per la sua politica favorevole ai mazdakiti; tornò nel 498-499 con l'aiuto eftalita", "9101bfe7"], "d": ["Kavad I (re dal 488) fu rovesciato per la reazione dei nobili e del clero, si rifugiò presso gli Eftaliti e nel 498-499, con il loro sostegno militare, tornò a Ctesifonte e riprese il trono. Il sostegno eftalita fece nascere il tributo da pagare; la guerra del 502 con Roma nacque da questa necessità.", "06883ad8"]},
"OLAYLAR_AVMAC_A_1029:0009-01-01:0":{"b": ["La Pannonia è organizzata come provincia romana autonoma", "2c130744"], "d": ["Dopo la repressione della rivolta di Pannonia e Dalmazia iniziata nel 6 d.C., nel 9 d.C. la regione fu organizzata come provincia a sé, presidiata da tre legioni; sotto Traiano (circa 106) fu divisa in Pannonia Superiore e Inferiore.", "98bf30e5"]},
"OLAYLAR_AVMAC_A_1029:0433-01-01:0":{"b": ["Roma d'Occidente cede la Pannonia agli Unni; la pianura ungherese entra nel regno unno", "62d960a0"], "d": ["Nel 433, anno in cui iniziò il regno di Attila e Bleda, l'Impero romano d'Occidente cedette agli Unni i territori in Pannonia (la data della cessione è discussa: ipotesi 425/431/433); EB11 «Attila»: il regno personale di Attila comprendeva l'attuale Ungheria e la Transilvania.", "82917628"]},
"OLAYLAR_AVMAC_A_1029:0567-01-01:0":{"b": ["Gli Avari distruggono il regno dei Gepidi; nella pianura ungherese inizia il Khaganato avaro", "cd517799"], "d": ["Gli Avari, alleati dei Longobardi, schiacciarono i Gepidi (567-568) e i Longobardi si ritirarono in Italia; il dominio avaro si estese dal territorio tra Danubio e Tibisco al bacino dei Carpazi.", "5ae3fe4c"]},
"OLAYLAR_AVMAC_A_1029:0822-01-01:0":{"b": ["Ultima menzione del Khaganato avaro: la pianura ungherese resta senza un unico signore (LACUNA DICHIARATA)", "ea8d1f7b"], "d": ["L'ultima menzione politica dello Stato avaro risale al 822 circa (Pohl; Curta); in seguito si contesero l'area sfere di dominio bulgara, franco-orientale e della Grande Moravia, e per il territorio tra Danubio e Tibisco non si è trovata una fonte con un unico detentore — l'atlante lascia questa fascia come lacuna dichiarata.", "09224326"]},
"OLAYLAR_AVMAC_A_1029:0895-01-01:0":{"b": ["Le tribù magiare si stabiliscono nel bacino dei Carpazi (Honfoglalás): nella pianura ungherese inizia il Principato d'Ungheria", "38cd1362"], "d": ["Le tribù magiare guidate da Árpád nell'895-896 varcarono i Carpazi e si stabilirono nel bacino carpatico; l'area tra Danubio e Tibisco passò al Principato d'Ungheria.", "c408bfe0"]},
"OLAYLAR_AVMAC_A_1029:0976-01-01:0":{"b": ["Ottone II nomina Leopoldo di Babenberg margravio della Marca Orientale: a Melk inizia il dominio dei Babenberg", "db5618ff"], "d": ["Nel 976 Ottone II diede la Marca Orientale a Leopoldo di Babenberg; la marca era una marca di confine con centro a Melk e durò fino al 1156.", "65e477d3"]},
"OLAYLAR_AVMAC_A_1029:1129-01-01:0":{"b": ["Prima menzione di Graz (circa 1129): la Marca di Stiria nel Sacro Romano Impero sotto la sovranità del duca di Baviera", "5665e2f1"], "d": ["Graz è menzionata con questo nome intorno al 1129; in questo periodo la Stiria era un territorio di margravi sotto la sovranità del duca di Baviera.", "3de15106"]},
"OLAYLAR_AVMAC_A_1029:1135-01-01:0":{"b": ["I Babenberg diventano signori di Vienna intorno al 1135 (Vienna, Marca dei Babenberg)", "1be7d76c"], "d": ["AEIOU: i Babenberg (976-1246) divennero signori di Vienna intorno al 1135; la città, menzionata per la prima volta nell'881, era stata prima a lungo sotto l'influenza ungherese (l'anno di fine non è dato dalla fonte).", "61ad6f68"]},
"OLAYLAR_AVMAC_A_1029:1156-09-17:0":{"b": ["Privilegium minus (Ratisbona): la Marca d'Austria elevata a ducato — Melk e Vienna nel Ducato d'Austria", "aae53ec8"], "d": ["Il 17 settembre 1156, alla Dieta di Ratisbona, Enrico II Jasomirgott di Babenberg restituì all'imperatore la Baviera dal ducato di Baviera, e la Marca d'Austria fu elevata a ducato completamente separato dalla Baviera; Enrico II aveva trasferito la sua residenza da Klosterneuburg a Vienna intorno al 1155.", "699d9349"]},
"OLAYLAR_AVMAC_A_1029:1180-01-01:0":{"b": ["La Stiria elevata a ducato autonomo (duca Ottocaro IV): Graz nel Ducato di Stiria", "c411776c"], "d": ["La Marca di Stiria, sotto la sovranità del duca di Baviera, nel 1180 divenne ducato indipendente; Graz ne era il centro. Il giorno non è nella fonte (la scheda cita la Dieta di Gelnhausen).", "ba70cadc"]},
"OLAYLAR_AVMAC_A_1029:1192-05-08:0":{"b": ["Muore Ottocaro IV, ultimo duca ottocariano: la Stiria (Graz) passa a Leopoldo V di Babenberg, al Ducato d'Austria, in base al Patto di Georgenberg", "e9a69d4d"], "d": ["Con la morte, l'8 maggio 1192, di Ottocaro IV, senza figli, il Ducato di Stiria passò a Leopoldo V di Babenberg in base al Patto di Georgenberg del 17 agosto 1186; i due ducati continuarono in unione personale.", "6a7f7440"]},
"OLAYLAR_AVMAC_A_1029:1194-01-01:0":{"b": ["Wiener Neustadt fondata dal duca babenberghese Leopoldo V contro il confine ungherese", "a5c1bd3f"], "d": ["La città fu fondata da Leopoldo V intorno al 1192-94 contro il confine ungherese; si assume come anno di fondazione il 1194.", "4a6b4cb3"]},
"OLAYLAR_AVMAC_A_1029:1254-04-03:0":{"b": ["Pace preliminare di Ofen: la Stiria (Graz) al re d'Ungheria Béla IV, l'Austria a Ottocaro II", "06d3f258"], "d": ["Estinta la dinastia dei Babenberg nel 1246, il re di Boemia Ottocaro II e il re d'Ungheria Béla IV si contesero Austria e Stiria; nella pace preliminare firmata a Ofen il 3 aprile 1254 Ottocaro tenne l'Austria e la Stiria settentrionale, mentre Béla ebbe il resto della Stiria (Graz).", "9926cc5c"]},
"OLAYLAR_AVMAC_A_1029:1260-07-12:0":{"b": ["Battaglia di Kressenbrunn (Groißenbrunn): Ottocaro II sconfigge gli Ungheresi, Béla rinuncia alla Stiria (Graz)", "c2343628"], "d": ["Alla fine del 1259 scoppiò in Stiria una rivolta contro il dominio ungherese; con l'appoggio di Ottocaro II, il 12 luglio 1260 a Kroissenbrunn, nel Marchfeld, l'esercito ungherese fu sconfitto, Béla IV rinunciò alla Stiria, che nelle mani di Ottocaro si unì all'Austria.", "3d598fe2"]},
"OLAYLAR_AVMAC_A_1029:1282-12-27:0":{"b": ["Ad Augusta il re Rodolfo fa duchi d'Austria e di Stiria i figli Alberto e Rodolfo: Vienna, Graz, Linz, Freistadt, Gmünd, Maribor, Hartberg e Wiener Neustadt in feudo agli Asburgo", "c34bf152"], "d": ["Il 27 dicembre 1282, nella dieta di corte di Augusta, Rodolfo I investì i figli Alberto e Rodolfo dei ducati d'Austria e di Stiria (con la Carniola e la Marca Windisch). I territori austriaci, in mano all'Impero dal 1276 al 1282, da questo giorno sono territorio asburgico; inizia il dominio asburgico in Austria, durato circa 650 anni.", "97864694"]},
"OLAYLAR_AVMAC_A_1029:1363-01-26:0":{"b": ["Margherita Maultasch cede il Tirolo agli Asburgo: Innsbruck e Landeck diventano territorio asburgico", "0b606d4e"], "d": ["La contessa del Tirolo Margherita «Maultasch» il 26 gennaio 1363 a Bolzano cedette i propri diritti sul paese al duca asburgico Rodolfo IV e ai suoi fratelli; la Contea del Tirolo ebbe fine, e Innsbruck e Landeck furono unite ai ducati asburgici.", "96cae3e2"]},
"OLAYLAR_AVMAC_A_1029:1379-01-01:0":{"b": ["Completato il passaggio della contea di Montfort-Feldkirch agli Asburgo: Feldkirch in mano al duca Leopoldo III (vendita nel maggio 1375)", "5fbe6055"], "d": ["Il conte Rodolfo di Montfort-Feldkirch nel maggio 1375 vendette la contea di Feldkirch e i suoi possedimenti al duca Leopoldo III; dopo il pagamento il passaggio avvenne nel 1379, e il conte conservò l'usufrutto (Vogt) a vita; il ramo Montfort-Feldkirch si estinse nel 1390.", "1af13fa1"]},
"OLAYLAR_AVMAC_A_1029:1500-04-12:0":{"b": ["Muore a Lienz il conte di Gorizia Leonhard: i possedimenti goriziani (Lienz e Tirolo orientale) passano a Massimiliano I d'Asburgo", "0f63cdc0"], "d": ["Quando il 12 aprile 1500 morì a Lienz Leonhard, ultimo conte della dinastia dei conti di Gorizia, in base al patto successorio (Erbvertrag) firmato poco prima della morte i possedimenti goriziani passarono alla Casa d'Asburgo (re Massimiliano I); il Tirolo orientale (Lienz) fu amministrato con il Land Tirolo.", "2525327d"]},
"OLAYLAR_AVMAC_A_1029:1523-01-01:0":{"b": ["La seconda metà di Bregenz venduta all'arciduca Ferdinando: Bregenz interamente territorio asburgico", "57fa353f"], "d": ["La metà della contea di Montfort-Bregenz era stata venduta nel 1451 al duca Sigismondo; Hugo XVII di Montfort nel 1523 vendette l'altra metà all'arciduca Ferdinando (Ferdinando I) e Bregenz divenne interamente asburgica.", "7e3168c4"]},
"OLAYLAR_AVMAC_B_1029:1363-01-26:0":{"b": ["La Contea del Tirolo passa agli Asburgo", "aeb497e3"], "d": ["La contessa del Tirolo Margherita Maultasch, dopo la morte del figlio Mainardo III (gennaio 1363), lasciò il paese ai duchi asburgici; il Tirolo entrò senza guerra nel complesso dei territori asburgici. Sulla mappa, in questo anno Innsbruck e Landeck passano dalla Contea del Tirolo all'Austria asburgica.", "0a7ec25a"]},
"OLAYLAR_AVMAC_B_1029:1526-10-23:0":{"b": ["Ferdinando I eletto re di Boemia — gli Asburgo ottengono la corona di Boemia", "1fd034bc"], "d": ["Dopo la morte di Luigi II a Mohács la Dieta di Boemia elesse re Ferdinando in cambio di condizioni elettorali (conferma dei privilegi); l'incoronazione è del febbraio 1527. Boemia, Moravia e Slesia furono così legate alla corona asburgica.", "d02cb97b"]},
"OLAYLAR_AVMAC_B_1029:1527-11-03:0":{"b": ["Ferdinando I incoronato re d'Ungheria ad Alba Reale (Székesfehérvár)", "3273aa8b"], "d": ["Ferdinando, che nel settembre 1527 aveva preso Buda a Szapolyai, fu incoronato a Székesfehérvár, città dell'incoronazione dei re ungheresi, e con il rivale Szapolyai si consolidò l'epoca dei due re.", "6ac87b55"]},
"OLAYLAR_AVMAC_B_1029:1540-07-22:0":{"b": ["Morte di János Szapolyai — la questione di Buda e la porta della divisione dell'Ungheria", "6bfecba1"], "d": ["Szapolyai, re dell'Ungheria orientale e vassallo ottomano, morì lasciando come erede il figlio nato da poco. L'ingresso di Solimano il Magnifico a Buda nel 1541 e la divisione dell'Ungheria in tre (Ungheria reale, eyalet di Buda, Transilvania) sono conseguenze di questa morte.", "3506b4e8"]},
"OLAYLAR_AVMAC_B_1029:1555-01-01:0":{"b": ["Ptuj (Pettau) ripresa a Salisburgo e unita alla Stiria asburgica", "cfbd3d64"], "d": ["Ptuj, che Massimiliano I nel 1511 aveva lasciato all'arcivescovo di Salisburgo come pegno o con diritto di vendita, fu riacquistata nel 1555 dal re Ferdinando e unita al ducato di Stiria; la signoria di Salisburgo sul Dravsko polje ebbe fine.", "f23f6ca1"]},
"OLAYLAR_AVMAC_B_1029:1606-06-23:0":{"b": ["Pace di Vienna — finisce la rivolta di Bocskai, riconosciuto il principe di Transilvania", "30fced42"], "d": ["Il sovrano asburgico riconobbe a Bocskai il diritto ereditario sulla Transilvania e il governo di quattro comitati dell'Ungheria reale, e confermò i privilegi costituzionali e confessionali della nobiltà ungherese. Il Trattato di Zsitvatorok del novembre dello stesso anno completò questa pace.", "691e8a43"]},
"OLAYLAR_AVMAC_B_1029:1711-04-29:0":{"b": ["Pace di Szatmár — finisce la guerra d'indipendenza di Rákóczi, la Transilvania passa all'amministrazione asburgica", "02940f3c"], "d": ["L'accordo tra Sándor Károlyi, comandante dell'esercito kuruc, e János Pálffy, comandante in capo imperiale, pose fine alla rivolta di Rákóczi in corso dal 1703; furono salvaguardati i privilegi della nobiltà ungherese e l'esistenza costituzionale della Transilvania, ma il paese passò di fatto sotto l'amministrazione del sovrano asburgico. Si consolidò così il periodo asburgico del Principato di Transilvania, vassallo ottomano, iniziato nel 1699.", "27c9430c"]},
"OLAYLAR_AVMAC_B_1029:1803-02-25:0":{"b": ["Reichsdeputationshauptschluss: Bressanone e Trento all'Austria, Salisburgo all'elettorato del duca di Toscana Ferdinando", "84176083"], "d": ["In base alla decisione finale che abolì i principati ecclesiastici del Sacro Romano Impero, i principati vescovili di Bressanone e Trento furono uniti all'Austria; il Principato arcivescovile di Salisburgo fu secolarizzato e dato come elettorato al duca di Toscana Ferdinando. Con questa decisione Trento (Principato vescovile di Trento) passò all'Austria.", "eed61208"]},
"OLAYLAR_AVMAC_B_1029:1804-08-11:0":{"b": ["Francesco II proclama l'Impero austriaco — impero ereditario d'Austria", "a7a21bd4"], "d": ["In risposta al fatto che Napoleone era diventato imperatore dei Francesi, Francesco II con un patente assunse per i territori asburgici il titolo di imperatore ereditario d'Austria. Poiché deteneva ancora la corona del Sacro Romano Impero, i due titoli imperiali coesistettero fino al 1806.", "c36c2b17"]},
"OLAYLAR_AVMAC_B_1029:1805-12-26:0":{"b": ["Dettaglio territoriale della Pace di Presburgo: Salisburgo all'Austria; Bressanone, Trento, Tirolo e Vorarlberg alla Baviera", "89320189"], "d": ["Dopo Austerlitz l'Austria cedette al re di Baviera la Contea del Tirolo (con i principati vescovili di Bressanone e Trento) e il Vorarlberg. In cambio l'antico arcivescovato di Salisburgo e Berchtesgaden furono uniti all'impero austriaco.", "cc8f9ed7"]},
"OLAYLAR_AVMAC_B_1029:1806-08-06:0":{"b": ["Francesco II depone la corona del Sacro Romano Impero — l'Impero finisce", "4c2d7db6"], "d": ["Dopo la fondazione della Confederazione del Reno, Francesco dichiarò sciolto il Sacro Romano Impero e rinunciò alla corona, restando soltanto imperatore d'Austria.", "0adaf7b6"]},
"OLAYLAR_AVMAC_B_1029:1809-10-14:0":{"b": ["Dettaglio territoriale della Pace di Schönbrunn: Salisburgo e l'Alta Carinzia (Villach, Tarvisio, Lienz) separate dall'Austria", "cb38caa1"], "d": ["Dopo la sconfitta del 1809 l'Austria cedette Salisburgo, l'Alta Carinzia (con Villach e, nel Tirolo orientale, Lienz), la Carniola e Trieste; le parti di Carinzia e Carniola formarono le Province Illiriche di Napoleone. Con questa pace Lubiana (Kranj), Gradisca (Gorizia) e Karlovac (Croazia a sud della Sava) passarono alla Francia; Cracovia, Kielce, Radom, Chełm (Nuova Galizia) e Zamość al Ducato di Varsavia.", "27b600e4"]},
"OLAYLAR_AVMAC_B_1029:1848-03-15:0":{"b": ["A Pest inizia la Rivoluzione di Marzo — Rivoluzione ungherese 1848-49", "8771df07"], "d": ["Le manifestazioni iniziate al caffè Pilvax, dopo la rivoluzione a Vienna (13 marzo), portarono a Pest all'accettazione dei Dodici Punti da parte del governatore; iniziò il movimento nazionale ungherese contro la monarchia asburgica.", "1a23901b"]},
"OLAYLAR_AVMAC_B_1029:1848-04-11:0":{"b": ["Sanzionate le Leggi d'Aprile — all'Ungheria governo responsabile e ministeri indipendenti", "93feca5f"], "d": ["Le leggi adottate a marzo dalla Dieta di Presburgo furono sanzionate dal re Ferdinando V: un consiglio dei ministri ungherese responsabile, l'abolizione degli obblighi servili e l'allargamento del diritto di voto. Queste leggi furono riprese come fondamento costituzionale che portò al Compromesso (Ausgleich) del 1867.", "747be87a"]},
"OLAYLAR_AVMAC_B_1029:1848-09-11:0":{"b": ["L'esercito croato di Jelačić attraversa la Drava — inizia la guerra d'indipendenza ungherese", "7b66436f"], "d": ["Il bano di Croazia Jelačić, con l'appoggio della corte asburgica, attraversò con un esercito di circa 50.000 uomini la Drava, confine ungaro-croato; lo stesso giorno il governo Batthyány si dimise e il conflitto si trasformò in guerra aperta.", "50b29c18"]},
"OLAYLAR_AVMAC_B_1029:1849-04-14:0":{"b": ["Dichiarazione d'indipendenza di Debrecen — la dinastia asburgica detronizzata, Kossuth capo dello Stato", "2510414e"], "d": ["La Dieta ungherese nella Grande Chiesa Riformata proclamò la detronizzazione della dinastia Asburgo-Lorena e l'Ungheria Stato indipendente; Kossuth fu eletto «governatore-presidente».", "451d3e00"]},
"OLAYLAR_AVMAC_B_1029:1849-08-13:0":{"b": ["A Világos l'esercito ungherese si arrende ai Russi — la Rivoluzione ungherese è repressa", "10218bca"], "d": ["Görgei, accerchiato dall'intervento russo, dopo che Kossuth gli ebbe trasferito i poteri (11 agosto) si arrese alle forze russe a Világos; ciò è considerato la fine di fatto della rivoluzione. Kossuth e i suoi compagni si rifugiarono presso gli Ottomani (v. 16 agosto 1849).", "f7f58bec"]},
"OLAYLAR_AVMAC_B_1029:1849-10-06:0":{"b": ["Ad Arad giustiziati 13 generali ungheresi, a Pest fucilato Lajos Batthyány", "962a8e24"], "d": ["Per ordine di Haynau tredici generali ungheresi furono giustiziati ad Arad e il primo primo ministro ungherese, Batthyány, fu fucilato a Pest. Il 6 ottobre è oggi in Ungheria giorno di lutto nazionale.", "ed583677"]},
"OLAYLAR_AVMAC_B_1029:1867-02-17:0":{"b": ["Ricostituito il governo costituzionale ungherese — Gyula Andrássy primo ministro", "6818a618"], "d": ["Francesco Giuseppe, su proposta di Ferenc Deák, nominò Gyula Andrássy primo ministro d'Ungheria, ripristinando l'ordinamento costituzionale ungherese anteriore al 1848; il governo prestò giuramento il 20 febbraio. Questo passo aprì la via all'accettazione del Compromesso (Ausgleich).", "6138daea"]},
"OLAYLAR_AVMAC_B_1029:1867-05-29:0":{"b": ["Compromesso (Ausgleich): la Dieta ungherese approva la legge n. XII del 1867 — monarchia duale austro-ungarica", "02a1a703"], "d": ["La Dieta ungherese, riconvocata, approvò con 209 voti contro 89 la legge n. XII del 1867, che regola gli affari comuni (politica estera, esercito e relative finanze). La monarchia asburgica si trasformò in una struttura duale di due metà sovrane (Impero d'Austria e Regno d'Ungheria); l'Ungheria divenne partner paritario.", "3692683a"]},
"OLAYLAR_AVMAC_B_1029:1867-06-08:0":{"b": ["Francesco Giuseppe ed Elisabetta incoronati a Buda re e regina d'Ungheria", "821b03d9"], "d": ["La corona di Santo Stefano fu posta sul capo di Francesco Giuseppe nella Chiesa di Mattia dal Primate e dal primo ministro Andrássy; con questa cerimonia il Compromesso fu legato all'autorità del re nel diritto ungherese.", "7fdd290d"]},
"OLAYLAR_AVMAC_C_1029:1867-06-08:0":{"b": ["Francesco Giuseppe I incoronato a Budapest re d'Ungheria — completata la monarchia duale (Austria-Ungheria)", "fb8bb53c"], "d": ["Il Compromesso (Ausgleich) del 1867 riconobbe all'Ungheria governo e parlamento distinti per gli affari interni; politica estera, esercito e finanze comuni restarono comuni. Francesco Giuseppe fu incoronato re d'Ungheria l'8 giugno 1867.", "aeaa3757"]},
"OLAYLAR_AVMAC_C_1029:1918-11-11:0":{"b": ["L'imperatore Carlo I dichiara di rinunciare a partecipare agli affari di Stato (per l'Austria)", "bcf92744"], "d": ["Carlo dichiarò l'11 novembre 1918 di rinunciare a partecipare agli affari di Stato in Austria; non abdicò esplicitamente al trono. Il giorno dopo l'Assemblea nazionale provvisoria proclamò la forma repubblicana. Il manifesto separato per l'Ungheria (Eckartsau) è datato 13 novembre.", "1e5db392"]},
"OLAYLAR_AVMAC_C_1029:1918-11-13:0":{"b": ["Manifesto di Carlo a Eckartsau: rinuncia a partecipare agli affari di Stato ungheresi, scioglie i funzionari dai giuramenti di fedeltà", "dad220a1"], "d": ["Il manifesto scritto a Eckartsau è datato 13 novembre 1918; fu pubblicato a Budapest il 14 novembre. Carlo rinunciò soltanto all'esercizio dei diritti di sovranità e non usò l'espressione «abdicazione». Sulla mappa le catene ungheresi cambiano l'11 novembre, e la proclamazione della Repubblica popolare nella scheda è del 16 novembre; il 13 novembre è l'anello giuridico tra questi due giorni.", "4bf52e81"]},
"OLAYLAR_AVMAC_C_1029:1918-11-16:0":{"b": ["Il Consiglio nazionale ungherese proclama la Repubblica popolare d'Ungheria — con Károlyi la monarchia è abolita ufficialmente", "aa84a13d"], "d": ["Károlyi era stato nominato primo ministro da Carlo il 31 ottobre 1918 (Rivoluzione dei crisantemi). Il 16 novembre 1918 il Consiglio nazionale e il governo proclamarono la Repubblica popolare; l'11 gennaio 1919 Károlyi divenne presidente provvisorio. Le schede macaristan-naiplik e macaristan-halk-cumhuriyeti iniziano da questo giorno. Con questo evento le città del Regno d'Ungheria al di fuori della Croazia, tra cui Aquincum-Óbuda-Pest, Esztergom, Eger, Szeged, Debrecen, Oradea e l'Alta Ungheria, passarono alla Repubblica popolare d'Ungheria.", "22729026"]},
"OLAYLAR_AVMAC_C_1029:1919-03-21:0":{"b": ["Il governo di Béla Kun proclama la Repubblica sovietica ungherese", "49fd405f"], "d": ["Quando la nota Vix dell'Intesa (20 marzo) chiese il ritiro delle truppe ungheresi, il governo Károlyi si dimise; i comunisti, uniti ai socialdemocratici, fondarono la Repubblica sovietica il 21 marzo 1919. La repubblica durò 133 giorni (TDV: esiste anche un'espressione che dice 121 giorni); in questo periodo la mappa usa l'identità macaristan-naiplik.", "6ab3f507"]},
"OLAYLAR_AVMAC_C_1029:1919-08-04:0":{"b": ["L'esercito romeno entra a Budapest — tre giorni dopo la fuga di Kun", "cef2c6e5"], "d": ["Kun e il suo entourage fuggirono in Austria il 1° agosto 1919; l'esercito romeno occupò Budapest tre giorni dopo e vi rimase fino a metà novembre 1919.", "d681e899"]},
"OLAYLAR_AVMAC_C_1029:1919-11-16:0":{"b": ["L'Esercito nazionale di Horthy entra a Budapest — dopo il ritiro romeno la controrivoluzione prende il potere", "1612486e"], "d": ["Le truppe romene lasciarono Budapest il 14 novembre 1919; l'Esercito nazionale al comando di Horthy entrò in città il 16 novembre 1919. Si aprì così la via alla nomina di Horthy a reggente il 1° marzo 1920.", "0204b470"]},
"OLAYLAR_AVMAC_C_1029:1921-10-13:0":{"b": ["Protocollo di Venezia — l'Ungheria accetta di cedere il Burgenland all'Austria e il plebiscito a Sopron", "b331d8e9"], "d": ["Al termine dei colloqui dell'11-13 ottobre 1921, mediati dall'Italia, l'Ungheria accettò di ritirare le truppe e lasciare il Burgenland all'Austria; l'Austria accettò di tenere un plebiscito a Sopron e in otto villaggi circostanti. Il primo tentativo austriaco del 28 agosto 1921 era fallito a causa delle bande ungheresi (la gendarmeria tornò al vecchio confine il 10 settembre).", "d1394072"]},
"OLAYLAR_AVMAC_C_1029:1921-12-14:0":{"b": ["Inizia il plebiscito di Sopron — circa il 65 per cento dei voti a favore dell'Ungheria", "19a0e821"], "d": ["Il 14-15 dicembre 1921 votarono Sopron e Brennbergbánya, il 16 dicembre gli otto villaggi circostanti. In città prevalse l'Ungheria, nella maggior parte dei villaggi l'Austria; nel complesso l'Ungheria ebbe circa il 65 per cento. La Commissione dei generali alleati cedette la zona all'Ungheria il 1° gennaio 1922 (la catena di Sopron sulla mappa resta ungherese).", "d6835a9a"]},
"OLAYLAR_AVMAC_C_1029:1938-03-12:0":{"b": ["Le truppe tedesche entrano in Austria — la legge sull'Anschluss emanata il giorno dopo", "67bcdbe4"], "d": ["L'appello di Schuschnigg a un plebiscito spinse Hitler a intervenire; l'esercito tedesco entrò in Austria il 12 marzo 1938 e il 13 marzo fu legiferata l'annessione dell'Austria al Reich (sulla mappa le catene cambiano il 13 marzo).", "75889d44"]},
"OLAYLAR_AVMAC_C_1029:1944-03-19:0":{"b": ["La Germania occupa l'Ungheria (Operazione Margarethe)", "af09f10c"], "d": ["Poiché l'Ungheria cercava una pace separata con gli Alleati, le truppe tedesche occuparono il paese il 19 marzo 1944; fu formato il governo Sztójay e iniziò la deportazione degli ebrei ungheresi. Horthy fu rovesciato il 15 ottobre 1944 dopo il tentativo di proclamare l'armistizio e prese il potere la Croce Frecciata.", "929c43ce"]},
"OLAYLAR_AVMAC_C_1029:1945-04-04:0":{"b": ["L'esercito sovietico libera l'Ungheria dal controllo tedesco — le ultime truppe tedesche cacciate dal paese", "42677734"], "d": ["L'esercito sovietico, entrato in Ungheria, pose fine all'influenza tedesca il 4 aprile 1945. L'Ungheria restò sotto il controllo della Commissione alleata (sovietica) di controllo fino al 1946; la repubblica fu proclamata il 1° febbraio 1946.", "889a06b4"]},
"OLAYLAR_AVMAC_C_1029:1945-04-13:0":{"b": ["L'Armata Rossa prende Vienna — finisce la battaglia di Vienna", "6e2c5932"], "d": ["L'Armata Rossa raggiunse la periferia occidentale di Vienna il 5 aprile 1945; il 13 aprile alle ore 14 il comando sovietico annunciò la fine dei combattimenti. Il governo provvisorio di Renner due settimane dopo, il 27 aprile, proclamò l'indipendenza dell'Austria (sulla mappa la catena di Vienna passa il 27 aprile dalla Germania alla Seconda Repubblica).", "edda5e9f"]},
"OLAYLAR_AVMAC_C_1029:1945-07-09:0":{"b": ["Accordo sulla divisione di Vienna in quattro settori — gli Alleati occidentali si insediano nei loro settori il 1° settembre", "fde401dc"], "d": ["L'accordo sulle zone di occupazione (Besatzungszonen) e sull'amministrazione della città di Vienna è datato 9 luglio 1945; le forze di Stati Uniti, Gran Bretagna e Francia giunsero nei loro settori il 1° settembre 1945 e il Consiglio alleato si riunì l'11 settembre. Il controllo delle quattro potenze durò fino al 1955. Sulla mappa non esiste un'identità di zona di occupazione a sé (congelamento del motore: non è stata aggiunta una nuova chiave BOYALAR).", "84400060"]},
"OLAYLAR_AVMAC_C_1029:1949-08-20:0":{"b": ["Entra in vigore la costituzione della Repubblica popolare d'Ungheria — regime monopartitico di tipo sovietico", "7ae2e817"], "d": ["La costituzione del 20 agosto 1949 fece dell'Ungheria una Repubblica popolare. La scheda macaristan-halk (1946-1989) tiene questi due regimi come un unico polity; il colore della mappa non cambia.", "5d0fed8b"]},
"OLAYLAR_AVMAC_C_1029:1955-05-15:0":{"b": ["Firmato a Vienna il Trattato di Stato austriaco — finisce l'occupazione delle quattro potenze", "24d4a84a"], "d": ["Stati Uniti, URSS, Gran Bretagna, Francia e Austria firmarono il Trattato di Stato nel Palazzo del Belvedere il 15 maggio 1955; il trattato entrò in vigore il 27 luglio 1955, le ultime truppe di occupazione partirono il 25 ottobre 1955 e il Parlamento austriaco il 26 ottobre 1955 approvò la legge costituzionale sulla neutralità permanente.", "bee39b98"]},
"OLAYLAR_AVMAC_C_1029:1956-10-23:0":{"b": ["Inizia l'insurrezione ungherese — l'intervento sovietico del 4 novembre la reprime", "1ee940b8"], "d": ["Le forti oppressioni portarono il 23 ottobre 1956 a una sollevazione popolare; le truppe sovietiche intervennero il 4 novembre. Territorio e confini non cambiarono; il regime continuò sotto Kádár (macaristan-halk).", "2840fe28"]},
"OLAYLAR_AVMAC_C_1029:1995-01-01:0":{"b": ["L'Austria entra nell'Unione Europea", "d0e82f3a"], "d": ["L'Austria divenne membro dell'UE il 1° gennaio 1995 insieme a Svezia e Finlandia. Stato e confini non cambiarono; la catena avusturya-ikinci-cumhuriyet prosegue.", "918c4a29"]},
"OLAYLAR_AVMAC_C_1029:2004-05-01:0":{"b": ["L'Ungheria entra nell'Unione Europea", "3a28647d"], "d": ["L'Ungheria divenne membro dell'UE il 1° maggio 2004 insieme a nove paesi. Stato e confini non cambiarono; la catena macaristan-cumhuriyeti prosegue.", "89c56f8e"]},
"OLAYLAR_AVMAC_FINAL_1029:1703-01-01:0":{"b": ["Inizia la rivolta kuruc antiasburgica guidata da Francesco II Rákóczi", "c7b4261d"], "d": ["Il manifesto di Brezán di Rákóczi (ricordato come 6 maggio 1703) e l'incontro di Tamás Esze con le truppe kuruc nel giugno 1703 diedero inizio alla rivolta; la guerra terminò con la Pace di Szatmár del 1711. Solo precisione all'anno: la data del manifesto/dell'inizio nelle fonti secondarie varia tra 6 maggio, 21 maggio e 15 giugno; non si è trovata una fonte accademica per il giorno (debito).", "a9813686"]},
"OLAYLAR_AVMAC_FINAL_1029:1866-07-03:0":{"b": ["Battaglia di Königgrätz (Sadowa): la Prussia sconfigge Austria e Sassonia", "ff3c7c9a"], "d": ["Battaglia decisiva della Guerra delle Sette Settimane; finì la guida austriaca nella Confederazione germanica e si aprì la via al Compromesso del 1867.", "e3230571"]},
"OLAYLAR_AVMAC_FINAL_1029:1866-08-23:0":{"b": ["Pace di Praga: l'Austria conserva i territori tranne Venezia, la Prussia prende lo Schleswig-Holstein", "d8dae04b"], "d": ["Il Trattato di Praga del 23 agosto 1866 pose fine alla Guerra delle Sette Settimane; l'Austria non subì occupazione e il suo confine non cambiò (Venezia fu lasciata all'Italia con il Trattato di Vienna del 3 ottobre 1866, v. voce separata).", "5d287a6a"]},
"OLAYLAR_AVUSTURYA_MACAR_1027:0455-01-01:0":{"b": ["Fondato il Regno dei Gepidi: Ardarico sconfigge gli Unni, il Tibisco e la Transilvania passano sotto sovranità gepida", "f67147d8"], "d": ["A Nedao la rivolta guidata dal gepida Ardarico fece crollare l'unione unna (Britannica 455, Maenchen-Helfen 454); Ardarico fondò sul Danubio medio il Regno dei Gepidi, con centro Sirmio. Il regno fu distrutto nel 567 dall'alleanza di Avari e Longobardi (precisione all'anno).", "a478d0c6"]},
"OLAYLAR_AVUSTURYA_MACAR_1027:1523-01-01:0":{"b": ["Bregenz passa agli Asburgo: Hugo XVII Montfort-Bregenz vende il resto del possedimento", "8571fa82"], "d": ["Metà di Bregenz fu venduta nel 1451 al duca Sigismondo, l'altra metà nel 1523 all'arciduca Ferdinando I; la mappa mostra il pieno dominio dal 1523, mentre il mezzo dominio 1451-1523 è dichiarato (giorno non trovato).", "b7bcbce4"]},
"OLAYLAR_AVUSTURYA_MACAR_1027:1918-11-16:0":{"b": ["Proclamata la Repubblica popolare d'Ungheria: la Grande Assemblea nazionale dichiara l'Ungheria repubblica popolare indipendente", "cbd2aeb9"], "d": ["Carlo il 13 novembre 1918 pubblicò il manifesto di ritiro dalla politica ungherese; il 16 novembre la Grande Assemblea nazionale del Consiglio nazionale ungherese proclamò il «Decreto popolare» e fece dell'Ungheria una repubblica popolare indipendente, con Károlyi primo ministro e presidente provvisorio; il dominio asburgico di 400 anni finì ufficialmente. (Il governo era stato formato il 31 ottobre dalla Rivoluzione dei crisantemi, e la repubblica fu proclamata in questo giorno.)", "3b6fc01d"]},
"OLAYLAR_CINHINDI1115B:0979-01-01:0":{"b": ["Finisce la dinastia Đinh; Lê Hoàn sale al trono di Đại Cồ Việt (Hall: Đinh 968-79, Lê 979-1009)", "aee5ca3e"], "d": ["Secondo Hall, il regno indipendente di Annam-Tonchino continuò dopo la dinastia Ngô con la dinastia Đinh (968-79); i Đinh ebbero vita brevissima. I primi Lê (979-1009) iniziarono con forza; il loro primo re, Lê Hoàn, invase il Champa nel 982. La capitale è Hoa-lu.", "fc94ca4e"]},
"OLAYLAR_CINHINDI1115B:1404-01-01:0":{"b": ["L'esercito birmano (Ava) prende Launggyet, capitale dell'Arakan; il re Narameikhla fugge in Bengala", "17449f1b"], "d": ["La spedizione del 1404 del principe Minrekyawswa, in nome del re di Ava Minhkaung, entrò in Arakan e occupò Launggyet; il re dell'Arakan Narameikhla fuggì in Bengala (Gaur) e i Birmani lasciarono al suo posto Anawrahtaminsaw.", "558ec7e3"]},
"OLAYLAR_CINHINDI1115B:1430-01-01:0":{"b": ["Narameikhla torna sul trono dell'Arakan con le truppe fornite dal sultanato di Gaur (Bengala); i re iniziano a usare titoli musulmani", "2de50176"], "d": ["Narameikhla, rimasto per molti anni in esilio in Bengala, nel 1430 fu reinsediato sul trono con le truppe date dal re di Gaur. Harvey registra che da allora i re buddhisti dell'Arakan usarono, accanto ai propri nomi, titoli musulmani e medaglioni con la shahada in persiano.", "1b45fa30"]},
"OLAYLAR_CINHINDI1115B:1433-01-01:0":{"b": ["Narameikhla sposta la capitale da Launggyet a Mrohaung (Mrauk U); la città resta capitale per quattro secoli", "d24b8d43"], "d": ["Secondo Harvey, gli indovini avevano detto che, se la capitale fosse stata spostata, il re sarebbe morto entro l'anno; Narameikhla fondò comunque Mrohaung nel 1433 e morì l'anno seguente. La città fu capitale dell'Arakan dal 1433 al 1785 (cronologia di Harvey: Launggyet 1237-1433, Mrohaung 1433-1785).", "6f658fb6"]},
"OLAYLAR_CINHINDI1115B:1459-01-01:0":{"b": ["Il re dell'Arakan Basawpyu prende Chittagong; la città resta per lo più in mano arakanese fino al 1666", "ebed3abb"], "d": ["Basawpyu (Kalima Shah, 1459-82), successore di Narameikhla, occupò Chittagong nel 1459. Secondo Harvey la città fu per lo più in mano arakanese fino al 1666; quando il Bengala era forte l'Arakan gli pagava tributo, quando l'Arakan era forte lo riscuoteva dal delta del Gange.", "a2258a32"]},
"OLAYLAR_CINHINDI1115B:1471-01-01:0":{"b": ["Lê Thánh Tông dà il colpo mortale al Champa; Vijaya viene annessa a Đại Việt", "b7e2f51c"], "d": ["Secondo Hall, nel 1446 gli Annamiti, approfittando della guerra civile, avevano occupato Vijaya per breve tempo e i Cham l'avevano ripresa; Lê Thánh Tông (1460-97), il più grande dei Lê, nel 1471 inflisse il colpo mortale al regno cham e fece del Champa un anello della propria sfera di sovranità.", "e2cbc8c0"]},
"OLAYLAR_CINHINDI1115B:1539-01-01:0":{"b": ["Tabinshwehti entra a Pegu (Bago) senza combattere; la capitale mon passa al re di Toungoo", "94c983ef"], "d": ["L'esecuzione, come traditori, di due comandanti del regno talaing (mon) fece perdere all'esercito il morale e i suoi capi; il re mon fuggì a Prome e Tabinshwehti nel 1539 entrò a Pegu senza combattere e vi stabilì la sua corte.", "6d2926cb"]},
"OLAYLAR_CINHINDI1115B:1591-01-01:0":{"b": ["Nokéo Koumane proclamato re a Vientiane; l'anno seguente spezza la resistenza di Luang Prabang e riunifica il Lan Xang", "381a2f2c"], "d": ["Secondo Hall, mentre l'impero di Bayinnaung si dissolveva, il Lan Xang (Laos) riprese l'indipendenza sotto la guida di Nokéo Koumane; Koumane fu proclamato re a Vientiane nel 1591 e nel 1592 sottomise anche Luang Prabang, riunificando il paese; il Tran Ninh gli giurò fedeltà.", "4c065cea"]},
"OLAYLAR_CINHINDI1115B:1592-01-01:0":{"b": ["Finisce il dominio della dinastia Mạc in Tonchino; la dinastia Lê torna a Thăng Long (Hanoi)", "82865be2"], "d": ["Mạc Đăng Dung aveva usurpato il trono nel 1527; nel 1533 la dinastia Lê era stata ristabilita tramite la famiglia Nguyễn (Nguyễn Kim aveva cacciato i Mạc da Nghệ An e Thanh Hóa), ma aveva lasciato il Tonchino in mano ai Mạc. Secondo Hall i Mạc governarono il Tonchino fino al 1592.", "7225b7df"]},
"OLAYLAR_CINHINDI1115B:1593-02-01:0":{"b": ["Il re del Siam Naresuan sconfigge l'erede al trono birmano; l'indipendenza siamese è definitiva", "44861a4e"], "d": ["Hall scrive che gli sforzi di Nanda Bayin per ristabilire il dominio sul Siam furono fermati nel 1593 da una sconfitta decisiva e che da quel momento l'indipendenza siamese fu assicurata; Pamaree Surakiat registra che Naresuan nel 1593 riportò a Nong Sarai una grande vittoria sull'erede al trono birmano e poi prese il controllo di Tavoy e Tenasserim.", "6128c3fb"]},
"OLAYLAR_CINHINDI1115B:1594-07-01:0":{"b": ["L'esercito siamese prende Lovek, capitale della Cambogia; il re Satha fugge a Luang Prabang", "96f68044"], "d": ["Dopo che Naresuan ebbe liberato Ayutthaya dalla pressione birmana, nel 1593 tre eserciti siamesi entrarono in Cambogia; secondo Hall, dopo un lungo e duro assedio Lovek fu presa nel luglio 1594. Il regno non fu annesso; migliaia di prigionieri furono stanziati nelle province settentrionali del Siam. Hall osserva che, sebbene un'iscrizione del 1587 ricordi la «caduta» di Lovek, non vi sono prove che il Siam abbia preso Lovek prima del 1594.", "0f96082d"]},
"OLAYLAR_CINHINDI1115B:1707-01-01:0":{"b": ["Il Lan Xang si divide in due: Luang Prabang e Vientiane diventano regni distinti", "fd170248"], "d": ["Nel 1700 Sai-Ong-Hué, con l'appoggio vietnamita, prese Vientiane e divenne re; i nipoti di Souligna-Vongsa, King-Kitsarat e Int'a-Som, con una forza di 6000 uomini radunata a Sip-Song-Panas, nel 1707 scacciarono da Luang Prabang T'ao-Nong, fratello di Sai-Ong-Hué; Kitsarat fu proclamato re e dichiarò regno indipendente a sé la zona a nord di Chieng Khane. Hall: dal 1707 Luang Prabang e Vientiane sono capitali di due Stati distinti e nemici.", "4e9e45bf"]},
"OLAYLAR_CINHINDI1115B:1713-01-01:0":{"b": ["Chao Soi-Sisamout fonda un regno distinto a Bassak (Champasak) e nelle province meridionali", "4bbd3327"], "d": ["Secondo Hall, Sai-Ong-Hué non ebbe successo a Bassak e nelle province dell'estremo sud; Chao Soi-Sisamout vi regnò dal 1713.", "8bea2ee8"]},
"OLAYLAR_CUKUROVA_0907:1919-02-22:0":{"b": ["Occupazione britannica di Maraş", "5c0faa70"], "d": ["Dopo l'Armistizio di Mudros le forze britanniche entrarono a Maraş. L'occupazione durò otto mesi; in base all'accordo tra Regno Unito e Francia la città fu ceduta ai Francesi il 29 ottobre 1919.", "bd1ef2bd"]},
"OLAYLAR_CUKUROVA_0907:1921-12-23:0":{"b": ["Liberazione di Kilis — evacuazione dei Francesi", "d4cbc76b"], "d": ["In base al calendario di evacuazione previsto dall'Accordo di Ankara (20 ottobre 1921) le forze francesi si ritirarono da Kilis. La città era stata occupata dagli Inglesi tre anni prima, il 6 dicembre 1918, e ceduta ai Francesi il 29 ottobre 1919.", "cafe0444"]},
"OLAYLAR_CUKUROVA_0907:1921-12-25:0":{"b": ["Liberazione di Antep — evacuazione della città da parte dei Francesi", "24b208f9"], "d": ["Dopo il Trattato di Ankara le forze francesi evacuarono Antep. La città era stata occupata dagli Inglesi il 17 dicembre 1918 e lasciata ai Francesi il 5 novembre 1919; la popolazione aveva opposto una lunga difesa alle forze francesi tra il 1° aprile 1920 e il 7 febbraio 1921.", "889e754b"]},
"OLAYLAR_CUKUROVA_0907:1921-12-27:0":{"b": ["Liberazione di Tarso — evacuazione della città da parte dei Francesi", "398f47fb"], "d": ["Le forze francesi si ritirarono da Tarso in base al Trattato di Ankara; la città era sotto occupazione dal 17 dicembre 1918.", "c457bada"]},
"OLAYLAR_CUKUROVA_0907:1922-01-03:0":{"b": ["Liberazione di Mersin — ingresso delle forze nazionali in città", "55ae8422"], "d": ["Le forze nazionali entrarono a Mersin; le ultime truppe francesi lasciarono la città il giorno dopo. Lo sbarco francese era avvenuto dal mare il 17 dicembre 1918.", "c078a706"]},
"OLAYLAR_CUKUROVA_0907:1922-01-05:0":{"b": ["Liberazione di Adana — i Francesi lasciano la città", "07cf1e71"], "d": ["Le forze francesi lasciarono Adana e l'evacuazione della Çukurova fu completata. La città era sotto occupazione francese dal 24 dicembre 1918. Questa data è oggi celebrata come giorno della liberazione di Adana.", "db68016f"]},
"OLAYLAR_DUNYA_AVRUPA2:-0228-01-01:0":{"b": ["Prima spedizione romana in Illiria: Corcira si arrende a Roma", "fffae4b7"], "d": ["I consoli partirono con flotta ed esercito per punire l'Illiria; la guarnigione di Corcira si consegnò ai Romani.", "41810771"]},
"OLAYLAR_DUNYA_AVRUPA2:0260-01-01:0":{"b": ["Gli Alamanni varcano il limes germanico-retico e avanzano fino al Danubio", "dd20a89f"], "d": ["Gli Alamanni, sfondato il limes germanico-retico, occuparono il territorio fino al Danubio e la regione del Meno inferiore.", "71468d5c"]},
"OLAYLAR_DUNYA_AVRUPA2:0378-01-01:0":{"b": ["Battaglia di Adrianopoli: i Goti sconfiggono Valente, l'imperatore muore", "3e6e3307"], "d": ["I Goti di Fritigerno sconfissero in Tracia, presso Adrianopoli, l'imperatore d'Oriente Valente; Valente, ferito, morì.", "124cd050"]},
"OLAYLAR_DUNYA_AVRUPA2:0437-01-01:0":{"b": ["Ezio sconfigge il regno dei Burgundi; il re Gundicario muore", "55e4c92e"], "d": ["Ezio sconfisse i Burgundi che erano entrati nella Belgica Prima; il re Gundicario cadde e il primo regno burgundo sul Reno ebbe fine.", "ffadfcb5"]},
"OLAYLAR_DUNYA_AVRUPA2:0443-01-01:0":{"b": ["I Burgundi si stabiliscono in Sapaudia con il consenso di Roma", "9bd1ce5d"], "d": ["I Burgundi sopravvissuti furono stanziati in Sapaudia come federati; nucleo del successivo Regno burgundo.", "775c0cfa"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0504-01-01:0":{"b": ["Battaglia di Aricia: gli Etruschi sono sconfitti da Aristodemo di Cuma", "a019f90f"], "d": ["Aristodemo di Cuma, con i Latini, fermò l'avanzata etrusca; il dominio etrusco sul Lazio ebbe fine.", "9c00bf17"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0505-01-01:0":{"b": ["Atene vince contro Calcide e la Beozia e fonda una cleruchia a Calcide", "46c2f3d5"], "d": ["Vittoria di Atene contro l'alleanza di Peloponneso, Calcide e Beozia; sul territorio di Calcide furono insediati 4000 cleruchi.", "314bbc8a"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0544-01-01:0":{"b": ["I Focei fondano Elea (Velia)", "c3548bfc"], "d": ["Dopo l'abbandono di Alalia, i Focei fondarono Elea.", "3407a40f"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0545-01-01:0":{"b": ["Battaglia di Pallene: Pisistrato instaura ad Atene una tirannide duratura", "671f71c2"], "d": ["Al terzo tentativo Pisistrato sconfisse gli Ateniesi a Pallene e instaurò la tirannide in modo stabile (546/5); durò fino al 527.", "0647a94e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0545-01-01:1":{"b": ["Battaglia di Tirea (dei Campioni): Sparta sconfigge Argo, la Cinuria resta a Sparta", "35b7197a"], "d": ["Si scontrarono 300 guerrieri scelti per parte; Sparta ottenne la Tireatide.", "8d9b3c39"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0549-01-01:0":{"b": ["Milziade (il Vecchio) stabilisce il dominio sul Chersoneso tracico", "6da9fbe4"], "d": ["Milziade, di origine ateniese, stabilì un governo semi-indipendente nella penisola di Gallipoli.", "88847c09"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0549-01-01:1":{"b": ["Cartagine si stabilisce in Sardegna (Malco, Magone)", "8b34c782"], "d": ["Cartagine stabilì il proprio dominio sulle coste della Sardegna.", "d3e0f4fa"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0573-01-01:0":{"b": ["Emporion (Empúries) fondata dai Focei", "c4706f54"], "d": ["Insediamento di Massalia sulla costa iberica; presenza greca in Hispania.", "525d2aff"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0593-01-01:0":{"b": ["Arcontato di Solone e riforme della seisachtheia", "705d0dbf"], "d": ["Riforme che abolirono la schiavitù per debiti; le classi dei cittadini furono riordinate.", "6d544b32"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0594-01-01:0":{"b": ["Prima guerra sacra: Cirra distrutta, Delfi passa sotto il controllo dell'Anfizionia", "e01a15f5"], "d": ["Cirra fu distrutta per il controllo dell'accesso a Delfi.", "1ad355f7"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0597-01-01:0":{"b": ["Camarina fondata da Siracusa", "47055e49"], "d": ["Siracusa fondò una colonia nel sud-est (135 anni dopo Siracusa).", "40d8cb35"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0599-01-01:0":{"b": ["Poseidonia (Paestum) fondata dai Sibariti", "5a2f0a73"], "d": ["Sibari fondò una colonia sulla costa tirrenica.", "3a48417e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0631-01-01:0":{"b": ["Tentativo di colpo di Stato di Cilone ad Atene", "32e4c5d1"], "d": ["Cilone tentò di impadronirsi dell'Acropoli; fallì.", "ba8fedde"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0646-01-01:0":{"b": ["Olbia/Berezan fondata da Mileto", "c05a7313"], "d": ["Primo insediamento greco a nord del Mar Nero.", "5e2f8c3f"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0656-01-01:0":{"b": ["Cipselo instaura la tirannide a Corinto, i Bacchiadi sono rovesciati", "f4f32246"], "d": ["Cipselo rovesciò l'oligarchia dei Bacchiadi e instaurò una tirannide di lunga durata.", "790b64e0"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0668-01-01:0":{"b": ["Battaglia di Isie: Argo sotto Fidone sconfigge Sparta", "47a0d03b"], "d": ["Supremazia di Argo all'epoca di Fidone (data e storicità discusse).", "c3d09b3d"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0672-01-01:0":{"b": ["Fondazione di Locri Epizefiri (Italia meridionale)", "1ca3a23e"], "d": ["Colonia nell'Italia meridionale.", "2471ca1e"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0684-01-01:0":{"b": ["Inizia la seconda guerra messenica", "760d8edb"], "d": ["Sparta soffocò la rivolta della Messenia e consolidò il sistema degli iloti.", "7f1466e7"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0687-01-01:0":{"b": ["Fondazione di Gela", "a7aa747a"], "d": ["Fondata 45 anni dopo Siracusa.", "3d774871"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0699-01-01:0":{"b": ["Guerra lelantina: lunga guerra tra Calcide ed Eretria", "ec4372c3"], "d": ["Guerra tra le due grandi città dell'Eubea per la piana di Lelanto; vi presero parte molti Stati greci.", "140a24c1"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0731-01-01:0":{"b": ["Fondazione di Reggio", "9b7b9f57"], "d": ["Colonia all'estremità dell'Italia meridionale.", "6de952a4"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0732-01-01:0":{"b": ["Corcira (Kerkyra) fondata dai Corinzi", "6fb853e7"], "d": ["Colonia corinzia alla porta dell'Adriatico.", "b7b072be"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0733-01-01:0":{"b": ["Fondazione di Nasso (Sicilia): prima colonia greca di Sicilia", "4850886a"], "d": ["Sotto la guida di Tucle, i Calcidesi fondarono nella Sicilia orientale la prima colonia greca.", "407aaab5"]},
"OLAYLAR_DUNYA_AVRUPA_MO:-0799-01-01:0":{"b": ["Gadir (Cadice) fondata dai Fenici", "9409a8e5"], "d": ["La tradizione la pone al 1100 a.C. (Velleio 1.2.3), l'archeologia al IX-VIII sec. a.C.", "907f05f8"]},
"OLAYLAR_DUNYA_BOLGE_1109:1385-08-14:0":{"b": ["Unione di Krewo — unificazione di Polonia e Lituania", "29f0d9ef"], "d": ["Il granduca di Lituania Jogaila si impegnò a sposare Edvige, ad accettare il cristianesimo e a legare la Lituania alla corona polacca. Nella narrazione nazionale polacca Krewo è il documento fondativo che diede origine a uno dei maggiori Stati d'Europa; è sottolineata in particolare come unione fondata non con una guerra ma con un atto di matrimonio.", "02686717"]},
"OLAYLAR_DUNYA_BOLGE_1109:1400-10-30:0":{"b": ["Caduta di Aleppo — l'esercito mamelucco in rotta", "77c7953d"], "d": ["Tamerlano, tornato dalla campagna d'India, entrò in Siria nell'ambito dell'operazione occidentale detta «Campagna dei Sette Anni» e sconfisse l'esercito mamelucco davanti ad Aleppo; la città fu saccheggiata per tre giorni e con i teschi furono costruite torri. La caduta di Aleppo fu il primo grande colpo che causò panico alla corte mamelucca del Cairo.", "eca82709"]},
"OLAYLAR_DUNYA_BOLGE_1109:1405-02-18:0":{"b": ["Muore Tamerlano", "1928b1f4"], "d": ["La morte di Tamerlano durante la campagna di Cina portò alla spartizione del suo impero tra figli e nipoti; gran parte della Persia fu infine riunita nelle mani del figlio Shah Rukh, e la capitale fu spostata a Herat.", "a94951bd"]},
"OLAYLAR_DUNYA_BOLGE_1109:1439-07-06:0":{"b": ["Proclamata l'unione di Firenze", "460f28e8"], "d": ["Fu proclamata l'unione delle Chiese ortodossa e cattolica; l'unico vescovo che non firmò fu Marco di Efeso. Nel racconto bizantino l'unione fu percepita come la vendita della fede per salvare lo Stato e fu rifiutata dalla popolazione: il detto «meglio il turbante turco che il cappello latino» è un prodotto di questi anni.", "888920ab"]},
"OLAYLAR_DUNYA_BOLGE_1109:1458-01-24:0":{"b": ["Elezione a re di Mattia Hunyadi (Mattia Corvino)", "f0c52c1a"], "d": ["La folla di nobili e popolo riunita sul Danubio ghiacciato attorno a Buda proclamò re il quindicenne Mattia; fu un momento eccezionale in cui, al posto di una dinastia straniera, salì al trono una famiglia nobile «locale». Il suo regno di trentadue anni avrebbe trasformato l'Ungheria in uno degli Stati più potenti dell'Europa centrale.", "4f3e2558"]},
"OLAYLAR_DUNYA_BOLGE_1109:1480-11-11:0":{"b": ["Il confronto sul fiume Ugra — fine del giogo tataro", "0a1d84b3"], "d": ["Gli eserciti di Ivan III e le forze del khan dell'Orda Grande Ahmed restarono per mesi di fronte sulle rive del fiume Ugra; senza scontro, Ahmed si ritirò. La storiografia russa considera questo evento la fine ufficiale e definitiva del «giogo tataro» (in corso dal 1237) e la nascita di Mosca come potenza indipendente — un punto di svolta quanto Kulikovo, e per alcuni storici anche più.", "955810b6"]},
"OLAYLAR_DUNYA_BOLGE_1109:1490-04-06:0":{"b": ["Morte di Mattia Corvino", "652fb823"], "d": ["Dopo la morte di Mattia, che non lasciò un erede legittimo, la politica di centralizzazione crollò; l'Armata Nera fu sciolta, i nobili ripresero il loro potere e il trono passò a un debole re Jagellone, Ladislao II. I contemporanei ricordarono questa morte come la fine dell'«età dell'oro» dell'Ungheria.", "a20bdc7f"]},
"OLAYLAR_DUNYA_BOLGE_1109:1492-03-31:0":{"b": ["Editto dell'Alhambra — espulsione degli ebrei", "2a4e2686"], "d": ["Isabella e Ferdinando ordinarono che tutti gli ebrei che non si fossero convertiti al cristianesimo lasciassero il paese entro quattro mesi; tra 40.000 e 100.000 persone (le stime variano) emigrarono verso il Portogallo, il Nordafrica e i territori ottomani. La tradizione secondo cui il sultano Bayezid II mandò la flotta a trasportare gli emigrati appartiene alla stessa ondata di questo evento.", "73ec3641"]},
"OLAYLAR_DUNYA_BOLGE_1109:1519-06-28:0":{"b": ["Carlo V eletto imperatore del Sacro Romano Impero", "7806defb"], "d": ["Il collegio degli elettori a Francoforte elesse imperatore il re di Spagna Carlo V contro il re di Francia Francesco I; egli divenne così il centro di un'unione personale comprendente Spagna, Germania, Paesi Bassi, Borgogna e gran parte dell'Italia. L'elezione, causando una lunga assenza di Carlo V dalla Spagna e pesanti richieste fiscali, innescò la rivolta dei Comuneros.", "eb77afea"]},
"OLAYLAR_DUNYA_BOLGE_1109:1524-05-23:0":{"b": ["Muore Shah Ismail, sale al trono Tahmasp I", "a4edbd63"], "d": ["Con la morte di Shah Ismail, ripiegatosi su se stesso dopo Çaldıran, salì al trono il figlio decenne Tahmasp; i suoi primi dieci anni trascorsero tra le lotte di reggenza dei capi tribali Qizilbash, ma il suo regno di 54 anni fu uno dei più lunghi dello Stato safavide.", "638c52e8"]},
"OLAYLAR_DUNYA_BOLGE_1109:1552-10-02:0":{"b": ["Caduta di Kazan — finisce il dominio turco di nove secoli sul Volga medio", "e0d16f1c"], "d": ["Dopo circa due mesi di sanguinosi combattimenti Kazan cadde il 2 ottobre 1552 (giuliano; corrispondente gregoriano 12 ottobre — il «15 ottobre» del TDV appare come differenza di conversione di 13 giorni) e finì il dominio turco sul Volga medio, in vigore dal VI secolo d.C. Le opere d'arte, di calligrafia e architettura della città furono saccheggiate; della grande maggioranza non è rimasta nemmeno traccia.", "d67d7483"]},
"OLAYLAR_DUNYA_BOLGE_1109:1556-01-01:0":{"b": ["Annessione del Khanato di Astrachan", "57d7fc0f"], "d": ["Quattro anni dopo la caduta di Kazan fu annesso anche il Khanato di Astrachan; così l'intero fiume Volga e lo sbocco sul Mar Caspio passarono in mano russa. Queste due conquiste costituirono la chiave geografica dell'espansione russa verso sud e verso est (Siberia).", "dde89031"]},
"OLAYLAR_DUNYA_BOLGE_1109:1556-01-16:0":{"b": ["Abdicazione di Carlo V — la corona di Spagna passa a Filippo II", "b92cba1e"], "d": ["Carlo V, con una cerimonia tenuta a Bruxelles, cedette al figlio Filippo la corona di Spagna e dei Paesi Bassi; lasciò il titolo imperiale al fratello Ferdinando. Questa divisione fu l'annuncio che i rami austriaco e spagnolo della dinastia asburgica avrebbero d'ora in poi proceduto separatamente.", "adb161a5"]},
"OLAYLAR_DUNYA_BOLGE_1109:1576-05-14:0":{"b": ["Muore Tahmasp I — inizia la crisi di successione", "aa20029c"], "d": ["Con la morte di Tahmasp I scoppiò tra i suoi figli una sanguinosa lotta per il trono; questa instabilità durata dieci anni (epoche di Ismail II e Muhammad Khodabanda) approfondì le lotte interne dei Qizilbash e offrì agli Ottomani una nuova occasione di guerra.", "5e55bbde"]},
"OLAYLAR_DUNYA_BOLGE_1109:1587-10-01:0":{"b": ["Shah Abbas I sale al trono", "724a0b0a"], "d": ["Il diciassettenne Abbas fu portato al trono dagli emiri Qizilbash al posto del padre Muhammad Khodabanda; il suo regno di 42 anni sarebbe stato l'apice militare, amministrativo e culturale dello Stato safavide. Nella storiografia iraniana l'epoca di Shah Abbas è un punto di riferimento di «età dell'oro» al livello del Pietro della Russia o del Solimano il Magnifico ottomano.", "7d5cb8fc"]},
"OLAYLAR_DUNYA_BOLGE_1109:1613-03-03:0":{"b": ["La dinastia Romanov sale al trono", "9e4bcca4"], "d": ["Lo Zemskij Sobor elesse zar il sedicenne Michele Romanov; così il Periodo dei Torbidi, durato quindici anni, fu ufficialmente chiuso e iniziò la dinastia Romanov, destinata a durare fino al 1917. Nella storiografia nazionale russa è la data di svolta della ricostituzione dello Stato e dell'ordine sociale, della chiusura della Smuta.", "742c1b73"]},
"OLAYLAR_DUNYA_BOLGE_1109:1629-01-19:0":{"b": ["Muore Shah Abbas", "5fc3247e"], "d": ["La morte di Shah Abbas, dopo un regno di quarantadue anni, è considerata la chiusura del periodo di apice dello Stato safavide; con l'epoca del nipote che gli succedette, Shah Safi, iniziò un processo di declino lento ma ininterrotto.", "30118d02"]},
"OLAYLAR_DUNYA_BOLGE_1109:1648-05-16:0":{"b": ["Inizia la rivolta di Chmel'nyc'kyj — Žovti Vody", "e9ae726f"], "d": ["La rivolta iniziata dall'atamano cosacco Bohdan Chmel'nyc'kyj in alleanza con i Tatari di Crimea annientò una forza polacca a Žovti Vody (Acque Gialle) e dieci giorni dopo distrusse a Korsun il grosso dell'esercito. La storiografia polacca assume questa data come il momento in cui finì l'età dell'oro: la repubblica non tornò più all'antica potenza.", "ec8357e9"]},
"OLAYLAR_DUNYA_BOLGE_1109:1682-05-07:0":{"b": ["Muore Fëdor III, Pietro I proclamato zar", "82534f8e"], "d": ["Dopo la morte di Fëdor III, senza figli, i rappresentanti dei ceti riuniti al Cremlino proclamarono zar il decenne Pietro. Dopo la rivolta degli strel'cy fomentata dalla fazione dei Miloslavskij, Pietro e il fratello maggiore Ivan V furono fatti zar congiunti e il governo passò alla reggente Sof'ja. Pietro governò da solo dopo il 1696.", "dfa6a305"]},
"OLAYLAR_DUNYA_BOLGE_1109:1709-07-08:0":{"b": ["Poltava — Mazepa e Carlo XII sconfitti, il destino dell'Etmanato è segnato", "2497e53c"], "d": ["La guerra russo-svedese del 1708-1709, combattuta in territorio ucraino, finì a Poltava con la sconfitta degli alleati; Mazepa, Orlyk e i sostenitori cosacchi si rifugiarono con Carlo XII in territorio ottomano, a Bender. Secondo l'EoU questa sconfitta segnò il destino dell'Ucraina; Pietro da allora restrinse passo dopo passo l'autonomia dell'Etmanato.", "3e9f9c5b"]},
"OLAYLAR_DUNYA_BOLGE_1109:1722-10-25:0":{"b": ["Mahmud Hotak proclamato scià", "97cd2096"], "d": ["Subito dopo aver ricevuto la resa di Isfahan, Mahmud si proclamò scià di Persia; l'ascesa di un capo afghano sunnita al trono persiano sciita è l'inizio della breve ma traumatica epoca hotaki (1722-1729), ricordata nella storiografia iraniana come «occupazione straniera» del paese.", "478f1a45"]},
"OLAYLAR_DUNYA_BOLGE_1109:1762-07-09:0":{"b": ["Caterina II sale al trono con un colpo di Stato", "e29e31b3"], "d": ["La zarina di origine tedesca Caterina, con l'appoggio di ufficiali della guardia (alcuni dei quali suoi amanti), rovesciò il marito Pietro III e salì al trono; Pietro fu ucciso pochi giorni dopo in circostanze sospette. Il suo regno di 34 anni vide la maggiore espansione territoriale della Russia e il discorso dell'«Autocrazia illuminata».", "458add50"]},
"OLAYLAR_DUNYA_BOLGE_1109:1783-08-04:0":{"b": ["Trattato di Georgievsk — il Kartli-Kakheti sotto protezione russa", "b5450242"], "d": ["Eraclio II, cercando garanzie contro la pressione ottomana e persiana, firmò con la Russia un trattato di protezione; cedette alla Russia la politica estera del Kartli-Kakheti e ottenne in cambio la promessa di protezione militare. Questo trattato preparò il terreno giuridico della piena annessione diciotto anni dopo.", "c7c6c8a1"]},
"OLAYLAR_DUNYA_BOLGE_1109:1805-12-02:0":{"b": ["Austerlitz — Battaglia dei Tre Imperatori", "b1ee0f76"], "d": ["I Russi e gli Austriaci furono sconfitti in modo decisivo ad Austerlitz. La successiva Pace di Presburgo portò pesanti perdite territoriali: Venezia, Istria e Dalmazia passarono alla Francia, tutta l'Austria Anteriore alla Baviera — circa tre milioni di abitanti.", "cde24675"]},
"OLAYLAR_DUNYA_BOLGE_1109:1813-10-24:0":{"b": ["Trattato di Gulistan — perduta gran parte del Caucaso", "18c35598"], "d": ["La Persia rinunciò alle sue pretese sulla Georgia, sul Daghestan e su tutto l'Azerbaigian settentrionale (compresi Baku, Shirvan, Karabakh e Ganja); perse anche il diritto di tenere una flotta nel Mar Caspio. Nella storiografia iraniana questo trattato è l'inizio giuridico del trauma del «Caucaso perduto», ancora oggi avvertito — ed è, anche su scala mondiale, un trattato che stabilì il dominio duraturo della Russia in Transcaucasia e ridisegnò la mappa politica della regione.", "8a41733e"]},
"OLAYLAR_DUNYA_BOLGE_1109:1815-09-26:0":{"b": ["Santa Alleanza — i sovrani di Russia, Austria e Prussia si uniscono a Parigi", "d4619104"], "d": ["Dopo la sconfitta di Napoleone, lo zar di Russia Alessandro I, l'imperatore d'Austria Francesco I e il re di Prussia Federico Guglielmo III firmarono una dichiarazione che impegnava a governare secondo i principi cristiani e ad aiutarsi a vicenda. L'alleanza divenne il sostegno conservatore dell'ordine del Congresso di Vienna.", "ec02bebb"]},
"OLAYLAR_DUNYA_BOLGE_1109:1879-10-07:0":{"b": ["Zweibund — l'Alleanza austro-tedesca firmata a Vienna", "ce79cc02"], "d": ["Dopo il Congresso di Berlino la Germania e l'Austria-Ungheria formarono un'alleanza difensiva reciproca contro la Russia. Il trattato segreto firmato da Andrássy e dal principe Reuss si trasformò nel 1882, con l'adesione dell'Italia, in Triplice Alleanza e durò fino al 1914.", "2f84b46e"]},
"OLAYLAR_DUNYA_BOLGE_1109:1881-06-18:0":{"b": ["Lega dei Tre Imperatori (seconda) — accordo segreto su Stretti, Bosnia-Erzegovina e Rumelia orientale", "532a98c2"], "d": ["Austria-Ungheria, Germania e Russia firmarono a Berlino un trattato segreto. Le parti accettarono che lo status territoriale della «Turchia in Europa» potesse cambiare solo con una decisione comune dei tre. Considerarono principio comune la chiusura degli Stretti alle navi da guerra. Con un protocollo aggiuntivo l'Austria-Ungheria ottenne il diritto di annettere la Bosnia-Erzegovina quando volesse; fu deciso che non ci si sarebbe opposti all'unione di Bulgaria e Rumelia orientale. Il trattato sostituì la prima lega del 1873, fu rinnovato nel 1884 e terminò nel 1887.", "c71c0cae"]},
"OLAYLAR_DUNYA_BOLGE_1109:1894-01-04:0":{"b": ["L'Alleanza franco-russa diventa ufficiale", "4d616905"], "d": ["La Francia e la Russia formarono un'alleanza segreta confermando con uno scambio di lettere le disposizioni della convenzione militare del 1892. Se la Germania o uno Stato da essa sostenuto avesse attaccato una delle parti, l'altra sarebbe entrata in guerra contro la Germania con tutte le sue forze. L'alleanza era valida finché durava la Triplice Alleanza e costituì l'ordine a blocchi della prima guerra mondiale.", "68fdddbe"]},
"OLAYLAR_DUNYA_BOLGE_1109:1905-01-22:0":{"b": ["Domenica di sangue", "7d7c38e0"], "d": ["La folla di operai che, guidata dal pope Gapon, aveva organizzato una marcia pacifica con una petizione, fu dispersa davanti al Palazzo d'Inverno dal fuoco delle guardie dello zar; centinaia di persone morirono. Nella storiografia russa questo massacro è la data in cui la tradizionale fiducia del popolo nello zar, «zar-padre», fu definitivamente spezzata e in cui la Rivoluzione del 1905 iniziò di fatto.", "6246c12c"]},
"OLAYLAR_DUNYA_BOLGE_1109:1906-08-05:0":{"b": ["Muzaffar al-Din Shah firma la costituzione — proclamato il regime costituzionale", "b661df69"], "d": ["Poche settimane prima della morte, Muzaffar al-Din Shah approvò la convocazione della prima Assemblea Nazionale (Majlis-e Shura-ye Melli) e la redazione di una costituzione; la Persia iniziò così la propria esperienza costituzionale, indipendente da quella ottomana (1876/1908) e da quella russa (1905). Nella storiografia iraniana ciò è, anche se non quanto la Rivoluzione del 1979, uno dei punti di svolta più radicali della storia politica dell'Iran moderno — su scala mondiale riflette anche una tendenza sistemica regionale/globale, come parte dell'onda di costituzionalismo in Asia (Giappone 1889, Impero ottomano 1908, Russia 1905/1906).", "25ff44af"]},
"OLAYLAR_DUNYA_BOLGE_1109:1907-08-31:0":{"b": ["Convenzione anglo-russa del 1907 — la Persia divisa in sfere d'influenza", "17c59cd8"], "d": ["Il Regno Unito e la Russia, senza il consenso della Persia, divisero di fatto il paese in tre: una sfera d'influenza russa a nord, una britannica a sud-est e una fascia neutrale al centro; questo trattato è considerato la fine ufficiale del «Grande Gioco» e uno dei colpi più gravi all'indipendenza della Persia, con cui la sovranità persiana fu apertamente ignorata da due grandi potenze — ed è anche un trattato di equilibrio regionale di potenza che spostò nel sistema mondiale la rivalità anglo-russa verso la struttura di alleanze precedente la prima guerra mondiale (Francia-Russia-Inghilterra).", "137c9397"]},
"OLAYLAR_DUNYA_BOLGE_1109:1917-03-15:0":{"b": ["Nicola II abdica, finisce la dinastia dei Romanov", "0866a3ad"], "d": ["Nicola II dichiarò di abdicare a nome proprio e del figlio; con il rifiuto del fratello Michele, il giorno dopo, di accettare la corona, la dinastia dei Romanov, durata 304 anni dal 1613, e la monarchia autocratica di tre secoli finirono ufficialmente. Nella storiografia russa è, al livello di Kulikovo, 1613, 1812 e 1861, la data di chiusura dell'epoca imperiale (cfr. [[rusya-gecici-hukumet]], [[sovyet-rusya]]).", "6a110185"]},
"OLAYLAR_DUNYA_BOLGE_1109:1917-11-02:0":{"b": ["Pubblicata la Dichiarazione Balfour", "d618cf61"], "d": ["Il ministro degli Esteri Arthur Balfour inviò a Lord Rothschild una lettera che comunicava il sostegno del governo britannico alla creazione in Palestina di un «focolare nazionale» per gli ebrei. La Dichiarazione fu un impegno che avrebbe plasmato profondamente la storia politica del Medio Oriente per il secolo successivo.", "d1b5d7de"]},
"OLAYLAR_DUNYA_BOLGE_1109:1917-11-07:0":{"b": ["Rivoluzione d'Ottobre — i bolscevichi rovesciano il Governo provvisorio russo", "a43063c1"], "d": ["I bolscevichi guidati da Lenin presero il potere rovesciando a Pietrogrado il Governo provvisorio (25 ottobre secondo il calendario giuliano, da cui «Rivoluzione d'Ottobre»).", "30353579"]},
"OLAYLAR_DUNYA_BOLGE_1109:1921-02-21:0":{"b": ["Colpo di Stato di Reza Khan", "dba4134e"], "d": ["Reza Khan, comandante della Brigata Cosacca, insieme al giornalista Seyyed Ziaeddin Tabatabai prese Teheran e formò un nuovo governo; sebbene in un primo momento lasciasse Ahmad Shah sul trono, prese il potere effettivo. Nella storiografia iraniana è la data iniziale della fine di fatto della dinastia Qajar e del passaggio all'epoca Pahlavi.", "8fa9e252"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Dopo la disfatta di Ankara il voivoda di Valacchia Mircea riprende la Dobrugia — Silistra, Costanza, Babadag, Isaccea", "5eaefc68"], "d": ["La sconfitta di Yıldırım Bayezid da Tamerlano ad Ankara scosse il dominio ottomano lungo il Danubio. Il voivoda di Valacchia Mircea, approfittando di questo vuoto, rientrò in Dobrugia; Silistra, i dintorni di Costanza e Babadag e Isaccea, sulla riva del Danubio, rimasero in mano sua per tutti gli anni dell'Interregno. Mircea sostenne Mûsâ Çelebi contro Çelebi Mehmed. Tenne Silistra fino alla morte nel 1418.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Passaggio di Babadag e dintorni agli Ottomani — Mircea e il figlio Mihail sconfitti", "bfda2c60"], "d": ["Çelebi Mehmed, dopo aver sconfitto il voivoda di Valacchia Mircea e il figlio Mihail, pose sotto dominio ottomano Babadag e i dintorni nella Dobrugia settentrionale. Babadag era una cittadina che portava il nome di Saltuk Baba e fondata con un insediamento turcomanno del XIII secolo. Silistra, Costanza e le altre fortezze della Dobrugia circostanti rimasero invece alla Valacchia fino al 1419; cioè Babadag appare per tre anni come un'isola (exclave) staccata dal territorio ottomano.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Ripresa di Silistra e della Dobrugia — dopo la morte di Mircea", "73eb6ae9"], "d": ["La confusione scoppiata in Valacchia dopo la morte del voivoda Mircea nel 1418 diede a Çelebi Sultan Mehmed l'occasione di riprendere Silistra e la Dobrugia. Nella primavera del 1419 Silistra, Costanza e gran parte della Dobrugia entrarono di nuovo sotto amministrazione ottomana; le fortezze di Enisala (Yenisale) e Isaccea furono riparate e fatte fortezze di confine (serhat); la Dobrugia da allora rimase ottomana fino al 1878.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Chiusura del basso Danubio — annessione di Giurgiu, Turnu e Orsova", "331a0b68"], "d": ["Dopo la chiusura dell'Interregno la mossa di Çelebi Mehmed per mettere in ordine la linea del Danubio nel 1420 diede frutto. La fortezza di Giurgiu, che il voivoda di Valacchia Mircea il Vecchio aveva fatto costruire sul proprio territorio coprendone la spesa con la vendita del sale, quest'anno passò in mano ottomana (la Dobrugia era stata ripresa un anno prima, nella primavera del 1419 — TDV silistre) e furono annesse Turnu (Kule/Holovnik) sulla riva destra del Danubio e Orșova — poi detta Fetislam. Così le due rive del fiume furono messe contemporaneamente sotto controllo. L'importanza di Giurgiu è nella sua geografia: è una fortezza ottomana costruita sulla riva sinistra, cioè valacca, del Danubio e tiene le due estremità dello stesso passaggio con Ruse sulla riva opposta. I documenti ottomani scrivono apertamente questa dualità — per Ruse si dice 'Yergöğü, riva di qua', per Giurgiu 'Yergöğü, riva di là'. La fortezza sarebbe stata ripresa dai Valacchi nel 1427, nel 1449 sarebbe tornata di nuovo sotto controllo ottomano e il kaza di Giurgiu, legato al sanjak di Nicopoli, sarebbe diventato un'isola amministrata direttamente all'interno del voivodato. Qui comincia la risposta sulla mappa al perché la riva danubiana della Valacchia sia di colore scuro.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["La regione di Toplica (Kuršumlija, Prokuplje) entra sotto il dominio ottomano", "e22e690d"], "d": ["Durante il fidanzamento di Murad II con Mara Branković si ritiene probabile che la regione di Dubočica e Toplica (dintorni di Leskovac, Kuršumlija e Prokuplje) sia passata al dominio ottomano; la registrazione del censimento del 1445-1447 mostra che la regione era data come timar ai sipahi ottomani. Sulla mappa Kuršumlija e Prokuplje da quest'anno sono sotto amministrazione ottomana.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Annessione della piana di Sarajevo (Saray) — stabilimento di un avamposto ottomano all'interno della Bosnia", "be5c0f00"], "d": ["Dopo che i re di Bosnia nel 1428-1429 furono sottoposti a tributo, gli Ottomani cominciarono a insediarsi in modo stabile all'interno del regno. Tra il 1428 e il 1435 fu presa la cittadina di Hodidjed; nell'852 (1448) la provincia di Hodidjed con la piana di Saray entrò completamente sotto amministrazione ottomana. È un territorio di confine stabilito nel mezzo del regno quindici anni prima della conquista della Bosnia e amministrato dal bey di Skopje Îsâ Bey, che portava il titolo di voivoda — poiché nei dintorni c'erano ancora bey bosniaci tributari agli Ottomani, la regione era sotto doppio controllo. Anche la città stessa nacque in questo periodo: prima del 1462 İshak Bey o il figlio Îsâ Bey fondò il primo quartiere musulmano, nell'862 (1458) fu costruita a nome di Maometto il Conquistatore la Moschea Hünkâr e, bonificati i campi del villaggio di Brodec, comparve la cittadina di Saray. La conquista del 1463 abolì il Regno di Bosnia; la piana di Saray in quella data era già da quindici anni territorio ottomano.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Annessione di Podgorica ai territori ottomani — messa sotto controllo della piana della Zeta", "46e401c5"], "d": ["La cittadina, sorta a venti chilometri a nord del lago di Scutari, nella piana in cui confluiscono le acque di Morača e Ribnica, nelle fonti è ricordata per la prima volta nel 1216 come Ribnica, nel 1326 come Podgorica. Nel 1457 fu annessa ai territori ottomani e il controllo della piana della Zeta uscì così dalle mani delle dinastie Balšić-Crnojević. Maometto il Conquistatore tra il 1474 e il 1478 fece costruire una fortezza e una moschea sulle rocce scoscese alla confluenza dei due fiumi; nel 1479, dopo la conquista di Scutari, la regione fu legata al nuovo sanjak di Scutari. Podgorica, cittadina cristiana di quaranta case nel censimento del 1485, nel 1529-30 raggiunse 800 persone e una guarnigione di trentadue uomini agli ordini di un dizdar nella fortezza, nel 1582 322 case. Evliya Çelebi nel 1662 contò nella Fortezza di Fatih trecento case, magazzini, arsenali e settecento guardie. Questi registri mostrano anche la differenza tra la pianura e la montagna della Zeta: la pianura è un kaza ottomano censito, tassato e con guarnigione — eppure nel XVIII secolo la città dovrà essere fortificata con sei bastioni e mura a tre porte per prevenire le incursioni delle tribù dei monti montenegrini. Podgorica passò al Montenegro alla fine della guerra del 1876-1878 e vi rimase con il Trattato di Berlino.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Presa di Foča — apertura del primo accesso al Ducato di Erzegovina", "f098a9e6"], "d": ["Dopo l'abolizione del Regno di Bosnia nel 1463, toccò ai territori di Stjepan Vukčić-Kosača, che si era staccato dal regno fondando un proprio ducato. Foča, nella valle della Drina, al crocevia della via commerciale che collega Istanbul a Dubrovnik, nel 1465 entrò sotto amministrazione ottomana. L'importanza della città fu subito compresa: nel 1470 fu fatta centro del nuovo sanjak di Erzegovina — cioè il nucleo amministrativo dell'Erzegovina fu stabilito a Foča prima che il ducato stesso fosse abbattuto. L'annessione dell'intero ducato sarebbe durata fino al 1483. Foča da allora si sviluppò come centro commerciale e amministrativo grazie al clima favorevole e alla posizione al crocevia. Sulla mappa questa data è il giorno in cui inizia la seconda ondata verso sud dopo la conquista della Bosnia.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Annessione definitiva di Livno e della Bosnia occidentale — creazione del confine con Venezia", "c14d4283"], "d": ["La fortezza sull'altopiano che domina la piana di Livno nel 1448-1454 era in mano a Stjepan Vukčić-Kosača, fondatore del Ducato di Erzegovina. Nella campagna di Bosnia del 1463 era stata occupata per breve tempo dalle forze ottomane, ma era stata ripresa nello stesso anno; nel 1466 il signore della città è Ivaniš Vlatković. Nelle parole del TDV il dominio ottomano definitivo si realizzò con grande probabilità nel 1468-1469 e il censimento del 1485 registra Livno ormai come territorio ottomano. Questa è la chiusura dell'estremità occidentale della conquista della Bosnia: Livno divenne una pericolosa cittadina di confine, confinante lungo la pianura piana con territori veneziani distanti solo trentasei chilometri, e mantenne questa posizione fino alla presa delle fortezze veneziane da parte del governatore di Bosnia Gazi Hüsrev Bey nel 1521-1522.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Perdita di Böğürdelen a favore degli Ungheresi — prima breccia sulla linea della Sava", "129fe8f2"], "d": ["Nel luogo passato in mano ottomana al tempo di Maometto il Conquistatore e prima detto Zaslon, nel 1471 era stato costruito un forte di legno e terra. Poiché si trovava in un punto che minacciava Belgrado e di lì si potevano facilmente compiere incursioni nelle regioni meridionali di Ungheria e Austria, la fortezza prendeva il nome da questa funzione — Böğürdelen significa 'bastione che colpisce di fianco'. Il re d'Ungheria Mattia Corvino verso la fine del 1475 assediò la fortezza e nel febbraio 1476 la prese. L'epopea ungherese Szabács viadala, che narra l'assedio, è uno degli esempi più lunghi giunti fino a noi dei poemi storici ungheresi del XV secolo. Gli Ungheresi costituirono nella regione un banato e rifortificarono in pietra la fortezza, facendone un anello della catena di forti di confine. Gli Ottomani tentarono di riprenderla nel 1492 e non vi riuscirono; la fortezza rimase quarantacinque anni in mano ungherese.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Conquista delle isole Ionie — fine del ducato dei Tocco: Ayamavra, Cefalonia, Zante, Itaca", "07b27251"], "d": ["Il Trattato di Istanbul firmato con Venezia nel gennaio dello stesso anno aveva lasciato agli Ottomani Scutari e la costa albanese; le isole Ionie invece non erano sotto l'amministrazione di Venezia ma della famiglia Tocco, che teneva la contea di Cefalonia-Zante, e furono prese con un'operazione separata. Secondo la voce Ayamavra del TDV l'ultimo duca Leonardo Tocco aveva dapprima conservato la fedeltà sposando Milica Branković, parente di Maometto il Conquistatore, ma nel 1464, alla morte della moglie, nel 1477 sposando Francesca Marzano della dinastia di Napoli aveva offeso il sultano. Due anni dopo la flotta al comando del bey di Valona Gedik Ahmed Pascià prese Ayamavra insieme a Cefalonia, a sud; Leonardo e Francesca fuggirono in Italia. La voce Gedik Ahmed Paşa registra che nella stessa operazione fu presa anche Zante (Zakynthos); Itaca, legata alla contea di Cefalonia, entrò con questo passaggio sotto amministrazione ottomana. Così la via marittima che si estende dall'imboccatura dell'Adriatico alla Morea fu interamente posta sotto controllo. Tra le isole, Zante sarebbe stata lasciata a Venezia tre anni dopo, Cefalonia e Itaca sarebbero andate perdute nel 1500, solo Ayamavra sarebbe rimasta ottomana per duecento anni.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Vassallaggio della Zeta dei Crnojević e Cetinje divenuta centro", "59d20267"], "d": ["Con la permanenza di Scutari agli Ottomani nel 1479 anche la regione montuosa della Zeta, nelle sue retrovie, rientrò nei confini dell'Impero. La famiglia Crnojević, che teneva la regione, dopo la morte di Maometto il Conquistatore riconobbe la sovranità di Bayezid II, salito al trono, e fu sottoposta a tributo restando libera negli affari interni; Ivan Crnojević ritirò il proprio centro dalla pianura e lo trasferì a Cetinje, ai piedi del monte Lovćen, fondando la città. Due anni dopo il monastero da lui fatto costruire qui divenne il centro religioso della regione. Così il Montenegro appare sulla mappa non come territorio ottomano diretto, ma come regione tributaria in tonalità chiara. La voce Karadağ del TDV ricorda la dinastia e il vescovato di Cetinje e scrive che il dominio nel 1514 fu trasformato in sanjak separato per mano di İskender Bey (della discendenza dei Crnojević, cresciuto a palazzo ottomano); l'anno 1482 non compare nel TDV, è la data data dalla storiografia montenegrina. Per la durezza della geografia l'amministrazione qui non funzionò mai in modo così stretto come nelle pianure.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Conquista della fortezza di Kilia — chiave della foce del Danubio", "ef4eca73"], "d": ["La Moldavia era un voivodato tributario che pagava duemila monete d'oro l'anno dal settembre 1455, ma i suoi due porti sul Mar Nero erano ancora in mano al voivoda e il commercio proveniente dal Danubio passava da lì. Bayezid II fece la prima grande campagna del suo regno contro questi due porti. Il comandante della fortezza di Kilia, bombardata notte e giorno per dieci giorni, fu costretto ad arrendersi. La fortezza fu posta sotto amministrazione ottomana diretta e fatta sanjak; nella seconda metà del XVI secolo, per il pericolo cosacco, fu fatta kaza e legata al sanjak di Akkerman, dipendente dal beylerbeylik di Rumelia. Da qui in poi la Moldavia appare sulla mappa a due livelli: all'interno il voivodato resta come territorio tributario in tonalità chiara, mentre i due porti sulla costa sono sanjak ottomano diretto in tonalità scura. La voce Boğdan del TDV chiama questi due 'le chiavi e le porte della Moldavia' e scrive che la regione fu legata in modo definitivo agli Ottomani al tempo di Bayezid II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Conquista di Akkerman — foce del Dnestr e chiusura della porta sul Mar Nero della Moldavia", "7cb20feb"], "d": ["Venti giorni dopo la resa di Kilia l'esercito giunse davanti ad Akkerman, alla foce del Dnestr, e la fortezza fu presa il 4 agosto. La città era il porto più attivo della Moldavia; al tempo di Maometto il Conquistatore, quando nel 1455 il voivoda Petru III aveva riconosciuto il dominio ottomano, ai mercanti di Akkerman era stato dato il permesso di commerciare, ora il porto passò direttamente allo Stato. Akkerman, fatta dopo la conquista sanjak dipendente dal beylerbeylik di Rumelia, nel 1593 fu annessa al nuovo eyalet di Özü. Così il guscio esterno della Moldavia, circondato da Hotin a nord e da Kilia e Akkerman a sud, cominciò a entrare sotto il controllo diretto degli Ottomani; il voivodato rimase libero negli affari interni ma non ebbe più sbocco sul mare. Sulla mappa non c'è una regione vuota in mezzo — i sanjak portuali in tonalità scura e il territorio del voivodato in tonalità chiara si toccano; la steppa del Bucak tra i due fa ancora parte del voivodato fino al 1538.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Resa di Lepanto (İnebahtı) — l'imboccatura del golfo di Corinto è tolta a Venezia", "2cfe0777"], "d": ["Lepanto era in mano a Venezia dal 1407 e teneva l'imboccatura del golfo di Corinto; tutta la costa all'interno del golfo era legata alla portata di questa fortezza. Nella campagna del 1499 la fortezza fu assediata da terra, mentre la flotta ottomana, che combatteva con la flotta veneziana al largo di Lepanto, aiutò dal mare le forze d'assedio. I Veneziani nella fortezza il 26 agosto consegnarono la cittadina agli Ottomani. La città da allora rimase ottomana per centottantotto anni, nel 1687 con la perdita della Morea passò di nuovo a Venezia, nel 1715 fu ripresa. La battaglia navale della stessa estate e questa resa sono due eventi distinti: lo scontro navale si svolse all'estremità occidentale della Morea, nelle acque di Sapienza-Zonchio; Lepanto cadde invece con un assedio terrestre all'imboccatura del golfo di Corinto.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Annessione del banato di Srebrenik — prima rottura della linea ungherese nella Bosnia settentrionale", "6d98c725"], "d": ["Dopo l'abbattimento del Regno di Bosnia nel 1463 Mattia Corvino era passato al contrattacco e a nord del regno aveva costituito due banati che fermavano l'avanzata ottomana: a ovest Jajce, a nordest Srebrenik. Erano la linea di difesa avanzata dell'Ungheria in Bosnia e chiudevano il corridoio tra Sava e Bosna. Il banato di Srebrenik fu preso nel 1512; così il fianco orientale della linea crollò e il sanjak di Zvornik poté estendersi verso nord. Jajce, sul fianco occidentale, avrebbe resistito per altri sedici anni e poté essere presa solo dopo Mohács, nel 1528.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Conquista di Böğürdelen — la prima fortezza presa da Solimano il Legislatore e il luogo in cui fu decisa la presa di Belgrado", "85177a90"], "d": ["Nella prima campagna d'Ungheria di Solimano il Legislatore, le forze del beylerbey di Rumelia Ahmed Pascià, inviato nella regione, dopo un violento assedio presero la fortezza il 7 luglio 1521. Böğürdelen è la prima fortezza conquistata nel regno di Solimano il Legislatore. Il sultano dopo la conquista entrò personalmente nella fortezza e ordinò la ricostruzione della città; qui furono prese anche le decisioni sulla conquista di Belgrado — cioè il piano di Belgrado, che sarebbe caduta il 29 agosto 1521, fu fatto a Böğürdelen. La fortezza da allora rimase per quasi duecento anni in mano ottomana; fu legata dapprima alla Rumelia, dal 1580 all'eyalet di Bosnia, poi per breve tempo a Smederevo e infine al sanjak di Zvornik. Sulla mappa questa data è il giorno in cui la linea della Sava si chiude a favore degli Ottomani.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Inizio della rivolta dei tre voivodati — la Transilvania passa alla Lega Santa, arrestati i bey filo-ottomani", "68a33800"], "d": ["Nel secondo anno della Lunga Guerra la fascia vassalla ottomana in Europa centrale si sciolse all'improvviso. Alla Lega Santa, costituita sotto la protezione di papa Clemente VIII, alla fine dell'estate passarono Moldavia e Transilvania: il voivoda di Moldavia Aron Vodă il 16 agosto 1594 formalizzò con un documento la propria adesione alla parte cristiana, e il principe di Transilvania Zsigmond Báthory il 28 agosto 1594 spezzò l'opposizione interna liquidando i bey filo-ottomani contrari alla guerra. Il voivoda di Valacchia Michele il Coraggioso aderì all'alleanza nell'autunno dello stesso anno. Così i tre principati tributari dell'Impero ottomano a nord del Danubio — tre voivodati che pagavano tributo da centocinquant'anni e il cui voivoda era confermato da Istanbul — passarono tutti insieme dalla parte opposta nello stesso autunno. La decisione fu formalizzata con il trattato firmato a Praga il 28 gennaio 1595. Fu lo scossone più grave subito dall'ordinamento di amministrazione indiretta ottomano nel nord dei Balcani; la rivolta sarebbe stata repressa ma la fedeltà dei tre principati non sarebbe più stata così salda come tra il 1526 e il 1593.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Rivolta di Bucarest e attacco alle fortezze del Danubio", "18971100"], "d": ["La decisione della Lega Santa fu applicata un mese dopo con il sangue: Michele il Coraggioso a Bucarest passò a fil di spada il reparto di guardia ottomano e i creditori levantini della città. La rivolta nello stesso inverno si estese alla linea del Danubio; le forze valacche attaccarono Giurgiu, Brăila, Hârșova e Silistra, mentre dalla parte della Moldavia Aron Vodă fece la stessa incursione contro le guardie ottomane a Bender. La scelta dei luoghi colpiti non è casuale: erano tutte fortezze e kaza non del territorio del voivodato ma legati lungo il Danubio all'amministrazione ottomana diretta — il kaza di Yergöğü (Giurgiu) al sanjak di Nicopoli, Brăila direttamente allo Stato dal 1538, Bender ancora dal 1538 al sanjak del Bucak. Cioè la rivolta non aveva colpito l'interno vassallo, ma il guscio ottomano diretto che circonda quella regione. Senza forare questo guscio il triangolo Transilvania-Valacchia-Moldavia non poteva essere legato al fronte asburgico.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Battaglia di Călugăreni — campagna di Valacchia di Koca Sinan Pascià", "201210a1"], "d": ["Con la perdita di tutti e tre i voivodati il gran visir Koca Sinan Pascià attraversò il Danubio con un grande esercito e marciò per ricondurre la Valacchia all'obbedienza. Michele il Coraggioso, sapendo di non poter resistere in battaglia aperta, attese l'esercito a Călugăreni, nel passaggio paludoso del Neajlov, e attaccò di sorpresa le forze strette nel terreno angusto. Dopo l'attacco, non potendo resistere all'esercito ottomano numericamente superiore, si ritirò a nord, sui monti; Sinan Pascià occupò Bucarest e Târgoviște e tentò di legare la Valacchia all'amministrazione diretta. Călugăreni per questo non fu per gli Ottomani una sconfitta, ma un attacco che ritardò il completamento della campagna; ma il fatto che Michele avesse potuto conservare il proprio esercito gli permise, poche settimane dopo, di passare al contrattacco con l'aiuto giunto dalla Transilvania.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Ritirata dalla Valacchia e incursione di Giurgiu — il fallimento della campagna di repressione", "118806e1"], "d": ["Per il contrattacco di Michele il Coraggioso, unitosi alle forze del principe di Transilvania, Sinan Pascià evacuò Târgoviște e Bucarest e si ritirò verso il Danubio. Il momento più costoso della ritirata si ebbe al punto di passaggio: nell'ottobre 1595 gli akıncı che inseguivano l'esercito di ritorno dalla Valacchia subirono a Giurgiu l'attacco di Michele. La campagna terminò così senza raggiungere l'obiettivo di legare la Valacchia all'amministrazione diretta e il voivodato rimase di fatto perduto. L'autorità ottomana in questo triangolo poté essere riparata solo negli anni, a pezzi; il ritorno all'obbedienza della Transilvania avrebbe atteso la rivolta di Bocskai nel 1604, la chiusura completa del fronte il Trattato di Zsitvatorok del 1606.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Distacco di Hotin dalla Moldavia — sanjak ottomano diretto in mezzo al voivodato", "947517cb"], "d": ["Nella campagna del Prut il passaggio del voivoda di Moldavia Dimitrie Cantemir alla parte russa mostrò che il confine settentrionale del voivodato non poteva più essere lasciato al voivoda. Perciò Hotin dopo il 1711 fu tolta alla Moldavia e posta sotto amministrazione ottomana diretta; le fu dato dapprima lo statuto di nahiye, poi di sanjak. Dopo la temporanea occupazione russa del 1713 la fortezza fu riparata e ampliata sotto la supervisione di una commissione tecnica ottomana e francese inviata da Istanbul e divenne la più forte fortificazione ottomana a nord del Danubio. Sulla mappa il fatto che da questa data Hotin esca dalla tonalità di voivodato tributario e torni al colore ottomano diretto, e stia come un'isola nel mezzo della Moldavia tributaria, è precisamente la corrispondenza di questa separazione amministrativa — non è un errore di disegno. La stessa struttura esisteva già nel Bucak dal 1538 e a Kilia e Akkerman dal 1484: voivodato libero negli affari interni, fortezze di confine dello Stato.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Seconda occupazione austriaca di Böğürdelen — apertura del fronte della Sava", "063b3ad0"], "d": ["Dopo l'entrata in guerra dell'Austria al fianco della Russia il 9 febbraio 1788 la linea della Sava tornò a essere fronte e Böğürdelen passò il 24 aprile 1788 sotto dominio austriaco. La fortezza era stata già lasciata all'Austria senza guerra il 17 agosto 1717 e tenuta fino al Trattato di Belgrado (1739); in quel periodo la popolazione si era ridotta al punto che in città erano rimaste trentaquattro case cristiane e nessun musulmano. Nel periodo ottomano 1739-1788 la popolazione era risalita a 1500-2000. La seconda occupazione sarebbe terminata con il Trattato di Sistova (4 agosto 1791) e la fortezza sarebbe stata restituita agli Ottomani.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Consegna di Böğürdelen a Karađorđe — prima fortezza nella Prima rivolta serba", "5c913eb4"], "d": ["Durante la prima rivoluzione serba, iniziata nel 1804 come reazione alla pressione dei dahi e dei yamak di Belgrado e poi divenuta di carattere nazionalista, la fortezza di Böğürdelen fu consegnata a Karađorđe il 26 gennaio 1806. Questa fortezza sulla Sava è la prima grande fortificazione ottomana presa dai ribelli e preannuncia la caduta di Belgrado. Quando la rivolta fu repressa nel 1813 e Belgrado fu ripresa, la fortezza tornò sotto amministrazione ottomana; ma con la condizione di guarnigione del firmano del 1830 Böğürdelen fu definita, insieme a Belgrado, Smederevo e Fetislam, una delle quattro fortezze entro la Serbia autonoma in cui rimaneva la truppa ottomana, e restò in questo statuto fino al ritiro della guarnigione nel 1867.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Lamia (İzdin) resta entro i confini della Grecia — linea Arta-Volos", "930f63b8"], "d": ["Il confine settentrionale dello Stato greco indipendente fu tracciato nel 1832 sulla linea che si estende dal golfo di Arta al golfo di Volos. Lamia (İzdin), centro di kaza dipendente dal sanjak di Negroponte in epoca ottomana (1424-1832), restando a sud di questa linea passò alla Grecia; il resto della Tessaglia (Larissa, Trikala) rimase ottomano fino al 1881.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Dichiarazione di guerra della Russia — inizio della Guerra del '93", "ac548ab8"], "d": ["La repressione della Rivolta bulgara del 1876 aveva suscitato grande indignazione nell'opinione pubblica europea e la Russia l'aveva sfruttata fino in fondo per isolare la Sublime Porta. Dopo che la proposta della Conferenza di Istanbul (dei Cantieri) di dividere la Bulgaria in due province autonome e poi il Protocollo di Londra del 31 marzo 1877 furono respinti dall'Impero ottomano, la Russia il 24 aprile 1877 dichiarò guerra e il suo esercito entrò nei territori del Principato di Romania, da essa attratto dalla propria parte (la mappa mostra Valacchia e Moldavia da questo momento fino all'Armistizio di Edirne con la copertura tratteggiata dell'avanzata russa). Poiché cadeva nell'anno 1293 del calendario rûmî la guerra è detta Guerra del '93. L'operazione si svolse su due fronti, Danubio e Anatolia orientale: sul Danubio l'esercito ottomano di 180.000 uomini aveva considerato la riva sinistra del fiume prima linea di difesa e i monti Balcani seconda; a oriente i 55.000 soldati di Ahmed Muhtar Pascià si erano attestati tra Ardahan e Doğubayazıt. Questa guerra è sulla mappa l'evento che avviò il crollo della Rumelia ottomana — gli odierni confini di Bulgaria, Serbia, Montenegro e Romania sono tutti il prodotto di questi quindici mesi.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Proclamazione dell'indipendenza della Romania — fine della dipendenza di Valacchia e Moldavia", "bdd164b3"], "d": ["Due settimane dopo la dichiarazione della Guerra del '93, il Principato di Romania proclamò l'indipendenza ed entrò in guerra al fianco della Russia; la sua parte nell'assedio di Plevna fu determinante nella sconfitta ottomana. La dipendenza di Valacchia e Moldavia, durata oltre quattrocento anni, ebbe così fine di fatto; l'indipendenza ottenne il riconoscimento internazionale al Congresso di Berlino (1878). La mappa da questa data mostra la Romania non come tributaria ma come Stato indipendente con il proprio colore. Con la dichiarazione d'indipendenza l'intera Valacchia e Moldavia (Iași, Galați, Brăila, Giurgiu, Calafat, Botoșani ecc.) divenne Romania indipendente.", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["L'esercito russo attraversa il Danubio — caduta di Sistova e Tărnovo", "811367b1"], "d": ["I Russi, entrati con l'inizio della guerra nei territori della Romania e avendo attratto dalla propria parte questo principato, avanzarono su due colonne, una in direzione della Dobrugia e l'altra di Bucarest. Il Danubio fu attraversato tra Ruse e Nicopoli e il 27 giugno furono prese Sistova e il 1° luglio l'antica capitale bulgara Tărnovo. Poiché, benché ne fosse stata ordinata l'evacuazione, non si era prestata attenzione a questo, anche Nicopoli resistette per un po' e poi si arrese. L'apertura della prima linea di difesa in una settimana provocò grande panico a Istanbul; si diffusero persino voci di un trasferimento del centro del sultanato a Bursa e la conduzione della guerra fu affidata a un consiglio militare costituito nella capitale.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Evacuazione del Passo di Shipka — sfondamento della linea dei Balcani", "1f45e50a"], "d": ["Le forze ottomane a Shipka, il più strategico dei passi che attraversano i monti Balcani, opposero violenta resistenza agli attacchi russi; ma convintesi che sarebbero state sconfitte evacuarono segretamente il passo il 19 luglio. Così fu aperta anche la seconda linea di difesa e il generale Gurko il 22 luglio prese Stara Zagora. Süleyman Pascià, giunto dalla parte del Montenegro, sconfisse Gurko e riprese i luoghi occupati a sud dei Balcani, ma nonostante gli attacchi durati mesi dal 21 agosto non poté riprendere Shipka. Sulla mappa questa è la mancata ricostituzione, mai più, dell'integrità difensiva tra il nord e il sud della catena dei Balcani: la lotta sul fronte del Danubio da ora in poi si annoderà a Plevna.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Lovech occupata dall'esercito russo", "70e54611"], "d": ["Nella Guerra del '93 Lovech era stata occupata dai Russi il 5 giugno 1877 e le forze ottomane al comando di Rifat Pascià il 15 giugno avevano respinto i Russi; la città il 23 agosto fu abbandonata dagli Ottomani ed entrò di nuovo sotto occupazione russa. La mappa mostra Lovech da questo giorno fino al Trattato di Berlino sotto occupazione russa (tratteggiata); giuridicamente continua a essere territorio ottomano.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Caduta di Kars — dissoluzione del fronte orientale e fortificazioni di Aziziye", "53fc3bf5"], "d": ["In Anatolia orientale i Russi, avanzati su tre colonne verso Kars, Doğubayazıt e Ardahan, il 30 aprile avevano preso Doğubayazıt ed erano entrati ad Ardahan, ma, mentre marciavano su Erzurum, il 15 luglio erano stati sconfitti e cacciati oltre il confine. Questo successo, che aveva valso ad Ahmed Muhtar Pascià il titolo di \"Gazi\", si rovesciò ad agosto con il nuovo attacco del generale Lazarev e il 18 novembre cadde Kars. Le forze ottomane, ritiratesi a Erzurum per una difesa più adatta, mostrarono grande resistenza presso le fortificazioni di Aziziye, con l'incoraggiamento alla popolazione di Nene Hatun. Kars, Ardahan e Batum sarebbero state lasciate alla Russia otto mesi dopo a Berlino in corrispondenza di una parte dell'indennità di guerra.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Inizio della Prima guerra balcanica — dichiarazione di guerra del Montenegro", "c0c2697e"], "d": ["Gli Stati balcanici, rimossa l'ostacolo maggiore tra loro con la soluzione della questione delle chiese da parte di Unione e Progresso con la legge del 3 luglio 1911, per l'istigazione della Russia nel corso del 1912 avevano firmato tra loro trattati di alleanza (13 marzo Serbia-Bulgaria, 29 maggio Bulgaria-Grecia, in agosto Montenegro-Bulgaria, 6 ottobre Montenegro-Serbia). La Sublime Porta non se ne accorse; anzi, fidandosi delle garanzie della Russia, congedò 120 battaglioni addestrati in Rumelia. I quattro Stati il 3 ottobre presentarono una nota comune chiedendo autonomia per Macedonia, Albania e Creta; non ricevendo risposta, le operazioni iniziarono con la dichiarazione di guerra del Montenegro l'8 ottobre 1912. Il 13 ottobre furono consegnati i passaporti agli ambasciatori di Serbia e Bulgaria, il giorno dopo questi due Stati e poi la Grecia dichiararono guerra. Durante la guerra le divergenze politiche all'interno dell'esercito ebbero un grande ruolo nella sconfitta.", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["Nei Rodopi il Distaccamento di Kırcaali è sconfitto, Kırcaali cade", "8cf59b7f"], "d": ["Dopo la dichiarazione di guerra bulgara le forze bulgare scese dai Rodopi, sconfitto il Distaccamento di Kırcaali di Mehmed Yaver Pascià, entrarono a Kırcaali. Il distaccamento sconfitto si ritirò in direzione di Komotini; la parte orientale dei Rodopi andò perduta nella prima settimana di guerra.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Disfatta dell'Armata d'Oriente e ritirata sulla linea di Çatalca — perdita di Kumanovo e Salonicco", "cf95591a"], "d": ["L'Armata d'Oriente ottomana il 23 ottobre 1912, sconfitta dall'esercito bulgaro tre volte più numeroso, si ritirò fino alla linea di Çatalca, trenta chilometri a ovest di Istanbul; la capitale nel primo mese di guerra fu direttamente minacciata. Negli stessi giorni l'Armata d'Occidente il 23-24 ottobre fu sconfitta dai Serbi a Kumanovo e Tahsin Pascià con il suo esercito di 35.000 uomini si arrese ai Greci a Salonicco. Per queste disfatte il 29 ottobre si dimise il gabinetto di Gazi Ahmed Muhtar Pascià; Abdülhamid II, che viveva in esilio a Salonicco, il 1° novembre fu trasferito a Istanbul. La linea di Çatalca fu tenuta fino alla fine della guerra — la geografia ottomana di cinquecento anni della Rumelia fu ridotta in poche settimane a questa stretta fascia.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Il principe Alessandro entra nel centro del sanjak di Novi Pazar", "326d0616"], "d": ["Le forze serbe nella prima settimana di guerra presero Novi Pazar e si unirono alle forze montenegrine giunte da ovest. Il sanjak di Novi Pazar, che per cento anni aveva separato Serbia e Montenegro, divenne così un ponte tra i due alleati.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Dopo la battaglia di Kırkkilise cade Kırklareli", "eda4c759"], "d": ["In Tracia orientale, con la sconfitta dell'Armata d'Oriente nella battaglia di Kırkkilise (Lozengrad), la città difesa da Kölemen Abdullah Pascià fu lasciata alle forze bulgare. La città fu liberata dall'occupazione di nove mesi solo nella Seconda guerra balcanica, il 21 luglio 1913.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Skopje (Üsküp), centro della provincia del Kosovo, lasciata senza resistenza", "455d9b71"], "d": ["Dopo la disfatta di Kumanovo (23-24 ottobre) Skopje, centro della provincia del Kosovo, rimase indifesa. Poiché la popolazione non voleva combattimenti intorno alla città, le forze serbe al comando del principe Alessandro, invitate tramite i consoli, entrarono in città senza resistenza la sera del 26 ottobre.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Perdita di Köprülü (Veles) sul Vardar", "73d20b7d"], "d": ["Due giorni dopo la caduta di Skopje l'esercito serbo, sceso a sud lungo il Vardar, prese Köprülü. La porta della valle del Vardar verso Salonicco passò così ai Serbi.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Bacino del Bregalnica: il generale Stefanović entra a Štip (İştip)", "70a84256"], "d": ["Le unità serbe al comando del generale Stefanović presero Štip senza incontrare resistenza; in città entrarono dapprima bande irregolari. Dopo Kumanovo il bacino del Bregalnica della Macedonia orientale passò sotto controllo serbo.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Dopo il passo di Sarantaporo Karaferye (Veria) passa sotto dominio greco", "02a68e02"], "d": ["L'esercito greco, che avanzava verso nord dalla Tessaglia, dopo aver superato il passo di Sarantaporo (Kırkgeçit) prese possesso di Karaferye. Una parte della popolazione musulmana della città in questo periodo lasciò la regione.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Perdita di Vodena sulla ferrovia Salonicco-Monastir", "fc15b917"], "d": ["Vodena, sulla ferrovia Salonicco-Monastir, passò in mano all'esercito greco. Con la partenza forzata delle popolazioni slava e turca la popolazione della città in breve tempo diminuì seriamente.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Battaglia di Yenice — Yenice-i Vardar passa ai Greci", "8f6cb76e"], "d": ["L'8° Corpo d'armata composito di Hasan Tahsin Pascià fu sconfitto dall'esercito greco a Yenice (Giannitsa), a ovest di Salonicco, e si ritirò nella zona di Salonicco. Durante la battaglia gran parte della cittadina bruciò; la strada di Salonicco fu aperta all'esercito greco.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Prizren, nel sud-ovest del Kosovo, si arrende", "bae6b1b9"], "d": ["Prizren, nel sud-ovest del Kosovo, si arrese alle forze serbe. L'atteggiamento delle unità entrate in città verso la popolazione musulmana fu registrato come una delle pagine più gravi della guerra in Kosovo.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Il colonnello Mitov proclama la legge marziale a Strumica", "bcad75cc"], "d": ["Il colonnello bulgaro Mitov, entrato a Strumica, proclamò la legge marziale; partendo il giorno dopo lasciò la cittadina a un kaymakam bulgaro e a un comandante serbo. Strumica durante la guerra passò di mano tra gli alleati e nel 1913 fu legata alla Bulgaria.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Hasan Tahsin Pascià lascia Salonicco ai Greci", "1738933c"], "d": ["Hasan Tahsin Pascià, ritiratosi a Salonicco dopo la sconfitta di Yenice, mentre l'esercito bulgaro si avvicinava da nord lasciò la città ai Greci; l'esercito greco entrò in città l'8 novembre verso mezzogiorno. Salonicco, il maggiore porto della Rumelia ottomana e luogo di nascita di Unione e Progresso, andò così perduta.", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Komotini (Gümülcine), centro della Tracia occidentale, aperta ai Bulgari", "96eec25f"], "d": ["Per il ritiro verso Fere del distaccamento di Yaver Pascià, ritiratosi da Kırcaali, Komotini si arrese alle forze bulgare. Il centro della Tracia occidentale era tra i primi dei territori che alla fine della guerra sarebbero stati lasciati alla Bulgaria.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["I Serbi giunti a Elbasan entrano lo stesso giorno a Debar", "16720246"], "d": ["Le forze serbe avanzate da Monastir verso ovest, il giorno in cui giunsero a Elbasan, entrarono anche a Debar e scesero verso l'Adriatico. Lo stesso giorno a Valona veniva proclamata l'indipendenza dell'Albania.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Tamerlano occupa Baghdad per la seconda volta — distrutti i quartieri abbasidi della città", "04b68a24"], "d": ["Tamerlano prese Baghdad due volte a otto anni di distanza. Nella prima occupazione del 1393 la città non aveva subito molti danni; la seconda, del 1401, è considerata il secondo duro colpo inferto alla vita culturale di Baghdad — la popolazione fu passata a fil di spada, la maggior parte dei quartieri e degli edifici rimasti dall'epoca abbaside fu distrutta. Il sovrano jalayiride Ahmed, tornato in città nel 1405, cercò di riparare le mura e i bazar distrutti ma non ne ebbe il tempo; Baghdad nel 1410 passò in mano ai turcomanni Qara Qoyunlu. Queste due occupazioni sono uno dei passi più concreti che mostrano quanto Tamerlano si fosse avvicinato ai confini ottomani e mamelucchi sulla via che porta alla Battaglia di Ankara.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Cüneyd Bey torna alla guida dell'Aydın-ili — gli Aydınidi di nuovo indipendenti", "63281658"], "d": ["Çelebi Mehmed nel 1414-15, preso İzmir, aveva inviato Cüneyd Bey al sanjak-beylik di Nicopoli legando l'Aydın-ili all'amministrazione ottomana. Cüneyd, dopo la morte di Çelebi Mehmed, ricomparve sulla scena al fianco di Mustafa Çelebi, avanzato da Bisanzio come pretendente al trono, e fu persino suo visir. Murad II lo separò da questa alleanza con la promessa di restituirgli il suo antico beylicato; Cüneyd tornò a İzmir, prese Ayasuluk e, uccidendo Aydınoğlu Mustafa Bey, si pose alla testa del beylicato. Così l'Aydın-ili nacque, dall'interno della crisi del Falso Mustafa, uscito dall'amministrazione ottomana.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Esecuzione di Cüneyd Bey e della sua famiglia — fine del beylik degli Aydınoğlu", "efa684ba"], "d": ["Poiché Cüneyd Bey, tornato a dominare l'Aydın-ili, incitava i bey anatolici e cercava contatti con Venezia, Murad II inviò contro di lui il beylerbey dell'Anatolia, Hamza Bey. Dopo che suo figlio Kurd Hasan fu sconfitto presso Akhisar e fatto prigioniero, Cüneyd si ritirò a İpsili, di fronte all'isola di Samo; non giungendo l'aiuto atteso dai Karamanoğlu e venendo bloccato dal mare dai Genovesi, che agivano insieme agli Ottomani, fu costretto ad arrendersi e fu eliminato con tutta la sua stirpe. I territori degli Aydınoğlu passarono così interamente sotto l'amministrazione ottomana.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Erzurum e il bacino di Van passano ai Safavidi — crolla il fianco settentrionale degli Aqquyunlu", "b418875f"], "d": ["Dopo aver sconfitto Alvand Bey a Şerûr ed essere entrato a Tabriz nell'estate del 1501, Shah Ismail l'anno seguente avanzò verso nord-ovest e pose sotto il proprio dominio la fascia che va da Erzurum al bacino del lago di Van. Lo Stato degli Aqquyunlu, dopo la morte di Uzun Hasan, era già diviso in due dalle lotte per il trono: Alvand Bey teneva l'Azerbaigian e Diyarbekir, il cugino paterno Murad l'Iraq persiano (Irak-ı Acem) e il Fars. Questa divisione facilitò l'avanzata safavide; la regione cambiò di mano in dieci registrazioni nel giro di un anno. Erzurum rimase poi per sedici anni in mano safavide ed entrò sotto il dominio ottomano solo dopo Çaldıran, nel 1518-19. In quest'anno (1502) Aşkale e Pasinler (Hasankale), insieme alla regione di Erzurum, passarono dagli Aqquyunlu ai Safavidi (giorno non confermato).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Sconfitta di Murad Bey a Hamadan: l'Iraq persiano e il Fars passano ai Safavidi", "8de07a31"], "d": ["Il sultano Murad, secondo pretendente al trono degli Aqquyunlu, subì una pesante sconfitta nella battaglia contro Shah Ismail presso Hamadan e fuggì a Baghdad. Con questa sola battaglia le regioni dell'Iraq persiano, del Fars e del Kirman entrarono sotto l'amministrazione safavide; sulla mappa queste regioni cambiano di mano nello stesso momento. È il singolo passo più grande nella dissoluzione dello Stato degli Aqquyunlu: la perdita di Tabriz aveva lasciato la dinastia senza capitale, la sconfitta di Hamadan la lasciò senza territorio.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Shah Ismail entrò a Yazd: cadde l'ultima roccaforte dei resti degli Aqquyunlu nell'Iran centrale", "6f9835df"], "d": ["Dopo la sconfitta di Hamadan del 1503, benché l'Iraq persiano e il Fars fossero passati ai Safavidi, Yazd era rimasta separata, in mano a Bayındırlı Murad Bey della dinastia degli Aqquyunlu. La città cadde dopo un assedio di un mese e si chiuse così l'ultima isola aqquyunlu nell'Iran centrale. Annotazione del TDV: \"Shah Ismail entrò in città il 28 Cemâziyelâhir 910 (6 dicembre 1504), dopo un assedio di un mese.\"", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Campagna di Shah Ismail a Diyarbekir: caddero gli ultimi centri degli Aqquyunlu", "b6d8504e"], "d": ["Dopo aver conquistato l'Azerbaigian e l'altopiano iranico, nel 1507 Shah Ismail si volse a occidente, verso la regione di Diyarbekir, dove era nata la dinastia degli Aqquyunlu. La fascia che va da Âmid a Mardin, da Urfa a Harput passò in due mosse sotto l'amministrazione safavide e gli Aqquyunlu scomparvero di fatto. Questa campagna portò per la prima volta il confine safavide a contatto con i confini ottomano e mamelucco; così si costruì il fondamento geografico della tensione che condusse a Çaldıran.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Passaggio di Baghdad ai Safavidi — l'Iraq arabo (Irâk-ı Arab) cambiò di mano", "39730186"], "d": ["Inseguendo il sultano aqquyunlu Murad, che dopo la sconfitta di Hamadan si era rifugiato a Baghdad, Shah Ismail entrò nell'Iraq arabo nel 1508 e prese Baghdad. Il passaggio dei mausolei di Kerbela e Najaf sotto l'amministrazione safavide fu importante, per la pretesa confessionale del movimento, quanto la presa di Tabriz. Sulla mappa l'Iraq arabo cambia di mano nello stesso giorno; è l'ultimo e più vasto passo geografico della dissoluzione. Baghdad rimase in mano safavide fino alla campagna dei Due Iraq (Irakeyn) di Solimano il Legislatore nel 1534.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Battaglia di Merv: gli Uzbeki subirono una pesante sconfitta, Merv ed Herat furono prese", "f8e45aaf"], "d": ["Compiuta a occidente l'eredità degli Aqquyunlu, Shah Ismail marciò a oriente, verso il Khorasan, e inflisse agli Uzbeki una pesante sconfitta davanti a Merv; Şeybânî Khan morì sul campo di battaglia. Merv ed Herat entrarono sotto il dominio safavide e lo Stato safavide raggiunse i suoi confini, dall'Eufrate all'Oxus (Ceyhun). Così il processo iniziato con l'ingresso a Tabriz nell'estate del 1501 si compì in nove anni: l'eredità degli Aqquyunlu passò per intero all'amministrazione safavide e lo Stato ottomano si trovò ad avere a oriente come vicino un secondo Stato della propria grandezza.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Ingresso definitivo di Zabid sotto il dominio ottomano", "ddd971c7"], "d": ["La flotta che aveva tolto l'assedio di Diu il 5 novembre 1538 toccò sulla via del ritorno la costa dello Yemen e Zabid fu legata definitivamente all'amministrazione ottomana; Hadım Süleyman Pascià lasciò la città il 10 marzo 1539 e giunse a Gedda il 1° aprile. La città dal 1517 era governata a nome degli Ottomani dagli antichi bey mamelucchi; con questa data passò all'amministrazione diretta.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Unione Iberica: la corona portoghese passò al re di Spagna", "1cc6dfdc"], "d": ["La disputa successoria apertasi con la morte senza eredi del cardinale-re Henrique si concluse a favore della Spagna nella battaglia di Alcântara (25 agosto 1580) e le Cortes portoghesi riunite a Tomar il 16 aprile 1581 riconobbero Filippo II come re del Portogallo. Secondo le condizioni di Tomar il Portogallo avrebbe conservato le proprie istituzioni, la moneta e la lingua, all'amministrazione sarebbero stati nominati solo Portoghesi e a Madrid vi sarebbe stato un consiglio portoghese separato — cioè l'unione fu personale, non un'annessione.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Restauração: il Portogallo riconquistò l'indipendenza", "64ec0738"], "d": ["Nei giorni in cui la rivolta di Catalogna teneva occupata la Spagna, a Lisbona un gruppo di nobili assalì il palazzo e rovesciò l'amministrazione spagnola, proclamando re il duca di Braganza con il nome di João IV. L'Unione Iberica di sessant'anni giunse così al termine; tuttavia Ceuta scelse di restare alla Spagna, e ciò fu riconosciuto con il trattato di Lisbona del 1668. Questa finestra, in cui il Portogallo fu trascinato nelle guerre asburgiche, è anche la cornice delle sue perdite in Asia: Ormuz fu perduta nel 1622, Malacca nel 1641, Colombo nel 1656; Tangeri e Bombay furono invece cedute all'Inghilterra come prezzo dell'indipendenza. Fonte: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Tangeri ceduta all'Inghilterra", "1f7cad6d"], "d": ["Il secondo articolo del trattato matrimoniale (23 giugno 1661), concluso per assicurarsi il sostegno inglese nella guerra d'indipendenza portoghese, lasciava Tangeri all'Inghilterra come dote di Caterina di Braganza. La flotta del conte di Sandwich gettò l'ancora il 29 gennaio 1662 e il giorno seguente, con la cerimonia del conte di Peterborough, avvenne la cessione ufficiale. Gli Inglesi avrebbero abbandonato la città nel 1684.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Assassinio di Nadir Shah — dissoluzione del dominio afsharide", "19c218c0"], "d": ["Nadir Shah, che aveva posto fine al trono safavide e nel 1736 aveva proclamato il sultanato a proprio nome, che con la campagna d'India era giunto fino a Delhi e che dopo tre guerre con gli Ottomani aveva fatto pace con il trattato di Kerden del 1746, fu ucciso nella sua tenda dalle proprie guardie. In seguito l'Iran non poté più essere governato da un'unica mano: per quarantanove anni si divisero il paese i resti degli Afsharidi nel Khorasan, gli Zand a sud e i Qajar in ascesa a nord. Grazie a questa frammentazione il confine orientale ottomano rimase tranquillo a lungo. Nadir Shah fu ucciso il 20 giugno 1747; secondo il TDV il khanato di Erevan fu fondato nello stesso anno (1747), giorno non confermato.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["I Qajar si impongono in Iran", "744b48c5"], "d": ["Agha Mohammad Khan, capo della tribù qajar, abbatté il dominio degli Zand e spezzò l'ultima resistenza afsharide nel Khorasan, riunendo di nuovo l'Iran in una sola mano e facendo di Teheran la capitale. L'epoca di frammentazione di quarantanove anni si chiuse così; da allora il vicino orientale dell'Impero ottomano sarebbe stato l'Iran qajar fino al 1923. Secondo il TDV İslâm Ansiklopedisi, Mashhad nel 1796 fu consegnata ad Agha Mohammad Shah dal sovrano afsharide Shahrokh e passò sotto il dominio qajar (il giorno non è nella fonte).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Ferdinando prese Buda — Szapolyai cacciato dalla capitale", "99f77c29"], "d": ["Dopo Mohács sul trono d'Ungheria vi erano due re: una parte dei nobili aveva eletto János Szapolyai, un'altra Ferdinando d'Asburgo. Nel 1527 Ferdinando prese Buda e scacciò Szapolyai dalla capitale; Szapolyai chiese aiuto al sultano Solimano. Questa è la ragione per cui il primo obiettivo della campagna di Vienna del 1529 fu Buda.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Campagna di Barbarossa nelle isole dell'Egeo — il Ducato di Nasso passò sotto il controllo ottomano", "722b2fea"], "d": ["Il Ducato di Nasso, governato dal 1207 da duchi latini sotto la tutela veneziana, passò sotto il controllo ottomano con la campagna di Barbaros Hayreddin Pascià nelle isole. Lo status dell'isola non fu toccato; il ducato continuò come vassallo degli Ottomani e con l'accordo ottomano-veneziano del 1540 il diritto di sovranità fu ufficialmente trasferito agli Ottomani.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["La flotta crociata occupò Gerba — perduta la base di Turgut Pascià", "f41b3f2a"], "d": ["La flotta crociata, composta da navi di Spagna, Papato, Malta, Genova e Firenze, prese di mira Gerba, che Turgut Reis usava dal 1551 come base per le sue incursioni. A causa di tempeste ed epidemie poté raggiungere l'isola solo all'inizio del 1560; il 12 marzo 1560 occupò l'isola e vi costruì un forte. Appresa la notizia, Piyâle Pascià il 28 marzo partì da Istanbul con una flotta di 120 galee. L'occupazione non durò a lungo: a maggio la flotta ottomana sconfisse gli alleati davanti a Gerba e il forte fu ripreso alla fine di luglio. Questa campagna è l'inizio della seconda grande operazione navale che, dopo Prevesa, consolidò la supremazia ottomana nel Mediterraneo.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Caduta del forte di Gerba — passaggio dell'isola all'amministrazione ottomana", "f1efc0df"], "d": ["Dopo la vittoria navale di Piyâle Pascià del 14 maggio 1560, le forze crociate si chiusero nel forte costruito sull'isola; le forze di Turgut Pascià, beylerbey di Tripoli di Barberia, lo assediarono da terra. L'assedio, durato due mesi, si concluse il 30 luglio 1560 con la caduta del forte e l'isola fu legata al beylerbeylik di Tripoli. Tra la vittoria navale e la conquista del forte passano settantasette giorni; l'isola ha cambiato di fatto mano il 30 luglio, non il 14 maggio.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["A Danzica cessò il doppio potere russo-prussiano — la città libera di Napoleone tornò alla Prussia", "1ccda4d2"], "d": ["Danzica, separata dalla Prussia con la pace di Tilsit (9 luglio 1807) e resa città libera sotto protezione francese, fu lasciata dalle forze di Napoleone dopo l'assedio del 1813. Tra il 2 gennaio e il 4 febbraio 1814 in città perdurò il doppio potere russo-prussiano; quando lo zar Alessandro rinunciò al piano di prendere Danzica e la foce della Vistola, la città passò all'amministrazione prussiana.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["A Vienna Cracovia proclamata città libera, indipendente e neutrale", "19eea839"], "d": ["Al Congresso di Vienna Russia, Austria e Prussia fecero della città di Cracovia, con il suo territorio, uno Stato libero sotto la protezione delle tre potenze; l'Atto finale di Vienna sancì questo assetto.", "21a6fe2b"]},
"OLAYLAR_EK12:1846-11-11:0":{"b": ["Abolita la Città Libera di Cracovia, annessa all'Austria", "15548a14"], "d": ["Prendendo a pretesto l'insurrezione di Cracovia del febbraio 1846, Russia, Austria e Prussia decisero, in una conferenza a Vienna, di abolire la città libera e di annetterla ai territori austriaci; le obiezioni di Inghilterra e Francia non ebbero effetto.", "bf12c063"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Il Bornu cadde sotto il dominio di Rabih b. Zubayr", "8be4ca96"], "d": ["Il signore della guerra sudanese Rabih b. Zubayr, che aveva scosso il Baghirmi e il Wadai, si impadronì del Bornu; entro il 1896 prese l'intero paese e fece di Dikwa il proprio centro.", "466276f3"]}
});
